    #if os(iOS) && !targetEnvironment(simulator)
    /// An app on the person's own phone, away from the Mac: Lamp answers its AI whenever the Mac is reachable,
    /// and otherwise the app asks the provider itself with the person's own key, kept in the phone's Keychain
    /// since the last time it saw Lamp (Settings → Experimental in Lamp decides whether it may keep one). The
    /// prompt is the same either way: the fencing and the dates are made here. What's spent this way doesn't
    /// show in Lamp, and using the Mac's other apps still needs the Mac.
    enum LampDirect {
        private static let keychainAccount = "lamp-ai-keys"

        /// Whether the Mac answered lately, shared by every call so two at once don't each decide for
        /// themselves: one probe at a time, and all callers wait for its answer.
        private actor Reach {
            private var lastProbe = Date.distantPast
            private var reachable = true
            private var probe: Task<Bool, Never>?

            func useMac(token: String) async -> Bool {
                if let probe { return await probe.value }
                if Date().timeIntervalSince(lastProbe) < 30 { return reachable }
                let task = Task<Bool, Never> { await LampDirect.probe(token: token) }
                probe = task
                let answer = await task.value
                probe = nil
                lastProbe = Date()
                reachable = answer
                return answer
            }

            /// A call to the Mac just failed to connect: the next caller checks again rather than trusting
            /// the last answer.
            func lost() { lastProbe = .distantPast; reachable = false }
        }
        private static let reach = Reach()

        /// Whether to go through Lamp now: looked up at most every half minute with a quick call that also
        /// refreshes the keys while the Mac is there.
        static func useMac(token: String) async -> Bool { await reach.useMac(token: token) }

        /// Whether an error from the Mac means the Mac couldn't be reached at all (as opposed to answering
        /// with a failure), so the phone should answer for itself.
        static func unreachable(_ error: Error) -> Bool {
            guard let error = error as? URLError else { return false }
            return [.cannotConnectToHost, .cannotFindHost, .dnsLookupFailed, .notConnectedToInternet, .networkConnectionLost,
                    .timedOut, .internationalRoamingOff, .dataNotAllowed].contains(error.code)
        }

        static func lost() async { await reach.lost() }

        private static func probe(token: String) async -> Bool {
            var request = URLRequest(url: URL(string: lampGateway + "/ai/keys")!)
            request.httpMethod = "POST"
            request.timeoutInterval = 4
            request.setValue("Bearer \(token)", forHTTPHeaderField: "Authorization")
            request.setValue("application/json", forHTTPHeaderField: "Content-Type")
            request.httpBody = Data("{}".utf8)
            do {
                let (data, response) = try await URLSession.shared.data(for: request)
                switch (response as? HTTPURLResponse)?.statusCode {
                case 200:
                    // Sealed with the secret that came with the build, never over the air: a copy of this
                    // traffic gives nobody the key.
                    if let reply = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
                       let sealed = (reply["sealed"] as? String).flatMap({ Data(base64Encoded: $0) }),
                       let box = try? AES.GCM.SealedBox(combined: sealed),
                       let sealingKey,
                       let opened = try? AES.GCM.open(box, using: sealingKey),
                       let keys = try? JSONSerialization.jsonObject(with: opened) as? [String: Any] {
                        save(keys)
                    }
                case 403, 404:
                    save(nil)   // the person turned keeping a key off, or there's no key any more: it goes
                default:
                    break   // a passing failure: the copy stays
                }
                return true
            } catch {
                return false
            }
        }

        /// From the secret Lamp put in this build's Info.plist: only the phone's own build carries it.
        private static var sealingKey: SymmetricKey? {
            guard let secret = Bundle.main.object(forInfoDictionaryKey: "LampPhoneSecret") as? String, !secret.isEmpty else { return nil }
            return SymmetricKey(data: SHA256.hash(data: Data(secret.utf8)))
        }

        /// The keys and model choices the phone keeps, or nil when it has none.
        static var keys: [String: Any]? {
            let query: [String: Any] = [kSecClass as String: kSecClassGenericPassword, kSecAttrService as String: Bundle.main.bundleIdentifier ?? "lamp",
                                        kSecAttrAccount as String: keychainAccount, kSecReturnData as String: true]
            var item: CFTypeRef?
            guard SecItemCopyMatching(query as CFDictionary, &item) == errSecSuccess, let data = item as? Data else { return nil }
            return try? JSONSerialization.jsonObject(with: data) as? [String: Any]
        }

        private static func save(_ keys: [String: Any]?) {
            let query: [String: Any] = [kSecClass as String: kSecClassGenericPassword, kSecAttrService as String: Bundle.main.bundleIdentifier ?? "lamp",
                                        kSecAttrAccount as String: keychainAccount]
            SecItemDelete(query as CFDictionary)
            guard let keys, let data = try? JSONSerialization.data(withJSONObject: keys) else { return }
            var add = query
            add[kSecValueData as String] = data
            add[kSecAttrAccessible as String] = kSecAttrAccessibleAfterFirstUnlock
            SecItemAdd(add as CFDictionary, nil)
        }

        /// Answers what the gateway would, with the provider directly.
        static func handle(_ path: String, _ body: [String: Any]) async throws -> [String: Any] {
            guard let keys, let key = keys["openrouter"] as? String else {
                throw LampAI.Failure(message: "Couldn't reach Lamp, and this phone has no key of its own yet. Open the app once while Lamp is reachable.",
                                     needsSetup: .text)
            }
            // What the phone carries answers all three.
            if path == "/ai/status" { return ["text": true, "decisions": true, "pictures": true] }
            fputs("LampAI \(path): Lamp isn't reachable, using the key kept on this phone\n", stderr)
            switch path {
            case "/ai":
                let text = try await complete(body, key: key, model: keys["text_model"] as? String ?? "anthropic/claude-sonnet-5.5")
                return ["text": text]
            case "/ai/decide":
                if keys["decision_provider"] as? String == "text" {
                    return ["answers": try await decideByText(body, key: key, model: keys["text_model"] as? String ?? "anthropic/claude-sonnet-5.5")]
                }
                return ["answers": try await decide(body, keys: keys)]
            case "/ai/image":
                return ["image": try await image(body, key: key, model: keys["image_model"] as? String ?? "google/gemini-3.1-flash-image"),
                        "media_type": "image/png"]
            default:
                throw LampAI.Failure(message: "Using the Mac's other apps needs this phone to reach Lamp. Try again on the same Wi‑Fi as the Mac.")
            }
        }

        private static func complete(_ body: [String: Any], key: String, model: String) async throws -> String {
            let prompt = body["prompt"] as? String ?? ""
            var system = body["system"] as? String ?? ""
            let json = body["json"] as? Bool ?? false
            if json { system += "\n\nRespond with only valid JSON. No prose, no code fences." }
            let schema = body["schema"] as? [String: Any]
            var text = try await chat(prompt: prompt, system: system, images: body["images"] as? [[String: String]] ?? [], json: json, schema: schema, key: key, model: model)
            guard json else { return text }
            // A JSON reply that doesn't parse is useless to the app: once more, saying so.
            text = unfenced(text)
            if !isJSON(text) {
                let again = "\(prompt)\n\nYour previous reply was not valid JSON (it may have been cut off). Reply with the complete JSON only."
                text = unfenced(try await chat(prompt: again, system: system, images: body["images"] as? [[String: String]] ?? [], json: true, schema: schema, key: key, model: model))
                if !isJSON(text) { throw LampAI.Failure(message: "The AI's reply wasn't valid JSON, even on a second try. Ask for less at once.") }
            }
            return text
        }

        private static func chat(prompt: String, system: String, images: [[String: String]], json: Bool, schema: [String: Any]? = nil,
                                 key: String, model: String) async throws -> String {
            var request = URLRequest(url: URL(string: "https://openrouter.ai/api/v1/chat/completions")!)
            request.httpMethod = "POST"
            request.timeoutInterval = 120
            request.setValue("Bearer \(key)", forHTTPHeaderField: "Authorization")
            request.setValue("application/json", forHTTPHeaderField: "Content-Type")
            request.setValue("Lamp", forHTTPHeaderField: "X-Title")
            var messages: [[String: Any]] = []
            if !system.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { messages.append(["role": "system", "content": system]) }
            let content: [[String: Any]] = [["type": "text", "text": prompt]] + images.compactMap { image in
                guard let type = image["media_type"], let data = image["data"] else { return nil }
                return ["type": "image_url", "image_url": ["url": "data:\(type);base64,\(data)"]]
            }
            messages.append(["role": "user", "content": content])
            var payload: [String: Any] = ["model": model, "messages": messages]
            if json {
                // With a schema, the reply must fit it (a decision's every key, its exact options).
                payload["response_format"] = schema.map { ["type": "json_schema", "json_schema": ["name": "answer", "strict": true, "schema": $0]] }
                    ?? ["type": "json_object"]
                payload["max_tokens"] = 16_000
            }
            request.httpBody = try JSONSerialization.data(withJSONObject: payload)
            // The provider's content filter sometimes refuses an ordinary request at random: ask again.
            for attempt in 0..<3 {
                let (data, response) = try await URLSession.shared.data(for: request)
                let obj = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any] ?? [:]
                let status = (response as? HTTPURLResponse)?.statusCode ?? 0
                guard status == 200, let choice = (obj["choices"] as? [[String: Any]])?.first else {
                    throw LampAI.Failure(message: friendly(status, (obj["error"] as? [String: Any])?["message"] as? String))
                }
                if choice["finish_reason"] as? String == "content_filter" {
                    if attempt < 2 { try await Task.sleep(for: .milliseconds(400 << attempt)); continue }
                    throw LampAI.Failure(message: "The AI provider's content filter cut the reply off. Try rewording the request.")
                }
                return (choice["message"] as? [String: Any])?["content"] as? String ?? ""
            }
            throw LampAI.Failure(message: "The AI didn't answer.")
        }
        /// The answers' shape as a JSON schema the model is held to: every question's key, and a choice's own options.
        private static func decisionSchema(_ questions: [String: Any]) -> [String: Any] {
            func object(_ properties: [String: Any]) -> [String: Any] {
                ["type": "object", "properties": properties, "required": properties.keys.sorted(), "additionalProperties": false]
            }
            let number: [String: Any] = ["type": "number"]
            var answers: [String: Any] = [:]
            for (id, value) in questions {
                guard let question = value as? [String: Any], let type = question["type"] as? String else { continue }
                switch type {
                case "noul":
                    answers[id] = object(["noul": number])
                case "choice":
                    // Each option once: an app may list one twice, and the schema's properties can't hold it twice.
                    let options = Set((question["criteria"] as? [String: Any]).map { Array($0.keys) } ?? (question["criteria"] as? [String] ?? [])).sorted()
                    answers[id] = object(["choice": ["type": "string", "enum": options] as [String: Any],
                                          "probabilities": object(Dictionary(uniqueKeysWithValues: options.map { ($0, number as Any) })),
                                          "confidence": number])
                case "score":
                    let levels = (question["criteria"] as? [Any])?.count ?? 0
                    answers[id] = object(["score": number,
                                          "probabilities": object(Dictionary(uniqueKeysWithValues: (0..<levels).map { (String($0), number as Any) })),
                                          "confidence": number])
                default:
                    continue
                }
            }
            return object(answers)
        }


        /// Decisions without a decision model: the questions go to the text model as JSON, and its answers
        /// come back in the shape Jev's would, checked against each question as Lamp checks them.
        private static func decideByText(_ body: [String: Any], key: String, model: String) async throws -> [String: Any] {
            let questions = body["questions"] as? [String: Any] ?? [:]
            let stateJSON = (try? JSONSerialization.data(withJSONObject: body["state"] ?? NSNull(), options: [.sortedKeys, .fragmentsAllowed]))
                .map { String(decoding: $0, as: UTF8.self) } ?? ""
            let questionsJSON = (try? JSONSerialization.data(withJSONObject: questions, options: [.sortedKeys]))
                .map { String(decoding: $0, as: UTF8.self) } ?? ""
            let system = """
            You answer typed questions about some state, like a calibrated classifier. The questions are JSON, keyed \
            by id; reply with one JSON object with the same keys and nothing else.

            For a question of type "noul", the value is {"noul": p}: p is the probability, from 0 to 1, that the \
            answer to its instructions is yes, judged against its criteria ("true" describes a yes, "false" a no). \
            A clear no is 0.0, a clear yes 1.0.

            For a question of type "choice", the criteria are the options (a description of when each applies, or \
            null). The value is {"choice": option, "probabilities": {option: p, ...}, "confidence": c}: one \
            probability per option, summing to 1; choice is the most likely option; confidence (0 to 1) is how \
            concentrated the probabilities are.

            For a question of type "score", the criteria are ordered levels, lowest first, each describing a \
            situation. The value is {"score": s, "probabilities": {"0": p, "1": p, ...}, "confidence": c}: one \
            probability per level index, summing to 1; s is the probability-weighted index; confidence (0 to 1) is \
            how concentrated the probabilities are.
            """
            let text = try await complete(["prompt": "State:\n\(stateJSON)\n\nQuestions:\n\(questionsJSON)", "system": system, "json": true,
                                           "schema": decisionSchema(questions)], key: key, model: model)
            guard let raw = try? JSONSerialization.jsonObject(with: Data(text.utf8)) as? [String: Any] else {
                throw LampAI.Failure(message: "The model's decision wasn't valid JSON.")
            }
            var answers: [String: Any] = [:]
            for (id, question) in questions {
                guard let q = question as? [String: Any], let type = q["type"] as? String else { continue }
                let given = raw[id] as? [String: Any] ?? [:]
                func clamp(_ value: Any?) -> Double? { (value as? NSNumber).map { min(max($0.doubleValue, 0), 1) } }
                switch type {
                case "noul":
                    guard let p = clamp(given["noul"]) else { throw LampAI.Failure(message: "The model didn't answer \"\(id)\".") }
                    answers[id] = ["noul": p]
                case "choice":
                    let options = (q["criteria"] as? [String: Any])?.keys.map { $0 } ?? (q["criteria"] as? [String] ?? [])
                    var probabilities = (given["probabilities"] as? [String: Any] ?? [:]).reduce(into: [String: Double]()) {
                        if options.contains($1.key), let p = clamp($1.value) { $0[$1.key] = p }
                    }
                    var choice = given["choice"] as? String
                    if choice == nil || !options.contains(choice!) { choice = probabilities.max { $0.value < $1.value }?.key }
                    guard let choice else { throw LampAI.Failure(message: "The model didn't pick an option for \"\(id)\".") }
                    if probabilities.isEmpty { probabilities = [choice: 1] }
                    let total = probabilities.values.reduce(0, +)
                    if total > 0 { probabilities = probabilities.mapValues { $0 / total } }
                    answers[id] = ["choice": choice, "probabilities": probabilities,
                                   "confidence": clamp(given["confidence"]) ?? probabilities[choice] ?? 1]
                case "score":
                    let levels = (q["criteria"] as? [Any])?.count ?? 0
                    let top = Double(max(levels - 1, 0))
                    var probabilities = (given["probabilities"] as? [String: Any] ?? [:]).reduce(into: [String: Double]()) {
                        if let index = Int($1.key), index >= 0, Double(index) <= top, let p = clamp($1.value) { $0[$1.key] = p }
                    }
                    let total = probabilities.values.reduce(0, +)
                    if total > 0 {
                        probabilities = probabilities.mapValues { $0 / total }
                    } else if let given = (given["score"] as? NSNumber).map({ min(max($0.doubleValue, 0), top) }) {
                        probabilities = [String(Int(given.rounded())): 1]
                    } else {
                        throw LampAI.Failure(message: "The model didn't rate \"\(id)\".")
                    }
                    let score = probabilities.reduce(0) { $0 + Double($1.key)! * $1.value }
                    answers[id] = ["score": score, "probabilities": probabilities,
                                   "confidence": clamp(given["confidence"]) ?? probabilities.values.max() ?? 1]
                default:
                    throw LampAI.Failure(message: "Unknown question type \"\(type)\".")
                }
            }
            return answers
        }

        private static func decide(_ body: [String: Any], keys: [String: Any]) async throws -> [String: Any] {
            let key = keys["openrouter"] as? String ?? ""
            var request = URLRequest(url: URL(string: "https://openrouter.ai/api/v1/systemone")!)
            request.httpMethod = "POST"
            request.timeoutInterval = 60
            request.setValue("Bearer \(key)", forHTTPHeaderField: "Authorization")
            request.setValue("application/json", forHTTPHeaderField: "Content-Type")
            request.setValue("Lamp", forHTTPHeaderField: "X-Title")
            request.httpBody = try JSONSerialization.data(withJSONObject: ["state": body["state"] ?? NSNull(), "model": keys["decision_model"] as? String ?? "jev-latest",
                                                                           "questions": body["questions"] ?? [:]] as [String: Any])
            for attempt in 0..<4 {
                let (data, response) = try await URLSession.shared.data(for: request)
                let status = (response as? HTTPURLResponse)?.statusCode ?? 0
                let obj = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any] ?? [:]
                if (status == 429 || status == 529) && attempt < 3 {
                    try await Task.sleep(for: .milliseconds(500 << attempt))
                    continue
                }
                guard status == 200, let answers = obj["answers"] as? [String: Any] else {
                    throw LampAI.Failure(message: friendly(status, (obj["error"] as? [String: Any])?["message"] as? String))
                }
                return answers
            }
            throw LampAI.Failure(message: "The decision model is busy. Try again in a moment.")
        }

        private static func image(_ body: [String: Any], key: String, model: String) async throws -> String {
            var request = URLRequest(url: URL(string: "https://openrouter.ai/api/v1/images")!)
            request.httpMethod = "POST"
            request.timeoutInterval = 240
            request.setValue("Bearer \(key)", forHTTPHeaderField: "Authorization")
            request.setValue("application/json", forHTTPHeaderField: "Content-Type")
            request.setValue("Lamp", forHTTPHeaderField: "X-Title")
            var payload: [String: Any] = ["model": model, "prompt": body["prompt"] ?? "", "n": 1, "output_format": "png"]
            if let ratio = body["aspect_ratio"] { payload["aspect_ratio"] = ratio }
            let references = (body["images"] as? [[String: String]] ?? []).compactMap { image -> [String: Any]? in
                guard let type = image["media_type"], let data = image["data"] else { return nil }
                return ["type": "image_url", "image_url": ["url": "data:\(type);base64,\(data)"]]
            }
            if !references.isEmpty { payload["input_references"] = references }
            request.httpBody = try JSONSerialization.data(withJSONObject: payload)
            let (data, response) = try await URLSession.shared.data(for: request)
            let obj = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any] ?? [:]
            let status = (response as? HTTPURLResponse)?.statusCode ?? 0
            guard status == 200 else { throw LampAI.Failure(message: friendly(status, (obj["error"] as? [String: Any])?["message"] as? String)) }
            guard let base64 = (obj["data"] as? [[String: Any]])?.first?["b64_json"] as? String else {
                throw LampAI.Failure(message: "The image model didn't return a picture.")
            }
            return base64
        }

        private static func friendly(_ status: Int, _ detail: String?) -> String {
            switch status {
            case 401, 403: return "Your OpenRouter key didn't work. Open the app while Lamp is reachable to get the current one."
            case 402: return "Your OpenRouter account is out of credit."
            case 429: return "The AI is busy right now. Wait a minute and try again."
            default: return "Something went wrong talking to the AI: \(detail ?? "HTTP \(status)")"
            }
        }

        private static func unfenced(_ text: String) -> String {
            var t = text.trimmingCharacters(in: .whitespacesAndNewlines)
            if t.hasPrefix("```") {
                t = String(t.drop(while: { $0 != "\n" }).dropFirst())
                if let end = t.range(of: "```", options: .backwards) { t = String(t[..<end.lowerBound]) }
            }
            return t.trimmingCharacters(in: .whitespacesAndNewlines)
        }

        private static func isJSON(_ text: String) -> Bool {
            (try? JSONSerialization.jsonObject(with: Data(text.utf8), options: [.fragmentsAllowed])) != nil
        }
    }
    #endif

    /// What Lamp told this copy of the app when it installed it, in its Info.plist: who the app is to Lamp, the
    /// secrets it shows Lamp, and where Lamp and its folders are. None of it is compiled in, so a copy built once
    /// (a starter Lamp ships) works on any Mac and for either Lamp once Lamp has written its own values in.
    enum LampInstall {
        static let values = Bundle.main.object(forInfoDictionaryKey: "LampInstall") as? [String: String] ?? [:]
        static func value(_ key: String) -> String { values[key] ?? "" }
        static func number(_ key: String) -> Int { Int(value(key)) ?? 0 }
        /// The app's folder name, which is how Lamp knows it.
        static var slug: String { value("slug") }
        /// Shown to Lamp with each request; only Lamp and this app have it.
        static var token: String { value("token") }
        static var dataID: String { value("dataID") }
        static var port: Int { number("port") }
        static var scheme: String { value("scheme") }
        /// What Lamp's notifications to and from its apps begin with.
        static var note: String { value("note") }
        /// Lamp's own bundle id.
        static var host: String { value("host") }
        /// The folder of Lamp's apps, and this app's in it.
        static var apps: String { value("apps") }
        /// Its folder: under its own name, or for a part of a wish (an app beside a TV app) inside its wish's. An app
        /// installed by a Lamp from before says only its name.
        static var app: String { apps + "/" + (value("folder").isEmpty ? slug : value("folder")) }
        static var macHost: String { value("macHost") }
        /// A link that asks Lamp to do something for this app.
        static func link(_ action: String) -> URL {
            URL(string: "\(scheme.isEmpty ? "lamp" : scheme)://\(action)?app=\(slug)") ?? URL(fileURLWithPath: "/")
        }
    }

    /// Where Lamp is: on this Mac for a Mac app and for the simulator, and the Mac's name on the local
    /// network for an app on a phone, which Lamp answers on the same Wi‑Fi.
    #if os(iOS) && !targetEnvironment(simulator)
    let lampGateway = "http://\(LampInstall.macHost):\(LampInstall.port)"
    #else
    let lampGateway = "http://127.0.0.1:\(LampInstall.port)"
    #endif

    /// Where the person turns a permission on: System Settings on a Mac, Settings on a phone.
    #if os(macOS)
    let lampSettings = "System Settings"
    #else
    let lampSettings = "Settings"
    #endif

    /// The few things the two platforms' images do differently, named once.
    extension LampImage {
        static func lamp(contentsOf url: URL) -> LampImage? {
            #if os(macOS)
            NSImage(contentsOf: url)
            #else
            UIImage(contentsOfFile: url.path)
            #endif
        }

        /// The pixels, the right way up. A photo from the camera or the library keeps its pixels as the
        /// sensor took them and an orientation to turn them by; the AI and Vision would see it sideways.
        var lampCGImage: CGImage? {
            #if os(macOS)
            cgImage(forProposedRect: nil, context: nil, hints: nil)
            #else
            if imageOrientation == .up, let cgImage { return cgImage }
            let format = UIGraphicsImageRendererFormat()
            format.scale = 1
            return UIGraphicsImageRenderer(size: size, format: format).image { _ in draw(in: CGRect(origin: .zero, size: size)) }.cgImage
            #endif
        }

        var lampPNGData: Data? {
            #if os(macOS)
            tiffRepresentation.flatMap { NSBitmapImageRep(data: $0)?.representation(using: .png, properties: [:]) }
            #else
            pngData()
            #endif
        }

        static func lampJPEG(_ cgImage: CGImage, quality: Double) -> Data? {
            #if os(macOS)
            NSBitmapImageRep(cgImage: cgImage).representation(using: .jpeg, properties: [.compressionFactor: quality])
            #else
            UIImage(cgImage: cgImage).jpegData(compressionQuality: quality)
            #endif
        }
    }

    #if os(macOS)
    // Mac only: the Customize with Lamp command, windows, and what Lamp needs to watch and try the app.

    /// Adds "Customize with Lamp…" (⇧⌘E), which opens this app's chat beside the window in front
    /// (`LampSidebar.openFromMenu`); its button up top opens the same chat in Lamp's own window. And File ▸ Share…,
    /// which sends the app to someone as a file to open with Lamp (`LampShareApp`).
    struct LampCommands: Commands {
        init() {
            LampRuntime.start
            LampWindows.start
            LampWidget.start
            LampMagic.start
            #if LAMP_LIVE
            LampLive.start
            #endif
        }

        var body: some Commands {
            CommandGroup(after: .appInfo) {
                Button("Customize with Lamp…") {
                    LampSidebar.openFromMenu()
                }
                .keyboardShortcut("e", modifiers: [.command, .shift])
            }
            CommandGroup(after: .saveItem) {
                Button("Share…") { LampShareApp.share() }
            }
        }
    }

    /// File ▸ Share…: the app as a file someone else opens with Lamp. Lamp makes it from the app's folder, the same
    /// file as Lamp's own Share…, and the app shows the system's share picker for it from its window, as Apple's apps
    /// do. When Lamp isn't open it's opened, and asked again once it answers.
    @MainActor enum LampShareApp {
        private static var picker: NSSharingServicePicker?

        static func share() {
            Task {
                var answer = await ask()
                if answer == nil, NSRunningApplication.runningApplications(withBundleIdentifier: LampInstall.host).isEmpty,
                   let lamp = NSWorkspace.shared.urlForApplication(withBundleIdentifier: LampInstall.host) {
                    let config = NSWorkspace.OpenConfiguration()
                    config.activates = false
                    _ = try? await NSWorkspace.shared.openApplication(at: lamp, configuration: config)
                    for _ in 0..<40 where answer == nil {
                        try? await Task.sleep(for: .milliseconds(500))
                        answer = await ask()
                    }
                }
                guard let answer, let path = answer["file"] as? String else {
                    let alert = NSAlert()
                    alert.messageText = "This app couldn't be shared"
                    alert.informativeText = "Lamp makes the file to share it. Open Lamp and try again."
                    alert.runModal()
                    return
                }
                let items: [Any] = [answer["note"] as? String, (answer["picture"] as? String).map(URL.init(fileURLWithPath:)),
                                    URL(fileURLWithPath: path)].compactMap { $0 }
                let picker = NSSharingServicePicker(items: items)
                self.picker = picker
                // From the top of the window, where a toolbar's Share button would be: a menu command has no control
                // of its own to open from. With every window closed one is opened again first, as a click in the Dock
                // would; an app with none to open shows the file in Finder, whose Share is the same.
                var window = NSApp.keyWindow ?? NSApp.windows.first { $0.isVisible && $0.canBecomeKey }
                if window == nil {
                    LampWindows.show(relaunching: false)
                    for _ in 0..<20 where window == nil {
                        try? await Task.sleep(for: .milliseconds(100))
                        window = NSApp.keyWindow ?? NSApp.windows.first { $0.isVisible && $0.canBecomeKey }
                    }
                }
                guard let content = window?.contentView else {
                    NSWorkspace.shared.activateFileViewerSelecting([URL(fileURLWithPath: path)])
                    return
                }
                let top = NSRect(x: content.bounds.midX, y: content.isFlipped ? 0 : content.bounds.maxY - 1, width: 1, height: 1)
                picker.show(relativeTo: top, of: content, preferredEdge: content.isFlipped ? .minY : .maxY)
            }
        }

        /// Lamp's answer: where the file and its picture are. Nil when Lamp didn't answer or couldn't make it.
        private static func ask() async -> [String: Any]? {
            guard let url = URL(string: lampGateway + "/app/share") else { return nil }
            var request = URLRequest(url: url, timeoutInterval: 120)
            request.httpMethod = "POST"
            request.setValue("application/json", forHTTPHeaderField: "Content-Type")
            request.setValue("Bearer \(LampInstall.token)", forHTTPHeaderField: "Authorization")
            request.httpBody = Data("{}".utf8)
            guard let (data, response) = try? await URLSession.shared.data(for: request) else { return nil }
            let answer = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any]
            guard (response as? HTTPURLResponse)?.statusCode == 200 else {
                fputs("LampShareApp: \(answer?["error"] as? String ?? "Lamp didn't make the file")\n", stderr)
                return nil
            }
            return answer
        }
    }

    #if LAMP_LIVE
    import Combine
    /// A spare place for a stored property added while the app is open (LiveSlots): live builds give every class of
    /// the app's a few, and every struct one that holds any number by name, empty, so a new property kept in one
    /// leaves the type's layout as the open app has it. Saved data never holds one (it encodes as nothing and
    /// decodes empty), and it compares and hashes by what it holds that can, so a struct's own Equatable and
    /// Hashable still see a new property.
    struct LampSpare: Codable, Hashable, @unchecked Sendable {
        var value: Any?
        init(_ value: Any?) { self.value = value }
        init(from decoder: Decoder) throws { value = nil }
        func encode(to encoder: Encoder) throws {
            var container = encoder.singleValueContainer()
            try container.encodeNil()
        }
        /// Tells an ObservableObject's watchers that a @Published property kept in a spare is changing: a class's
        /// spare places are plain, so a property added without @Published doesn't announce. Asked at run time, so a
        /// @Published property in a class that isn't one still compiles.
        static func announce(_ object: AnyObject) {
            func send<O: ObservableObject>(_ object: O) { (object.objectWillChange as Any as? ObservableObjectPublisher)?.send() }
            if let object = object as? any ObservableObject { send(object) }
        }
        /// The names of properties taken out of the code while the app was open (`LiveSlots.retire`): what they left
        /// in a spare neither reads nor counts.
        nonisolated(unsafe) static var retired = Set<String>()
        /// A struct's property, by name: what was set, kept as set.
        func field(_ name: String) -> Any? { Self.retired.contains(name) ? nil : (value as? [String: Entry])?[name]?.value }
        /// Whether the property was ever set: a value set to nil is a value, told apart from one never set.
        func has(_ name: String) -> Bool { !Self.retired.contains(name) && (value as? [String: Entry])?[name] != nil }
        struct Entry { var value: Any; var initial: Any }
        /// A struct's mirror without its spare, and with what the spare keeps after its own fields: its description
        /// (`print`, `"\(item)"`, `dump`) reads as the app wrote it rather than `Item(__lampSpare_Item: …)`. The copy
        /// step makes each struct with a spare CustomReflectable with this; its fields are read through the runtime's
        /// own calls, which the default mirror is made from, since asking for the mirror here would ask for this one.
        static func mirror<T>(of subject: T) -> Mirror {
            var children: [(label: String?, value: Any)] = [], kept: [(label: String?, value: Any)] = []
            for index in 0..<_lampChildCount(subject, type: T.self) {
                var name: UnsafePointer<CChar>? = nil, free: LampNameFree? = nil
                let value = _lampChild(of: subject, type: T.self, index: index, outName: &name, outFreeFunc: &free)
                let label = name.map { String(cString: $0) }
                free?(name)
                if let label, label.hasPrefix("__lampSpare_") {
                    let entries = ((value as? LampSpare)?.value as? [String: Entry]) ?? [:]
                    // Each is kept by its type's name and its own, with a number when it was brought back
                    // (`Item.badge#2`): shown by its own.
                    kept = entries.keys.sorted().filter { !retired.contains($0) }.map { key in
                        (label: String(key.prefix { $0 != "#" }.split(separator: ".").last ?? Substring(key)), value: entries[key]!.value)
                    }
                } else {
                    children.append((label: label, value: value))
                }
            }
            return Mirror(subject, children: children + kept, displayStyle: .struct)
        }
        /// Keeps what was set beside the property's starting value, which is what a struct that never set it holds:
        /// two values compare and hash by what their properties are, set or not, as they would stored.
        static func setting(_ name: String, to new: Any, initial: Any, in spare: LampSpare) -> LampSpare {
            var entries = (spare.value as? [String: Entry]) ?? [:]
            entries[name] = Entry(value: new, initial: initial)
            return LampSpare(entries)
        }
        private static func same(_ a: Any?, _ b: Any?) -> Bool {
            guard let a, let b else { return a == nil && b == nil }
            guard let equatable = a as? any Equatable else { return false }
            func compare<T: Equatable>(_ x: T) -> Bool { (b as? T) == x }
            return compare(equatable)
        }
        static func == (a: LampSpare, b: LampSpare) -> Bool {
            guard let left = a.value as? [String: Entry] ?? (a.value == nil ? [:] : nil),
                  let right = b.value as? [String: Entry] ?? (b.value == nil ? [:] : nil) else { return same(a.value, b.value) }
            for name in Set(left.keys).union(right.keys).subtracting(retired) {
                let one = left[name]?.value ?? right[name]?.initial, other = right[name]?.value ?? left[name]?.initial
                if !same(one, other) { return false }
            }
            return true
        }
        func hash(into hasher: inout Hasher) {
            guard let entries = value as? [String: Entry] else {
                if let value = value as? AnyHashable { hasher.combine(value) }
                return
            }
            // What equals its starting value hashes as if never set, as it compares.
            for (name, entry) in entries.sorted(by: { $0.key < $1.key }) where !Self.retired.contains(name) && !Self.same(entry.value, entry.initial) {
                hasher.combine(name)
                if let value = entry.value as? AnyHashable { hasher.combine(value) }
            }
        }
    }

    /// The runtime's calls the standard library's own mirrors are made from: a value's fields, read as its type has them.
    @_silgen_name("swift_reflectionMirror_count") func _lampChildCount<T>(_: T, type: Any.Type) -> Int
    typealias LampNameFree = @convention(c) (UnsafePointer<CChar>?) -> Void
    @_silgen_name("swift_reflectionMirror_subscript") func _lampChild<T>(of: T, type: Any.Type, index: Int,
        outName: UnsafeMutablePointer<UnsafePointer<CChar>?>, outFreeFunc: UnsafeMutablePointer<LampNameFree?>) -> Any

    /// A struct's spare is a property it doesn't spell, so saved data leaves it out: nothing is written for it, and
    /// data without it reads as empty. The app's own Codable code, written by the compiler, takes these over the
    /// general ones.
    extension KeyedEncodingContainer {
        mutating func encode(_ value: LampSpare, forKey key: Key) throws {}
    }
    extension KeyedDecodingContainer {
        func decode(_ type: LampSpare.Type, forKey key: Key) throws -> LampSpare { LampSpare(nil) }
    }

    /// A constant (a static or global `let`) whose value changed while the app is open (LiveSlots): the open app
    /// keeps the value it made at first, so the live copy reads it from here instead, made once for each value it's
    /// been given (`key` names the value too).
    enum LampConstants {
        private static var values: [String: Any] = [:]
        private static var making: [String: NSRecursiveLock] = [:]
        private static let lock = NSLock()
        /// Each value is made once, as Swift makes a constant: a second reader waits for the first to finish. One
        /// constant's value may read another's while it's made.
        static func value<T>(_ key: String, _ make: () -> T) -> T {
            lock.lock()
            if let value = values[key] as? T { lock.unlock(); return value }
            let own = making[key] ?? NSRecursiveLock()
            making[key] = own
            lock.unlock()
            own.lock()
            defer { own.unlock() }
            lock.lock()
            if let value = values[key] as? T { lock.unlock(); return value }
            lock.unlock()
            let value = make()
            lock.lock()
            values[key] = value
            lock.unlock()
            return value
        }
    }

    /// A view's spare state (LiveSlots): `@State` added to a view while the app is open is kept here by name, so the
    /// view holds what it did. A starting value is worked out on the first read and kept without redrawing anything;
    /// a change redraws the views that read any of it.
    @Observable final class LampStateBox: @unchecked Sendable {
        @ObservationIgnored private var values: [String: Any] = [:]
        private var changes = 0
        func get<T>(_ name: String, _ initial: () -> T) -> T {
            _ = changes
            if let stored = values[name] {
                if let value = stored as? T { return value }
                // An optional set to nil is kept boxed, which doesn't cast: it was set, to nil.
                if let kind = T.self as? ExpressibleByNilLiteral.Type { return kind.init(nilLiteral: ()) as! T }
            }
            let value = initial()
            values[name] = value
            return value
        }
        func set<T>(_ name: String, _ value: T) {
            values[name] = value
            changes += 1
        }

        /// A view's `@AppStorage` added while the app is open: read from and written to the defaults as AppStorage
        /// does, and the views that read it drawn again when it changes, whether here or anywhere else in the app.
        @ObservationIgnored private var seen: [String: NSObject] = [:]
        @ObservationIgnored private var observer: NSObjectProtocol?
        private var stored = 0
        private func watch(_ key: String) {
            _ = stored
            if observer == nil {
                observer = NotificationCenter.default.addObserver(forName: UserDefaults.didChangeNotification, object: UserDefaults.standard,
                                                                  queue: .main) { [weak self] _ in self?.recheck() }
            }
            if seen.index(forKey: key) == nil { seen[key] = UserDefaults.standard.object(forKey: key) as? NSObject ?? NSNull() }
        }
        private func recheck() {
            var changed = false
            for (key, before) in seen {
                let now = UserDefaults.standard.object(forKey: key) as? NSObject ?? NSNull()
                if !now.isEqual(before) { seen[key] = now; changed = true }
            }
            if changed { stored += 1 }
        }
        deinit { if let observer { NotificationCenter.default.removeObserver(observer) } }
        func defaults<T>(_ key: String, _ initial: T) -> T {
            watch(key)
            return UserDefaults.standard.object(forKey: key) as? T ?? initial
        }
        func defaults<T: RawRepresentable>(_ key: String, _ initial: T) -> T {
            watch(key)
            return (UserDefaults.standard.object(forKey: key) as? T.RawValue).flatMap(T.init(rawValue:)) ?? initial
        }
        func defaults<T: RawRepresentable>(_ key: String, _ initial: T?) -> T? {
            watch(key)
            return (UserDefaults.standard.object(forKey: key) as? T.RawValue).flatMap(T.init(rawValue:)) ?? initial
        }
        func defaults(_ key: String, _ initial: URL) -> URL { watch(key); return UserDefaults.standard.url(forKey: key) ?? initial }
        func defaults(_ key: String, _ initial: URL?) -> URL? { watch(key); return UserDefaults.standard.url(forKey: key) ?? initial }
        func setDefaults<T>(_ key: String, _ value: T) { UserDefaults.standard.set(Self.unwrapped(value), forKey: key); defaultsSet(key) }
        func setDefaults<T: RawRepresentable>(_ key: String, _ value: T) { UserDefaults.standard.set(value.rawValue, forKey: key); defaultsSet(key) }
        func setDefaults<T: RawRepresentable>(_ key: String, _ value: T?) { UserDefaults.standard.set(value?.rawValue, forKey: key); defaultsSet(key) }
        func setDefaults(_ key: String, _ value: URL?) { UserDefaults.standard.set(value, forKey: key); defaultsSet(key) }
        private func defaultsSet(_ key: String) {
            seen[key] = UserDefaults.standard.object(forKey: key) as? NSObject ?? NSNull()
            stored += 1
        }
        /// An optional's value, or nil, which the defaults take as taking the key away (an optional boxed as Any isn't nil).
        private static func unwrapped(_ value: Any) -> Any? {
            let mirror = Mirror(reflecting: value)
            guard mirror.displayStyle == .optional else { return value }
            return mirror.children.first.flatMap { unwrapped($0.value) }
        }
    }

    /// Changes made while the app is open, put into it without a restart (live builds only: debug, linked
    /// -interposable, from Lamp's copy of the sources with each view's body wrapped). Lamp compiles the files a
    /// change touched into a library in `.lamp/live`; asked with the app's token, this loads it and points the
    /// app's calls to its own functions at the new ones. Data, types and objects stay as they are, so what's on
    /// screen keeps its state, and every view draws again through `generation`, which each wrapped body reads.
    @MainActor @Observable final class LampLive {
        static let shared = LampLive()
        var generation = 0
        static var generation: Int { shared.generation }
        /// Read by what SwiftUI keeps besides a body (the copy step adds it), on the main thread where SwiftUI asks.
        nonisolated static func touch() { if Thread.isMainThread { MainActor.assumeIsolated { _ = shared.generation } } }
        /// The same around a value made by one expression, where a statement before it would stop it being returned.
        nonisolated static func touched<T>(_ make: () -> T) -> T { touch(); return make() }

        static let start: Void = {
            DistributedNotificationCenter.default().addObserver(
                forName: Notification.Name(LampInstall.note + "reload"), object: Bundle.main.bundleIdentifier, queue: .main
            ) { note in
                let path = note.userInfo?["path"] as? String, signature = note.userInfo?["signature"] as? String
                let whole = note.userInfo?["whole"] as? String == "1"
                let retired = (note.userInfo?["retired"] as? String ?? "").split(separator: ",").map(String.init)
                let until = note.userInfo?["until"] as? String ?? ""
                MainActor.assumeIsolated { shared.load(path, signature: signature, whole: whole, retired: retired, until: until) }
            }
            // A change of the app's files alone (a picture in Assets, read from the app's folder in a live build) has no
            // code to load: the views draw again, and read the new file.
            DistributedNotificationCenter.default().addObserver(
                forName: Notification.Name(LampInstall.note + "redraw"), object: Bundle.main.bundleIdentifier, queue: .main
            ) { note in
                let at = note.userInfo?["at"] as? String, signature = note.userInfo?["signature"] as? String
                MainActor.assumeIsolated { shared.redraw(at: at, signature: signature) }
            }
        }()

        private func redraw(at: String?, signature: String?) {
            guard let at, let signature, let time = Double(at), abs(Date().timeIntervalSince1970 - time) < 30 else { return }
            let key = SymmetricKey(data: Data(LampInstall.token.utf8))
            let expected = HMAC<SHA256>.authenticationCode(for: Data(("redraw\n" + at).utf8), using: key).map { String(format: "%02x", $0) }.joined()
            guard signature == expected else { return }
            generation += 1
        }

        private var loaded: Set<String> = []
        /// Every replacement so far, by name, and the images whose calls go through pointers: the app and each
        /// library loaded before. A later change has to reach calls made from an earlier change's code too, and
        /// a library's calls to functions it doesn't hold were bound to the app's first copies.
        private var latest: [String: UnsafeRawPointer] = [:]
        private var images: [String] = []
        /// The accessors of each stored global and static, and each class's metadata, by name, from the image that
        /// first had it.
        private var kept: [String: UnsafeRawPointer] = [:]
        /// What the app itself defines, by name, its private names included.
        private var original: [String: UnsafeRawPointer] = [:]
        /// Every version of each changed function so far, from the app's on: a method table made after a change
        /// from the app's description holds the app's code, and is pointed at the newest.
        private var versions: [String: [UnsafeRawPointer]] = [:]
        /// The order each class lists its methods in, by the class, as the app or the change that first brought
        /// the class had it: what a table made as the app runs is laid out from.
        private var orders: [String: [String]] = [:]
        /// What `classMade` and `tableMade` read on whatever thread makes a class or asks for a table, so kept
        /// under a lock rather than on the main actor: the classes Swift has made as the app ran, from its launch
        /// on; the newest code for every version of each changed function; and the descriptions of the app's and
        /// the changes' classes. The lock can be taken again by the thread holding it: a generic call made under
        /// it may ask the runtime for a witness table or a class, which comes back through a hook.
        nonisolated private static let lock = NSRecursiveLock()
        nonisolated(unsafe) private static var made: [UnsafeRawPointer] = []
        nonisolated(unsafe) private static var newest: [UnsafeRawPointer: UnsafeRawPointer] = [:]
        nonisolated(unsafe) private static var descriptions = Set<UnsafeRawPointer>()
        /// The conformances of the app's and the changes' types, and the witness tables the runtime has made for
        /// a generic type's conformance at each type it's used at (`tablesMade`, through `tableMade`), since the
        /// launch: like a class made as the app runs, such a table is copied from the app's pattern.
        nonisolated(unsafe) private static var conformances = Set<UnsafeRawPointer>()
        nonisolated(unsafe) private static var tablesMade: [UnsafeRawPointer] = []
        nonisolated(unsafe) private static var tablesSeen = Set<UnsafeRawPointer>()

        /// The suffix Lamp renames a library's own copy of a type's metadata or descriptor with (`LiveObject`): its
        /// code asks for the one under the original name, which is bound here to the app's. With the other suffix
        /// the library's copy is the one to bind from now on (an enum that gained cases, which the app's doesn't know).
        nonisolated private static let copySuffix = "$lampcopy", ownSuffix = "$lampown"

        /// The library's copies of types, by the names they were defined under, with whether each is its own to keep.
        private static func copies(in symbols: [(String, UnsafeRawPointer)]) -> [(name: String, address: UnsafeRawPointer, own: Bool)] {
            symbols.compactMap {
                if $0.0.hasSuffix(copySuffix) { return (String($0.0.dropLast(copySuffix.count)), $0.1, false) }
                if $0.0.hasSuffix(ownSuffix) { return (String($0.0.dropLast(ownSuffix.count)), $0.1, true) }
                return nil
            }
        }

        private func keep(_ symbols: [(String, UnsafeRawPointer)]) {
            for (name, address) in symbols where kept[name] == nil && (name.hasSuffix("vau") || Self.isClass(name)) {
                kept[name] = address
            }
        }

        /// A call to a class's method that can be overridden goes through the method table in the class's
        /// metadata, which holds each method's code itself, not a pointer `rebind` reaches. The classes are kept
        /// (`isClass`), so their tables are pointed at the changed methods here, for the objects the app made and
        /// those the new code makes alike. A table runs from the metadata's description to its end, which the
        /// metadata gives (its size, and where its address point is in it).
        nonisolated private static func redirectMethods(of classes: [UnsafeRawPointer], _ moved: [UnsafeRawPointer: UnsafeRawPointer]) -> Int {
            guard !moved.isEmpty else { return 0 }
            let page = Int(vm_page_size)
            var count = 0
            for metadata in classes {
                let size = Int(metadata.load(fromByteOffset: 56, as: UInt32.self))
                let point = Int(metadata.load(fromByteOffset: 60, as: UInt32.self))
                guard size < 1 << 20, point <= size, size - point > 72, point >= 16 else { continue }
                let words = UnsafeMutablePointer<UnsafeRawPointer?>(mutating: metadata.assumingMemoryBound(to: UnsafeRawPointer?.self))
                // Two words before the metadata is the class's deinit, which the runtime calls when an object goes.
                for index in [-2] + Array(9..<((size - point) / 8)) {
                    guard let code = words[index], let new = moved[code] else { continue }
                    let start = UInt(bitPattern: words.advanced(by: index)) & ~UInt(page - 1)
                    mprotect(UnsafeMutableRawPointer(bitPattern: start), page, PROT_READ | PROT_WRITE)
                    words[index] = new
                    count += 1
                }
            }
            return count
        }

        /// Why a class the change has (`defined`, its copies under their original names) can't take its changed
        /// methods into the table of the copy that's kept, if it can't: the two tables differ in size, or a slot
        /// holds a different method in each.
        private static func reshapedMethods(_ defined: [(String, UnsafeRawPointer)], against kept: [String: UnsafeRawPointer]) -> String? {
            var names: [UnsafeRawPointer: String] = [:]
            // The app's and the libraries' names, since an earlier change's method may be in a table now.
            for image in 0..<_dyld_image_count() where image == 0 || String(cString: _dyld_get_image_name(image)).contains("/.lamp/live/") {
                guard let header = _dyld_get_image_header(image) else { continue }
                for (name, address) in definedSymbols(header, slide: _dyld_get_image_vmaddr_slide(image)) where isCode(name) { names[address] = name }
            }
            func table(_ metadata: UnsafeRawPointer) -> [UnsafeRawPointer?]? {
                let size = Int(metadata.load(fromByteOffset: 56, as: UInt32.self))
                let point = Int(metadata.load(fromByteOffset: 60, as: UInt32.self))
                guard size < 1 << 20, point <= size, size - point > 72 else { return nil }
                let words = metadata.assumingMemoryBound(to: UnsafeRawPointer?.self)
                return (9..<((size - point) / 8)).map { words[$0] }
            }
            for (name, mine) in defined where name.hasSuffix("CN") {
                guard let theirs = kept[name], theirs != mine else { continue }
                let class_ = String(name.dropLast(1))
                guard let old = table(theirs), let new = table(mine) else { continue }
                guard old.count == new.count else { return "the methods of \(readable(class_)) changed" }
                for (a, b) in zip(old, new) {
                    guard let a, let b, let before = names[a], let after = names[b] else { continue }
                    if before != after { return "the methods of \(readable(class_)) changed" }
                }
            }
            return nil
        }

        /// A class's metadata and what finds it. The library has its own copy of each class in the files it was
        /// compiled from, and code asking for the class there would get that one: an object the app made is then
        /// not of its type, and what's looked up by type (an environment object, a cast) isn't found. So the new
        /// code is pointed at the app's, whose layout the change kept (a new stored property has its own slot).
        /// A struct's or an enum's stays the library's: an enum may have gained cases.
        private static func isClass(_ name: String) -> Bool {
            name.hasPrefix("_$s") && ["CMa", "CN", "CMn", "CMm", "CMf", "CMo"].contains { name.hasSuffix($0) }
        }

        /// Loads a change. `whole` says every file of the app's was compiled into it (what's declared changed), so
        /// what it doesn't define of a class's Objective-C methods was taken away, not left in a file it didn't compile.
        private func load(_ path: String?, signature: String?, whole: Bool = false, retired: [String] = [], until: String = "") {
            let folder = LampInstall.app + "/.lamp/live/"
            guard let path, let signature, path.hasPrefix(folder), !path.contains(".."), path.hasSuffix(".dylib"),
                  !loaded.contains(path) else { return }
            let key = SymmetricKey(data: Data(LampInstall.token.utf8))
            let expected = HMAC<SHA256>.authenticationCode(for: Data(("reload\n\(path)" + (whole ? "\nwhole" : "") + (retired.isEmpty ? "" : "\nretired " + retired.joined(separator: ","))
                + (until.isEmpty ? "" : "\nuntil " + until)).utf8), using: key).map { String(format: "%02x", $0) }.joined()
            guard signature == expected else { return }
            loaded.insert(path)
            var result = "failed"
            defer {
                try? (result + "\n" + path).write(to: LampRuntime.folder.appendingPathComponent("reloaded.txt"), atomically: true, encoding: .utf8)
            }
            // Lamp waits only so long for the answer and then treats the change as not in: one that reaches the app
            // after that (the app busy, the notification late) must stay out, or the app would run code Lamp doesn't
            // know it has.
            if let deadline = Double(until), Date().timeIntervalSince1970 > deadline {
                result = "failed: the change reached the app too late to go in"
                return
            }
            guard dlopen(path, RTLD_NOW) != nil else {
                result = "failed: the change couldn't be loaded (\(String(cString: dlerror()).prefix(200)))"
                return
            }
            // The loader names the image by its real path, which may differ from the one asked for by a link.
            let real = realpath(path, nil).map { String(cString: $0) } ?? path
            guard let image = (0..<_dyld_image_count()).first(where: { [path, real].contains(String(cString: _dyld_get_image_name($0))) }),
                  let header = _dyld_get_image_header(image) else { return }
            let slide = _dyld_get_image_vmaddr_slide(image)
            Self.takeFieldOffsets(header, slide: slide, earlier: images)
            let defined = Self.definedSymbols(header, slide: slide)
            let everything = Self.definedSymbols(header, slide: slide, local: true)
            let all = Self.copies(in: everything)
            let copies = all.map { ($0.name, $0.address) }
            // The change's categories (an extension with `@objc` members, an override in one): the runtime doesn't
            // see them, since their list was renamed before linking, so a change refused leaves the kept class
            // answering as it did; they're attached by hand once the checks pass.
            let categories = Self.categories(header)
            if original.isEmpty, let app = _dyld_get_image_header(0) {
                let everything = Self.definedSymbols(app, slide: _dyld_get_image_vmaddr_slide(0), local: true)
                original = Dictionary(everything, uniquingKeysWith: { first, _ in first })
                orders = Self.methodOrder(everything)
                keep(Self.definedSymbols(app, slide: _dyld_get_image_vmaddr_slide(0)))
            }
            // A change refused leaves what's known of the app as it was, for the changes after it.
            let (keptBefore, latestBefore) = (kept, latest)
            func refuse(_ why: String) { (kept, latest) = (keptBefore, latestBefore); result = "failed: \(why)" }
            // The types the change defines over again are the app's, or an earlier change's that first brought
            // one, and only a new type's is the library's own: so there's one of each type however many changes
            // have gone in, and a value made before a change is still of its type after it. One the change brings
            // as its own (an enum that gained cases) has the library's descriptor and conformances from now on, but its
            // metadata stays the app's, made to describe the new cases below: one identity, so a value boxed before the
            // change (in `Any`, an `AnyHashable`, SwiftUI's tags) still casts to it.
            func isMetadata(_ name: String) -> Bool { name.hasSuffix("ON") || name.hasSuffix("OMf") }
            // The metadata an enum already has is the app's, or that of the earlier change that first brought it.
            for copy in all where kept[copy.name] == nil || copy.own {
                let first = keptBefore[copy.name] ?? original[copy.name]
                kept[copy.name] = copy.own && !(isMetadata(copy.name) && first != nil) ? copy.address : first ?? copy.address
            }
            // A kept class's method table is the app's, so the new code's has to have the same shape: a method added,
            // taken away or moved would put a call in another method's place. Such a change reopens the app.
            if let why = Self.reshapedMethods(defined + copies, against: kept) { return refuse(why) }
            // Each changed function's code before this change, for the class method tables that still hold it.
            var moved: [UnsafeRawPointer: UnsafeRawPointer] = [:], code: [(String, UnsafeRawPointer)] = []
            // Every symbol, not only the exported ones: a protocol witness (the thunk a witness table holds, or for an
            // async one the record of the thunk) is private to its file, and so are the methods of a private class and
            // a private override, whose places in a method table move to the new code too.
            for (name, address) in everything where Self.isCode(name) {
                if let before = latest[name] ?? original[name] { moved[before] = address }
                latest[name] = address
                code.append((name, address))
            }
            // A class whose metadata is made as the app runs (a generic one at each type it's used at, a class under
            // a generic superclass) gets its table from the description that first brought the class, in the order
            // its methods are listed there: the change's have to be listed the same, or its calls would land in
            // other methods' places.
            let listed = Self.methodOrder(everything)
            for (class_, methods) in listed {
                guard let before = orders[class_], before != methods else { continue }
                return refuse("the methods of \(Self.readable(String(class_.dropLast(2)))) changed")
            }
            // Started without Lamp's entry (an App declared in a shape the copy step didn't know), nothing records
            // the classes made as the app runs, so a change to the methods of one reopens the app as before.
            if !Self.watching, let why = Self.unwatchedClassMethod(changed: Set(defined.map(\.0)), copies: copies) { return refuse(why) }
            // A class the change has may no longer answer to something from Objective-C that the kept class does (an
            // override taken out, a selector's target); the kept class would go on answering with old code. Only a
            // change compiled from every file can say: another leaves what an unchanged file's extension adds.
            if whole, let why = Self.removedMethods(copies: copies, kept: kept, original: original, categories: categories) { return refuse(why) }
            // Stored globals and statics, and classes, stay where they were first made: the new code's own copies
            // would be a second set, made afresh. So its calls to them go to the app's, or to the earlier change's
            // that first added one, and only one that's new keeps its own. Their accessors are code like any other:
            // they reach the storage through the kept addressor, so a `didSet` added to one goes in.
            keep(defined)
            // What the library's data names is worked out, and found possible, before anything is pointed at the
            // new code: a change refused leaves the app as it was.
            guard let descriptors = Self.plannedDescriptors(header, copies: copies, kept: kept) else {
                return refuse("the change's types couldn't all be made the app's")
            }
            // The library's data is pointed at the app's types before any call is pointed at its code: each write
            // opens and closes a page of the library for writing, and a thread already running the new code on that
            // page would stop there.
            var rebound = 0
            for write in descriptors where write.apply() { rebound += 1 }
            let bindings = latest.merging(kept) { new, _ in new }
            images.append(String(cString: _dyld_get_image_name(image)))
            // The libraries first, this one included, so its references to the types it brings are bound before its
            // new classes are worked out, and both before the app's calls reach its code.
            for index in images.compactMap(Self.imageIndex) { rebound += Self.rebind(image: index, to: bindings) }
            Self.takeFieldOffsets(header, slide: slide, earlier: images, ownClasses: true)
            rebound += Self.rebind(image: 0, to: latest)
            orders.merge(listed) { first, _ in first }
            Self.lock.lock()
            // Every version of each function, the app's included, so a table made from any description that ever
            // held one is pointed at the newest: a function born in a change has its first version too.
            for (name, address) in code {
                var history = versions[name] ?? [original[name]].compactMap { $0 }
                if !history.contains(address) { history.append(address) }
                versions[name] = history
                for earlier in history where earlier != address { Self.newest[earlier] = address }
            }
            Self.descriptions = Self.allDescriptions
            let classes = Self.classes(kept.filter { $0.key.hasSuffix("CN") }.map(\.value))
            Self.lock.unlock()
            // Only now, outside the lock: listing the runtime's classes can make a class, which takes the lock.
            rebound += Self.redirectMethods(of: classes + Self.dynamicSubclasses(of: classes), Self.newest)
            // A kept witness table holds the app's thunks; one compiled when a requirement was answered by the
            // protocol's own default goes on calling it after the change answers it in the type. So the tables are
            // pointed at the new thunks: the app's and the earlier changes' (`WP`), and those the runtime made
            // from them for a generic type (`tablesMade`).
            Self.lock.lock()
            Self.conformances = Self.allConformances
            Self.lock.unlock()
            Self.recordTables(of: all.filter { $0.name.hasSuffix("Mc") && kept[$0.name] == $0.address }.map(\.address))
            Self.lock.lock()
            let tables = Self.tablesMade
            Self.lock.unlock()
            rebound += Self.redirectWitnesses(of: kept.filter { $0.key.hasSuffix("WP") }.map(\.value) + tables, Self.newest)
            // What a class answers to from Objective-C (an override of a system class's method, a selector's
            // target) is in its method list, not its table: the kept class takes the change's copy's.
            for (name, copy) in copies where name.hasSuffix("CN") {
                if let theirs = kept[name], theirs != copy {
                    rebound += Self.takeMethods(from: copy, to: theirs, accessor: original[String(name.dropLast()) + "Ma"])
                }
            }
            // The change's categories go to the kept classes: one on a class the change defines names the copy.
            let keptClass = Self.keptClasses(copies: copies, kept: kept)
            for category in categories {
                let target = keptClass[category.class_] ?? category.class_
                rebound += Self.attach(category, to: target, accessor: Self.accessor(of: target, original: original, defined: defined))
            }
            // An enum that gained cases keeps the app's metadata, which every value of it made before carries and the
            // change's code is bound to: it's pointed at the change's description, which knows the new cases, and at the
            // change's value witness table (the word before it), which knows how many there are, so a tag past the old
            // last case is read as the case it is.
            for copy in all where copy.own && copy.name.hasSuffix("ON") {
                guard let old = keptBefore[copy.name] ?? original[copy.name], old != copy.address else { continue }
                let description = copy.address.load(fromByteOffset: 8, as: UnsafeRawPointer.self)
                let witnesses = copy.address.load(fromByteOffset: -8, as: UnsafeRawPointer.self)
                if DescriptorWrite(field: old.advanced(by: 8), pointer: description).apply() { rebound += 1 }
                if DescriptorWrite(field: old.advanced(by: -8), pointer: witnesses).apply() { rebound += 1 }
            }
            // A struct's property taken out of the code leaves its value in the spare, which would go on counting in
            // `==` and `hash`: the names retired are set aside.
            LampSpare.retired.formUnion(retired)
            Self.watch(image: image)
            generation += 1
            // With the library it answers, so an answer to an earlier request is never read as this one's.
            result = "ok \(rebound)"
        }

        /// A change to the library's data: a relative pointer given a new offset, or a slot a new pointer.
        @MainActor private struct DescriptorWrite {
            var field: UnsafeRawPointer
            var relative: Int32?
            var pointer: UnsafeRawPointer?
            /// The field's page is opened for the moment; a slot's is in data and stays open, as the symbol pointers'
            /// pages do, while the library's text is given back as it was, executable.
            func apply() -> Bool {
                if let pointer { return write(pointer, to: field, executable: false) }
                return write(relative ?? 0, to: field, executable: true)
            }
        }

        /// The library's own copies of the app's types are what its data still names: the mangled type names its
        /// code resolves at run time (a view's body, `[Mood]`, `any Shape`) and its conformance records refer to the
        /// copies' descriptors by relative pointers, which no symbol reaches. Pointed at the kept descriptors
        /// (`DescriptorWrite`), so an existential of the app's protocol, a conformance the change adds, and every
        /// generic type made from a mangled name are the app's. The sections sit in the library's text. Nil when a
        /// reference can't be pointed over (the app's descriptor is out of a relative pointer's reach, or a page can't
        /// be opened): the change is then refused, before anything else has changed, rather than left naming two of
        /// a type.
        private static func plannedDescriptors(_ header: UnsafePointer<mach_header>, copies: [(String, UnsafeRawPointer)],
                                               kept: [String: UnsafeRawPointer]) -> [DescriptorWrite]? {
            var replacements: [UnsafeRawPointer: UnsafeRawPointer] = [:]
            for (name, address) in copies where name.hasSuffix("Mn") || name.hasSuffix("Mp") {
                if let theirs = kept[name], theirs != address { replacements[address] = theirs }
            }
            guard !replacements.isEmpty else { return [] }
            let header64 = UnsafeRawPointer(header).assumingMemoryBound(to: mach_header_64.self)
            var writes: [DescriptorWrite] = [], failed = false
            // A relative pointer to a descriptor, made to point at the kept one when it points at a copy; one through
            // a slot (`indirect`, or the low bit set where the pointer may say so itself, `flagged`) has the slot's
            // pointer changed instead.
            func redirect(_ field: UnsafeRawPointer, indirect: Bool = false, flagged: Bool = false) {
                let value = field.loadUnaligned(as: Int32.self)
                if indirect || (flagged && value & 1 != 0) {
                    let slot = field.advanced(by: Int(value & ~1))
                    guard let pointer = slot.loadUnaligned(as: UnsafeRawPointer?.self), let theirs = replacements[pointer] else { return }
                    if canWrite(slot) { writes.append(DescriptorWrite(field: slot, pointer: theirs)) } else { failed = true }
                } else {
                    guard let theirs = replacements[field.advanced(by: Int(value))] else { return }
                    let distance = Int(bitPattern: theirs) - Int(bitPattern: field)
                    guard let relative = Int32(exactly: distance), canWrite(field) else { return failed = true }
                    writes.append(DescriptorWrite(field: field, relative: relative))
                }
            }
            var size: UInt = 0
            if let names = getsectiondata(header64, "__TEXT", "__swift5_typeref", &size) {
                // Mangled names, each ended by a zero byte. A control byte in one is a symbolic reference: up to 0x17
                // it carries a relative pointer, 0x01 to a descriptor and 0x02 to a slot holding one; above, an
                // absolute pointer, passed over.
                var at = 0
                while at < Int(size) {
                    let byte = names[at]
                    if byte == 0 || byte >= 0x20 { at += 1; continue }
                    if byte >= 0x18 { at += 9; continue }
                    if byte == 1 || byte == 2 { redirect(UnsafeRawPointer(names.advanced(by: at + 1)), indirect: byte == 2) }
                    at += 5
                }
            }
            // A conformance the app has already is found through its own record; the library's copy is left naming
            // the copies, which nothing asks about. One the change adds is made to name the kept descriptors.
            let known = Set(copies.filter { $0.0.hasSuffix("Mc") && kept[$0.0] != $0.1 }.map(\.1))
            if let records = getsectiondata(header64, "__TEXT", "__swift5_proto", &size) {
                for index in 0..<(Int(size) / 4) {
                    let entry = UnsafeRawPointer(records.advanced(by: index * 4))
                    let descriptor = entry.advanced(by: Int(entry.loadUnaligned(as: Int32.self)))
                    guard !known.contains(descriptor) else { continue }
                    redirect(descriptor, flagged: true)
                    // The type it's for: a descriptor, directly (0) or through a slot (1); the others name a class.
                    switch (descriptor.loadUnaligned(fromByteOffset: 12, as: UInt32.self) >> 3) & 0x7 {
                    case 0: redirect(descriptor.advanced(by: 4))
                    case 1: redirect(descriptor.advanced(by: 4), indirect: true)
                    default: break
                    }
                }
            }
            return failed ? nil : writes
        }

        /// Whether the page holding `pointer` can be opened for writing: tried, and given back as it was.
        private static func canWrite(_ pointer: UnsafeRawPointer) -> Bool {
            let page = Int(vm_page_size)
            let start = UnsafeMutableRawPointer(bitPattern: UInt(bitPattern: pointer) & ~UInt(page - 1))
            guard mprotect(start, page, PROT_READ | PROT_WRITE) == 0 else { return false }
            mprotect(start, page, PROT_READ | PROT_EXEC)
            return true
        }

        /// Stores a value in memory that may be read-only, opening its page for the moment: the library's text is
        /// given back as it was, executable. False when the page can't be opened.
        nonisolated private static func write<T>(_ value: T, to pointer: UnsafeRawPointer, executable: Bool) -> Bool {
            let page = Int(vm_page_size)
            let start = UnsafeMutableRawPointer(bitPattern: UInt(bitPattern: pointer) & ~UInt(page - 1))
            let length = Int(UInt(bitPattern: pointer) + UInt(MemoryLayout<T>.size) - 1 - (UInt(bitPattern: pointer) & ~UInt(page - 1))) / page * page + page
            guard mprotect(start, length, PROT_READ | PROT_WRITE) == 0 else { return false }
            UnsafeMutableRawPointer(mutating: pointer).storeBytes(of: value, as: T.self)
            if executable { mprotect(start, length, PROT_READ | PROT_EXEC) }
            return true
        }

        /// The loaded image with this path, by its index now.
        nonisolated private static func imageIndex(_ path: String) -> UInt32? {
            (0..<_dyld_image_count()).first { String(cString: _dyld_get_image_name($0)) == path }
        }

        /// Whether a class's metadata is one Swift made from a description in the app or a change: a Swift class
        /// says so in the low bits of its data word, and its description is then at the end of its header.
        nonisolated private static func isOwnClass(_ metadata: UnsafeRawPointer, _ descriptions: Set<UnsafeRawPointer>) -> Bool {
            guard metadata.load(fromByteOffset: 32, as: UInt.self) & 2 != 0,
                  let description = metadata.load(fromByteOffset: 64, as: UnsafeRawPointer?.self) else { return false }
            return descriptions.contains(description)
        }

        /// The descriptions of every class in the app and the changes, where a class made as the app runs points.
        nonisolated private static var allDescriptions: Set<UnsafeRawPointer> {
            var all = Set<UnsafeRawPointer>()
            for image in 0..<_dyld_image_count() where image == 0 || String(cString: _dyld_get_image_name(image)).contains("/.lamp/live/") {
                guard let header = _dyld_get_image_header(image) else { continue }
                // A change's are renamed as copies, or as its own (`LiveObject`); a class born in a change is its own.
                for (name, address) in definedSymbols(header, slide: _dyld_get_image_vmaddr_slide(image), local: true)
                where name.hasSuffix("CMn") || name.hasSuffix("CMn" + copySuffix) || name.hasSuffix("CMn" + ownSuffix) {
                    all.insert(address)
                }
            }
            return all
        }

        /// The kept classes' metadata and every class Swift has made since the launch (`made`): nothing of the
        /// app's makes one before its entry runs. Called with the lock held.
        nonisolated private static func classes(_ kept: [UnsafeRawPointer]) -> [UnsafeRawPointer] {
            var all = kept, seen = Set(kept)
            for metadata in made where seen.insert(metadata).inserted { all.append(metadata) }
            return all
        }

        /// The classes the Objective-C runtime has made under the app's (key-value observing makes one for each
        /// class it observes, with a copy of its method table as it was then), by their superclass chain. Listed
        /// without realizing every class in the process, and never as classes, which would send them messages.
        nonisolated private static func dynamicSubclasses(of classes: [UnsafeRawPointer]) -> [UnsafeRawPointer] {
            let own = Set(classes)
            var found: [UnsafeRawPointer] = []
            for class_ in objc_enumerateClasses(fromImage: .dynamicClasses) {
                let metadata = unsafeBitCast(class_, to: UnsafeRawPointer.self)
                var above = metadata.load(fromByteOffset: 8, as: UnsafeRawPointer?.self)
                var depth = 0
                while let superclass = above, depth < 64 {
                    if own.contains(superclass) { found.append(metadata); break }
                    above = superclass.load(fromByteOffset: 8, as: UnsafeRawPointer?.self)
                    depth += 1
                }
            }
            return found
        }

        /// A class Swift makes as the app runs (a generic class at each type it's used at, a class under a generic
        /// superclass) gets its method table from its description, which holds the app's code. So the runtime's
        /// call that fills such a table in is pointed, in the app from its launch (`LampLive.watch()`, from the
        /// entry the live copy adds before the App's own) and in each change as it loads, at `classMade`, which
        /// lets it fill the table and then points the table at the newest code. The pointer the runtime's function
        /// is called through is the one `rebind` reaches, as any function's; once pointed over it stays so.
        nonisolated(unsafe) private static var watching = false
        nonisolated static func watch(image: UInt32 = 0) {
            guard initClassMetadata != nil, getWitnessTable != nil else { return }
            lock.lock()
            if image == 0 { (descriptions, conformances, watching) = (allDescriptions, allConformances, true) }
            lock.unlock()
            if image != 0, let header = _dyld_get_image_header(image) { noteGetters(header, slide: _dyld_get_image_vmaddr_slide(image)) }
            var hooks = ["_swift_initClassMetadata2": unsafeBitCast(classMade, to: UnsafeRawPointer.self),
                         "_swift_getWitnessTable": unsafeBitCast(tableMade, to: UnsafeRawPointer.self)]
            if getKeyPath != nil { hooks["_swift_getKeyPath"] = unsafeBitCast(keyPathMade, to: UnsafeRawPointer.self) }
            _ = rebind(image: image, to: hooks)
            if image == 0, let header = _dyld_get_image_header(0) {
                recordTables(of: definedSymbols(header, slide: _dyld_get_image_vmaddr_slide(0), local: true).filter { $0.0.hasSuffix("Mc") }.map(\.1))
            }
        }

        /// A witness table the runtime makes for a conformance that has none of its own in the image (one to a
        /// protocol of the system's that may change between releases: Comparable, Hashable, Codable) is made the
        /// first time something asks, which may be a cast (`as? any Comparable`) rather than a request through the
        /// hook. So at launch, and for the conformances a change brings, the table of each such conformance of a
        /// type that isn't generic is asked for here and recorded as `tableMade` records the rest; a generic type's
        /// are made at each type it's used at, which only a request names.
        nonisolated private static func recordTables(of conformances: [UnsafeRawPointer]) {
            guard let get = getWitnessTable else { return }
            typealias Call = @convention(thin) (UnsafeRawPointer, UnsafeRawPointer?, UnsafeRawPointer?) -> UnsafeRawPointer?
            for conformance in conformances {
                // The protocol first: one the app only has on a later system (a conformance under `@available`) is a
                // slot the loader left empty, and asking for a table through it would crash before any check of
                // the system's version could run.
                let toProtocol = conformance.loadUnaligned(as: Int32.self)
                if toProtocol & 1 != 0 {
                    guard conformance.advanced(by: Int(toProtocol & ~1)).load(as: UnsafeRawPointer?.self) != nil else { continue }
                } else if toProtocol == 0 { continue }
                // The type: its descriptor, directly (0) or through a slot (1); a class named another way is passed over.
                let kind = (conformance.loadUnaligned(fromByteOffset: 12, as: UInt32.self) >> 3) & 0x7
                guard kind == 0 || kind == 1 else { continue }
                var descriptor = conformance.advanced(by: 4 + Int(conformance.loadUnaligned(fromByteOffset: 4, as: Int32.self)))
                if kind == 1 { guard let direct = descriptor.load(as: UnsafeRawPointer?.self) else { continue }; descriptor = direct }
                guard descriptor.load(as: UInt32.self) & 0x80 == 0 else { continue }
                // The type's metadata, from the accessor its descriptor names.
                let toAccessor = descriptor.loadUnaligned(fromByteOffset: 12, as: Int32.self)
                guard toAccessor != 0,
                      let metadata = unsafeBitCast(descriptor.advanced(by: 12 + Int(toAccessor)), to: (@convention(c) (Int) -> UnsafeRawPointer?).self)(0),
                      let table = unsafeBitCast(get, to: Call.self)(conformance, metadata, nil) else { continue }
                lock.lock()
                if tablesSeen.insert(table).inserted { tablesMade.append(table) }
                lock.unlock()
            }
        }
        /// A key path to a computed property is told apart by its getter's address (the id in its pattern), and a change
        /// has a getter of its own for every property in the files it was compiled from: `\Model.count` made by its code
        /// would be another key path than the app's, so observation keyed by the app's (`withObservationTracking`, an
        /// App's or a scene's body, which a change doesn't draw again) would no longer hear the property change. Each key
        /// path made is passed through here, and every getter of a change's in it is pointed at the getter of the same
        /// name the app has, or the first change that had it: the id is only compared and hashed, never called.
        nonisolated(unsafe) private static var getterIDs: [UInt: UInt] = [:]
        nonisolated(unsafe) private static var firstGetters: [String: UInt]?
        nonisolated(unsafe) private static let getKeyPath: UnsafeRawPointer? = dlsym(UnsafeMutableRawPointer(bitPattern: -2), "swift_getKeyPath").map { UnsafeRawPointer($0) }

        nonisolated private static func isGetter(_ name: String) -> Bool { name.hasPrefix("_$s") && (name.hasSuffix("vg") || name.hasSuffix("ig")) }

        nonisolated private static func noteGetters(_ header: UnsafePointer<mach_header>, slide: Int) {
            lock.lock()
            defer { lock.unlock() }
            if firstGetters == nil, let app = _dyld_get_image_header(0) {
                firstGetters = Dictionary(definedSymbols(app, slide: _dyld_get_image_vmaddr_slide(0), local: true)
                    .filter { isGetter($0.0) }.map { ($0.0, UInt(bitPattern: $0.1)) }, uniquingKeysWith: { first, _ in first })
            }
            for (name, address) in definedSymbols(header, slide: slide, local: true) where isGetter(name) {
                let mine = UInt(bitPattern: address)
                if let first = firstGetters?[name] { if first != mine { getterIDs[mine] = first } } else { firstGetters?[name] = mine }
            }
        }

        /// Takes `swift_getKeyPath`'s two arguments (a pattern, its arguments) and returns the key path as the runtime's
        /// does, with a change's getters in it pointed at the first of their name. A key path is a heap object whose
        /// components follow a 32-bit header at byte 24, the header's low bits saying how many bytes they take; a
        /// computed component's id is a whole word, and only a word equal to one of a change's getters is touched.
        nonisolated private static let keyPathMade: @convention(c) (UnsafeRawPointer, UnsafeRawPointer?) -> UnsafeMutableRawPointer? = { pattern, arguments in
            typealias Call = @convention(c) (UnsafeRawPointer, UnsafeRawPointer?) -> UnsafeMutableRawPointer?
            guard let real = getKeyPath, let made = unsafeBitCast(real, to: Call.self)(pattern, arguments) else { return nil }
            lock.lock()
            defer { lock.unlock() }
            // Every time, not once per object: a key path made with arguments (in generic code, a subscript's) isn't
            // kept by the runtime, and another may be made where it was. Writing the same id again changes nothing.
            guard !getterIDs.isEmpty else { return made }
            let size = Int(made.load(fromByteOffset: 24, as: UInt32.self) & 0x00FF_FFFF)
            guard size < 1 << 16 else { return made }
            var offset = 28
            while offset + 8 <= 32 + size {
                if let first = getterIDs[made.loadUnaligned(fromByteOffset: offset, as: UInt.self)] {
                    made.storeBytes(of: first, toByteOffset: offset, as: UInt.self)
                    offset += 8
                } else {
                    offset += 4
                }
            }
            return made
        }

        /// The runtime's own `swift_initClassMetadata2` and `swift_getWitnessTable`, found by name.
        nonisolated(unsafe) private static let initClassMetadata: UnsafeRawPointer? = dlsym(UnsafeMutableRawPointer(bitPattern: -2), "swift_initClassMetadata2").map { UnsafeRawPointer($0) }
        nonisolated(unsafe) private static let getWitnessTable: UnsafeRawPointer? = dlsym(UnsafeMutableRawPointer(bitPattern: -2), "swift_getWitnessTable").map { UnsafeRawPointer($0) }

        /// Takes `swift_getWitnessTable`'s three arguments (a conformance, a type, instantiation arguments) and
        /// returns the table as the runtime's does. A table for one of the app's conformances is recorded the first
        /// time it's seen, and pointed at the newest thunks then: one made before a change was copied from the
        /// app's pattern.
        nonisolated private static let tableMade: @convention(thin) (UnsafeRawPointer, UnsafeRawPointer?, UnsafeRawPointer?) -> UnsafeRawPointer? = { conformance, type, arguments in
            typealias Call = @convention(thin) (UnsafeRawPointer, UnsafeRawPointer?, UnsafeRawPointer?) -> UnsafeRawPointer?
            guard let real = getWitnessTable else { return nil }
            guard let table = unsafeBitCast(real, to: Call.self)(conformance, type, arguments) else { return nil }
            lock.lock()
            defer { lock.unlock() }
            if conformances.contains(conformance), tablesSeen.insert(table).inserted {
                tablesMade.append(table)
                _ = redirectWitnesses(of: [table], newest)
            }
            return table
        }

        /// The conformance descriptors in the app and the changes, under whatever name (`LiveObject` renames a
        /// change's).
        nonisolated private static var allConformances: Set<UnsafeRawPointer> {
            var all = Set<UnsafeRawPointer>()
            for image in 0..<_dyld_image_count() where image == 0 || String(cString: _dyld_get_image_name(image)).contains("/.lamp/live/") {
                guard let header = _dyld_get_image_header(image) else { continue }
                for (name, address) in definedSymbols(header, slide: _dyld_get_image_vmaddr_slide(image), local: true)
                where name.hasSuffix("Mc") || name.hasSuffix("Mc" + copySuffix) || name.hasSuffix("Mc" + ownSuffix) {
                    all.insert(address)
                }
            }
            return all
        }

        /// Points each witness table's entries that hold a replaced thunk at the newest one. A table begins with
        /// its conformance's descriptor, which names the protocol, whose descriptor says how many requirements
        /// (and so entries) follow.
        nonisolated private static func redirectWitnesses(of tables: [UnsafeRawPointer], _ moved: [UnsafeRawPointer: UnsafeRawPointer]) -> Int {
            guard !moved.isEmpty else { return 0 }
            var count = 0
            for table in tables {
                guard let conformance = table.load(as: UnsafeRawPointer?.self) else { continue }
                // The protocol: a relative pointer, through a slot when its low bit is set.
                let relative = conformance.loadUnaligned(as: Int32.self)
                var protocol_ = conformance.advanced(by: Int(relative & ~1))
                if relative & 1 != 0 { guard let direct = protocol_.load(as: UnsafeRawPointer?.self) else { continue }; protocol_ = direct }
                let requirements = Int(protocol_.load(fromByteOffset: 16, as: UInt32.self))
                guard requirements < 1 << 12 else { continue }
                for index in stride(from: 1, through: requirements, by: 1) {
                    let slot = table.advanced(by: index * 8)
                    guard let old = slot.load(as: UnsafeRawPointer?.self), let new = moved[old] else { continue }
                    if write(new, to: slot, executable: false) { count += 1 }
                }
            }
            return count
        }

        /// Why the change can't go in for what a class answers to from Objective-C, if it can't: the kept class
        /// answers to a selector of its own (an override of a system class's method, an `@objc` method) that its copy
        /// in the change no longer has. The kept class is completed first (its accessor), so the runtime lists it.
        nonisolated private static func removedMethods(copies: [(String, UnsafeRawPointer)], kept: [String: UnsafeRawPointer],
                                                       original: [String: UnsafeRawPointer], categories: [Category]) -> String? {
            let keptClass = keptClasses(copies: copies, kept: kept)
            for (name, copy) in copies where name.hasSuffix("CN") {
                guard let theirs = kept[name], theirs != copy else { continue }
                if let accessor = original[String(name.dropLast()) + "Ma"] { _ = unsafeBitCast(accessor, to: (@convention(c) (Int) -> UnsafeRawPointer?).self)(0) }
                guard isRealized(theirs) else { continue }
                let own = categories.filter { (keptClass[$0.class_] ?? $0.class_) == theirs }
                for meta in [false, true] {
                    let have = Set(methods(of: meta ? theirs.load(as: UnsafeRawPointer.self) : theirs).map { NSStringFromSelector($0.0) })
                    var has = Set(methods(of: meta ? copy.load(as: UnsafeRawPointer.self) : copy).map { NSStringFromSelector($0.0) })
                    for category in own { has.formUnion((meta ? category.classMethods : category.instance).map(methods(in:))?.map { NSStringFromSelector($0.0) } ?? []) }
                    if let gone = have.subtracting(has).sorted().first {
                        return "\(readable(String(name.dropLast()))) no longer answers to \(gone) from Objective-C"
                    }
                }
            }
            return nil
        }

        /// Gives a kept class the methods its copy in a change answers to from Objective-C: each of the copy's,
        /// and its metaclass's, is added to the kept class, or replaces the one it has of its own (a superclass's
        /// is left as it is, which the add refuses to touch). The copy is a class object the Objective-C runtime
        /// has never seen (Swift registers a class with it on first use, and nothing uses the copy), so its methods
        /// are read off its class data as the compiler laid it out, never asked of the runtime, which would take
        /// the class for one it had set up and crash. The kept class is completed first (its accessor, which also
        /// registers it), and one the runtime still doesn't have is left alone.
        nonisolated private static func takeMethods(from copy: UnsafeRawPointer, to kept: UnsafeRawPointer, accessor: UnsafeRawPointer?) -> Int {
            if let accessor { _ = unsafeBitCast(accessor, to: (@convention(c) (Int) -> UnsafeRawPointer?).self)(0) }
            guard isRealized(kept) else { return 0 }
            let target: AnyClass = unsafeBitCast(kept, to: AnyClass.self)
            var count = 0
            // The class's own methods, then its metaclass's (the first word of a class is its metaclass).
            for (source, to) in [(copy, target), (copy.load(as: UnsafeRawPointer.self), object_getClass(target))] {
                guard let to else { continue }
                count += add(methods(of: source), to: to)
            }
            return count
        }

        /// Whether the Objective-C runtime has set a class up: its data word then points at the runtime's record,
        /// whose first word says so (bit 31); before that it points at the compiler's, whose never has it.
        /// The bits of a class's data word that are the pointer: the runtime keeps flags in the low three and the top.
        nonisolated private static let dataMask: UInt = 0x0f00_7fff_ffff_fff8
        nonisolated private static func isRealized(_ class_: UnsafeRawPointer) -> Bool {
            guard let data = UnsafeRawPointer(bitPattern: class_.load(fromByteOffset: 32, as: UInt.self) & dataMask) else { return false }
            return data.load(as: UInt32.self) & 0x8000_0000 != 0
        }

        /// A category of the change's: an extension with `@objc` members, or an override of a system class's method
        /// in one, which the compiler puts in a list of its own. The list is renamed before the library is linked
        /// (`__lamp_catlist`), so the runtime, which attaches every category it finds as an image loads, before any
        /// check here could run, leaves these to be attached once the change is found to fit.
        struct Category { var class_: UnsafeRawPointer; var instance: UnsafeRawPointer?; var classMethods: UnsafeRawPointer?; var protocols: UnsafeRawPointer? }
        nonisolated private static func categories(_ header: UnsafePointer<mach_header>) -> [Category] {
            let header64 = UnsafeRawPointer(header).assumingMemoryBound(to: mach_header_64.self)
            var out: [Category] = []
            for segment in ["__DATA", "__DATA_CONST"] {
                var size: UInt = 0
                guard let list = getsectiondata(header64, segment, "__lamp_catlist", &size) else { continue }
                for index in 0..<(Int(size) / 8) {
                    // Name, class, instance methods, class methods, protocols, then properties, a word each.
                    guard let category = UnsafeRawPointer(list).load(fromByteOffset: index * 8, as: UnsafeRawPointer?.self),
                          let class_ = category.load(fromByteOffset: 8, as: UnsafeRawPointer?.self) else { continue }
                    out.append(Category(class_: class_, instance: category.load(fromByteOffset: 16, as: UnsafeRawPointer?.self),
                                        classMethods: category.load(fromByteOffset: 24, as: UnsafeRawPointer?.self),
                                        protocols: category.load(fromByteOffset: 32, as: UnsafeRawPointer?.self)))
                }
            }
            return out
        }

        /// The kept class for each class the change defines a copy of, by the copy's address.
        nonisolated private static func keptClasses(copies: [(String, UnsafeRawPointer)], kept: [String: UnsafeRawPointer]) -> [UnsafeRawPointer: UnsafeRawPointer] {
            Dictionary(copies.filter { $0.0.hasSuffix("CN") }.compactMap { name, copy in kept[name].map { (copy, $0) } }, uniquingKeysWith: { first, _ in first })
        }

        /// The metadata accessor of a class, by its address: the app's, or the change's own for a class it brings.
        nonisolated private static func accessor(of class_: UnsafeRawPointer, original: [String: UnsafeRawPointer],
                                                 defined: [(String, UnsafeRawPointer)]) -> UnsafeRawPointer? {
            for (name, address) in original where address == class_ && name.hasSuffix("CN") {
                if let accessor = original[String(name.dropLast()) + "Ma"] { return accessor }
            }
            for (name, address) in defined where address == class_ && name.hasSuffix("CN$lampcopy") {
                if let accessor = defined.first(where: { $0.0 == String(name.dropLast(10)) + "Ma" })?.1 { return accessor }
            }
            return nil
        }

        /// Attaches a category of the change's to a kept class: its methods as `takeMethods` gives a copy's, and its
        /// protocols. The class is completed first; one the runtime still doesn't have is left alone.
        nonisolated private static func attach(_ category: Category, to kept: UnsafeRawPointer, accessor: UnsafeRawPointer?) -> Int {
            if let accessor { _ = unsafeBitCast(accessor, to: (@convention(c) (Int) -> UnsafeRawPointer?).self)(0) }
            let target: AnyClass = unsafeBitCast(kept, to: AnyClass.self)
            // A class of the system's (an extension of ByteCountFormatter) has no accessor of the app's, and may not
            // have been used yet: asking the runtime for it by name completes it.
            if accessor == nil, !isRealized(kept) { _ = objc_getClass(class_getName(target)) }
            guard isRealized(kept) else { return 0 }
            var count = 0
            for (list, to) in [(category.instance, target), (category.classMethods, object_getClass(target))] {
                guard let list, let to else { continue }
                count += add(methods(in: list), to: to)
            }
            if let protocols = category.protocols {
                let number = Int(protocols.load(as: UInt64.self))
                for index in 0..<min(number, 1 << 10) {
                    // The list names the library's own copy of each protocol, which the runtime left unregistered
                    // when it already had one by that name (its isa unset): asked for by its name, the runtime's is adopted.
                    guard let protocol_ = protocols.load(fromByteOffset: 8 + index * 8, as: UnsafeRawPointer?.self),
                          let name = protocol_.load(fromByteOffset: 8, as: UnsafePointer<CChar>?.self),
                          let known = objc_getProtocol(name) else { continue }
                    if class_addProtocol(target, known) { count += 1 }
                }
            }
            return count
        }

        /// Gives a class methods: each is added, or replaces the one it has of its own (a superclass's is left as it
        /// is, which the add refuses to touch).
        nonisolated private static func add(_ methods: [(Selector, IMP, UnsafePointer<CChar>?)], to class_: AnyClass) -> Int {
            var count = 0
            for (selector, code, types) in methods {
                if class_addMethod(class_, selector, code, types) { count += 1; continue }
                if let own = class_getInstanceMethod(class_, selector), method_getImplementation(own) != code {
                    method_setImplementation(own, code)
                    count += 1
                }
            }
            return count
        }

        /// A class's methods as the compiler laid them out, from its class data (`methods(in:)`). A class the runtime
        /// has set up is asked instead, since its data is the runtime's.
        nonisolated private static func methods(of class_: UnsafeRawPointer) -> [(Selector, IMP, UnsafePointer<CChar>?)] {
            if isRealized(class_) {
                var number: UInt32 = 0
                guard let list = class_copyMethodList(unsafeBitCast(class_, to: AnyClass.self), &number) else { return [] }
                defer { free(list) }
                return (0..<Int(number)).map { (method_getName(list[$0]), method_getImplementation(list[$0]), method_getTypeEncoding(list[$0])) }
            }
            guard let data = UnsafeRawPointer(bitPattern: class_.load(fromByteOffset: 32, as: UInt.self) & dataMask),
                  let list = data.load(fromByteOffset: 32, as: UnsafeRawPointer?.self) else { return [] }
            return methods(in: list)
        }

        /// The methods in a list as the compiler laid it out: it begins with each entry's size (in the low bits of
        /// its first word; the top bit says the entries are three offsets rather than three pointers) and their
        /// number. An offset entry names its selector through a slot the loader filled in.
        nonisolated private static func methods(in list: UnsafeRawPointer) -> [(Selector, IMP, UnsafePointer<CChar>?)] {
            let header = list.load(as: UInt32.self), count = Int(list.load(fromByteOffset: 4, as: UInt32.self))
            let size = Int(header & 0xFFFC), offsets = header & 0x8000_0000 != 0
            guard count < 1 << 12, offsets ? size == 12 : size == 24 else { return [] }
            var out: [(Selector, IMP, UnsafePointer<CChar>?)] = []
            for index in 0..<count {
                let entry = list.advanced(by: 8 + index * size)
                let name: UnsafePointer<CChar>?, types: UnsafePointer<CChar>?, code: UnsafeRawPointer?
                if offsets {
                    let slot = entry.advanced(by: Int(entry.load(as: Int32.self)))
                    name = slot.load(as: UnsafePointer<CChar>?.self)
                    types = UnsafePointer(entry.advanced(by: 4 + Int(entry.load(fromByteOffset: 4, as: Int32.self))).assumingMemoryBound(to: CChar.self))
                    code = entry.advanced(by: 8 + Int(entry.load(fromByteOffset: 8, as: Int32.self)))
                } else {
                    name = entry.load(as: UnsafePointer<CChar>?.self)
                    types = entry.load(fromByteOffset: 8, as: UnsafePointer<CChar>?.self)
                    code = entry.load(fromByteOffset: 16, as: UnsafeRawPointer?.self)
                }
                guard let name, let code else { continue }
                out.append((sel_registerName(name), unsafeBitCast(code, to: IMP.self), types))
            }
            return out
        }

        /// Takes `swift_initClassMetadata2`'s five arguments and returns its two words as the runtime's does.
        nonisolated private static let classMade: @convention(thin) (UnsafeRawPointer, Int, Int, UnsafeRawPointer?, UnsafeRawPointer?) -> (UnsafeRawPointer?, Int) = { metadata, flags, fields, types, offsets in
            typealias Call = @convention(thin) (UnsafeRawPointer, Int, Int, UnsafeRawPointer?, UnsafeRawPointer?) -> (UnsafeRawPointer?, Int)
            guard let real = initClassMetadata else { return (nil, 0) }
            let result = unsafeBitCast(real, to: Call.self)(metadata, flags, fields, types, offsets)
            // Only once the metadata is complete: the runtime asks again for one that isn't.
            guard result.0 == nil else { return result }
            lock.lock()
            defer { lock.unlock() }
            if isOwnClass(metadata, descriptions) {
                made.append(metadata)
                _ = redirectMethods(of: [metadata], newest)
            }
            return result
        }

        /// Why the change can't go in while nothing watches the classes made as the app runs, if it can't: one of
        /// the overridable methods (those with a method descriptor, `Tq`) of a class whose table is made then (a
        /// generic class, or one the app has no complete metadata for) is among the changed functions.
        private static func unwatchedClassMethod(changed: Set<String>, copies: [(String, UnsafeRawPointer)]) -> String? {
            let complete = Set(copies.map(\.0).filter { $0.hasSuffix("CN") })
            for (name, descriptor) in copies where name.hasSuffix("CMn") {
                let class_ = String(name.dropLast(2))
                guard descriptor.load(as: UInt32.self) & 0x80 != 0 || !complete.contains(class_ + "N") else { continue }
                if changed.contains(where: { $0.hasPrefix(class_) && isCode($0) && changed.contains($0 + "Tq") }) {
                    return "a method of \(readable(class_)) changed, and the app wasn't started through Lamp's entry"
                }
            }
            return nil
        }

        /// The method descriptors (`Tq`) of each class in an image, in their order, by the class's descriptor they
        /// follow: a class's methods are listed after its description.
        private static func methodOrder(_ symbols: [(String, UnsafeRawPointer)]) -> [String: [String]] {
            let sorted = symbols.filter { $0.0.hasSuffix("CMn") || $0.0.hasSuffix("CMn" + copySuffix) || $0.0.hasSuffix("CMn" + ownSuffix) || $0.0.hasSuffix("Tq") }
                .sorted { $0.1 < $1.1 }
            var order: [String: [String]] = [:], current: String?
            for (name, _) in sorted {
                if name.hasSuffix("Tq") { if let current { order[current, default: []].append(name) } }
                else if name.hasSuffix(copySuffix) { current = String(name.dropLast(copySuffix.count)) }
                else if name.hasSuffix(ownSuffix) { current = String(name.dropLast(ownSuffix.count)) }
                else { current = name }
            }
            return order
        }

        /// A mangled name in plain words for the chat's details, by the runtime's own demangler.
        nonisolated private static func readable(_ name: String) -> String {
            guard name.hasPrefix("_$s"), let demangle = dlsym(UnsafeMutableRawPointer(bitPattern: -2), "swift_demangle") else { return name }
            typealias Demangle = @convention(c) (UnsafePointer<CChar>, Int, UnsafeMutablePointer<CChar>?, UnsafeMutablePointer<Int>?, UInt32) -> UnsafeMutablePointer<CChar>?
            let mangled = String(name.dropFirst())
            guard let out = unsafeBitCast(demangle, to: Demangle.self)(mangled, mangled.utf8.count, nil, nil, 0) else { return name }
            defer { free(out) }
            return String(cString: out)
        }

        /// Functions, getters, setters and deinits, by their Swift names: never a type's metadata, descriptors,
        /// witness tables or the accessors of stored globals, whose new copies would be a second set of the app's
        /// types and state.
        private static func isCode(_ name: String) -> Bool {
            guard name.hasPrefix("_$s") else { return false }
            if name.hasSuffix("fD") || name.hasSuffix("TW") { return true }
            // A default argument is made by a function of its own, which every caller calls.
            if name.hasSuffix("_"), let fA = name.range(of: "fA", options: .backwards), name[fA.upperBound...].dropLast().allSatisfy(\.isNumber) { return true }
            // An async function is called through a small record of its own (its code and how much room it needs),
            // which is what calls and method tables hold.
            if name.hasSuffix("Tu") { return isCode(String(name.dropLast(2))) }
            // A type's own (static) functions and properties are named as an instance's, with a Z after.
            let name = name.hasSuffix("Z") ? String(name.dropLast()) : name
            for kept in ["Mn", "Mf", "MV", "Ma", "Mm", "MF", "Mc", "Ml", "MXX", "Ms", "Wp", "WP", "Wl", "WL", "lau", "vau", "Wz", "Qo", "QO", "So", "WV", "Wvd", "MQ"]
            where name.hasSuffix(kept) { return false }
            return name.hasSuffix("F") || name.hasSuffix("g") || name.hasSuffix("s") || name.hasSuffix("M") || name.hasSuffix("fC") || name.hasSuffix("fc")
        }

        nonisolated private static func commands(_ header: UnsafePointer<mach_header>) -> [UnsafeRawPointer] {
            let header64 = UnsafeRawPointer(header).assumingMemoryBound(to: mach_header_64.self)
            var command = UnsafeRawPointer(header64).advanced(by: MemoryLayout<mach_header_64>.size)
            var all: [UnsafeRawPointer] = []
            for _ in 0..<header64.pointee.ncmds {
                all.append(command)
                command = command.advanced(by: Int(command.assumingMemoryBound(to: load_command.self).pointee.cmdsize))
            }
            return all
        }

        nonisolated private static func segmentName(_ segment: UnsafePointer<segment_command_64>) -> String {
            withUnsafeBytes(of: segment.pointee.segname) { String(cString: Array($0.bindMemory(to: CChar.self)) + [0]) }
        }

        /// The symbol and string tables of an image, where they sit in memory.
        nonisolated private static func tables(_ header: UnsafePointer<mach_header>, slide: Int)
            -> (symbols: UnsafePointer<nlist_64>, strings: UnsafePointer<CChar>, count: Int, base: UnsafeRawPointer, dysymtab: UnsafePointer<dysymtab_command>?)? {
            var symtab: UnsafePointer<symtab_command>?, dysymtab: UnsafePointer<dysymtab_command>?, linkedit: UnsafePointer<segment_command_64>?
            for command in commands(header) {
                switch command.assumingMemoryBound(to: load_command.self).pointee.cmd {
                case UInt32(LC_SYMTAB): symtab = command.assumingMemoryBound(to: symtab_command.self)
                case UInt32(LC_DYSYMTAB): dysymtab = command.assumingMemoryBound(to: dysymtab_command.self)
                case UInt32(LC_SEGMENT_64):
                    let segment = command.assumingMemoryBound(to: segment_command_64.self)
                    if segmentName(segment) == "__LINKEDIT" { linkedit = segment }
                default: break
                }
            }
            guard let symtab, let linkedit,
                  let base = UnsafeRawPointer(bitPattern: slide + Int(linkedit.pointee.vmaddr) - Int(linkedit.pointee.fileoff)) else { return nil }
            return (base.advanced(by: Int(symtab.pointee.symoff)).assumingMemoryBound(to: nlist_64.self),
                    base.advanced(by: Int(symtab.pointee.stroff)).assumingMemoryBound(to: CChar.self),
                    Int(symtab.pointee.nsyms), base, dysymtab)
        }

        /// The symbols an image defines, with their addresses: every one with `local`, else the exported ones. An
        /// image is read once and kept (`scanned`): the app's is asked for at launch and with every change, several
        /// times each, and each earlier change's with every later one, and none of them changes or goes away.
        nonisolated(unsafe) private static var scanned: [UnsafeRawPointer: (all: [(String, UnsafeRawPointer)], exported: [(String, UnsafeRawPointer)])] = [:]
        nonisolated private static func definedSymbols(_ header: UnsafePointer<mach_header>, slide: Int, local: Bool = false) -> [(String, UnsafeRawPointer)] {
            let key = UnsafeRawPointer(header)
            lock.lock()
            let known = scanned[key]
            lock.unlock()
            if let known { return local ? known.all : known.exported }
            guard let tables = tables(header, slide: slide) else { return [] }
            var all: [(String, UnsafeRawPointer)] = [], exported: [(String, UnsafeRawPointer)] = []
            for index in 0..<tables.count {
                let symbol = tables.symbols[index]
                guard symbol.n_type & UInt8(N_STAB) == 0, symbol.n_type & UInt8(N_TYPE) == UInt8(N_SECT), symbol.n_value != 0,
                      let address = UnsafeRawPointer(bitPattern: Int(symbol.n_value) + slide) else { continue }
                let entry = (String(cString: tables.strings.advanced(by: Int(symbol.n_un.n_strx))), address)
                all.append(entry)
                if symbol.n_type & UInt8(N_EXT) != 0 { exported.append(entry) }
            }
            lock.lock()
            scanned[key] = (all, exported)
            lock.unlock()
            return local ? all : exported
        }

        /// Where a class's fields are is worked out as the app runs when it can't be known when it's compiled (a
        /// subclass, or fields after one of the system's types, such as an @Observable class's registrar), and kept
        /// in a global for each field (`Wvd`); so is where a class's own members begin when its superclass is one of
        /// the system's whose size may change between releases (`CMo`, the class's bounds), which is how its code
        /// finds its method table. A library has its own copies, which nothing fills in: its code would read every
        /// such field at the start of the object, and look for the table where there is none. So they take the
        /// app's values, once the app has worked the class out (asking for its metadata does that). A field's
        /// value the compiler knew may differ from the app's too (a guess under a system class), so a copy that
        /// differs is replaced, not only an empty one. A class an earlier change brought takes that change's values the
        /// same way. A field neither has is new, and stays the library's:
        /// its class is worked out by the library's own accessor, only with `ownClasses`, once the library's
        /// references to its own types are bound (`rebind`): before, the accessor reads a null description and the
        /// app crashes.
        private static func takeFieldOffsets(_ header: UnsafePointer<mach_header>, slide: Int, earlier: [String], ownClasses: Bool = false) {
            // The app's, then each earlier change's that went in (`images`, in that order): a class an earlier change
            // brought is that change's (`kept`), which worked its fields out when it went in, and a later change that
            // compiles the class again has to take them from there, or its code would read every field at the
            // object's start. A change refused is left out: its own classes were never worked out.
            var theirs: [String: UnsafeRawPointer] = [:]
            for image in [UInt32(0)] + earlier.compactMap(imageIndex) {
                guard let other = _dyld_get_image_header(image), other != header else { continue }
                theirs.merge(definedSymbols(other, slide: _dyld_get_image_vmaddr_slide(image), local: true), uniquingKeysWith: { first, _ in first })
            }
            guard !theirs.isEmpty else { return }
            let accessors = theirs.filter { $0.key.hasSuffix("CMa") }
            let mine = definedSymbols(header, slide: slide, local: true)
            let ownAccessors = Dictionary(mine.filter { $0.0.hasSuffix("CMa") }, uniquingKeysWith: { first, _ in first })
            func complete(_ name: String, in accessors: [String: UnsafeRawPointer]) {
                if let accessor = accessors.filter({ name.hasPrefix($0.key.dropLast(2)) }).max(by: { $0.key.count < $1.key.count }) {
                    _ = unsafeBitCast(accessor.value, to: (@convention(c) (Int) -> UnsafeRawPointer?).self)(0)
                }
            }
            for (name, address) in mine where name.hasSuffix("Wvd") || name.hasSuffix("CMo") {
                let bounds = name.hasSuffix("CMo")
                guard let source = theirs[name] else {
                    // A field the app has under no such name: a new class's, or a private one whose code moved to
                    // another file (a private name carries its file's). The library works its class out itself,
                    // which lays it out as the app did when it's the same class.
                    if ownClasses, address.load(as: Int.self) == 0 { complete(name, in: ownAccessors) }
                    continue
                }
                guard !ownClasses else { continue }
                if source.load(as: Int.self) == 0 { complete(name, in: accessors) }
                // The bounds are where the members begin, then two sizes; a field's place is one word.
                for offset in bounds ? [0, 8] : [0] {
                    let value = source.load(fromByteOffset: offset, as: Int.self)
                    guard address.load(fromByteOffset: offset, as: Int.self) != value else { continue }
                    _ = write(value, to: address.advanced(by: offset), executable: false)
                }
            }
        }

        /// Points the image's symbol pointers, which its calls to its own functions go through, at the new code.
        nonisolated private static func rebind(image: UInt32, to replacements: [String: UnsafeRawPointer]) -> Int {
            guard let header = _dyld_get_image_header(image) else { return 0 }
            let slide = _dyld_get_image_vmaddr_slide(image)
            guard let tables = tables(header, slide: slide), let dysymtab = tables.dysymtab else { return 0 }
            let indirect = tables.base.advanced(by: Int(dysymtab.pointee.indirectsymoff)).assumingMemoryBound(to: UInt32.self)
            let page = Int(vm_page_size)
            var count = 0
            for command in commands(header) where command.assumingMemoryBound(to: load_command.self).pointee.cmd == UInt32(LC_SEGMENT_64) {
                let segment = command.assumingMemoryBound(to: segment_command_64.self)
                var section = command.advanced(by: MemoryLayout<segment_command_64>.size).assumingMemoryBound(to: section_64.self)
                for _ in 0..<segment.pointee.nsects {
                    defer { section = section.advanced(by: 1) }
                    let type = section.pointee.flags & UInt32(SECTION_TYPE)
                    guard type == UInt32(S_LAZY_SYMBOL_POINTERS) || type == UInt32(S_NON_LAZY_SYMBOL_POINTERS),
                          let slots = UnsafeMutablePointer<UnsafeRawPointer?>(bitPattern: slide + Int(section.pointee.addr)) else { continue }
                    let first = Int(section.pointee.reserved1)
                    for i in 0..<(Int(section.pointee.size) / MemoryLayout<UnsafeRawPointer>.size) {
                        let index = indirect[first + i]
                        guard index & 0xC000_0000 == 0 else { continue }   // a local or absolute symbol
                        let name = String(cString: tables.strings.advanced(by: Int(tables.symbols[Int(index)].n_un.n_strx)))
                        guard let new = replacements[name] else { continue }
                        let start = UInt(bitPattern: slots.advanced(by: i)) & ~UInt(page - 1)
                        mprotect(UnsafeMutableRawPointer(bitPattern: start), page, PROT_READ | PROT_WRITE)
                        slots[i] = new
                        count += 1
                    }
                }
            }
            return count
        }
    }
    #endif

    /// The 🪄 in each window's title bar: it opens this app's chat beside its content (`LampSidebar`), to change
    /// the app while using it. The app also says where its window is, for the picture Lamp shows in its place
    /// while a change reopens it.
    enum LampMagic {
        static let start: Void = {
            MainActor.assumeIsolated {
                let center = NotificationCenter.default
                center.addObserver(forName: NSWindow.didBecomeKeyNotification, object: nil, queue: .main) { note in
                    MainActor.assumeIsolated {
                        guard let window = note.object as? NSWindow, isAppWindow(window) else { return }
                        // The chat in the window now in front is the one that will be typed in.
                        LampSidebar.Placing.shared.place(in: window)
                        guard isOn else { return detach(from: window) }
                        putBack(window)
                        attach(to: window)
                        report(window)
                        LampSidebar.restore(window)
                    }
                }
                // The lit wand's symbol follows whether its window is in front (`showWand`).
                for name in [NSWindow.didBecomeMainNotification, NSWindow.didResignMainNotification,
                             NSApplication.didBecomeActiveNotification, NSApplication.didResignActiveNotification] {
                    center.addObserver(forName: name, object: nil, queue: .main) { _ in
                        MainActor.assumeIsolated {
                            for window in NSApp.windows where isAppWindow(window) { showWand(in: window) }
                        }
                    }
                }
                // Opened behind the person's windows (Lamp's looks during a change), no window becomes key: the
                // first one is put back in place and reported once launching is done all the same.
                center.addObserver(forName: NSApplication.didFinishLaunchingNotification, object: nil, queue: .main) { _ in
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                        MainActor.assumeIsolated {
                            // Only when no window has said where it is yet, and then the frontmost one: with several
                            // windows restored, another would move the chat beside the wrong one.
                            guard isOn, !reported, let window = [NSApp.keyWindow, NSApp.mainWindow].compactMap({ $0 })
                                    .first(where: { isAppWindow($0) && $0.isVisible })
                                    ?? NSApp.orderedWindows.first(where: { isAppWindow($0) && $0.isVisible }) else { return }
                            putBack(window)
                            report(window)
                        }
                    }
                }
                // A change reopens the app: where its window was is left for the new copy to open there.
                center.addObserver(forName: NSApplication.willTerminateNotification, object: nil, queue: .main) { _ in
                    MainActor.assumeIsolated { leavePlace() }
                }
                // Lamp hands the chat over to the app (`LampSidebar.openForLamp`).
                DistributedNotificationCenter.default().addObserver(
                    forName: Notification.Name(LampInstall.note + "openSidebar"), object: Bundle.main.bundleIdentifier, queue: .main
                ) { _ in
                    MainActor.assumeIsolated { if isOn { LampSidebar.openForLamp() } }
                }
                // Lamp's chat asks for something on the screen to be pointed at.
                DistributedNotificationCenter.default().addObserver(
                    forName: Notification.Name(LampInstall.note + "pick"), object: Bundle.main.bundleIdentifier, queue: .main
                ) { _ in
                    MainActor.assumeIsolated { Picker.start() }
                }
                // A change that can't go into the app as it runs waits for the person: Lamp asks for a Reload button
                // in the title bar, and takes it away once the change is in (`Store.awaitReload`).
                DistributedNotificationCenter.default().addObserver(
                    forName: Notification.Name(LampInstall.note + "reloadReady." + LampInstall.slug), object: nil, queue: .main
                ) { note in
                    let on = (note.userInfo?["on"] as? String) == "1"
                    MainActor.assumeIsolated { setReload(on ? .ready : .none) }
                }
                for name in [NSWindow.didMoveNotification, NSWindow.didResizeNotification,
                             NSWindow.didMiniaturizeNotification, NSWindow.didDeminiaturizeNotification,
                             NSWindow.didEnterFullScreenNotification, NSWindow.didExitFullScreenNotification] {
                    center.addObserver(forName: name, object: nil, queue: .main) { note in
                        MainActor.assumeIsolated {
                            guard let window = note.object as? NSWindow, isAppWindow(window) else { return }
                            LampSidebar.Placing.shared.place(in: window)
                            guard window.isKeyWindow || window.isMainWindow else { return }
                            report(window)
                        }
                    }
                }
            }
        }()

        private static var coverFrame: URL { LampRuntime.folder.appendingPathComponent("cover-frame.txt") }

        /// The front window's place, as the app quits: the new copy opens its window there (`putBack`).
        @MainActor private static func leavePlace() {
            guard isOn, let window = NSApp.windows.first(where: { isAppWindow($0) && $0.isVisible && ($0.isKeyWindow || $0.isMainWindow) })
                    ?? NSApp.windows.first(where: { isAppWindow($0) && $0.isVisible })
                    ?? NSApp.windows.first(where: { isAppWindow($0) && $0.isMiniaturized }) else { return }
            // A window in full screen or the Dock is still owed its width, though it has no place to hand on.
            LampSidebar.handOn(window)
            guard !window.isMiniaturized, !window.styleMask.contains(.fullScreen) else { return }
            try? NSStringFromRect(window.frame).write(to: coverFrame, atomically: true, encoding: .utf8)
        }

        /// The first window of a copy started for a change goes where the last one was, once.
        @MainActor private static func putBack(_ window: NSWindow) {
            guard let text = try? String(contentsOf: coverFrame, encoding: .utf8),
                  let made = (try? coverFrame.resourceValues(forKeys: [.contentModificationDateKey]))?.contentModificationDate else { return }
            try? FileManager.default.removeItem(at: coverFrame)
            let frame = NSRectFromString(text)
            guard Date().timeIntervalSince(made) < 600, frame.width > 0, frame.height > 0,
                  NSScreen.screens.contains(where: { $0.visibleFrame.intersects(frame) }) else { return }
            window.setFrame(frame, display: true)
            putBackWindow = window
            LampSidebar.takeOn(window)
        }

        /// The window put back where the last copy's was, with the chat's width if it had the chat open then.
        @MainActor static weak var putBackWindow: NSWindow?

        /// Pointing at part of the window for Lamp's chat: the named thing under the pointer is outlined, and a
        /// click sends what it is and a picture of it to Lamp; a click where nothing is named (a game's ball, a
        /// drawing) sends the area around it, a drag the box drawn, and Escape ends it.
        /// Lamp is told when it ends either way: its chat may have stepped aside meanwhile.
        @MainActor private final class Picker: NSView {
            private static var current: Picker?
            private var items: [LampScreen.Item] = []
            /// For each item, the window it's in: -1 the target, else its place in `covers`.
            private var inWindow: [Int] = []
            /// The app's own windows over the target (`windowsOver`), front to back, in this view's points.
            private var covers: [NSRect] = []
            /// The windows and frames `covers` and the items were worked out for.
            private var coverKey: [String]?
            /// The target's own named things, read before the glass is up: the accessibility API finds a window by
            /// its frame, which the glass shares.
            private var targetItems: [LampScreen.Item] = []
            private var scale: CGFloat = 1
            private var hovered: Int?
            private var keyMonitor: Any?

            private weak var target: NSWindow?

            /// The outline is drawn in a clear window of its own laid over the app's window (a child, so it moves
            /// with it), which takes the clicks without bringing the app in front first.
            static func start() {
                current?.stop(tell: false)
                guard let window = NSApp.keyWindow.flatMap({ isAppWindow($0) ? $0 : nil })
                        ?? NSApp.windows.first(where: { isAppWindow($0) && $0.isVisible }) else { return }
                let glass = NSPanel(contentRect: window.frame, styleMask: [.borderless, .nonactivatingPanel], backing: .buffered, defer: false)
                glass.isOpaque = false
                glass.backgroundColor = .clear
                glass.hasShadow = false
                glass.isReleasedWhenClosed = false
                glass.becomesKeyOnlyIfNeeded = false
                // It has the window's frame, so the window's own read of itself (`LampDriver.elements`) could take it
                // for the window, and it has nothing in it to read.
                glass.setAccessibilityElement(false)
                // An alert the app runs while the person points would otherwise keep every click for itself.
                glass.worksWhenModal = true
                let picker = Picker(frame: NSRect(origin: .zero, size: window.frame.size))
                picker.autoresizingMask = [.width, .height]
                picker.targetItems = LampDriver.elements(in: window).map(\.item)
                picker.scale = LampRuntime.scale(of: window)
                picker.target = window
                glass.contentView = picker
                window.addChildWindow(glass, ordered: .above)
                glass.makeKeyAndOrderFront(nil)
                picker.keepOnTop()
                // A panel, sheet or alert of the app's, open already or opening while the person points, would
                // cover the outline and take its clicks.
                picker.observers = [NSApplication.didUpdateNotification, NSWindow.didBecomeKeyNotification,
                                    NSApplication.didResignActiveNotification, NSApplication.didBecomeActiveNotification].map {
                    NotificationCenter.default.addObserver(forName: $0, object: nil, queue: .main) { _ in
                        MainActor.assumeIsolated { picker.keepOnTop() }
                    }
                } + [NSWindow.didMoveNotification, NSWindow.didResizeNotification].map {
                    NotificationCenter.default.addObserver(forName: $0, object: window, queue: .main) { _ in
                        MainActor.assumeIsolated { picker.keepOnTop() }
                    }
                } + [NSWindow.willCloseNotification, NSWindow.willMiniaturizeNotification].map {
                    // Pointing ends with its window: away from it, the glass would be left where the window was.
                    NotificationCenter.default.addObserver(forName: $0, object: window, queue: .main) { _ in
                        MainActor.assumeIsolated { picker.stop() }
                    }
                }
                picker.addTrackingArea(NSTrackingArea(rect: .zero, options: [.mouseMoved, .activeAlways, .inVisibleRect, .cursorUpdate],
                                                      owner: picker, userInfo: nil))
                picker.keyMonitor = NSEvent.addLocalMonitorForEvents(matching: .keyDown) { event in
                    if event.keyCode == 53 { picker.stop(); return nil }
                    return event
                }
                current = picker
            }

            private var observers: [NSObjectProtocol] = []

            /// The app's own windows in front of `target` and over it, front to back: its panels, alerts and
            /// sheets, not its other windows, and not Lamp's own (the chat beside it, a change's effect, the glass).
            /// A floating panel goes when the app isn't in front (macOS hides it a moment after saying so).
            static func windowsOver(_ target: NSWindow) -> [NSWindow] {
                let order = NSWindow.windowNumbers(options: []) ?? []
                func place(_ window: NSWindow) -> Int { order.firstIndex(of: NSNumber(value: window.windowNumber)) ?? .max }
                return NSApp.windows.filter {
                    $0 !== target && !isAppWindow($0) && $0.isVisible && !$0.isMiniaturized && $0.frame.intersects(target.frame)
                        && $0.level < .popUpMenu && place($0) < place(target) && (NSApp.isActive || !$0.hidesOnDeactivate)
                        && !($0.contentView is Picker) && !($0 is LampTransition.Glass) && !($0 is LampSidebar.Beside)
                }
                .sorted { place($0) < place($1) }
            }

            /// Keeps the glass over the app's own windows on the target, however high they float (a floating
            /// panel, a modal panel or an alert), and over its sheets, but no higher: at the window's own level,
            /// so other apps' windows still cover it as they cover the app. With nothing of the app's over the
            /// window the glass is its child and moves with it. Otherwise it can't be: AppKit keeps a child at its
            /// parent's level, and a sheet above its window and its children, so the glass leaves the window's
            /// children, follows its frame itself and is ordered just above the frontmost of them.
            func keepOnTop() {
                guard let glass = window, glass.isVisible else { return }
                guard let target, target.isVisible, !target.isMiniaturized else { return stop() }
                let over = Self.windowsOver(target)
                // Again when one of them, or the window, moved or changed size: the places are relative to the window.
                let key = ([target] + over).map { "\($0.windowNumber) \(NSStringFromRect($0.frame))" }
                if coverKey != key { coverKey = key; gather(target, over) }
                guard let top = over.first else {
                    if glass.parent == nil {
                        glass.level = target.level
                        glass.setFrame(target.frame, display: true)
                        target.addChildWindow(glass, ordered: .above)
                    }
                    return
                }
                if glass.parent != nil { target.removeChildWindow(glass) }
                let level = over.map(\.level).reduce(target.level) { max($0, $1) }
                if glass.level != level { glass.level = level }
                if glass.frame != target.frame { glass.setFrame(target.frame, display: true) }
                // Front to back, this app's windows on the screen.
                let order = NSWindow.windowNumbers(options: []) ?? []
                func place(_ window: NSWindow) -> Int { order.firstIndex(of: NSNumber(value: window.windowNumber)) ?? .max }
                if place(top) < place(glass) { glass.order(.above, relativeTo: top.windowNumber) }
            }

            /// What can be pointed at: the named things in the target and in each of the app's windows over it,
            /// all in the target's picture's pixels. Where a panel covers the target, only the panel's count.
            private func gather(_ target: NSWindow, _ over: [NSWindow]) {
                covers = over.map { NSRect(x: $0.frame.minX - target.frame.minX, y: target.frame.maxY - $0.frame.maxY,
                                           width: $0.frame.width, height: $0.frame.height) }
                var found = targetItems
                var inWindow = Array(repeating: -1, count: found.count)
                for (index, window) in over.enumerated() {
                    let own = LampRuntime.scale(of: window), cover = covers[index]
                    for var item in LampDriver.elements(in: window).map(\.item) {
                        let frame = item.frame
                        item.frame = CGRect(x: (frame.minX / own + cover.minX) * scale, y: (frame.minY / own + cover.minY) * scale,
                                            width: frame.width / own * scale, height: frame.height / own * scale)
                        found.append(item)
                        inWindow.append(index)
                    }
                }
                items = found
                self.inWindow = inWindow
                hovered = nil
                needsDisplay = true
            }

            /// The window with the app's own windows over it as they're shown, so a pick over a panel is of the
            /// panel. Its own windows need no screen recording permission; the call is looked up by name as in
            /// `LampRuntime.shown`.
            private static func picture(of window: NSWindow) -> Data? {
                typealias Capture = @convention(c) (CGRect, CFArray, UInt32) -> Unmanaged<CGImage>?
                let over = windowsOver(window)
                guard !over.isEmpty, let symbol = dlsym(UnsafeMutableRawPointer(bitPattern: -2), "CGWindowListCreateImageFromArray") else {
                    return LampRuntime.picture(of: window)
                }
                var ids = (over + [window]).map { UnsafeRawPointer(bitPattern: UInt($0.windowNumber)) }
                let list = CFArrayCreate(nil, &ids, ids.count, nil)
                let top = (NSScreen.screens.first?.frame.maxY ?? 0) - window.frame.maxY
                let bounds = CGRect(x: window.frame.minX, y: top, width: window.frame.width, height: window.frame.height)
                // At full resolution (1 << 3).
                guard let list, let image = unsafeBitCast(symbol, to: Capture.self)(bounds, list, 1 << 3)?.takeRetainedValue(),
                      image.width > 1, image.height > 1 else { return LampRuntime.picture(of: window) }
                return LampRuntime.png(image, at: window)
            }

            /// `tell` is false when Lamp hears instead that something was picked, or pointing starts over.
            func stop(tell: Bool = true) {
                keyMonitor.map(NSEvent.removeMonitor)
                keyMonitor = nil
                observers.forEach(NotificationCenter.default.removeObserver)
                observers = []
                if let glass = window {
                    glass.parent?.removeChildWindow(glass)
                    glass.orderOut(nil)
                }
                if Picker.current === self { Picker.current = nil }
                // Pointing may have been asked for from Lamp's window, which then comes back in front: macOS lets
                // Lamp do that only when the app in front hands it over.
                NSApp.yieldActivation(toApplicationWithBundleIdentifier: LampInstall.host)
                if tell {
                    DistributedNotificationCenter.default().postNotificationName(
                        Notification.Name(LampInstall.note + "pickEnded"), object: Bundle.main.bundleIdentifier, userInfo: nil, deliverImmediately: true)
                }
            }

            override func cursorUpdate(with event: NSEvent) { NSCursor.crosshair.set() }
            override var acceptsFirstResponder: Bool { true }
            override func keyDown(with event: NSEvent) { if event.keyCode == 53 { stop() } else { super.keyDown(with: event) } }

            override var isFlipped: Bool { true }
            override func acceptsFirstMouse(for event: NSEvent?) -> Bool { true }

            /// An item's frame in this view's points: the items are in the picture's pixels, from its top left.
            private func rect(_ item: LampScreen.Item) -> NSRect {
                NSRect(x: item.frame.minX / scale, y: item.frame.minY / scale, width: item.frame.width / scale, height: item.frame.height / scale)
            }

            /// The smallest named thing under the point: a button inside a row, not the row.
            private func item(at point: NSPoint) -> Int? {
                let front = covers.firstIndex { $0.contains(point) } ?? -1
                return items.indices.filter { inWindow[$0] == front && rect(items[$0]).contains(point) }
                    .min { rect(items[$0]).width * rect(items[$0]).height < rect(items[$1]).width * rect(items[$1]).height }
            }

            /// The box being dragged, or where nothing named is under a click (a game's ball, a drawing) the area
            /// around it: anything on the screen can be pointed at. Nothing is drawn for an area until it's dragged.
            private var dragStart: NSPoint?
            private var dragged: NSRect?
            private static let areaSide: CGFloat = 96

            private func area(around point: NSPoint) -> NSRect {
                NSRect(x: point.x - Self.areaSide / 2, y: point.y - Self.areaSide / 2, width: Self.areaSide, height: Self.areaSide)
                    .intersection(bounds)
            }

            override func mouseMoved(with event: NSEvent) {
                NSCursor.crosshair.set()
                let point = convert(event.locationInWindow, from: nil)
                let found = item(at: point)
                if found != hovered { hovered = found; needsDisplay = true }
            }

            override func mouseDown(with event: NSEvent) {
                dragStart = convert(event.locationInWindow, from: nil)
                dragged = nil
            }

            override func mouseDragged(with event: NSEvent) {
                guard let dragStart else { return }
                let point = convert(event.locationInWindow, from: nil)
                let box = NSRect(x: min(dragStart.x, point.x), y: min(dragStart.y, point.y),
                                 width: abs(point.x - dragStart.x), height: abs(point.y - dragStart.y)).intersection(bounds)
                dragged = box.width > 6 || box.height > 6 ? box : nil
                needsDisplay = true
            }

            /// A box dragged is what's meant; else the named thing under the click; else the area around it.
            override func mouseUp(with event: NSEvent) {
                let point = convert(event.locationInWindow, from: nil)
                defer { dragStart = nil; dragged = nil }
                if let dragged { return pick(dragged, role: "area", label: Self.place(of: dragged, in: bounds)) }
                if let index = item(at: point) {
                    let item = items[index]
                    return pick(rect(item), role: item.role, label: item.label.isEmpty ? item.value : item.label, context: context(of: index))
                }
                let box = area(around: point)
                pick(box, role: "area", label: Self.place(of: box, in: bounds))
            }

            /// Where a box is in the window, in words: "top left", "middle", "bottom".
            private static func place(of box: NSRect, in bounds: NSRect) -> String {
                let x = box.midX / max(bounds.width, 1), y = box.midY / max(bounds.height, 1)
                let row = y < 1.0 / 3 ? "top" : y > 2.0 / 3 ? "bottom" : "middle"
                let column = x < 1.0 / 3 ? "left" : x > 2.0 / 3 ? "right" : ""
                return row == "middle" && !column.isEmpty ? column : [row, column].filter { !$0.isEmpty }.joined(separator: " ")
            }

            /// What a named thing is part of, to tell it from others like it: the "Kitchen basil" of one of several
            /// "Watered" buttons. Short words on its own line to its left; else the nearest named thing around it
            /// that isn't most of the window (a list's row says what's in it, "Kitchen basil · Last watered…"); else
            /// the heading just above it in its column, for things laid out without rows.
            private func context(of index: Int) -> String {
                let own = rect(items[index])
                let label = items[index].label.isEmpty ? items[index].value : items[index].label
                func short(_ text: String) -> Bool { !text.isEmpty && text.count <= 40 && text != label && !text.contains("\n") }
                // Only things in the same window: a panel's button isn't part of what's under the panel.
                let peers = items.indices.filter { inWindow[$0] == inWindow[index] }
                let words = peers.filter { $0 != index && ["text", "heading"].contains(items[$0].role) && short(items[$0].label) }
                let left = words.filter { rect(items[$0]).maxX <= own.minX + 2 && abs(rect(items[$0]).midY - own.midY) < own.height / 2 + 4 }
                    .max { rect(items[$0]).maxX < rect(items[$1]).maxX }
                if let left { return items[left].label }
                let around = peers.filter { other in
                    let box = rect(items[other])
                    return other != index && box.contains(own) && box != own && box.width * box.height < bounds.width * bounds.height / 2
                        && items[other].label.components(separatedBy: " · ").contains(where: short)
                }
                .min { rect(items[$0]).width * rect(items[$0]).height < rect(items[$1]).width * rect(items[$1]).height }
                if let around, let first = items[around].label.components(separatedBy: " · ").first(where: short) { return first }
                // Going up from it, the first words larger than the line just above it: a plant's name over the
                // line about it, not the page's title further up. With none larger, that nearest line.
                let above = words.filter {
                    let text = rect(items[$0])
                    return text.maxY <= own.minY + 2 && own.minY - text.maxY < 120
                        && text.minX < own.maxX && text.maxX > own.minX - 24
                }
                .sorted { rect(items[$0]).maxY > rect(items[$1]).maxY }
                guard let nearest = above.first else { return "" }
                let larger = above.first { items[$0].role == "heading" || rect(items[$0]).height > rect(items[nearest]).height + 2 }
                return items[larger ?? nearest].label
            }

            /// Leaves a picture of `box` (this view's points) in the runtime folder and tells Lamp what it is.
            private func pick(_ box: NSRect, role: String, label: String, context: String = "") {
                guard let window = target else { return stop() }
                let scale = scale
                stop(tell: false)
                // The picture is taken once the outline is off the screen, a little wider than the thing itself. An
                // alert the app runs holds the run loop in a mode of its own, where the main queue waits until it's
                // answered and the alert is gone from the picture, so the timer runs in that mode too.
                let later = Timer(timeInterval: 0.15, repeats: false) { _ in MainActor.assumeIsolated {
                    // What it is and what it says; Lamp names the picture with them.
                    var info: [String: String] = ["role": role, "label": label, "context": context]
                    if let png = Self.picture(of: window), let image = NSBitmapImageRep(data: png)?.cgImage {
                        let margin = 12 * scale
                        let crop = CGRect(x: box.minX * scale, y: box.minY * scale, width: box.width * scale, height: box.height * scale)
                            .insetBy(dx: -margin, dy: -margin)
                            .intersection(CGRect(x: 0, y: 0, width: image.width, height: image.height))
                        if let part = image.cropping(to: crop),
                           let data = NSBitmapImageRep(cgImage: part).representation(using: .png, properties: [:]) {
                            let url = LampRuntime.folder.appendingPathComponent("pointed-\(UUID().uuidString.prefix(8)).png")
                            if (try? data.write(to: url)) != nil { info["picture"] = url.path }
                        }
                    }
                    DistributedNotificationCenter.default().postNotificationName(
                        Notification.Name(LampInstall.note + "picked"), object: Bundle.main.bundleIdentifier, userInfo: info, deliverImmediately: true)
                } }
                for mode in [RunLoop.Mode.common, .modalPanel] { RunLoop.main.add(later, forMode: mode) }
            }

            override func rightMouseDown(with event: NSEvent) { stop() }

            /// Says what the mode is for, at the top of the window under its title bar: the pointer can only
            /// change for the app in front, so this is what tells the person they're pointing.
            private func drawHint() {
                let text = NSAttributedString(string: "Click or drag over what you want to change  ·  Esc to cancel", attributes: [
                    .font: NSFont.systemFont(ofSize: 13, weight: .medium), .foregroundColor: NSColor.white])
                let size = text.size()
                let titlebar = (target.map { $0.frame.height - $0.contentLayoutRect.height } ?? 28)
                let box = NSRect(x: (bounds.width - size.width) / 2 - 14, y: titlebar + 10, width: size.width + 28, height: size.height + 12)
                NSColor.controlAccentColor.setFill()
                NSBezierPath(roundedRect: box, xRadius: box.height / 2, yRadius: box.height / 2).fill()
                text.draw(at: NSPoint(x: box.minX + 14, y: box.minY + 6))
            }

            override func draw(_ dirtyRect: NSRect) {
                NSColor.black.withAlphaComponent(0.08).setFill()
                bounds.fill()
                drawHint()
                // A named thing is outlined; a box being dragged, dashed.
                let box: NSRect, dashed: Bool
                if let dragged { box = dragged; dashed = true }
                else if let hovered { box = rect(items[hovered]).insetBy(dx: -3, dy: -3); dashed = false }
                else { return }
                let path = NSBezierPath(roundedRect: box, xRadius: 6, yRadius: 6)
                NSColor.controlAccentColor.withAlphaComponent(0.15).setFill()
                path.fill()
                NSColor.controlAccentColor.setStroke()
                path.lineWidth = 2
                if dashed { path.setLineDash([6, 4], count: 2, phase: 0) }
                path.stroke()
            }
        }

        /// Whether Lamp's experiment is on (Settings → Experimental): a file Lamp keeps beside the apps' folders.
        /// On while Lamp has written its mark beside the apps, and on a Mac with no Lamp at all (the app was copied over,
        /// or Lamp was removed): there the wand opens the chat's own way into Lamp (`RemixPanel`).
        static var isOn: Bool { FileManager.default.fileExists(atPath: LampInstall.apps + "/.magic") || !lampInstalled }
        /// Whether the Lamp that installed this app is on this Mac at all. Here and not in `LampInstall`, which every
        /// kind of app has and which reads only its own values: this asks macOS.
        static var lampInstalled: Bool { NSWorkspace.shared.urlForApplication(withBundleIdentifier: LampInstall.host) != nil }

        @MainActor private static func detach(from window: NSWindow) {
            while let index = window.titlebarAccessoryViewControllers.firstIndex(where: { $0.view.identifier == identifier }) {
                window.removeTitlebarAccessoryViewController(at: index)
            }
            floating(in: window)?.superview?.subviews.filter { $0 is ReloadButton }.forEach { $0.removeFromSuperview() }
            floating(in: window)?.removeFromSuperview()
        }

        /// A window of the app's own: not a panel (menus, popovers, the menu bar's), a sheet or an alert.
        @MainActor static func isAppWindow(_ window: NSWindow) -> Bool {
            !(window is NSPanel) && window.styleMask.contains(.titled) && window.canBecomeMain && window.sheetParent == nil
        }

        /// A round button like the toolbar's own, centered in the title bar whatever its height (a window with a
        /// toolbar has a tall one, one without a short one). SwiftUI may add its toolbar after the window first
        /// shows, so it's sized again each time the window comes to the front (`fit`).
        @MainActor private static func attach(to window: NSWindow) {
            if isFullBleed(window) {
                while let index = window.titlebarAccessoryViewControllers.firstIndex(where: { $0.view.identifier == identifier }) {
                    window.removeTitlebarAccessoryViewController(at: index)
                }
                return float(in: window)
            }
            floating(in: window)?.removeFromSuperview()
            if let holder = window.titlebarAccessoryViewControllers.first(where: { $0.view.identifier == identifier })?.view {
                fit(holder, in: window)
                return showWand(in: window)
            }
            let holder = NSView()
            holder.identifier = identifier
            holder.addSubview(button(LampGlyph.image(pointSize: 14, weight: .medium), "Customize This App", "Customize this app with Lamp", #selector(Opener.open(_:))))
            holder.addSubview(ReloadButton.make(floating: false))
            let accessory = NSTitlebarAccessoryViewController()
            accessory.view = holder
            accessory.layoutAttribute = .trailing
            window.addTitlebarAccessoryViewController(accessory)
            fit(holder, in: window)
            showWand(in: window)
            DispatchQueue.main.async { fit(holder, in: window) }
        }

        /// The button as tall as the toolbar's buttons when there's a toolbar, smaller in a plain title bar, in
        /// the middle of the title bar's height, at the right of the app's own content.
        @MainActor private static func fit(_ holder: NSView, in window: NSWindow) {
            guard let button = holder.subviews.first(where: { !($0 is ReloadButton) }) else { return }
            let titlebar = max(window.frame.height - window.contentLayoutRect.height, 28)
            let side = buttonSide(titlebar)
            // A holder made by an app built before the button, kept across a live change, gets it now.
            let reload = holder.subviews.compactMap { $0 as? ReloadButton }.first ?? {
                let made = ReloadButton.make(floating: false)
                holder.addSubview(made)
                return made
            }()
            var x: CGFloat = 4
            reload.show(reloadState, height: side)
            if !reload.isHidden {
                reload.frame.origin = NSPoint(x: x, y: ((titlebar - reload.frame.height) / 2).rounded())
                x += reload.frame.width + 8
            }
            holder.frame.size = NSSize(width: x + side + 10, height: titlebar)
            button.frame = NSRect(x: x, y: ((titlebar - side) / 2).rounded(), width: side, height: side)
        }

        /// Whether a change waits for the person to reload the app (`Store.awaitReload`), and whether they have.
        enum ReloadState { case none, ready, reloading }
        @MainActor static var reloadState = ReloadState.none

        /// Shows or takes away the Reload button in every window.
        @MainActor static func setReload(_ state: ReloadState) {
            reloadState = state
            for window in NSApp.windows where isAppWindow(window) && isOn { attach(to: window) }
        }

        /// The button that reloads the app for a change waiting on it, beside the wand: tinted glass in the accent
        /// color whose tint brightens and settles again, so it's seen without being in the way (a push button in
        /// the accent color before macOS 26). Its tint is all that moves: faded as a whole it would look disabled.
        /// A click asks Lamp to put the change in, by reopening the app as it was.
        @MainActor final class ReloadButton: NSButton {
            private var pulse: Timer?

            static func make(floating: Bool) -> ReloadButton {
                let button = ReloadButton(title: "Reload", image: NSImage(systemSymbolName: "arrow.clockwise", accessibilityDescription: nil) ?? NSImage(),
                                          target: Opener.shared, action: #selector(Opener.reload(_:)))
                button.identifier = NSUserInterfaceItemIdentifier("lampReload")
                button.imagePosition = .imageLeading
                button.imageHugsTitle = true
                // The glass style is macOS 26's, and its names exist only in Xcode 26's SDK: a build with an older
                // Xcode (the compiler says which) gets the push style on every macOS.
                #if compiler(>=6.2)
                if #available(macOS 26, *) {
                    button.bezelStyle = .glass
                    button.borderShape = .capsule
                    button.tintProminence = .primary
                } else {
                    button.bezelStyle = .push
                }
                #else
                button.bezelStyle = .push
                #endif
                button.bezelColor = .controlAccentColor
                button.toolTip = "Reload the app to see the latest change"
                button.setAccessibilityLabel("Reload to see the latest change")
                button.isHidden = true
                return button
            }

            /// Shown while a change waits, and says so while the app reopens. As tall as the wand beside it, with its
            /// words and symbol at the size of the toolbar's own, so the title bar reads as one row of buttons.
            func show(_ state: ReloadState, height: CGFloat) {
                isHidden = state == .none
                isEnabled = state == .ready
                title = state == .reloading ? "Reloading…" : "Reload"
                let tall = height > 30
                controlSize = tall ? .large : .regular
                font = .systemFont(ofSize: tall ? 15 : NSFont.systemFontSize(for: .regular), weight: .medium)
                image = NSImage(systemSymbolName: "arrow.clockwise", accessibilityDescription: nil)?
                    .withSymbolConfiguration(.init(pointSize: tall ? 14 : 12, weight: .medium))
                sizeToFit()
                frame.size.height = height
                breathe(state == .ready)
            }

            private func breathe(_ on: Bool) {
                guard on else {
                    pulse?.invalidate()
                    pulse = nil
                    bezelColor = .controlAccentColor
                    return
                }
                guard pulse == nil else { return }
                let start = Date()
                pulse = Timer.scheduledTimer(withTimeInterval: 1.0 / 30, repeats: true) { [weak self] timer in
                    MainActor.assumeIsolated {
                        // A button taken away with its window or its title bar stops, rather than tick on unseen.
                        guard let self, self.window != nil else { return timer.invalidate() }
                        let phase = (1 - cos(Date().timeIntervalSince(start) * 2 * .pi / 2.2)) / 2
                        self.bezelColor = NSColor.controlAccentColor.blended(withFraction: 0.4 * phase, of: .white)
                    }
                }
            }

            override func viewDidMoveToWindow() {
                super.viewDidMoveToWindow()
                if window == nil {
                    pulse?.invalidate()
                    pulse = nil
                } else if !isHidden, isEnabled {
                    breathe(true)
                }
            }

            // One click works in a window in the back too, as it does on the wand beside it.
            override func acceptsFirstMouse(for event: NSEvent?) -> Bool { true }
        }

        /// A window whose content runs under a title bar with nothing drawn in it (a game, a full-bleed app) has no
        /// bar to hold the wand: an accessory would give it one, a strip across the top it asked not to have. There
        /// the wand floats at the top right, over the content, level with the window's own close, minimize and zoom
        /// buttons. SwiftUI may add a toolbar after the window first shows, so this is asked again each time the
        /// window comes to the front.
        @MainActor private static func isFullBleed(_ window: NSWindow) -> Bool {
            window.toolbar == nil && window.styleMask.contains(.fullSizeContentView)
                && (window.titlebarAppearsTransparent || window.titleVisibility == .hidden)
        }

        /// The wand floating beside the traffic lights, in the view that holds them.
        @MainActor private static func floating(in window: NSWindow) -> NSButton? {
            window.standardWindowButton(.zoomButton)?.superview?.subviews.first { $0.identifier == identifier } as? NSButton
        }

        @MainActor private static func float(in window: NSWindow) {
            guard let zoom = window.standardWindowButton(.zoomButton), let bar = zoom.superview else { return }
            let wand = floating(in: window) ?? {
                let made = FloatingWand()
                made.identifier = identifier
                bar.addSubview(made)
                return made
            }()
            // At the top right, where the title bar's wand is in other windows: a touch larger than the traffic
            // lights, level with them, as far from the right edge as they are from the left. It keeps to the right edge as the window is resized.
            let side = (zoom.frame.height + 6).rounded()
            let inset = window.standardWindowButton(.closeButton)?.frame.minX ?? 12
            let right = bar.bounds.width - inset
            wand.autoresizingMask = [.minXMargin]
            wand.frame = NSRect(x: (right - side).rounded(), y: (zoom.frame.midY - side / 2).rounded(), width: side, height: side)
            let reload = bar.subviews.compactMap { $0 as? ReloadButton }.first ?? {
                let made = ReloadButton.make(floating: true)
                bar.addSubview(made)
                return made
            }()
            reload.show(reloadState, height: side)
            reload.autoresizingMask = [.minXMargin]
            reload.frame.origin = NSPoint(x: (wand.frame.minX - 8 - reload.frame.width).rounded(), y: (wand.frame.midY - reload.frame.height / 2).rounded())
            showWand(in: window)
        }

        /// The wand floating over the app's own content: a dark disc with a white wand, legible over a game's night
        /// sky and a bright canvas alike, as the controls over a playing video are. The title bar's glass takes its
        /// colors from the window's appearance, and over content of the other shade it all but disappeared.
        @MainActor private final class FloatingWand: NSButton {
            convenience init() {
                let image = LampGlyph.image(pointSize: 10, weight: .semibold)
                self.init(image: image, target: Opener.shared, action: #selector(Opener.open(_:)))
                toolTip = "Customize this app with Lamp"
                isBordered = false
                imagePosition = .imageOnly
                contentTintColor = .white
                wantsLayer = true
            }

            /// The chat is open: the disc takes the accent color.
            var active = false { didSet { needsDisplay = true } }

            override var wantsUpdateLayer: Bool { true }
            override func updateLayer() {
                guard let layer else { return }
                layer.cornerRadius = bounds.height / 2
                layer.backgroundColor = active
                    ? NSColor.controlAccentColor.withAlphaComponent(isHighlighted ? 0.8 : 1).cgColor
                    : NSColor.black.withAlphaComponent(isHighlighted ? 0.62 : 0.45).cgColor
                layer.borderWidth = 1
                layer.borderColor = NSColor.white.withAlphaComponent(0.25).cgColor
            }
            override func layout() {
                super.layout()
                needsDisplay = true
            }
            override var isHighlighted: Bool { didSet { needsDisplay = true } }
            // One click works in a window in the back too, as it does on the traffic lights beside it.
            override func acceptsFirstMouse(for event: NSEvent?) -> Bool { true }
        }

        /// The wand in this window, wherever it is, for what points at it (`LampSidebar.coach`).
        @MainActor static func wand(in window: NSWindow) -> NSButton? {
            floating(in: window) ?? window.titlebarAccessoryViewControllers
                .first { $0.view.identifier == identifier }?.view.subviews.first as? NSButton
        }

        /// As tall as the toolbar's buttons when there's a toolbar, smaller in a plain title bar.
        static func buttonSide(_ titlebar: CGFloat) -> CGFloat { titlebar > 40 ? 34 : 22 }

        /// A round button like the toolbar's own: the wand, and the chat's own buttons above it.
        @MainActor static func button(_ image: NSImage, _ name: String, _ tip: String, _ action: Selector) -> NSButton {
            image.accessibilityDescription = name
            let button = NSButton(image: image, target: Opener.shared, action: action)
            button.toolTip = tip
            #if compiler(>=6.2)
            if #available(macOS 26, *) {
                button.bezelStyle = .glass
                button.borderShape = .circle
            } else {
                button.bezelStyle = .accessoryBarAction
                button.isBordered = false
            }
            #else
            button.bezelStyle = .accessoryBarAction
            button.isBordered = false
            #endif
            return button
        }

        private static let identifier = NSUserInterfaceItemIdentifier("lampMagic")

        /// The wand placed again, when the chat beside the content opens, closes or is resized. Floating, it's put
        /// back: the window's title bar is laid out anew when the chat's split view becomes its content, and the
        /// wand goes with the old one.
        @MainActor static func refit(_ window: NSWindow) {
            if isOn, isFullBleed(window) {
                float(in: window)
                // Again once AppKit has finished laying out the new title bar.
                DispatchQueue.main.async { MainActor.assumeIsolated { float(in: window) } }
                return
            }
            guard let holder = window.titlebarAccessoryViewControllers.first(where: { $0.view.identifier == identifier })?.view else { return }
            fit(holder, in: window)
            showWand(in: window)
        }

        /// The wand is always where people know to find it, lit while the chat is open, and a click on it then closes
        /// the chat, as the chat's own close button does.
        @MainActor private static func showWand(in window: NSWindow) {
            guard let wand = wand(in: window) else { return }
            let open = LampSidebar.isOpen(in: window)
            wand.isHidden = false
            wand.toolTip = open ? "Close the chat" : "Customize this app with Lamp"
            if let floating = wand as? FloatingWand {
                floating.active = open
            } else {
                // A toggle that's on, as a toolbar's are drawn lit. In the window in front the lit glass is filled
                // with the accent color and draws the symbol white; behind, or with the app in the back, the glass
                // is gray and the symbol is put in the accent color itself, since a tint alone doesn't show there.
                // An accent symbol on the accent glass all but disappeared.
                let inFront = NSApp.isActive && window.isMainWindow
                wand.setButtonType(.pushOnPushOff)
                wand.state = open ? .on : .off
                wand.image = LampGlyph.image(pointSize: 14, weight: .medium, color: open && !inFront ? .controlAccentColor : nil)
            }
        }

        /// Where the window is, in screen coordinates, for the picture Lamp shows in its place while a change
        /// reopens the app; nothing when it's out of sight (in the Dock, or full screen).
        @MainActor private static var reported = false

        @MainActor private static func report(_ window: NSWindow) {
            reported = true
            let shown = window.isVisible && !window.isMiniaturized && !window.styleMask.contains(.fullScreen)
            DistributedNotificationCenter.default().postNotificationName(
                Notification.Name(LampInstall.note + "windowFrame"), object: Bundle.main.bundleIdentifier,
                userInfo: ["frame": shown ? NSStringFromRect(window.frame) : ""], deliverImmediately: true)
        }

        @MainActor final class Opener: NSObject {
            static let shared = Opener()
            @objc func open(_ sender: NSButton) {
                guard let window = sender.window ?? NSApp.keyWindow ?? NSApp.mainWindow, isAppWindow(window) else { return }
                LampSidebar.toggle(window)
            }
            /// Asks Lamp to put in the change that's waiting: it closes the app the usual way and opens it again
            /// where it was. Only a change Lamp holds for this app goes in, whoever asks.
            @objc func reload(_ sender: NSButton) {
                guard reloadState == .ready else { return }
                setReload(.reloading)
                if NSRunningApplication.runningApplications(withBundleIdentifier: LampInstall.host).isEmpty {
                    // Lamp was quit: the link opens it, and it reloads the app once it's running.
                    let configuration = NSWorkspace.OpenConfiguration()
                    configuration.activates = false
                    NSWorkspace.shared.open(LampInstall.link("reload"), configuration: configuration)
                } else {
                    DistributedNotificationCenter.default().postNotificationName(
                        Notification.Name(LampInstall.note + "reloadNow"), object: nil,
                        userInfo: ["app": LampInstall.slug], deliverImmediately: true)
                }
                // The app is closed for the change within moments. Still open later, the request didn't arrive (or
                // the change went in another way): the button is there to press again.
                DispatchQueue.main.asyncAfter(deadline: .now() + 30) {
                    MainActor.assumeIsolated { if reloadState == .reloading { setReload(.ready) } }
                }
            }
        }
    }

    /// The app's chat inside its window, beside its content: Lamp's own extension in the app
    /// (Contents/Extensions/LampSidebar.appex), shown here and drawn by a process of its own that only Lamp
    /// talks to. The app shows it and can do nothing else with it: what's typed there goes to Lamp, not here.
    /// The one thing the app says to its chat: where it is on screen (the extension declares the same).
    @objc(LampSidebarPlacement) protocol LampSidebarPlacement {
        func place(x: Double, y: Double)
    }

    /// What the chat asks of the app about its own panel, which only the app can do: close it, or move it with the
    /// pointer, since the chat draws its bar (the extension declares the same). Nothing about the app goes this way.
    @objc(LampSidebarHost) protocol LampSidebarHost {
        func closeChat(request: String)
        func startMove(request: String)
    }

    enum LampSidebar {
        /// How wide the chat is: dragged wider or narrower by its edge, and kept for
        /// the app, so it comes back at the width the person left it.
        fileprivate static let narrowest: CGFloat = 320
        fileprivate static let widest: CGFloat = 640
        private static let widthKey = "LampSidebarWidth"
        fileprivate static var width: CGFloat {
            get {
                let kept = UserDefaults.standard.double(forKey: widthKey)
                return kept > 0 ? min(max(kept, narrowest), widest) : 400
            }
            set { UserDefaults.standard.set(Double(min(max(newValue, narrowest), widest)), forKey: widthKey) }
        }
        private static let openKey = "LampSidebarOpen"
        private static let narrowedKey = "LampSidebarNarrowedBy"
        private static let coachedKey = "LampSidebarCoached"
        private static var pointID: String { (Bundle.main.bundleIdentifier ?? "") + ".lamp-sidebar" }
        @MainActor private static var restored = false
        /// Lamp asked for the chat while every window was closed: it opens beside the next one to come forward.
        @MainActor private static var openWhenShown = false

        /// One window's chat: the chat itself (`host`, drawn by the extension) on its card with its bar, in a panel of
        /// its own beside the window (`Beside`). It never goes inside the window: the room a column takes from the app
        /// is more than it gives the chat.
        @MainActor final class Chat {
            let host: EXHostViewController
            let card: NSView
            /// What the chat is laid out in.
            var pane: NSView = NSView()
            weak var window: NSWindow?
            var panel: Beside?
            var side: Side = .right
            /// Over the window's own edge rather than beside it: where there's no room beside it and none can be made
            /// (full screen, or a window that can't be made narrow enough).
            var over = false
            /// Open, whether or not its panel is on screen this moment (it's taken down while the window goes in or
            /// out of full screen, or to the Dock).
            var wanted = false
            /// How much narrower the window was made to leave room for the chat, given back when it closes. A change
            /// that reopens the app hands it on to the window put back in this one's place (`handOn`, `takeOn`).
            var narrowedBy: CGFloat = 0
            var observers: [NSObjectProtocol] = []

            init(host: EXHostViewController, card: NSView, window: NSWindow) {
                self.host = host
                self.card = card
                self.window = window
            }

            /// Moved away from the window by the person (`Beside.startMove`): it stays where they put it, whatever the
            /// window does, until the app quits.
            var detached: Bool { panel?.detached == true }

            var inPanel: Bool { panel?.isVisible == true && (panel?.parent != nil || detached) }
        }

        enum Side { case right, left }

        @MainActor private static var chats: [ObjectIdentifier: Chat] = [:]
        @MainActor private static func chat(in window: NSWindow) -> Chat? { chats[ObjectIdentifier(window)] }

        @MainActor static func isOpen(in window: NSWindow) -> Bool { chat(in: window)?.wanted == true }

        /// Whether the chat was open when the app last quit: a menu bar app opens its panel as a window to hold it
        /// again (`LampMenuBar.arrive`), since it has no first window of its own to bring it back with.
        @MainActor static var wasOpen: Bool { UserDefaults.standard.bool(forKey: openKey) }

        /// The window the chat was in was closed: it isn't opened with the app next time.
        @MainActor static func forget() { UserDefaults.standard.set(false, forKey: openKey) }

        @MainActor static func toggle(_ window: NSWindow) {
            isOpen(in: window) ? close(window) : open(window)
        }

        /// A change that reopens the app brings its chat back with its first window.
        @MainActor static func restore(_ window: NSWindow) {
            if openWhenShown {
                openWhenShown = false
                _ = askedToOpen()
                return open(window)
            }
            guard !restored else { return }
            restored = true
            // Not put back where a cover was left (full screen, the Dock): the first window takes on what's owed.
            takeOn(window)
            if let wait = askedToOpen() {
                // A wish Lamp came with, opened for the first time, is seen on its own a moment before its chat
                // comes in beside it: the file says how long (`MagicPanel.startWithChat`).
                guard wait > 0 else { return open(window) }
                DispatchQueue.main.asyncAfter(deadline: .now() + wait) {
                    MainActor.assumeIsolated {
                        if window.isVisible, !isOpen(in: window) { open(window) }
                    }
                }
            }
            else if wasOpen { open(window) }
        }

        /// Lamp hands a new app's chat over to the app once it's first built (`Store.handOff`): it leaves a file in
        /// the runtime folder for a copy that is only starting, and says so to one already running. Either way the
        /// file is taken once, so the chat isn't opened again on the next launch by it.
        private static var handOff: URL { LampRuntime.folder.appendingPathComponent("open-sidebar") }

        /// How long to wait before opening the chat, when Lamp asked for it: nothing written means at once.
        @MainActor private static func askedToOpen() -> TimeInterval? {
            guard FileManager.default.fileExists(atPath: handOff.path) else { return nil }
            let wait = (try? String(contentsOf: handOff, encoding: .utf8)).flatMap { TimeInterval($0.trimmingCharacters(in: .whitespacesAndNewlines)) }
            try? FileManager.default.removeItem(at: handOff)
            return max(0, min(wait ?? 0, 5))
        }

        /// The window the chat goes beside: the one in front, else the frontmost of the app's own windows.
        @MainActor private static func frontWindow() -> NSWindow? {
            [NSApp.keyWindow, NSApp.mainWindow].compactMap({ $0 }).first(where: { LampMagic.isAppWindow($0) && $0.isVisible })
                ?? NSApp.orderedWindows.first(where: { LampMagic.isAppWindow($0) && $0.isVisible })
        }

        /// Customize with Lamp… in the app's menu: the chat beside the window in front, left open when it is already.
        /// An app that lives in the menu bar opens its panel as a window to put it beside (`LampMenuBar.customize`);
        /// one with no window to put it beside (a widget, or a window in the Dock) has its chat in Lamp's window.
        @MainActor static func openFromMenu() {
            if LampMagic.isOn, frontWindow() == nil, LampMenuBar.isInstalled { return LampMenuBar.customize() }
            guard LampMagic.isOn, let window = frontWindow(), !window.isMiniaturized else {
                NSWorkspace.shared.open(LampMagic.lampInstalled ? LampInstall.link("edit") : URL(string: "https://lamp.dev/")!)
                return
            }
            window.makeKeyAndOrderFront(nil)
            open(window)
        }

        /// Lamp asks for the chat: in the window in front, which comes forward with it.
        @MainActor static func openForLamp() {
            guard let window = frontWindow() else {
                // A copy still starting has no window yet: the file stays for its first one (`restore`). One that's
                // running with every window closed opens one, as a click in the Dock would, and the chat goes beside
                // it as it comes forward.
                if restored {
                    openWhenShown = true
                    LampWindows.show()
                }
                return
            }
            _ = askedToOpen()
            restored = true
            NSApp.activate()
            window.makeKeyAndOrderFront(nil)
            open(window)
        }

        @MainActor static func open(_ window: NSWindow) {
            UserDefaults.standard.set(true, forKey: openKey)
            tellLamp()
            if let chat = chat(in: window) {
                guard !isOpen(in: window) else { return }
                show(chat)
                return
            }
            // An app built from its code with its own script has no chat of its own: the extension is Lamp's and goes
            // into an app only as Lamp installs it. Nothing to wait for, so it goes straight to Lamp, or its site.
            guard FileManager.default.fileExists(atPath: Bundle.main.bundleURL.appendingPathComponent("Contents/Extensions/LampSidebar.appex").path) else {
                return fallback()
            }
            Task { @MainActor in
                // Just after Lamp installs a new build, macOS may not have registered its chat yet: the first
                // answer can be an empty list with the chat a moment behind it. A few seconds are given before
                // the chat goes to Lamp's window instead.
                let identity: AppExtensionIdentity? = await withTaskGroup(of: AppExtensionIdentity?.self) { group in
                    group.addTask {
                        guard let found = try? AppExtensionIdentity.matching(appExtensionPointIDs: pointID) else { return nil }
                        for await list in found { if let first = list.first { return first } }
                        return nil
                    }
                    group.addTask {
                        try? await Task.sleep(for: .seconds(6))
                        return nil
                    }
                    let first = await group.next() ?? nil
                    group.cancelAll()
                    return first
                }
                guard let identity else { return fallback() }
                guard self.chat(in: window) == nil else { return show(self.chat(in: window)!) }
                let host = EXHostViewController()
                host.delegate = Placing.shared
                host.configuration = .init(appExtension: identity, sceneID: "chat")
                let made = card(for: host, in: window)
                let chat = Chat(host: host, card: made.card, window: window)
                chat.narrowedBy = owed.removeValue(forKey: ObjectIdentifier(window)) ?? 0
                chat.pane = made.pane
                chats[ObjectIdentifier(window)] = chat
                follow(window, chat)
                watchClicks()
                watchCycling()
                show(chat)
            }
        }

        @MainActor static func close(_ window: NSWindow) {
            UserDefaults.standard.set(false, forKey: openKey)
            guard isOpen(in: window), let chat = chat(in: window) else { return }
            chat.wanted = false
            hidePanel(chat)
            giveBackWidth(chat)
            LampMagic.refit(window)
            coach(window)
        }

        /// The width a window was made narrower by, handed on as the app quits for a change (`LampMagic.leavePlace`)
        /// to the window put back in its place (`LampMagic.putBack`), or the new copy's first window when none is put
        /// back, whose chat gives it back when it closes. Only that window takes it: another was never narrowed.
        @MainActor static func handOn(_ window: NSWindow) {
            UserDefaults.standard.set(Double(chat(in: window)?.narrowedBy ?? 0), forKey: narrowedKey)
        }

        @MainActor private static var owed: [ObjectIdentifier: CGFloat] = [:]

        @MainActor static func takeOn(_ window: NSWindow) {
            let width = CGFloat(UserDefaults.standard.double(forKey: narrowedKey))
            UserDefaults.standard.removeObject(forKey: narrowedKey)
            if width > 0 { owed[ObjectIdentifier(window)] = width }
        }

        /// A window made narrower for the chat gets its width back once the chat is closed; in full screen, once it
        /// leaves full screen, where its own size comes back.
        @MainActor private static func giveBackWidth(_ chat: Chat) {
            guard let window = chat.window, !chat.wanted, chat.narrowedBy > 0, !window.styleMask.contains(.fullScreen) else { return }
            resize(window, by: chat.narrowedBy)
            chat.narrowedBy = 0
        }

        /// The chat shown beside the window, on the side with room for it (`makeRoom`).
        @MainActor private static func show(_ chat: Chat) {
            guard let window = chat.window else { return }
            chat.wanted = true
            chat.card.alphaValue = 0
            // Moved away from the window, it opens again where it was left.
            if !chat.detached { makeRoom(for: chat) }
            putInPanel(chat)
            LampMagic.refit(window)
            fadeIn(chat.card)
        }

        private static let gap: CGFloat = 10

        /// Where the chat goes as it opens. Beside the window on a side with room for it; with room on neither side
        /// the window makes some: it moves over on its screen when that's enough, else it's made narrower (never
        /// below its own smallest width) to leave the chat its narrowest on the right, and gets the width back when the
        /// chat closes. Only where neither can be done (full screen, a window that can't be that narrow) does the chat
        /// go over the window's right edge, still a panel of its own.
        @MainActor private static func makeRoom(for chat: Chat) {
            guard let window = chat.window else { return }
            chat.over = false
            if let side = side(for: window, preferring: chat.side) {
                chat.side = side
                return
            }
            chat.side = .right
            if let room = roomBeside(window) {
                window.setFrame(room, display: true)
            } else if let narrower = narrowed(window) {
                chat.narrowedBy += window.frame.width - narrower.width
                window.setFrame(narrower, display: true, animate: false)
            } else {
                chat.over = true
            }
        }

        /// Where beside the window the chat has room, on the screen the window is on: the side it was on while it still
        /// fits there, else the right, else the left. None in full screen, where the window is the whole screen.
        @MainActor private static func side(for window: NSWindow, preferring preferred: Side) -> Side? {
            guard !window.styleMask.contains(.fullScreen), let screen = (window.screen ?? NSScreen.main)?.visibleFrame else { return nil }
            // A side with room for the chat at its width first, else one with room for it at its narrowest.
            let order = preferred == .right ? [Side.right, .left] : [Side.left, .right]
            for need in [width, narrowest] {
                if let side = order.first(where: { room(on: $0, of: window.frame, in: screen) >= need }) { return side }
            }
            return nil
        }

        /// The room beside the window on one side, up to its screen's edge, less the gap between them.
        private static func room(on side: Side, of frame: NSRect, in screen: NSRect) -> CGFloat {
            (side == .right ? screen.maxX - frame.maxX : frame.minX - screen.minX) - gap
        }

        /// Where the window would go to leave room for the chat on its right, kept on its screen; nil when it can't: in
        /// full screen, or wider than its screen leaves room for.
        @MainActor private static func roomBeside(_ window: NSWindow) -> NSRect? {
            guard !window.styleMask.contains(.fullScreen), let screen = (window.screen ?? NSScreen.main)?.visibleFrame else { return nil }
            // Room for the chat at its width when the screen has it, else at its narrowest.
            guard let need = [width + gap, narrowest + gap].first(where: { window.frame.width + $0 <= screen.width }) else { return nil }
            var frame = window.frame
            frame.origin.x = max(screen.minX, min(frame.minX, screen.maxX - need - frame.width))
            return frame
        }

        /// The window at the left of its screen, as wide as leaves the chat its narrowest on the right; nil in full
        /// screen, or when that's narrower than the window can be.
        @MainActor private static func narrowed(_ window: NSWindow) -> NSRect? {
            guard !window.styleMask.contains(.fullScreen), window.styleMask.contains(.resizable),
                  let screen = (window.screen ?? NSScreen.main)?.visibleFrame else { return nil }
            let target = screen.width - narrowest - gap
            let smallest = max(window.minSize.width, window.frameRect(forContentRect: NSRect(origin: .zero, size: window.contentMinSize)).width)
            guard target >= smallest, target < window.frame.width else { return nil }
            var frame = window.frame
            frame.origin.x = screen.minX
            frame.size.width = target
            return frame
        }

        /// The panel's frame: beside the window on the chat's side, as wide as it's kept or the room there is, or over
        /// the window's right edge, below its title bar.
        @MainActor private static func panelFrame(for chat: Chat) -> NSRect {
            guard let window = chat.window else { return .zero }
            let frame = window.frame
            let screen = (window.screen ?? NSScreen.main)?.visibleFrame
            if chat.over {
                let shown = max(narrowest, min(width, frame.width / 2))
                let titlebar = max(frame.height - window.contentLayoutRect.height, 0)
                let right = min(frame.maxX, screen?.maxX ?? frame.maxX) - gap
                return NSRect(x: right - shown, y: frame.minY + gap, width: shown, height: max(frame.height - titlebar - 2 * gap, 200))
                    .insetBy(dx: -Beside.shade, dy: -Beside.shade)
            }
            var shown = width
            if let screen { shown = max(narrowest, min(width, room(on: chat.side, of: frame, in: screen))) }
            let x = chat.side == .right ? frame.maxX + gap : frame.minX - gap - shown
            return NSRect(x: x, y: frame.minY, width: shown, height: frame.height).insetBy(dx: -Beside.shade, dy: -Beside.shade)
        }

        /// Into its panel, which is put where the chat now goes.
        @MainActor private static func putInPanel(_ chat: Chat) {
            guard let window = chat.window else { return }
            let panel = chat.panel ?? Beside()
            chat.panel = panel
            // Its outer edge widens it: over the window that's the one facing into it.
            panel.side = chat.over ? .left : chat.side
            if chat.host.parent !== panel.holder, let ground = panel.holder.view as? PanelGround {
                panel.holder.addChild(chat.host)
                // In its panel the card leaves the edges that resize it clear (`PanelGround.layout`).
                chat.card.translatesAutoresizingMaskIntoConstraints = true
                ground.addSubview(chat.card)
                ground.addSubview(ground.edges)
                ground.card = chat.card
            }
            panel.holder.view.needsLayout = true
            if !panel.detached {
                panel.setFrame(panelFrame(for: chat), display: true)
                if panel.parent == nil { window.addChildWindow(panel, ordered: .above) }
            }
            panel.orderFront(nil)
            Placing.shared.place(chat.host)
        }

        @MainActor private static func hidePanel(_ chat: Chat) {
            guard let panel = chat.panel else { return }
            panel.parent?.removeChildWindow(panel)
            panel.orderOut(nil)
        }

        /// What happens to the window decides where its chat goes: a move or a size that leaves no room on its side
        /// moves the panel to the other side, or over the window's edge when neither has room; room again takes it back
        /// beside. Going in or out of full screen takes the panel down for the change and puts it back after. The panel
        /// goes with the window when it closes or goes to the Dock.
        @MainActor private static func follow(_ window: NSWindow, _ chat: Chat) {
            let center = NotificationCenter.default
            func on(_ name: Notification.Name, _ act: @escaping @MainActor (Chat) -> Void) {
                chat.observers.append(center.addObserver(forName: name, object: window, queue: .main) { [weak chat] _ in
                    MainActor.assumeIsolated { if let chat { act(chat) } }
                })
            }
            on(NSWindow.didResizeNotification) { chat in
                guard let window = chat.window, !chat.detached else { return }
                if chat.inPanel, let panel = chat.panel { panel.setFrame(panelFrame(for: chat), display: true) }
                // A size set all at once (zoom, a tile, a size the app sets) may leave room beside it, or take it away.
                if !window.inLiveResize { replace(chat) }
            }
            on(NSWindow.didEndLiveResizeNotification) { replace($0) }
            on(NSWindow.didMoveNotification) { replace($0) }
            on(NSWindow.didChangeScreenNotification) { replace($0) }
            on(NSWindow.willEnterFullScreenNotification) { chat in
                // A chat moved away goes back beside the window, which is now the whole screen.
                chat.panel?.detached = false
                if chat.wanted { hidePanel(chat) }
            }
            on(NSWindow.didEnterFullScreenNotification) { chat in
                guard chat.wanted else { return }
                makeRoom(for: chat)
                putInPanel(chat)
            }
            on(NSWindow.willExitFullScreenNotification) { chat in if chat.wanted { hidePanel(chat) } }
            on(NSWindow.didExitFullScreenNotification) { chat in
                // Back from full screen, the chat goes beside the window again as when it opened; closed while in full
                // screen, the window gets back the width it gave it.
                guard chat.wanted else { return giveBackWidth(chat) }
                makeRoom(for: chat)
                putInPanel(chat)
            }
            on(NSWindow.didMiniaturizeNotification) { chat in if chat.inPanel { chat.panel?.orderOut(nil) } }
            on(NSWindow.didDeminiaturizeNotification) { chat in
                guard let window = chat.window, let panel = chat.panel, chat.wanted,
                      panel.parent === window || chat.detached else { return }
                panel.orderFront(nil)
            }
            on(NSWindow.willCloseNotification) { chat in
                hidePanel(chat)
                chat.observers.forEach { NotificationCenter.default.removeObserver($0) }
                if let window = chat.window { chats[ObjectIdentifier(window)] = nil }
            }
        }

        /// The chat where it now fits, if it's open and that isn't where it is. The window isn't moved or narrowed
        /// here, while the person is placing it: with no room beside it, the chat goes over its edge.
        @MainActor private static func replace(_ chat: Chat) {
            guard let window = chat.window, chat.inPanel, !chat.detached, !window.inLiveResize else { return }
            if let side = side(for: window, preferring: chat.side) {
                if !chat.over, side == chat.side {
                    // Same side: only its width may change, back towards the kept width when there's more room now.
                    if let panel = chat.panel {
                        let fitted = panelFrame(for: chat)
                        if abs(fitted.width - panel.frame.width) > 0.5 { panel.setFrame(fitted, display: true) }
                    }
                    return
                }
                chat.side = side
                chat.over = false
            } else {
                guard !chat.over else { return }
                chat.side = .right
                chat.over = true
            }
            window.disableScreenUpdatesUntilFlush()
            putInPanel(chat)
            LampMagic.refit(window)
        }

        /// The first time the chat is closed, a note points at the wand, so the way back is known: the chat may have
        /// opened by itself after the app's first build, and nothing else says where it went. Once for each app.
        @MainActor private static func coach(_ window: NSWindow) {
            guard !UserDefaults.standard.bool(forKey: coachedKey) else { return }
            UserDefaults.standard.set(true, forKey: coachedKey)
            DispatchQueue.main.async {
                guard let wand = LampMagic.wand(in: window), wand.window != nil else { return }
                let label = NSTextField(wrappingLabelWithString: "To change \(appName) any time, click here.")
                label.font = .systemFont(ofSize: NSFont.systemFontSize, weight: .medium)
                label.preferredMaxLayoutWidth = 220
                let content = NSViewController()
                let box = NSView()
                label.translatesAutoresizingMaskIntoConstraints = false
                box.addSubview(label)
                NSLayoutConstraint.activate([
                    label.leadingAnchor.constraint(equalTo: box.leadingAnchor, constant: 14),
                    label.trailingAnchor.constraint(equalTo: box.trailingAnchor, constant: -14),
                    label.topAnchor.constraint(equalTo: box.topAnchor, constant: 10),
                    label.bottomAnchor.constraint(equalTo: box.bottomAnchor, constant: -10),
                    label.widthAnchor.constraint(lessThanOrEqualToConstant: 220),
                ])
                content.view = box
                // A popover is as big as its content says: the label's wrapped size, with the margins around it.
                box.layoutSubtreeIfNeeded()
                content.preferredContentSize = box.fittingSize
                let popover = NSPopover()
                popover.contentViewController = content
                popover.behavior = .transient
                popover.show(relativeTo: wand.bounds, of: wand, preferredEdge: wand.isFlipped ? .maxY : .minY)
                DispatchQueue.main.asyncAfter(deadline: .now() + 8) { popover.performClose(nil) }
            }
        }

        /// The chat beside the window: a borderless panel of the app's, attached to the window as its child so macOS
        /// moves, stacks and hides it with the window, holding the card on its glass. It takes the keyboard for the
        /// message box without becoming the main window, so the app's window stays the active one, as with any
        /// inspector panel. Dragged by the chat's bar it comes away from the window (`detached`) and goes where it's put,
        /// resized by any edge, floating over the app's windows while the app is in front.
        @MainActor final class Beside: NSPanel {
            let holder = NSViewController()
            /// Which side of the window it's on: its outer edge, away from the window, is the one that widens it.
            var side: Side = .right
            /// Moved away from the window: no longer its child, and resized by every edge.
            var detached = false {
                didSet {
                    guard detached != oldValue else { return }
                    level = detached && NSApp.isActive ? .floating : .normal
                    holder.view.needsLayout = true
                    holder.view.window?.invalidateCursorRects(for: (holder.view as? PanelGround)?.edges ?? holder.view)
                }
            }
            /// The rim inside the card, around the chat, where the pointer resizes it: the room around the card is its
            /// shadow, which clicks go through.
            static let rim: CGFloat = 6
            /// The room around the card for its own shadow. The window's shadow drew a hard gray line round the card, as
            /// macOS outlines every window; this one is soft, and gone within the room, so clicks there reach what's
            /// behind (the app's own edge, beside it).
            static let shade: CGFloat = 14

            init() {
                super.init(contentRect: NSRect(x: 0, y: 0, width: LampSidebar.width, height: 400), styleMask: [.borderless],
                           backing: .buffered, defer: false)
                isOpaque = false
                backgroundColor = .clear
                // The card draws its own shadow (`Card`), and the clear room around it lets clicks through.
                hasShadow = false
                isMovable = false
                hidesOnDeactivate = false
                isReleasedWhenClosed = false
                let ground = PanelGround()
                ground.panel = self
                holder.view = ground
                contentViewController = holder
                ground.edges.began = { [weak self] in self?.dragStart = self?.frame }
                ground.edges.moved = { [weak self] zone, change in
                    guard let self, let start = self.dragStart else { return }
                    self.resize(zone, from: start, by: change)
                }
                // A new size or place moves the chat on the screen, which the window's own moves are all the chat is
                // otherwise told of: say where it is now, for the input method's candidates and the emoji picker.
                for name in [NSWindow.didResizeNotification, NSWindow.didMoveNotification] {
                    observers.append(NotificationCenter.default.addObserver(forName: name, object: self, queue: .main) { [weak self] _ in
                        MainActor.assumeIsolated {
                            guard let self else { return }
                            self.contentView?.layoutSubtreeIfNeeded()
                            if let parent = self.parent ?? LampSidebar.window(of: self) { LampSidebar.Placing.shared.place(in: parent) }
                        }
                    })
                }
                // Moved away, it floats over the app's windows while the app is in front, as an inspector does, and
                // keeps its place among other apps' windows when it isn't.
                for name in [NSApplication.didBecomeActiveNotification, NSApplication.didResignActiveNotification] {
                    observers.append(NotificationCenter.default.addObserver(forName: name, object: nil, queue: .main) { [weak self] _ in
                        MainActor.assumeIsolated {
                            guard let self, self.detached else { return }
                            self.level = NSApp.isActive ? .floating : .normal
                        }
                    })
                }
            }

            private var observers: [any NSObjectProtocol] = []
            private var dragStart: NSRect?
            private var moving: Timer?

            /// The person pressed on the chat's bar and is dragging (`LampSidebarHost.startMove`): the press went to the
            /// chat's own process, so the panel follows the pointer from here until the button is let go. The first
            /// move takes it away from the window.
            func startMove() {
                guard moving == nil, NSEvent.pressedMouseButtons & 1 != 0 else { return }
                let pointer = NSEvent.mouseLocation
                if !detached { detach() }
                let origin = frame.origin
                let timer = Timer(timeInterval: 1.0 / 120, repeats: true) { [weak self] timer in
                    MainActor.assumeIsolated {
                        guard let self, NSEvent.pressedMouseButtons & 1 != 0 else {
                            timer.invalidate()
                            self?.moving = nil
                            return
                        }
                        let now = NSEvent.mouseLocation
                        self.setFrameOrigin(NSPoint(x: (origin.x + now.x - pointer.x).rounded(), y: (origin.y + now.y - pointer.y).rounded()))
                    }
                }
                moving = timer
                RunLoop.main.add(timer, forMode: .common)
            }

            /// Away from the window, resized by any edge from here on.
            private func detach() {
                parent?.removeChildWindow(self)
                detached = true
            }

            /// Bigger or smaller by an edge. Beside the window only its outer edge widens it, between the chat's
            /// narrowest and widest and never past the screen's edge; away from it, any edge or corner, and the
            /// height too. The width is kept for next time.
            func resize(_ zone: Edges.Zone, from start: NSRect, by change: NSSize) {
                var frame = start
                if zone.contains(.left) { frame.size.width = start.width - change.width }
                if zone.contains(.right) { frame.size.width = start.width + change.width }
                if zone.contains(.bottom) { frame.size.height = start.height - change.height }
                if zone.contains(.top) { frame.size.height = start.height + change.height }
                let shadows = 2 * Self.shade
                frame.size.width = min(max(frame.width, LampSidebar.narrowest + shadows), LampSidebar.widest + shadows)
                if !detached, let screen = (parent?.screen ?? screen ?? NSScreen.main)?.visibleFrame {
                    frame.size.width = min(frame.width, (side == .right ? screen.maxX - start.minX : start.maxX - screen.minX) + Self.shade)
                }
                frame.size.height = max(frame.height, 300 + shadows)
                if zone.contains(.left) { frame.origin.x = start.maxX - frame.width }
                if zone.contains(.bottom) { frame.origin.y = start.maxY - frame.height }
                setFrame(frame, display: true)
                LampSidebar.width = frame.width - shadows
            }

            override var canBecomeKey: Bool { true }
            override var canBecomeMain: Bool { false }
        }

        /// The chat a request from the chats' process is for (`Answering`), chosen when the request first arrives and
        /// kept for its other copies: the one under the pointer, else the one with the keyboard.
        @MainActor private static var answered: [(request: String, chat: ObjectIdentifier?)] = []

        @MainActor static func isAsked(_ chat: Chat, for request: String) -> Bool {
            if let earlier = answered.first(where: { $0.request == request }) { return earlier.chat == ObjectIdentifier(chat) }
            let target = chosen().map(ObjectIdentifier.init)
            answered.append((request, target))
            if answered.count > 20 { answered.removeFirst() }
            return target == ObjectIdentifier(chat)
        }

        @MainActor private static func chosen() -> Chat? {
            let open = chats.values.filter { $0.inPanel }
            let pointer = NSEvent.mouseLocation
            // Front to back, as the windows are stacked: of two chats moved over each other, the click was on the one
            // in front.
            let stacked = NSApp.orderedWindows.compactMap { window in open.first { $0.panel === window } }
            return stacked.first { $0.panel?.frame.insetBy(dx: Beside.shade, dy: Beside.shade).contains(pointer) == true }
                ?? open.first { $0.panel?.isKeyWindow == true }
                ?? (open.count == 1 ? open.first : nil)
        }

        /// The window a panel's chat belongs to, attached or not.
        @MainActor static func window(of panel: Beside) -> NSWindow? {
            chats.values.first { $0.panel === panel }?.window
        }

        /// The chat on a card in its panel, on the chat's own paper (`Paper`): opaque, since what's behind the window
        /// showing through glass drew the eye from the chat, and glass drew a bright line round its edge. The chat draws its own bar, close button included, and asks the app to close or move the
        /// panel (`LampSidebarHost`): what changes the wish (undo, versions, sharing…) is in the chat, which only Lamp
        /// speaks to.
        @MainActor private static func card(for host: EXHostViewController, in window: NSWindow) -> (card: NSView, pane: NSView) {
            let outer = Card()
            let pane = Passing()
            let paper = Paper()
            paper.frame = outer.bounds
            paper.autoresizingMask = [.width, .height]
            pane.frame = paper.bounds
            pane.autoresizingMask = [.width, .height]
            paper.addSubview(pane)
            outer.addSubview(paper)
            host.view.translatesAutoresizingMaskIntoConstraints = false
            host.view.identifier = chatIdentifier
            pane.addSubview(host.view)
            // A rim of the card's own around the chat: the chat's process takes every click on its part of the window,
            // so the edges that resize the panel lie in this rim (`Edges`).
            let rim = Beside.rim
            NSLayoutConstraint.activate([
                host.view.topAnchor.constraint(equalTo: pane.topAnchor, constant: rim),
                host.view.bottomAnchor.constraint(equalTo: pane.bottomAnchor, constant: -rim),
                host.view.leadingAnchor.constraint(equalTo: pane.leadingAnchor, constant: rim),
                host.view.trailingAnchor.constraint(equalTo: pane.trailingAnchor, constant: -rim),
            ])
            return (outer, pane)
        }

        private static let chatIdentifier = NSUserInterfaceItemIdentifier("lampSidebarChat")
        nonisolated(unsafe) private static var clicks: Any?
        nonisolated(unsafe) private static var cycling: Any?

        /// ⌘` goes through the app's windows with each open chat right after its window, so the keyboard alone moves
        /// between an app and its chat; ⇧⌘` goes back. macOS leaves panels out of its own cycle.
        @MainActor private static func watchCycling() {
            guard cycling == nil else { return }
            cycling = NSEvent.addLocalMonitorForEvents(matching: .keyDown) { event in
                MainActor.assumeIsolated {
                    let modifiers = event.modifierFlags.intersection([.command, .shift, .option, .control])
                    guard event.keyCode == 50, modifiers == .command || modifiers == [.command, .shift] else { return event }
                    var stops: [NSWindow] = []
                    // In the order the windows were made, which stays put as they come forward, so each press moves on.
                    for window in NSApp.windows where LampMagic.isAppWindow(window) && window.isVisible && !window.isMiniaturized {
                        stops.append(window)
                        if let chat = chat(in: window), chat.inPanel, let panel = chat.panel { stops.append(panel) }
                    }
                    // With nothing but one window, macOS's own cycle has nothing to do either.
                    guard stops.count > 1 else { return event }
                    let current = stops.firstIndex { $0 === NSApp.keyWindow } ?? 0
                    let next = stops[(current + (modifiers.contains(.shift) ? stops.count - 1 : 1)) % stops.count]
                    next.makeKeyAndOrderFront(nil)
                    // In the chat the keyboard goes to the chat's own view, as a click there gives it (`watchClicks`).
                    if let panel = next as? Beside, let view = chats.values.first(where: { $0.panel === panel })?.host.view {
                        let target = sequence(first: view, next: { $0.subviews.first }).first { $0.acceptsFirstResponder } ?? view
                        panel.makeFirstResponder(target)
                    }
                    return nil
                }
            }
        }

        /// The chat is drawn by another process, which AppKit's focus doesn't follow, so what had the keyboard before
        /// keeps it through a click in the chat: once the click has landed, the keyboard goes to the chat.
        @MainActor private static func watchClicks() {
            guard clicks == nil else { return }
            clicks = NSEvent.addLocalMonitorForEvents(matching: .leftMouseDown) { event in
                MainActor.assumeIsolated {
                    guard let panel = event.window as? Beside else { return event }
                    let window: NSWindow = panel
                    let area = panel.holder.view
                    let point = area.convert(event.locationInWindow, from: nil)
                    guard area.bounds.contains(point) else { return event }
                    func all(_ view: NSView) -> [NSView] { view.subviews + view.subviews.flatMap(all) }
                    let inside = all(area)
                    if let chat = inside.first(where: { $0.identifier == chatIdentifier }),
                       chat.convert(chat.bounds, to: area).contains(point) {
                        let location = event.locationInWindow
                        DispatchQueue.main.async {
                            guard let hit = chat.hitTest(chat.superview?.convert(location, from: nil) ?? .zero) else { return }
                            let target = sequence(first: hit, next: \.superview).first { $0.acceptsFirstResponder && $0.isDescendant(of: chat) }
                            if let target, window.firstResponder !== target { window.makeFirstResponder(target) }
                        }
                    }
                    return event
                }
            }
        }

        /// The chat's paper, as the chat draws it (`ChatLook.paper`): a warm off-white, a warm near-black in the dark.
        private final class Paper: NSView {
            override init(frame: NSRect) {
                super.init(frame: frame)
                wantsLayer = true
                layer?.cornerRadius = 20
                layer?.cornerCurve = .continuous
                layer?.masksToBounds = true
            }
            required init?(coder: NSCoder) { fatalError() }

            override var wantsUpdateLayer: Bool { true }
            override func updateLayer() {
                let dark = effectiveAppearance.bestMatch(from: [.aqua, .darkAqua]) == .darkAqua
                layer?.backgroundColor = dark ? CGColor(srgbRed: 0x1F / 255, green: 0x1E / 255, blue: 0x1C / 255, alpha: 1)
                                              : CGColor(srgbRed: 0xF7 / 255, green: 0xF5 / 255, blue: 0xF1 / 255, alpha: 1)
            }
        }

        private class Passing: NSView {
            override func hitTest(_ point: NSPoint) -> NSView? {
                let hit = super.hitTest(point)
                return hit === self ? nil : hit
            }
        }

        /// The card, with a soft shadow of its own round it.
        private final class Card: Passing {
            override init(frame: NSRect) {
                super.init(frame: frame)
                wantsLayer = true
                layer?.masksToBounds = false
                layer?.shadowColor = NSColor.black.cgColor
                layer?.shadowOpacity = 0.14
                layer?.shadowRadius = 7
                layer?.shadowOffset = CGSize(width: 0, height: -2)
            }
            required init?(coder: NSCoder) { fatalError() }

            override func layout() {
                super.layout()
                layer?.shadowPath = CGPath(roundedRect: bounds, cornerWidth: 20, cornerHeight: 20, transform: nil)
            }
        }

        /// The panel's ground: the card, and over its rim the edges that resize it. Beside the window that's the side
        /// away from the window; moved away from it, every side.
        @MainActor final class PanelGround: NSView {
            weak var panel: Beside?
            weak var card: NSView?
            let edges = Edges()

            /// The edges over the card's rim, never over the chat: the chat is drawn by another process, which takes
            /// every click on its part of the window, so an edge laid over the chat would never be dragged.
            override func layout() {
                super.layout()
                let card = bounds.insetBy(dx: Beside.shade, dy: Beside.shade)
                self.card?.frame = card
                edges.frame = card
                edges.card = edges.bounds.insetBy(dx: Beside.rim, dy: Beside.rim)
                edges.allowed = panel?.detached == true ? [.left, .right, .top, .bottom] : panel?.side == .left ? .left : .right
                window?.invalidateCursorRects(for: edges)
            }

            override func hitTest(_ point: NSPoint) -> NSView? {
                let hit = super.hitTest(point)
                return hit === self ? nil : hit
            }
        }

        /// The room around the card where the pointer turns into the resize arrows and a drag makes the chat bigger or
        /// smaller, as a window's own edges do; near a corner, both ways.
        @MainActor final class Edges: NSView {
            struct Zone: OptionSet {
                let rawValue: Int
                static let left = Zone(rawValue: 1), right = Zone(rawValue: 2), top = Zone(rawValue: 4), bottom = Zone(rawValue: 8)
            }

            /// The edges that resize it now, and where the chat is inside the rim, in this view.
            var allowed: Zone = .right
            var card: NSRect = .zero
            /// A drag began, and how far it has gone since, in points.
            var began: (() -> Void)?
            var moved: ((Zone, NSSize) -> Void)?
            private var start: NSPoint?
            private var dragging: Zone = []
            /// How far along an edge from a corner counts as the corner.
            private let corner: CGFloat = 16

            func zone(at point: NSPoint) -> Zone {
                guard bounds.contains(point), !card.contains(point) else { return [] }
                var zone: Zone = []
                if point.x < card.minX { zone.insert(.left) }
                if point.x > card.maxX { zone.insert(.right) }
                if point.y < card.minY { zone.insert(.bottom) }
                if point.y > card.maxY { zone.insert(.top) }
                if zone == .left || zone == .right {
                    if point.y < bounds.minY + corner { zone.insert(.bottom) } else if point.y > bounds.maxY - corner { zone.insert(.top) }
                } else if zone == .top || zone == .bottom {
                    if point.x < bounds.minX + corner { zone.insert(.left) } else if point.x > bounds.maxX - corner { zone.insert(.right) }
                }
                return zone.intersection(allowed)
            }

            override func hitTest(_ point: NSPoint) -> NSView? {
                guard let superview else { return nil }
                return zone(at: convert(point, from: superview)).isEmpty ? nil : self
            }

            override func resetCursorRects() {
                let c = corner
                let areas: [(NSRect, Zone)] = [
                    (NSRect(x: 0, y: c, width: card.minX, height: bounds.height - 2 * c), .left),
                    (NSRect(x: card.maxX, y: c, width: bounds.maxX - card.maxX, height: bounds.height - 2 * c), .right),
                    (NSRect(x: c, y: card.maxY, width: bounds.width - 2 * c, height: bounds.maxY - card.maxY), .top),
                    (NSRect(x: c, y: 0, width: bounds.width - 2 * c, height: card.minY), .bottom),
                    (NSRect(x: 0, y: 0, width: c, height: c), [.left, .bottom]),
                    (NSRect(x: bounds.maxX - c, y: 0, width: c, height: c), [.right, .bottom]),
                    (NSRect(x: 0, y: bounds.maxY - c, width: c, height: c), [.left, .top]),
                    (NSRect(x: bounds.maxX - c, y: bounds.maxY - c, width: c, height: c), [.right, .top]),
                ]
                for (area, zone) in areas {
                    let usable = zone.intersection(allowed)
                    guard !usable.isEmpty, let cursor = Self.cursor(usable) else { continue }
                    let rect = outsideCard(area)
                    if !rect.isEmpty { addCursorRect(rect, cursor: cursor) }
                }
            }

            /// The part of a corner square that's in the rim, not over the chat.
            private func outsideCard(_ rect: NSRect) -> NSRect {
                guard rect.intersects(card) else { return rect }
                if rect.minX < card.minX { return NSRect(x: rect.minX, y: rect.minY, width: card.minX - rect.minX, height: rect.height) }
                if rect.maxX > card.maxX { return NSRect(x: card.maxX, y: rect.minY, width: rect.maxX - card.maxX, height: rect.height) }
                return .zero
            }

            private static func cursor(_ zone: Zone) -> NSCursor? {
                let sideways = zone.contains(.left) || zone.contains(.right)
                let upright = zone.contains(.top) || zone.contains(.bottom)
                if sideways && upright {
                    if #available(macOS 15, *) {
                        let position: NSCursor.FrameResizePosition = zone.contains(.top)
                            ? (zone.contains(.left) ? .topLeft : .topRight) : (zone.contains(.left) ? .bottomLeft : .bottomRight)
                        return .frameResize(position: position, directions: .all)
                    }
                    return .crosshair
                }
                return sideways ? .resizeLeftRight : upright ? .resizeUpDown : nil
            }

            override func acceptsFirstMouse(for event: NSEvent?) -> Bool { true }
            override func mouseDown(with event: NSEvent) {
                dragging = zone(at: convert(event.locationInWindow, from: nil))
                start = NSEvent.mouseLocation
                began?()
            }
            override func mouseDragged(with event: NSEvent) {
                guard let start, !dragging.isEmpty else { return }
                let now = NSEvent.mouseLocation
                moved?(dragging, NSSize(width: now.x - start.x, height: now.y - start.y))
            }
            override func mouseUp(with event: NSEvent) {
                start = nil
                dragging = []
            }
        }

        /// The app's name as the person knows it, for what the chat says about it.
        static var appName: String {
            Bundle.main.object(forInfoDictionaryKey: "CFBundleDisplayName") as? String
                ?? Bundle.main.object(forInfoDictionaryKey: "CFBundleName") as? String ?? ProcessInfo.processInfo.processName
        }

        @MainActor private static func fadeIn(_ view: NSView) {
            NSAnimationContext.runAnimationGroup { context in
                context.duration = 0.18
                view.animator().alphaValue = 1
            }
        }

        /// Wider or narrower on the right, kept on its screen: moved left when there's no room.
        @MainActor private static func resize(_ window: NSWindow, by change: CGFloat) {
            guard !window.styleMask.contains(.fullScreen) else { return }
            var frame = window.frame
            frame.size.width += change
            if let screen = (window.screen ?? NSScreen.main)?.visibleFrame, frame.maxX > screen.maxX {
                frame.origin.x = max(screen.minX, screen.maxX - frame.width)
                frame.size.width = min(frame.width, screen.width)
            }
            window.setFrame(frame, display: true, animate: false)
        }

        /// Where the chat is on screen, told to it over the app's own connection to it: its message box lives in a
        /// process whose window macOS keeps out of sight, and would put the typing indicator and the emoji picker
        /// at the screen's edge. Told again as the window moves or the chat is resized.
        @MainActor final class Placing: NSObject, EXHostViewControllerDelegate {
            static let shared = Placing()
            private var connections: [ObjectIdentifier: NSXPCConnection] = [:]

            nonisolated func hostViewControllerDidActivate(_ controller: EXHostViewController) {
                MainActor.assumeIsolated {
                    guard let connection = try? controller.makeXPCConnection() else { return }
                    connection.remoteObjectInterface = NSXPCInterface(with: LampSidebarPlacement.self)
                    connection.exportedInterface = NSXPCInterface(with: LampSidebarHost.self)
                    connection.exportedObject = Answering(controller)
                    connection.resume()
                    connections[ObjectIdentifier(controller)] = connection
                    place(controller)
                }
            }

            nonisolated func hostViewControllerWillDeactivate(_ controller: EXHostViewController, error: (any Error)?) {
                MainActor.assumeIsolated { connections.removeValue(forKey: ObjectIdentifier(controller))?.invalidate() }
            }

            /// Only for the window in front: the chat keeps one place for all its windows, and only the front one
            /// has a caret, so a window moved or resized behind it mustn't take that place. Coming to the front
            /// says it again (`LampMagic`).
            func place(_ controller: EXHostViewController) {
                guard let connection = connections[ObjectIdentifier(controller)], let window = controller.view.window,
                      window.isKeyWindow || window.parent?.isKeyWindow == true || (window as? Beside)?.detached == true else { return }
                let origin = window.convertToScreen(controller.view.convert(controller.view.bounds, to: nil)).origin
                (connection.remoteObjectProxy as? LampSidebarPlacement)?.place(x: origin.x, y: origin.y)
            }

            /// Every chat in this window, after it moved or changed size.
            func place(in window: NSWindow) {
                if let chat = LampSidebar.chats[ObjectIdentifier(window)] { place(chat.host) }
            }
        }

        /// What the chat asks of its panel (`LampSidebarHost`). The chat's process asks over every chat's connection,
        /// not knowing which is its own, so each connection acts only for the chat the request was meant for: the one the
        /// pointer is on, where the click or drag was; with none (a press from VoiceOver), the one with the keyboard.
        /// That's chosen once for each request, by the first connection it arrives on (`isAsked`): chosen again,
        /// a chat the first one closed would no longer be a choice, and another could be taken for it.
        final class Answering: NSObject, LampSidebarHost {
            private weak var controller: EXHostViewController?
            init(_ controller: EXHostViewController) { self.controller = controller }

            private func chat(_ request: String, _ act: @escaping @MainActor (Chat) -> Void) {
                DispatchQueue.main.async { [weak controller] in
                    MainActor.assumeIsolated {
                        guard let controller, let chat = LampSidebar.chats.values.first(where: { $0.host === controller }),
                              LampSidebar.isAsked(chat, for: request) else { return }
                        act(chat)
                    }
                }
            }

            func closeChat(request: String) { chat(request) { chat in if let window = chat.window { LampSidebar.close(window) } } }
            func startMove(request: String) { chat(request) { chat in chat.panel?.startMove() } }
        }

        /// Lamp listens for the chat: told directly when it's running (so this Lamp answers, not another copy),
        /// else started by its link, without coming in front.
        @MainActor private static func tellLamp() {
            if !NSRunningApplication.runningApplications(withBundleIdentifier: LampInstall.host).isEmpty {
                DistributedNotificationCenter.default().postNotificationName(
                    Notification.Name(LampInstall.note + "sidebar"), object: nil, userInfo: ["app": LampInstall.slug], deliverImmediately: true)
                return
            }
            let configuration = NSWorkspace.OpenConfiguration()
            configuration.activates = false
            NSWorkspace.shared.open(LampInstall.link("sidebar"), configuration: configuration)
        }

        /// No chat in this copy of the app (installed by a Lamp from before it): the chat in Lamp's window.
        @MainActor private static func fallback() {
            UserDefaults.standard.set(false, forKey: openKey)
            // Lamp's window, or on a Mac without Lamp, its site.
            NSWorkspace.shared.open(LampMagic.lampInstalled ? LampInstall.link("edit") : URL(string: "https://lamp.dev/")!)
        }
    }

    /// Brings the app back with a window when there isn't one: clicking it in the Dock, opening it again from
    /// Finder or Launchpad, and Lamp's Play button. SwiftUI doesn't open a new window for macOS's "reopen"
    /// request on its own, so this answers that request itself; Lamp also sends its own message. An app that
    /// lives in the menu bar (LampMenuBar) shows its panel.
    enum LampWindows {
        static let start: Void = {
            LampBackground.start
            DistributedNotificationCenter.default().addObserver(
                forName: Notification.Name(LampInstall.note + "showWindow"), object: Bundle.main.bundleIdentifier, queue: .main
            ) { _ in
                MainActor.assumeIsolated { show() }
            }
            // AppKit installs its own handler while launching, so take over once launching is done.
            MainActor.assumeIsolated { ReopenHandler.shared.install() }
            NotificationCenter.default.addObserver(forName: NSApplication.didFinishLaunchingNotification,
                                                   object: nil, queue: .main) { _ in
                MainActor.assumeIsolated { ReopenHandler.shared.install() }
            }
        }()

        // begin LampWindows.reopen
        @MainActor private final class ReopenHandler: NSObject {
            static let shared = ReopenHandler()

            func install() {
                NSAppleEventManager.shared().setEventHandler(
                    self, andSelector: #selector(reopen(_:reply:)),
                    forEventClass: AEEventClass(kCoreEventClass), andEventID: AEEventID(kAEReopenApplication))
            }

            /// After the Apple Event is handled, not inside it. A new window is the app's own code (its views' first
            /// `makeNSView`), which may throw an Objective-C exception, such as WebKit's for a script message handler
            /// added twice. Thrown inside the Apple Event it's caught there and the app goes on, but Swift can't be
            /// unwound by one: what the skipped code had set, such as SwiftUI's record of what a view is reading, is
            /// never put back, and the app crashes later, somewhere unrelated, with a report that names neither the
            /// exception nor the code that threw it. Thrown here, it ends the app with a report that names both
            /// (`Runtime.crash`).
            @objc func reopen(_ event: NSAppleEventDescriptor, reply: NSAppleEventDescriptor) {
                DispatchQueue.main.async { MainActor.assumeIsolated { LampWindows.show() } }
            }
        }
        // end LampWindows.reopen

        /// `relaunching` false for a caller with work in hand (Share…): then a window that can't be brought back is
        /// left for it to deal with, rather than the app starting again and ending that work.
        @MainActor static func show(relaunching: Bool = true) {
            NSApp.unhide(nil)
            let windows = NSApp.windows.filter { $0.canBecomeMain }
            if !windows.contains(where: \.isVisible) {
                if let minimized = windows.first(where: \.isMiniaturized) {
                    minimized.deminiaturize(nil)
                } else if let (menu, item) = windowOpener() {
                    // A main window first, even for an app that also has a menu bar icon.
                    menu.performActionForItem(at: menu.index(of: item))
                } else if LampMenuBar.isInstalled {
                    // An app that lives in the menu bar: the panel behind its icon is its window.
                    LampMenuBar.show()
                    return shown()
                }
            }
            NSApp.activate()
            if let window = NSApp.windows.first(where: { $0.isVisible && $0.canBecomeMain }) {
                window.makeKeyAndOrderFront(nil)
                return shown()
            }
            // Nothing could bring a window back: the app replaced New Window with something else, or its only
            // window has no menu item. Rather than sit in the Dock with nothing to show, start again with one.
            guard relaunching else { return }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                if !NSApp.windows.contains(where: { $0.isVisible && $0.canBecomeMain }) { relaunch() }
            }
        }

        /// Tells Lamp the app has something on screen (a window or its menu bar panel), so Lamp's Play doesn't
        /// take a missing ordinary window for a failure and relaunch the app.
        private static func shown() {
            DistributedNotificationCenter.default().postNotificationName(
                Notification.Name(LampInstall.note + "windowShown"), object: Bundle.main.bundleIdentifier, userInfo: nil, deliverImmediately: true)
        }

        /// The menu item that opens a window: File ▸ New Window (⌘N) while it still does that, or for an app with
        /// one window scene, the item SwiftUI puts in the Window menu under the app's name.
        private static func windowOpener() -> (NSMenu, NSMenuItem)? {
            if let item = newWindowItem(in: NSApp.mainMenu), item.title.localizedCaseInsensitiveContains("window"), let menu = item.menu {
                return (menu, item)
            }
            let name = Bundle.main.object(forInfoDictionaryKey: "CFBundleName") as? String ?? ""
            if let menu = NSApp.windowsMenu, let item = menu.items.first(where: { $0.title == name && $0.isEnabled }) {
                return (menu, item)
            }
            return nil
        }

        private static func newWindowItem(in menu: NSMenu?) -> NSMenuItem? {
            for item in menu?.items ?? [] {
                if item.keyEquivalent == "n", item.keyEquivalentModifierMask == .command, item.isEnabled { return item }
                if let found = newWindowItem(in: item.submenu) { return found }
            }
            return nil
        }

        /// Quits the app and opens it again, in front, so it comes back with a window. Also what a permission
        /// macOS only applies to a fresh start needs (LampPermissions).
        @MainActor static func relaunch() {
            let wait = "n=0; while kill -0 \"$1\" 2>/dev/null && [ $n -lt 100 ]; do sleep 0.1; n=$((n+1)); done; "
            let task = Process()
            task.executableURL = URL(fileURLWithPath: "/bin/sh")
            task.arguments = ["-c", wait + "/usr/bin/open \"$2\" --args -LampInFront YES", "sh",
                              String(ProcessInfo.processInfo.processIdentifier), Bundle.main.bundlePath]
            do {
                try task.run()
                NSApp.terminate(nil)
            } catch {
                print("LampWindows: couldn't reopen the app: \(error.localizedDescription)")
            }
        }
    }

    /// Saves what this app prints (`print`, `NSLog`, SwiftUI runtime warnings, fatal errors) and a picture of
    /// its windows to its Lamp project, where Lamp's builder looks to see what happened while the app ran.
    enum LampRuntime {
        static let folder = URL(fileURLWithPath: LampInstall.app + "/.lamp/runtime")

        /// Runs once, at launch. Each launch starts a new log.txt and keeps the one before as previous-log.txt.
        static let start: Void = {
            let fm = FileManager.default
            // Only on a Mac where Lamp has this app's project.
            guard fm.fileExists(atPath: folder.deletingLastPathComponent().path) else { return }
            try? fm.createDirectory(at: folder, withIntermediateDirectories: true)
            // Pictures: once the first window has settled, and whenever the user leaves the app
            // (often to ask Lamp for a change).
            DispatchQueue.main.async { MainActor.assumeIsolated { firstSnapshot() } }
            NotificationCenter.default.addObserver(forName: NSApplication.didResignActiveNotification,
                                                   object: nil, queue: .main) { _ in
                MainActor.assumeIsolated { snapshot() }
            }
            // Lamp asks for fresh pictures when its builder wants to look at the app.
            DistributedNotificationCenter.default().addObserver(
                forName: Notification.Name(LampInstall.note + "snapshot." + LampInstall.slug), object: nil, queue: .main) { _ in
                MainActor.assumeIsolated { snapshot() }
            }
            // ...and a few seconds of its front window, frame after frame, when the builder wants to see what moves.
            DistributedNotificationCenter.default().addObserver(
                forName: Notification.Name(LampInstall.note + "motion." + LampInstall.slug), object: nil, queue: .main) { _ in
                MainActor.assumeIsolated { recordMotion() }
            }
            // ...and clicks, types and presses keys in it when the builder wants to try something (LampDriver).
            DistributedNotificationCenter.default().addObserver(
                forName: Notification.Name(LampInstall.note + "useApp." + LampInstall.slug), object: nil, queue: .main) { note in
                let actions = note.userInfo?["actions"] as? String, id = note.userInfo?["id"] as? String
                let signature = note.userInfo?["lampUseAppSignature"] as? String
                MainActor.assumeIsolated { LampDriver.perform(actions, id: id, signature: signature) }
            }
            // ...and stops part way through when the person takes the app back with Lamp's Stop.
            DistributedNotificationCenter.default().addObserver(
                forName: Notification.Name(LampInstall.note + "useAppStop." + LampInstall.slug), object: nil, queue: .main) { note in
                let id = note.userInfo?["id"] as? String, signature = note.userInfo?["lampUseAppStop"] as? String
                MainActor.assumeIsolated { LampDriver.Handover.stop(id: id, signature: signature, token: LampInstall.token) }
            }
            // ...and, before it asks the app to quit for a rebuild, whether it still answers, so it can tell the
            // person when an app isn't responding rather than wait in silence. Answered on the main thread,
            // since that's the one a stuck app has lost. The file says this copy listens.
            let pid = String(ProcessInfo.processInfo.processIdentifier)
            DistributedNotificationCenter.default().addObserver(
                forName: Notification.Name(LampInstall.note + "stillThere." + LampInstall.slug), object: nil, queue: .main) { _ in
                DistributedNotificationCenter.default().postNotificationName(
                    Notification.Name(LampInstall.note + "here." + LampInstall.slug), object: pid, userInfo: nil, deliverImmediately: true)
            }
            try? pid.write(to: folder.appendingPathComponent("listening"), atomically: true, encoding: .utf8)
            let log = folder.appendingPathComponent("log.txt")
            let previous = folder.appendingPathComponent("previous-log.txt")
            try? fm.removeItem(at: previous)
            try? fm.moveItem(at: log, to: previous)
            LampWidgetPlacement.start
            LampTransition.start
            guard freopen(log.path, "a", stderr) != nil else { return }
            dup2(fileno(stderr), STDOUT_FILENO)
            setvbuf(stdout, nil, _IOLBF, 0)   // so nothing is lost if the app crashes
            setvbuf(stderr, nil, _IONBF, 0)
            fputs("Launched \(Date().formatted(date: .abbreviated, time: .standard))\n", stderr)
            NSSetUncaughtExceptionHandler { exception in
                fputs("Uncaught exception \(exception.name.rawValue): \(exception.reason ?? "")\n"
                      + exception.callStackSymbols.prefix(20).joined(separator: "\n") + "\n", stderr)
            }
            trimmer.resume()
        }()

        /// The first pictures after launch, which Lamp's builder waits for when it opens the app to look at it: half a
        /// second after a window is first on screen, time for it to draw and finish appearing, or at two seconds
        /// whatever there is (a menu bar app may have nothing).
        @MainActor
        private static func firstSnapshot(waited: Double = 0) {
            guard windowsOnScreen.isEmpty, waited < 2 else {
                DispatchQueue.main.asyncAfter(deadline: .now() + (waited < 2 ? 0.5 : 0)) { MainActor.assumeIsolated { snapshot() } }
                return
            }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) { MainActor.assumeIsolated { firstSnapshot(waited: waited + 0.1) } }
        }

        /// Saves up to three open windows, frontmost first, as screenshot.png, screenshot-2.png and screenshot-3.png,
        /// then calls `done`. An app may picture its own windows without screen recording permission.
        @MainActor
        static func snapshot(then done: (@MainActor () -> Void)? = nil) {
            LampDriver.keepBarPanel()
            let windows = windowsOnScreen
            guard !windows.isEmpty else { done?(); return }   // nothing on screen: keep the last pictures
            // The app's own window, not a dialog or sheet in front of it (a menu bar app's panel when that's all it has):
            // the desk keeps this picture until the next launch.
            let previewWindow = previewTaken ? nil : windows.first(where: { !$0.isSheet && !($0 is NSPanel) }) ?? windows.first(where: LampDriver.isBarPanel)
            if previewWindow != nil { previewTaken = true }
            let front = Array(windows.prefix(3))
            let seen = capturable()
            let shots = front.map { seen ? shot(of: $0) : nil }
            let previewShot = previewWindow.flatMap { seen ? shot(of: $0) : nil }
            // The front window as text, beside its picture (LampScreen), for the builder to read and act on by name: read
            // now, with the window as it's pictured, and written with the pictures, so a later snapshot's text never
            // lands beside this one's pictures.
            let words = LampScreen.text(for: LampDriver.elements(in: windows[0]).map(\.item))
            // The window server's pictures are taken off the main thread: the first after a build has the system check
            // the app's signature before it answers, which can take seconds, and the app froze (a spinning cursor) meanwhile.
            pictures.async {
                let taken = shots.map { $0.flatMap(capture) }
                let previewPicture = previewShot.flatMap(capture)
                DispatchQueue.main.async {
                    MainActor.assumeIsolated {
                        // The picture Lamp's desk shows when the pointer rests on this app's icon: the first window it
                        // shows after each launch, without Lamp's chat beside it, so it keeps up with the app as it changes.
                        if let previewWindow {
                            if let png = previewPicture ?? drawn(previewWindow) {
                                try? png.write(to: folder.appendingPathComponent("preview.png"), options: .atomic)
                            } else {
                                previewTaken = false
                            }
                        }
                        let text = folder.appendingPathComponent("screen.txt")
                        if let words {
                            try? words.write(to: text, atomically: true, encoding: .utf8)
                        } else {
                            try? FileManager.default.removeItem(at: text)
                        }
                        for index in 0..<3 {
                            let url = folder.appendingPathComponent(index == 0 ? "screenshot.png" : "screenshot-\(index + 1).png")
                            if index < front.count, let png = taken[index] ?? drawn(front[index]) {
                                try? png.write(to: url, options: .atomic)
                            } else {
                                try? FileManager.default.removeItem(at: url)
                            }
                        }
                        done?()
                    }
                }
            }
        }

        @MainActor private static var previewTaken = false
        private static let pictures = DispatchQueue(label: "lamp.pictures")

        /// What a picture of a window needs from it, read on the main thread; the picture is taken off it (`capture`).
        struct Shot: Sendable {
            let number: Int
            let size: CGSize
            let scale: CGFloat
        }

        @MainActor
        static func shot(of window: NSWindow) -> Shot? {
            guard window.windowNumber > 0, let view = window.contentView?.superview ?? window.contentView else { return nil }
            return Shot(number: window.windowNumber, size: view.bounds.size, scale: scale(of: window))
        }

        /// The window server's picture of a window, as a PNG at the size every picture of it is sent at.
        static func capture(_ shot: Shot) -> Data? {
            shown(number: shot.number).flatMap { png($0, size: shot.size, scale: shot.scale) }
        }

        /// Open windows, frontmost first. A dialog or sheet comes before the window it's attached to: it's
        /// what the user has to deal with first, and `orderedWindows` leaves those out.
        @MainActor
        static var windowsOnScreen: [NSWindow] {
            func withSheets(_ window: NSWindow) -> [NSWindow] { (window.attachedSheet.map(withSheets) ?? []) + [window] }
            var windows = NSApp.orderedWindows.flatMap(withSheets)
            // Alerts and panels shown on their own.
            windows.insert(contentsOf: NSApp.windows.filter { $0 is NSPanel && !$0.isSheet && !windows.contains($0) }, at: 0)
            // Not the clear windows a change's effect is drawn in (LampTransition), nor the chat's panel beside a window,
            // which another process draws and the app pictures as blank: the pictures are of the app.
            return windows.filter { $0.isVisible && !$0.isMiniaturized && $0.frame.width > 40 && $0.frame.height > 40
                && !($0 is LampTransition.Glass) && !($0 is LampSidebar.Beside) }
        }

        /// Picture pixels per window point: at most 1400 pixels on the long side, a size models see unscaled.
        @MainActor
        static func scale(of window: NSWindow) -> CGFloat {
            let size = (window.contentView?.superview ?? window.contentView)?.bounds.size ?? window.frame.size
            return min(window.backingScaleFactor, 1400 / max(size.width, size.height))
        }

        /// The window with its title bar, at most 1400 pixels on the long side. It's the window as the system
        /// shows it, so video, maps and web pages are in the picture; asking for one's own windows needs no
        /// screen recording permission. If the system has no picture (the app is hidden), the app draws one itself,
        /// which leaves those out.
        @MainActor
        static func picture(of window: NSWindow) -> Data? {
            if let shown = shown(window) { return png(shown, at: window) }
            return drawn(window)
        }

        /// The app's own drawing of the window, when the window server has no picture of it.
        @MainActor
        private static func drawn(_ window: NSWindow) -> Data? {
            guard let view = window.contentView?.superview ?? window.contentView,
                  let bitmap = bitmap(for: window) else { return nil }
            view.cacheDisplay(in: view.bounds, to: bitmap)
            return bitmap.representation(using: .png, properties: [:])
        }

        /// A picture the window server took of the window, at the size every picture of it is sent at.
        @MainActor
        static func png(_ image: CGImage, at window: NSWindow) -> Data? {
            guard let view = window.contentView?.superview ?? window.contentView else { return nil }
            return png(image, size: view.bounds.size, scale: scale(of: window))
        }

        static func png(_ image: CGImage, size: CGSize, scale: CGFloat) -> Data? {
            guard let bitmap = bitmap(size: size, scale: scale), let context = NSGraphicsContext(bitmapImageRep: bitmap) else { return nil }
            context.cgContext.interpolationQuality = .high
            context.cgContext.draw(image, in: CGRect(origin: .zero, size: bitmap.size))
            return bitmap.representation(using: .png, properties: [:])
        }

        @MainActor
        private static func bitmap(for window: NSWindow) -> NSBitmapImageRep? {
            guard let view = window.contentView?.superview ?? window.contentView else { return nil }
            return bitmap(size: view.bounds.size, scale: scale(of: window))
        }

        private static func bitmap(size: CGSize, scale: CGFloat) -> NSBitmapImageRep? {
            let bitmap = NSBitmapImageRep(
                bitmapDataPlanes: nil, pixelsWide: Int(size.width * scale), pixelsHigh: Int(size.height * scale),
                bitsPerSample: 8, samplesPerPixel: 4, hasAlpha: true, isPlanar: false,
                colorSpaceName: .deviceRGB, bytesPerRow: 0, bitsPerPixel: 0)
            bitmap?.size = size
            return bitmap
        }

        /// The window as the window server has it, without its shadow. The call is looked up by name: the SDK
        /// marks it unavailable in favour of ScreenCaptureKit, which would ask for screen recording permission.
        @MainActor
        private static func shown(_ window: NSWindow) -> CGImage? {
            guard window.windowNumber > 0, capturable() else { return nil }
            return shown(number: window.windowNumber)
        }

        /// Whether the window server would give a picture now: not while the app is hidden, the screen is locked or the
        /// display sleeps, when it hands back a blank one.
        @MainActor
        private static func capturable() -> Bool {
            let session = CGSessionCopyCurrentDictionary() as? [String: Any]
            return NSApp.isHidden == false && session?["CGSSessionScreenIsLocked"] == nil && CGDisplayIsAsleep(CGMainDisplayID()) == 0
        }

        private static func shown(number: Int) -> CGImage? {
            typealias Capture = @convention(c) (CGRect, UInt32, UInt32, UInt32) -> Unmanaged<CGImage>?
            guard number > 0, let symbol = dlsym(UnsafeMutableRawPointer(bitPattern: -2), "CGWindowListCreateImage") else { return nil }
            // Only this window (1 << 3); its bounds without the shadow (1 << 0), at full resolution (1 << 3).
            let image = unsafeBitCast(symbol, to: Capture.self)(.null, 1 << 3, UInt32(number), 1 | 1 << 3)?
                .takeRetainedValue()
            guard let image, image.width > 1, image.height > 1 else { return nil }
            return image
        }

        /// Watches the front window for about two and a half seconds, as fast as the system hands out pictures of
        /// it, and writes what changed from frame to frame to motion.json, with the two frames that differ most
        /// (motion-1.png, motion-2.png). Something that changes and changes straight back is flicker, which a
        /// single picture never shows.
        @MainActor
        static func recordMotion() {
            guard let window = windowsOnScreen.first else {
                try? #"{"error":"no window"}"#.write(to: folder.appendingPathComponent("motion.json"), atomically: true, encoding: .utf8)
                return
            }
            // Each frame is compared as it comes, as a small gray picture, so only those and the two full frames
            // that differ most so far are kept: a window's full frames would add up to gigabytes.
            func small(_ image: CGImage) -> [UInt8] {
                let w = 160, h = max(1, Int(160 * Double(image.height) / Double(max(image.width, 1))))
                var gray = [UInt8](repeating: 0, count: w * h)
                gray.withUnsafeMutableBytes { raw in
                    CGContext(data: raw.baseAddress, width: w, height: h, bitsPerComponent: 8, bytesPerRow: w,
                              space: CGColorSpaceCreateDeviceGray(), bitmapInfo: CGImageAlphaInfo.none.rawValue)?
                        .draw(image, in: CGRect(x: 0, y: 0, width: w, height: h))
                }
                return gray
            }
            // The share of the picture that changed between two frames.
            func changed(_ a: [UInt8], _ b: [UInt8]) -> Double {
                guard a.count == b.count, !a.isEmpty else { return 0 }
                var n = 0
                for i in a.indices where abs(Int(a[i]) - Int(b[i])) > 24 { n += 1 }
                return Double(n) / Double(a.count)
            }
            var thumbs: [[UInt8]] = [], changes: [Double] = []
            var last: CGImage?, worst: (index: Int, before: CGImage, after: CGImage)?
            let started = Date()
            func finish() {
                // A frame that differs a lot from the one before while the one after is back like the one before.
                var flickers = 0
                for i in 1..<max(1, thumbs.count - 1) where changes[i - 1] > 0.01 && changed(thumbs[i - 1], thumbs[i + 1]) < changes[i - 1] / 3 {
                    flickers += 1
                }
                if let worst {
                    // At the size of every other picture of the window, so x and y in it mean what use_app expects.
                    for (index, image) in [worst.before, worst.after].enumerated() {
                        try? png(image, at: window)?.write(to: folder.appendingPathComponent("motion-\(index + 1).png"), options: .atomic)
                    }
                }
                let report: [String: Any] = ["frames": thumbs.count, "seconds": Date().timeIntervalSince(started), "changes": changes,
                                             "flickers": flickers, "worst": worst?.index ?? 0]
                if let data = try? JSONSerialization.data(withJSONObject: report) {
                    try? data.write(to: folder.appendingPathComponent("motion.json"), options: .atomic)
                }
            }
            Timer.scheduledTimer(withTimeInterval: 1.0 / 30, repeats: true) { timer in
                MainActor.assumeIsolated {
                    if let image = shown(window) {
                        let thumb = small(image)
                        if let before = thumbs.last, let last {
                            let change = changed(before, thumb)
                            changes.append(change)
                            if worst == nil || change > changes[worst!.index] { worst = (changes.count - 1, last, image) }
                        }
                        thumbs.append(thumb)
                        last = image
                    }
                    if Date().timeIntervalSince(started) > 2.5 || thumbs.count >= 90 {
                        timer.invalidate()
                        finish()
                    }
                }
            }
        }

        /// Keeps a chatty app from filling the disk: past 1 MB, the log starts over.
        private static let trimmer: DispatchSourceTimer = {
            let timer = DispatchSource.makeTimerSource(queue: .global(qos: .utility))
            timer.schedule(deadline: .now() + 30, repeating: 30)
            timer.setEventHandler {
                var info = stat()
                guard fstat(fileno(stderr), &info) == 0, info.st_size > 1_000_000 else { return }
                ftruncate(fileno(stderr), 0)
                fputs("(Earlier output was dropped: the log passed 1 MB.)\n", stderr)
            }
            return timer
        }()
    }

    // LampTransition
    /// While Lamp builds a change for this app, smoke curls up from the bottom of its windows, and when the change
    /// goes in a band of white whooshes up across them once, so the change looks alive rather than abrupt. Only Lamp starts it: the
    /// request is signed with the app's token (the "lampTransitionSignature" key marks the builds that understand
    /// it), and nothing here is reachable from the app's own code. It's drawn in clear windows laid over the app's
    /// (children, so they move and stack with them) that let every click through, and the pictures Lamp takes for
    /// its builder are of the app's windows alone, so the effect is never in them.
    fileprivate enum LampTransition {
        static let start: Void = {
            DistributedNotificationCenter.default().addObserver(
                forName: Notification.Name(LampInstall.note + "transition." + LampInstall.slug), object: nil, queue: .main
            ) { note in
                let info = note.userInfo
                let phase = info?["phase"] as? String ?? "", id = info?["id"] as? String ?? ""
                let at = info?["at"] as? String ?? "", signature = info?["lampTransitionSignature"] as? String ?? ""
                MainActor.assumeIsolated {
                    guard gate.admits(phase: phase, id: id, at: at, signature: signature, now: Date()) else { return }
                    switch phase {
                    case "begin": begin()
                    case "land": land()
                    default: end()
                    }
                }
            }
            for name in [NSWindow.didResizeNotification, NSWindow.didEnterFullScreenNotification, NSWindow.didExitFullScreenNotification] {
                NotificationCenter.default.addObserver(forName: name, object: nil, queue: .main) { note in
                    MainActor.assumeIsolated {
                        guard let window = note.object as? NSWindow, let glass = glasses.first(where: { $0.over === window }) else { return }
                        glass.fit()
                    }
                }
            }
        }()

        /// Whether a request is Lamp's, and new: signed with the token over its phase, id and time, sent in the
        /// last few seconds, and not seen before, so a request another process overheard can't be played again.
        struct Gate {
            let token: String
            private var seen: [String] = []

            init(token: String) { self.token = token }

            static func signature(phase: String, id: String, at: String, token: String) -> String {
                HMAC<SHA256>.authenticationCode(for: Data("transition\n\(id)\n\(phase)\n\(at)".utf8), using: SymmetricKey(data: Data(token.utf8)))
                    .map { String(format: "%02x", $0) }.joined()
            }

            mutating func admits(phase: String, id: String, at: String, signature: String, now: Date) -> Bool {
                guard !token.isEmpty, !id.isEmpty, ["begin", "land", "end"].contains(phase), let sent = Double(at),
                      abs(now.timeIntervalSince1970 - sent) < 10, !seen.contains(id),
                      signature == Self.signature(phase: phase, id: id, at: at, token: token) else { return false }
                seen.append(id)
                if seen.count > 64 { seen.removeFirst(seen.count - 64) }
                return true
            }
        }

        @MainActor private static var gate = Gate(token: LampInstall.token)
        @MainActor private static var glasses: [Glass] = []
        /// An effect never outlives what it's for: a begin Lamp stops renewing (it renews it while a build runs) fades by itself.
        @MainActor private static var timeout: DispatchWorkItem?
        private static let patience: TimeInterval = 90

        private static var reduceMotion: Bool { NSWorkspace.shared.accessibilityDisplayShouldReduceMotion }

        /// The app's own windows and its menu bar panel: not dialogs, sheets or the chat beside it, which says what's going on itself.
        @MainActor private static var windows: [NSWindow] {
            NSApp.windows.filter { ($0 is Glass) == false && $0.isVisible && !$0.isMiniaturized
                && (LampMagic.isAppWindow($0) || LampDriver.isBarPanel($0)) && $0.frame.width > 40 && $0.frame.height > 40 }
        }

        @MainActor static func begin() {
            renew()
            glasses.removeAll { $0.over == nil || $0.isLeaving }
            for window in windows where !glasses.contains(where: { $0.over === window }) {
                let glass = Glass(over: window)
                glasses.append(glass)
                glass.glow(still: reduceMotion)
            }
        }

        /// The change went in: the band whooshes up each window once (a soft wash where motion is reduced), then the smoke and the glow go.
        @MainActor static func land() {
            timeout?.cancel()
            if glasses.isEmpty {
                // A copy opened for this change never saw the begin: it shows that it's new all the same.
                for window in windows { glasses.append(Glass(over: window)) }
            }
            for glass in glasses { glass.reveal(still: reduceMotion) }
            glasses.removeAll()
        }

        @MainActor static func end() {
            timeout?.cancel()
            for glass in glasses { glass.fade() }
            glasses.removeAll()
        }

        @MainActor private static func renew() {
            timeout?.cancel()
            let work = DispatchWorkItem { MainActor.assumeIsolated { end() } }
            timeout = work
            DispatchQueue.main.asyncAfter(deadline: .now() + patience, execute: work)
        }

        /// A clear window over one of the app's, holding the effect's layers (`Look`).
        @MainActor final class Glass: NSPanel {
            weak var over: NSWindow?
            private(set) var isLeaving = false
            private let look: Look

            init(over window: NSWindow) {
                over = window
                look = Look(frame: NSRect(origin: .zero, size: window.frame.size))
                super.init(contentRect: window.frame, styleMask: [.borderless, .nonactivatingPanel], backing: .buffered, defer: false)
                isOpaque = false
                backgroundColor = .clear
                hasShadow = false
                ignoresMouseEvents = true
                isReleasedWhenClosed = false
                hidesOnDeactivate = false
                animationBehavior = .none
                // Its frame is the window's, so the app's own read of the window (`LampDriver.elements`) would take
                // this empty panel for it while a change goes in.
                setAccessibilityElement(false)
                look.cornerRadius = Self.cornerRadius(of: window)
                contentView = look
                window.addChildWindow(self, ordered: .above)
            }

            override var canBecomeKey: Bool { false }
            override var canBecomeMain: Bool { false }

            /// The window's own rounding, so the glow follows its corners; macOS's usual when it doesn't say.
            private static func cornerRadius(of window: NSWindow) -> CGFloat {
                guard window.styleMask.contains(.titled), !window.styleMask.contains(.fullScreen) else { return 0 }
                if window.responds(to: NSSelectorFromString("_cornerRadius")),
                   let radius = window.value(forKey: "_cornerRadius") as? CGFloat, radius > 0 { return radius }
                return 12
            }

            func fit() {
                guard let over else { return }
                setFrame(over.frame, display: true)
                look.cornerRadius = Self.cornerRadius(of: over)
            }

            func glow(still: Bool) {
                orderFront(nil)
                look.glow(still: still)
            }

            func reveal(still: Bool) {
                isLeaving = true
                orderFront(nil)
                close(after: look.reveal(still: still))
            }

            func fade() {
                isLeaving = true
                close(after: look.fade())
            }

            private func close(after seconds: Double) {
                DispatchQueue.main.asyncAfter(deadline: .now() + seconds) {
                    MainActor.assumeIsolated {
                        self.over?.removeChildWindow(self)
                        self.orderOut(nil)
                    }
                }
            }
        }

        // TransitionLook
        /// The effect's layers, filling the window they're laid over and cut to its rounding. Core Animation runs
        /// them out of the app's process, so they keep moving while the app is busy taking the change in.
        ///
        /// While the change is built, smoke in many colors curls up from the bottom edge, thick there and thinning as
        /// it rises a third of the way up, with a faint glow round the edge: noticeable on any ground, and out of the way
        /// of most of the window. When the change goes in the smoke surges for a moment, then a level band of white,
        /// the window's width, whooshes from the bottom to the top with a soft gray shadow just ahead of it, covering the
        /// moment the new code draws and leaving the window clear behind it.
        @MainActor final class Look: NSView {
            /// The colors the smoke mixes: blue, violet, pink, orange and teal.
            static let hues: [NSColor] = [
                NSColor(red: 0.25, green: 0.5, blue: 1, alpha: 1),
                NSColor(red: 0.6, green: 0.38, blue: 1, alpha: 1),
                NSColor(red: 1, green: 0.38, blue: 0.68, alpha: 1),
                NSColor(red: 1, green: 0.6, blue: 0.22, alpha: 1),
                NSColor(red: 0.2, green: 0.82, blue: 0.9, alpha: 1),
            ]

            /// The window's own rounding, so the glow follows its corners.
            var cornerRadius: CGFloat = 12 {
                didSet {
                    guard cornerRadius != oldValue else { return }
                    layer?.cornerRadius = cornerRadius
                    arranged = .zero
                    needsLayout = true
                }
            }

            private let glowLayer = CALayer()
            private let wisps = CAEmitterLayer()
            private let band = CAGradientLayer()
            private let wash = CALayer()
            private var arranged = CGRect.zero

            override init(frame: NSRect) {
                super.init(frame: frame)
                wantsLayer = true
                autoresizingMask = [.width, .height]
                layer?.masksToBounds = true
                layer?.cornerRadius = cornerRadius
                for sublayer in [glowLayer, wash, wisps, band] {
                    sublayer.opacity = 0
                    layer?.addSublayer(sublayer)
                }
                wisps.birthRate = 0
            }

            required init?(coder: NSCoder) { nil }

            /// Every click goes through to what's under it.
            override func hitTest(_ point: NSPoint) -> NSView? { nil }

            override func setFrameSize(_ newSize: NSSize) {
                super.setFrameSize(newSize)
                needsLayout = true
            }

            override func layout() {
                super.layout()
                guard bounds != arranged, bounds.width > 0, bounds.height > 0 else { return }
                arranged = bounds
                CATransaction.begin()
                CATransaction.setDisableActions(true)
                arrange()
                CATransaction.commit()
            }

            private func arrange() {
                // Only blur, no line: each band of the glow is drawn just outside the window, where the window's own
                // rounding cuts it off, so all that shows is its shadow coming in from the edge, going round the colors.
                glowLayer.frame = bounds
                glowLayer.sublayers?.forEach { $0.removeFromSuperlayer() }
                for (blur, strength) in [(CGFloat(54), Float(0.8)), (24, 1)] {
                    let width: CGFloat = 40
                    let edge = CAShapeLayer()
                    edge.frame = bounds
                    edge.path = CGPath(roundedRect: bounds.insetBy(dx: -width / 2, dy: -width / 2), cornerWidth: cornerRadius + width / 2,
                                       cornerHeight: cornerRadius + width / 2, transform: nil)
                    edge.fillColor = nil
                    edge.strokeColor = NSColor.white.cgColor
                    edge.lineWidth = width
                    edge.shadowColor = Self.hues[0].cgColor
                    edge.shadowOpacity = strength
                    edge.shadowRadius = blur
                    edge.shadowOffset = .zero
                    let cycle = CAKeyframeAnimation(keyPath: "shadowColor")
                    cycle.values = (Self.hues + [Self.hues[0]]).map(\.cgColor)
                    cycle.duration = 5
                    cycle.repeatCount = .infinity
                    edge.add(cycle, forKey: "hue")
                    glowLayer.addSublayer(edge)
                }

                // Smoke rising from below the bottom edge, a stream of puffs for each color. How far it rises goes with
                // the window's height (speed times life, and the puffs growing), so it reaches about a third of the way
                // up at any size.
                wisps.frame = bounds
                wisps.emitterShape = .line
                wisps.emitterPosition = CGPoint(x: bounds.midX, y: -24)
                wisps.emitterSize = CGSize(width: bounds.width * 1.1, height: 0)
                let rise = bounds.height * 0.1, life: Float = 6
                wisps.emitterCells = Self.hues.enumerated().map { index, hue in
                    let cell = CAEmitterCell()
                    cell.contents = Self.puff
                    cell.color = hue.withAlphaComponent(0.42).cgColor
                    cell.redRange = 0.08; cell.greenRange = 0.08; cell.blueRange = 0.08
                    cell.birthRate = Float(bounds.width / 55)
                    cell.lifetime = life; cell.lifetimeRange = 1.5
                    cell.velocity = rise; cell.velocityRange = rise * 0.45
                    cell.emissionLongitude = .pi / 2; cell.emissionRange = 0.55
                    cell.xAcceleration = index.isMultiple(of: 2) ? 3 : -3
                    cell.scale = 0.8; cell.scaleRange = 0.35; cell.scaleSpeed = 0.16
                    cell.alphaSpeed = -0.42 / life
                    cell.spinRange = 0.6
                    return cell
                }

                // The band: the window's width and level, white through its body, fading out below where it's been, and
                // a narrow gray shadow just above its top edge, ahead of it. Its colors run from the bottom of the layer up.
                let height = max(bounds.height * 0.4, 120), shadow: CGFloat = 24
                band.frame = CGRect(x: 0, y: -height - shadow, width: bounds.width, height: height + shadow)
                band.startPoint = CGPoint(x: 0.5, y: 0)
                band.endPoint = CGPoint(x: 0.5, y: 1)
                let top = Double(height / (height + shadow))
                band.colors = [NSColor(white: 1, alpha: 0), NSColor(white: 1, alpha: 0.85), NSColor(white: 1, alpha: 1), NSColor(white: 1, alpha: 1),
                               NSColor(white: 0.35, alpha: 0.22), NSColor(white: 0.2, alpha: 0)].map(\.cgColor)
                band.locations = [0, NSNumber(value: top * 0.45), NSNumber(value: top * 0.7), NSNumber(value: top),
                                  NSNumber(value: top + 0.001), 1]

                wash.frame = bounds
                wash.backgroundColor = NSColor(white: 1, alpha: 0.35).cgColor
            }

            /// A puff of smoke: white, soft all the way to its edge, tinted by the cell that uses it.
            private static let puff: CGImage? = {
                let size = 128
                guard let context = CGContext(data: nil, width: size, height: size, bitsPerComponent: 8, bytesPerRow: 0,
                                              space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue),
                      let gradient = CGGradient(colorsSpace: nil, colors: [NSColor(white: 1, alpha: 0.9).cgColor, NSColor(white: 1, alpha: 0.45).cgColor,
                                                                           NSColor(white: 1, alpha: 0).cgColor] as CFArray, locations: [0, 0.45, 1])
                else { return nil }
                let center = CGPoint(x: size / 2, y: size / 2)
                context.drawRadialGradient(gradient, startCenter: center, startRadius: 0, endCenter: center, endRadius: CGFloat(size / 2), options: [])
                return context.makeImage()
            }()

            /// The glow and the smoke come up; where motion is reduced, only the glow, still.
            func glow(still: Bool) {
                layoutSubtreeIfNeeded()
                Self.animate(glowLayer, "opacity", from: 0, to: 0.22, duration: 0.6)
                guard !still else { return }
                Self.animate(wisps, "opacity", from: 0, to: 1, duration: 1.2)
                wisps.birthRate = 1
            }

            /// The change went in: the smoke surges and the band whooshes up (a soft wash where motion is reduced), and
            /// the glow and the smoke go. Answers how long that takes, after which the layers can go.
            func reveal(still: Bool) -> TimeInterval {
                layoutSubtreeIfNeeded()
                let glowing = glowLayer.presentation()?.opacity ?? glowLayer.opacity
                if still {
                    wisps.birthRate = 0
                    Self.animate(glowLayer, "opacity", from: glowing, to: 0, duration: 0.6)
                    Self.animate(wisps, "opacity", from: wisps.presentation()?.opacity ?? wisps.opacity, to: 0, duration: 0.6)
                    Self.animate(wash, "opacity", from: 1, to: 0, duration: 0.7)
                    return 0.8
                }
                // The smoke gathers itself, more of it and rising faster, for a moment before the whoosh. Timed by
                // animations, not by the main thread, which may be busy with the new code.
                let gather = 0.3
                wisps.opacity = 1
                Self.animate(wisps, "velocity", from: 1, to: 3.5, duration: gather, timing: CAMediaTimingFunction(name: .easeIn))
                let surge = CAKeyframeAnimation(keyPath: "birthRate")
                surge.values = [1, 3, 0]
                surge.keyTimes = [0, 0.95, 1]
                surge.duration = gather
                surge.calculationMode = .discrete
                wisps.birthRate = 0
                wisps.add(surge, forKey: "surge")

                // Then the band goes up, quickening as it goes, and the smoke and the glow go with it.
                let whoosh = 0.8
                band.opacity = 1
                Self.animate(band, "position.y", from: Float(band.position.y), to: Float(bounds.height + band.bounds.height / 2),
                             duration: whoosh, delay: gather, timing: CAMediaTimingFunction(controlPoints: 0.55, 0, 0.3, 1))
                Self.animate(wisps, "opacity", from: 1, to: 0, duration: 0.6, delay: gather + 0.1)
                Self.animate(glowLayer, "opacity", from: glowing, to: 0, duration: 0.6, delay: gather)
                return gather + whoosh + 0.2
            }

            /// The glow and the smoke go without a change going in. Answers how long that takes.
            func fade() -> TimeInterval {
                wisps.birthRate = 0
                Self.animate(glowLayer, "opacity", from: glowLayer.presentation()?.opacity ?? glowLayer.opacity, to: 0, duration: 0.5)
                Self.animate(wisps, "opacity", from: wisps.presentation()?.opacity ?? wisps.opacity, to: 0, duration: 1.0)
                return 1.1
            }

            private static func animate(_ layer: CALayer, _ key: String, from: Float, to: Float, duration: Double, delay: Double = 0,
                                        timing: CAMediaTimingFunction = CAMediaTimingFunction(name: .easeOut)) {
                let animation = CABasicAnimation(keyPath: key)
                animation.fromValue = from
                animation.toValue = to
                animation.duration = duration
                animation.timingFunction = timing
                if delay > 0 {
                    animation.beginTime = layer.convertTime(CACurrentMediaTime(), from: nil) + delay
                    animation.fillMode = .backwards
                }
                layer.setValue(to, forKey: key)
                layer.add(animation, forKey: key)
            }
        }
        // end TransitionLook
    }
    // end LampTransition

    #endif

    /// Keeps the app's data safe across launches and across changes to the app, in a SQLite database
    /// (~/Library/Application Support/<bundle id>/data.sqlite). Three ways in, simplest first:
    ///
    ///     // 1. One value, saved whole: settings, small state.
    ///     @State private var prefs = LampStore.load(Prefs.self, from: "prefs") ?? Prefs()
    ///     .onChange(of: prefs) { LampStore.save(prefs, to: "prefs") }
    ///
    ///     // 2. A collection of items, saved one at a time: notes, tasks, files seen. Scales to large lists.
    ///     let notes = LampStore.collection("notes", of: Note.self)   // Note: Codable & Identifiable
    ///     notes.put(note); notes.all(); notes.get(id); notes.delete(id)
    ///     notes.all(where: "kind", equals: "receipt", orderBy: "date", descending: true, limit: 50)
    ///
    ///     // 3. Your own tables, for joins, aggregates or full-text search.
    ///     LampStore.execute("CREATE TABLE IF NOT EXISTS visits (url TEXT, at REAL)")
    ///     LampStore.execute("INSERT INTO visits VALUES (?, ?)", url, Date().timeIntervalSince1970)
    ///     let rows = LampStore.query("SELECT url, count(*) AS n FROM visits GROUP BY url")   // [[String: Any]]
    ///
    /// Values and items are stored as JSON, so adding an optional property never breaks old data. Before the
    /// first change of each launch, the database is copied to Backups/ (the newest 20 are kept). Anything this
    /// version of the app can't read is left untouched: the user is told once, and it loads again once fixed.
    /// `folder` suits other files the app keeps, such as images (store their names, not their bytes).
    enum LampStore {
        static let folder: URL = {
            let base = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
            #if os(macOS)
            // On a Mac the data is kept under the app's plain id, whatever the app is signed as: an app made for
            // the Mac and later made for the iPhone too carries its team in its id, and its data stays where it
            // was. One that was kept under its signed id before is moved here once.
            let url = base.appendingPathComponent(LampInstall.dataID)
            if let signed = Bundle.main.bundleIdentifier, signed != LampInstall.dataID {
                let old = base.appendingPathComponent(signed)
                if FileManager.default.fileExists(atPath: old.path), !FileManager.default.fileExists(atPath: url.path) {
                    try? FileManager.default.moveItem(at: old, to: url)
                }
            }
            #else
            let url = base.appendingPathComponent(Bundle.main.bundleIdentifier ?? "{{EXE}}")
            #endif
            try? FileManager.default.createDirectory(at: url, withIntermediateDirectories: true)
            return url
        }()

        static var backups: URL { folder.appendingPathComponent("Backups") }

        // MARK: One value

        /// The saved value, or nil when there's none yet (or it can't be read; see above).
        static func load<T: Decodable>(_ type: T.Type, from name: String = "data") -> T? {
            importJSONFile(name)
            recoverIfReadable(type, name)
            guard let json = query("SELECT json FROM forge_values WHERE name = ?", name).first?["json"] as? String else {
                return nil
            }
            do {
                return try decoder.decode(T.self, from: Data(json.utf8))
            } catch {
                lock.withLock { _ = unreadable.insert(name) }
                problem("couldn't read the saved \"\(name)\", so it won't be overwritten. Make the types decode the "
                        + "existing data (add new properties as optionals), and it loads again. Error: \(error)")
                return nil
            }
        }

        /// What the user did while the saved value couldn't be read (see `save`) becomes the value again once
        /// the types read it: it's the newer of the two, and it's what they last saw. The copy that couldn't be
        /// read is kept as a backup row rather than lost.
        private static func recoverIfReadable<T: Decodable>(_ type: T.Type, _ name: String) {
            // All under the lock, so a save on another thread can't slip in between reading the copy and
            // replacing it.
            lock.withLock {
                let copy = name + " (while unreadable)"
                guard let row = query("SELECT json, updated FROM forge_values WHERE name = ?", copy).first,
                      let json = row["json"] as? String, (try? decoder.decode(T.self, from: Data(json.utf8))) != nil else { return }
                let copied = row["updated"] as? Double ?? 0
                let primary = query("SELECT updated FROM forge_values WHERE name = ?", name).first?["updated"] as? Double ?? 0
                // A copy left behind from before a relaunch can be older than what was saved since: then the
                // saved value stays, and the copy goes to the backup row instead.
                let newer = copied >= primary
                transaction {
                    execute("INSERT OR REPLACE INTO forge_values (name, json, updated) SELECT ?, json, updated FROM forge_values WHERE name = ?",
                            name + " (before recovery)", newer ? name : copy)
                    if newer { execute("INSERT OR REPLACE INTO forge_values (name, json, updated) VALUES (?, ?, ?)", name, json, copied) }
                    execute("DELETE FROM forge_values WHERE name = ?", copy)
                }
                _ = unreadable.remove(name)
            }
        }

        static func save<T: Encodable>(_ value: T, to name: String = "data") {
            guard let json = encode(value) else { return }
            if lock.withLock({ unreadable.contains(name) }) {
                // Keep what the user does now as well, without touching the data that couldn't be read.
                execute("INSERT OR REPLACE INTO forge_values (name, json, updated) VALUES (?, ?, ?)",
                        name + " (while unreadable)", json, Date().timeIntervalSince1970)
                return
            }
            execute("INSERT OR REPLACE INTO forge_values (name, json, updated) VALUES (?, ?, ?)",
                    name, json, Date().timeIntervalSince1970)
        }

        // MARK: Collections

        static func collection<T: Codable & Identifiable>(_ name: String, of type: T.Type) -> Collection<T> {
            Collection(name: name)
        }

        struct Collection<T: Codable & Identifiable> {
            let name: String

            /// Adds the item, or replaces the one with the same id.
            func put(_ item: T) {
                guard let json = LampStore.encode(item) else { return }
                LampStore.execute("INSERT OR REPLACE INTO forge_items (collection, id, json, updated) VALUES (?, ?, ?, ?)",
                                   name, "\(item.id)", json, Date().timeIntervalSince1970)
            }

            /// Adds or replaces several items in one transaction (much faster than one at a time).
            func put(_ items: [T]) {
                LampStore.transaction { items.forEach(put) }
            }

            func get(_ id: T.ID) -> T? {
                decode(LampStore.query("SELECT id, json FROM forge_items WHERE collection = ? AND id = ?", name, "\(id)")).first
            }

            func delete(_ id: T.ID) {
                LampStore.execute("DELETE FROM forge_items WHERE collection = ? AND id = ?", name, "\(id)")
            }

            func deleteAll() {
                LampStore.execute("DELETE FROM forge_items WHERE collection = ?", name)
            }

            var count: Int {
                LampStore.query("SELECT count(*) AS n FROM forge_items WHERE collection = ?", name).first?["n"] as? Int ?? 0
            }

            /// Items, optionally only those whose `field` equals `value`, sorted by a field (default: oldest
            /// change first). Fields are top-level property names; nested ones use a path like "author.name".
            func all(where field: String? = nil, equals value: Any? = nil, orderBy order: String? = nil,
                     descending: Bool = false, limit: Int? = nil) -> [T] {
                var sql = "SELECT id, json FROM forge_items WHERE collection = ?"
                var args: [Any?] = [name]
                if let field {
                    sql += " AND json_extract(json, ?) = ?"
                    args += ["$." + field, value is Bool ? ((value as! Bool) ? 1 : 0) : value]
                }
                if let order {
                    // Dates are text: one saved before fractions of a second were kept ("…:00Z") would sort
                    // after one with them ("…:00.123Z"), so such a value is read as "…:00.000Z" for sorting.
                    sql += " ORDER BY CASE WHEN json_extract(json, ?) GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z'"
                        + " THEN substr(json_extract(json, ?), 1, 19) || '.000Z' ELSE json_extract(json, ?) END"
                    args += ["$." + order, "$." + order, "$." + order]
                } else {
                    sql += " ORDER BY updated"
                }
                if descending { sql += " DESC" }
                if let limit { sql += " LIMIT \(max(0, limit))" }
                return decode(LampStore.query(sql, args))
            }

            /// Rows that can't be decoded are skipped and left as they are, never deleted.
            private func decode(_ rows: [[String: Any]]) -> [T] {
                rows.compactMap { row in
                    guard let json = row["json"] as? String else { return nil }
                    do {
                        return try LampStore.decoder.decode(T.self, from: Data(json.utf8))
                    } catch {
                        LampStore.problem("skipped an item in \"\(name)\" (id \(row["id"] ?? "?")) that couldn't be read; "
                                           + "it's kept as it is. Make the type decode it (add new properties as optionals). "
                                           + "Error: \(error)")
                        return nil
                    }
                }
            }
        }

        // MARK: SQL

        /// Runs a statement with `?` placeholders. Arguments: String, Int, Double, Bool, Date, Data or nil.
        /// Your own tables: create them with IF NOT EXISTS, and change them only by adding columns.
        @discardableResult
        static func execute(_ sql: String, _ args: Any?...) -> Bool { execute(sql, args) }

        @discardableResult
        static func execute(_ sql: String, _ args: [Any?]) -> Bool {
            lock.withLock {
                backUpOnce()
                return run(sql, args) { _ in } != nil
            }
        }

        /// Rows as dictionaries keyed by column name: Int, Double, String, Data or NSNull.
        static func query(_ sql: String, _ args: Any?...) -> [[String: Any]] { query(sql, args) }

        static func query(_ sql: String, _ args: [Any?]) -> [[String: Any]] {
            lock.withLock {
                var rows: [[String: Any]] = []
                _ = run(sql, args) { statement in
                    var row: [String: Any] = [:]
                    for column in 0..<sqlite3_column_count(statement) {
                        let key = String(cString: sqlite3_column_name(statement, column))
                        switch sqlite3_column_type(statement, column) {
                        case SQLITE_INTEGER: row[key] = Int(sqlite3_column_int64(statement, column))
                        case SQLITE_FLOAT: row[key] = sqlite3_column_double(statement, column)
                        case SQLITE_TEXT: row[key] = String(cString: sqlite3_column_text(statement, column))
                        case SQLITE_BLOB:
                            let count = Int(sqlite3_column_bytes(statement, column))
                            row[key] = count == 0 ? Data() : Data(bytes: sqlite3_column_blob(statement, column), count: count)
                        default: row[key] = NSNull()
                        }
                    }
                    rows.append(row)
                }
                return rows
            }
        }

        /// Runs `body` as one transaction: all its changes are saved together, or none are. A statement that
        /// fails inside it makes the whole transaction roll back. Transactions nest (a `put` of several items
        /// inside your own): an inner failure undoes the inner part and the outer one carries on.
        static func transaction(_ body: () -> Void) {
            lock.withLock {
                let depth = transactionDepth
                let savepoint = "lamp_\(depth)"
                if depth == 0 { backUpOnce() }   // a backup can't be taken inside a transaction
                _ = depth == 0 ? run("BEGIN", []) { _ in } : run("SAVEPOINT \(savepoint)", []) { _ in }
                transactionDepth += 1
                transactionFailed.append(false)
                afterCommit.append([])
                body()
                let failed = transactionFailed.removeLast()
                // Work waiting on this level's outcome: dropped with a rollback, otherwise handed up a level
                // (it still depends on the outer commit) or, at the top, run now.
                let pending = failed ? [] : afterCommit.removeLast()
                if failed { afterCommit.removeLast() }
                transactionDepth -= 1
                if depth == 0 {
                    // A commit can still be refused (a deferred constraint, say): then nothing was saved, the
                    // transaction is rolled back so the connection doesn't stay inside it, and the work waiting
                    // on the commit is dropped.
                    if failed {
                        _ = run("ROLLBACK", []) { _ in }
                    } else if run("COMMIT", []) { _ in } != nil {
                        pending.forEach { $0() }
                    } else {
                        _ = run("ROLLBACK", []) { _ in }
                    }
                } else {
                    if failed { _ = run("ROLLBACK TO \(savepoint)", []) { _ in } }
                    _ = run("RELEASE \(savepoint)", []) { _ in }
                    afterCommit[afterCommit.count - 1] += pending
                }
            }
        }

        // MARK: Internals

        private static let lock = NSRecursiveLock()
        nonisolated(unsafe) private static var transactionDepth = 0
        nonisolated(unsafe) private static var afterCommit: [[() -> Void]] = []   // per open transaction: work that waits for its commit
        nonisolated(unsafe) private static var transactionFailed: [Bool] = []
        nonisolated(unsafe) private static var unreadable: Set<String> = []
        nonisolated(unsafe) private static var backedUp = false
        nonisolated(unsafe) private static var warned = false

        /// Dates are saved with their fractions of a second, so a date reads back equal to what was saved
        /// (older rows without fractions still read). A number that isn't finite (a division by zero in a
        /// layout, say) is saved as text instead of failing the whole save silently.
        static let decoder: JSONDecoder = {
            let decoder = JSONDecoder()
            decoder.dateDecodingStrategy = .custom { decoder in
                let text = try decoder.singleValueContainer().decode(String.self)
                if let date = preciseDate.date(from: text) ?? plainDate.date(from: text) { return date }
                throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath, debugDescription: "Not a date: \(text)"))
            }
            decoder.nonConformingFloatDecodingStrategy = .convertFromString(positiveInfinity: "inf", negativeInfinity: "-inf", nan: "nan")
            return decoder
        }()
        private static let preciseDate: ISO8601DateFormatter = {
            let f = ISO8601DateFormatter(); f.formatOptions = [.withInternetDateTime, .withFractionalSeconds]; return f
        }()
        private static let plainDate = ISO8601DateFormatter()

        static func encode<T: Encodable>(_ value: T) -> String? {
            let encoder = JSONEncoder()
            encoder.dateEncodingStrategy = .custom { date, encoder in
                var container = encoder.singleValueContainer()
                try container.encode(preciseDate.string(from: date))
            }
            encoder.nonConformingFloatEncodingStrategy = .convertToString(positiveInfinity: "inf", negativeInfinity: "-inf", nan: "nan")
            encoder.outputFormatting = [.sortedKeys]
            do {
                return String(decoding: try encoder.encode(value), as: UTF8.self)
            } catch {
                print("LampStore: couldn't save a \(T.self): \(error)")
                return nil
            }
        }

        nonisolated(unsafe) private static let db: OpaquePointer? = {
            var db: OpaquePointer?
            let path = folder.appendingPathComponent("data.sqlite").path
            guard sqlite3_open_v2(path, &db, SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE | SQLITE_OPEN_FULLMUTEX, nil) == SQLITE_OK
            else {
                print("LampStore: couldn't open \(path)")
                return nil
            }
            sqlite3_busy_timeout(db, 5000)
            for sql in ["PRAGMA journal_mode = WAL",
                        "CREATE TABLE IF NOT EXISTS forge_values (name TEXT PRIMARY KEY, json TEXT NOT NULL, updated REAL)",
                        "CREATE TABLE IF NOT EXISTS forge_items (collection TEXT NOT NULL, id TEXT NOT NULL, json TEXT NOT NULL, "
                            + "updated REAL, PRIMARY KEY (collection, id))"] {
                sqlite3_exec(db, sql, nil, nil, nil)
            }
            return db
        }()

        /// Prepares, binds and steps one statement, calling `row` for each result row. nil on failure.
        private static func run(_ sql: String, _ args: [Any?], row: (OpaquePointer) -> Void) -> Void? {
            guard let db else { return nil }
            var statement: OpaquePointer?
            guard sqlite3_prepare_v2(db, sql, -1, &statement, nil) == SQLITE_OK, let statement else {
                print("LampStore: SQL error in \(sql): \(String(cString: sqlite3_errmsg(db)))")
                noteFailure()
                return nil
            }
            defer { sqlite3_finalize(statement) }
            let transient = unsafeBitCast(-1, to: sqlite3_destructor_type.self)
            for (index, arg) in args.enumerated() {
                let i = Int32(index + 1)
                switch arg {
                case nil, is NSNull: sqlite3_bind_null(statement, i)
                case let v as Bool: sqlite3_bind_int64(statement, i, v ? 1 : 0)
                case let v as Int: sqlite3_bind_int64(statement, i, Int64(v))
                case let v as Int64: sqlite3_bind_int64(statement, i, v)
                case let v as Double: sqlite3_bind_double(statement, i, v)
                case let v as Float: sqlite3_bind_double(statement, i, Double(v))
                case let v as Date: sqlite3_bind_double(statement, i, v.timeIntervalSince1970)
                case let v as Data: _ = v.withUnsafeBytes { sqlite3_bind_blob(statement, i, $0.baseAddress, Int32(v.count), transient) }
                case let v as String: sqlite3_bind_text(statement, i, v, -1, transient)
                case let v?: sqlite3_bind_text(statement, i, "\(v)", -1, transient)
                }
            }
            while true {
                switch sqlite3_step(statement) {
                case SQLITE_ROW: row(statement)
                case SQLITE_DONE: return ()
                default:
                    print("LampStore: SQL error in \(sql): \(String(cString: sqlite3_errmsg(db)))")
                    noteFailure()
                    return nil
                }
            }
        }

        /// A failed statement inside a transaction means that transaction rolls back at its end.
        private static func noteFailure() {
            if !transactionFailed.isEmpty { transactionFailed[transactionFailed.count - 1] = true }
        }

        /// Before the first change of each launch: a copy of the database in Backups/, keeping the newest 20.
        private static func backUpOnce() {
            guard !backedUp, let db else { return }
            backedUp = true
            let fm = FileManager.default
            var any = false
            _ = run("SELECT 1 FROM forge_values UNION ALL SELECT 1 FROM forge_items LIMIT 1", []) { _ in any = true }
            guard any else { return }
            try? fm.createDirectory(at: backups, withIntermediateDirectories: true)
            let stamp = ISO8601DateFormatter().string(from: Date()).replacingOccurrences(of: ":", with: "-")
            let target = backups.appendingPathComponent("data-\(stamp).sqlite").path
            sqlite3_exec(db, "VACUUM INTO '\(target.replacingOccurrences(of: "'", with: "''"))'", nil, nil, nil)
            let old = ((try? fm.contentsOfDirectory(at: backups, includingPropertiesForKeys: nil)) ?? [])
                .filter { $0.lastPathComponent.hasPrefix("data-20") && $0.pathExtension == "sqlite" }
                .sorted { $0.lastPathComponent > $1.lastPathComponent }
            for file in old.dropFirst(20) { try? fm.removeItem(at: file) }
        }

        /// Brings in a value saved as <name>.json by earlier versions of LampStore, once.
        private static func importJSONFile(_ name: String) {
            let file = folder.appendingPathComponent(name + ".json")
            guard let data = try? Data(contentsOf: file), let json = String(data: data, encoding: .utf8) else { return }
            // Under the (recursive) lock from the insert to the end, so the transaction the insert went into
            // is the one whose commit the archive waits for.
            lock.withLock {
            execute("INSERT OR IGNORE INTO forge_values (name, json, updated) VALUES (?, ?, ?)",
                    name, json, Date().timeIntervalSince1970)
            // Inside a transaction the insert may yet be rolled back, so the file waits for the commit:
            // moving it now would lose the value if the transaction failed.
            let archive = {
                try? FileManager.default.createDirectory(at: backups, withIntermediateDirectories: true)
                try? FileManager.default.moveItem(at: file, to: backups.appendingPathComponent("\(name)-imported.json"))
            }
            if transactionDepth == 0 { archive() } else { afterCommit[afterCommit.count - 1].append(archive) }
            }
        }

        static func problem(_ message: String) {
            print("LampStore: " + message)
            DispatchQueue.main.async {
                MainActor.assumeIsolated {
                    guard !warned else { return }
                    warned = true
                    #if os(macOS)
                    let alert = NSAlert()
                    alert.messageText = "Some saved data couldn't be opened"
                    alert.informativeText = "This version of the app can't read some data saved by an earlier one. Your data "
                        + "is safe and won't be overwritten. Choose Customize with Lamp (⇧⌘E) and ask Lamp to fix it."
                    alert.runModal()
                    #endif
                }
            }
        }
    }

    #if os(macOS)
    // Mac only: Lamp tries the app from inside it. On iPhone and iPad that is done from outside, through the Simulator.

    /// The front window as text, for Lamp's builder to read beside the picture and act on by name: one line
    /// for each thing the app's accessibility tree names, with a short id. Lamp writes the same lines for an
    /// iPhone's screen (its Simulator driver has a copy of this), so the builder learns one format: a change
    /// to one is a change to the other, and a test holds them together.
    enum LampScreen {
        struct Item: Equatable {
            var role: String          // in words: "button", "text field", "switch", …
            var label = ""
            var value = ""
            var frame: CGRect         // in the picture's pixels
            var selected = false
            var disabled = false
        }

        /// The most things listed: a full window is a few dozen, and past this the list costs more than it tells.
        static let itemLimit = 120

        /// A thing's id: a letter for its kind and a number counted within that kind, so a new label doesn't
        /// renumber the buttons.
        static func ids(for items: [Item]) -> [String] {
            var counts: [String: Int] = [:]
            return items.map { item in
                let letter = prefix(for: item.role)
                counts[letter, default: 0] += 1
                return "\(letter)\(counts[letter]!)"
            }
        }

        static func prefix(for role: String) -> String {
            switch role {
            case "button": "b"
            case "text field", "text area", "search field", "password field", "combo box": "f"
            case "text", "heading": "t"
            case "switch": "s"
            case "choice", "tab": "c"
            case "slider", "stepper": "n"
            case "picture": "i"
            case "link": "k"
            case "picker", "menu button", "menu item", "tabs": "m"
            case "row": "r"
            default: "e"
            }
        }

        /// What one thing is called when it's spoken of: `b2 (button "Add")`.
        static func name(_ item: Item, id: String) -> String {
            item.label.isEmpty ? "\(id) (\(item.role))" : "\(id) (\(item.role) \"\(item.label)\")"
        }

        enum Found: Equatable { case one(Int), none, several([String]) }

        /// The thing a `target` names: an id from the list, else the one thing with exactly that name.
        static func find(_ target: String, in items: [Item]) -> Found {
            let ids = ids(for: items)
            let wanted = plain(target)
            if let index = ids.firstIndex(where: { $0.lowercased() == wanted }) { return .one(index) }
            var matches = items.indices.filter { plain(items[$0].label) == wanted }
            // Something and its own caption are one thing: the control.
            if matches.count > 1 { matches = matches.filter { items[$0].role != "text" } }
            switch matches.count {
            case 0: return .none
            case 1: return .one(matches[0])
            default: return .several(matches.map { ids[$0] })
            }
        }

        private static func plain(_ text: String) -> String {
            text.lowercased().replacingOccurrences(of: "...", with: "…").trimmingCharacters(in: .whitespacesAndNewlines)
        }

        /// A number as a person would write it: a slider at 0.3076923 is at 0.31.
        static func number(_ value: Double) -> String {
            let rounded = (value * 100).rounded() / 100
            return rounded == rounded.rounded() ? String(Int(rounded)) : String(rounded)
        }

        /// One short line for each thing: its id, what it is, its name, what it holds, the point to aim at and
        /// its size. Nil when there's nothing with a name.
        static func text(for items: [Item]) -> String? {
            guard !items.isEmpty else { return nil }
            func short(_ text: String, _ limit: Int) -> String {
                let line = text.replacingOccurrences(of: "\n", with: " ")
                return line.count > limit ? line.prefix(limit - 1) + "…" : line
            }
            let ids = ids(for: items)
            var lines = zip(ids, items.prefix(itemLimit)).map { id, item -> String in
                var line = "\(id) \(item.role)"
                if !item.label.isEmpty { line += " \"\(short(item.label, 80))\"" }
                var value = item.value == item.label ? "" : item.value
                if item.role == "switch" { value = value == "1" ? "on" : value == "0" ? "off" : value }
                if item.role == "choice" || item.role == "button" || item.role == "tab", value == "1" || value == "0" { value = "" }
                if !value.isEmpty { line += " = \(short(value, 60))" }
                if item.selected || ((item.role == "choice" || item.role == "tab") && item.value == "1") { line += ", selected" }
                if item.disabled { line += ", dimmed" }
                return line + " @\(Int(item.frame.midX.rounded())),\(Int(item.frame.midY.rounded())) \(Int(item.frame.width.rounded()))x\(Int(item.frame.height.rounded()))"
            }
            if items.count > itemLimit { lines.append("… and \(items.count - itemLimit) more") }
            return heading + "\n" + lines.joined(separator: "\n")
        }

        static let heading = "The screen as text, in reading order. Each line is a thing's id, what it is, its name, \"= \" what it holds, " +
            "then @x,y (its middle in the picture) and its size. Act on a thing with `target` set to its id or exact name; " +
            "x and y are for what isn't listed:"
    }
    // end LampScreen

    /// Lets Lamp's builder use the app the way a person would: it clicks, types, presses keys and picks from
    /// menus in the front window, from inside the app, so no Accessibility permission is needed. An action names
    /// what it's for by `target`, an id or name from the screen as text (LampScreen, written beside each picture),
    /// and the thing is asked to press itself or take a value, the way VoiceOver would ask it; what has no such
    /// action, or isn't listed at all (a drawing), is clicked at a point, pixels in the latest picture of the
    /// window (LampRuntime.snapshot). A fresh picture and text are taken afterwards, then what happened goes to
    /// .lamp/runtime/use.json, which tells Lamp it's all ready.
    @MainActor
    enum LampDriver {
        struct Action: Decodable {
            let action: String          // click, double_click, right_click, menu, bar_icon, type, key, scroll, wait
            var target: String?         // what to act on: an id ("b2") or exact name from the screen as text
            var x: Double?
            var y: Double?
            var text: String?
            var key: String?            // "return", "escape", "cmd+a", "down"…
            var item: String?           // the menu item to pick: "Export…", "View > Zoom In"
            var amount: Double?         // scroll: points, positive is down; wait: seconds; key: seconds to hold it
            var to_x: Double?           // drag: where it ends, in the picture's pixels
            var to_y: Double?
        }

        // begin LampDriver.Handover
        /// The batch of actions being carried out, and the person's way to take the app back part way through it.
        /// Lamp's Stop (or Esc while Lamp is in front) arrives as a stop signed like the request. The person's own
        /// click or key in the app is seen here as it reaches the app: the driver's own events go straight to the
        /// window, never through the app's event queue, and the one kind that does (a key held down) is marked.
        /// Either way nothing more is done, keys held down are let go, and Lamp hears at once how far it got.
        @MainActor
        final class Handover {
            private(set) static var current: Handover?
            let id: String
            let count: Int
            /// How many of the actions have been begun.
            var done = 0
            private(set) var stopped = false
            private let finish: (String) -> Void
            private var held: [(up: NSEvent, timer: Timer)] = []
            /// When the driver's own queued presses were made: the queue keeps a press's time only to the
            /// nanosecond, so it's matched within a hair of that.
            private var own: [TimeInterval] = []
            private static var monitor: Any?

            private init(id: String, count: Int, finish: @escaping (String) -> Void) {
                self.id = id
                self.count = count
                self.finish = finish
            }

            /// A new batch. One still running is no longer carried on: its steps ask `carriesOn` first.
            static func begin(id: String, count: Int, finish: @escaping (String) -> Void) -> Handover {
                current?.letGo()
                let batch = Handover(id: id, count: count, finish: finish)
                current = batch
                watch()
                return batch
            }

            /// Whether the batch's next step may run: it wasn't stopped, and no newer batch took its place.
            var carriesOn: Bool { !stopped && Self.current === self }

            /// Every action was carried out: from now on the person's clicks and keys are just theirs.
            func end() {
                if Self.current === self { Self.current = nil }
            }

            /// A key held down by the driver: pressed now through the app's own event queue (where a game's key
            /// monitors see it) and let go after `seconds`, or at once if the batch stops first.
            func hold(_ down: NSEvent, _ up: NSEvent, for seconds: Double) {
                own.append(down.timestamp)
                NSApp.postEvent(down, atStart: false)
                let timer = Timer(timeInterval: seconds, repeats: false) { timer in
                    MainActor.assumeIsolated {
                        guard let index = self.held.firstIndex(where: { $0.timer === timer }) else { return }
                        NSApp.postEvent(self.held.remove(at: index).up, atStart: false)
                    }
                }
                RunLoop.main.add(timer, forMode: .common)
                held.append((up, timer))
            }

            /// Ends the batch where it is: nothing more is done, keys held down are let go, and Lamp is told.
            func stop() {
                guard carriesOn else { return }
                stopped = true
                letGo()
                finish("Stopped after \(done) of \(count) action\(count == 1 ? "" : "s"): the person took the app over. Nothing after that was done.")
            }

            private func letGo() {
                for key in held {
                    key.timer.invalidate()
                    NSApp.postEvent(key.up, atStart: true)
                }
                held = []
            }

            /// Lamp's Stop for batch `id`, signed with the app's token like the request, so no other process can stop it.
            static func stop(id: String?, signature: String?, token: String) {
                guard let id, let signature, let batch = current, batch.id == id else { return }
                let expected = HMAC<SHA256>.authenticationCode(for: Data("stop\n\(id)".utf8), using: SymmetricKey(data: Data(token.utf8)))
                    .map { String(format: "%02x", $0) }.joined()
                guard signature == expected else { return }
                batch.stop()
            }

            /// The person's own presses, as they reach the app, while a batch runs. Esc only stops; anything else
            /// goes on to the app as they meant it, so what they click or type isn't lost.
            private static func watch() {
                guard monitor == nil else { return }
                monitor = NSEvent.addLocalMonitorForEvents(matching: [.leftMouseDown, .rightMouseDown, .otherMouseDown, .keyDown]) { event in
                    let made = event.timestamp, escape = event.type == .keyDown && event.keyCode == 53
                    let stopped = MainActor.assumeIsolated { () -> Bool in
                        guard let batch = current, batch.carriesOn, !batch.own.contains(where: { abs($0 - made) < 0.000_01 }) else { return false }
                        batch.stop()
                        return true
                    }
                    return stopped && escape ? nil : event
                }
            }
        }
        // end LampDriver.Handover

        /// Only Lamp knows this app's token, so only Lamp can sign a request (the "lampUseAppSignature" key marks
        /// builds that check it; notifications reach every process, so the token itself never travels). Builds
        /// that take Lamp's Stop (`Handover`) have "lampUseAppStop" in them.
        static func perform(_ json: String?, id: String?, signature: String?) {
            guard let id, let json, let signature, let data = json.data(using: .utf8),
                  let actions = try? JSONDecoder().decode([Action].self, from: data) else { return }
            let key = SymmetricKey(data: Data(LampInstall.token.utf8))
            let expected = HMAC<SHA256>.authenticationCode(for: Data("\(id)\n\(json)".utf8), using: key)
                .map { String(format: "%02x", $0) }.joined()
            guard signature == expected else { return }
            barPanelUsed = Date()
            keepBarPanel()
            let front = LampRuntime.windowsOnScreen.first
            let before = front.flatMap(LampRuntime.picture), dialog = front.map(isDialog) ?? false
            var report: [String] = []
            func answer(stopped: Bool) {
                var answer = ["id": id, "report": report.joined(separator: "\n")]
                if stopped { answer["stopped"] = "person" }
                // Once the pictures are written, which Lamp reads with the answer.
                LampRuntime.snapshot {
                    try? JSONSerialization.data(withJSONObject: answer)
                        .write(to: LampRuntime.folder.appendingPathComponent("use.json"), options: .atomic)
                }
            }
            let batch = Handover.begin(id: id, count: actions.count) { why in
                // The person has the app now, the menu bar icon's panel included: it takes the keyboard again and
                // isn't put back up.
                if holdsBarPanel { forgetBarPanel() }
                report.append(why)
                answer(stopped: true)
            }
            // Which window the actions are in, before any of them and whenever an action changes it (a panel
            // opened, a dialog): Lamp's glow goes round it from the start.
            var told: Int?
            func tellWindow() {
                guard let window = LampRuntime.windowsOnScreen.first, window.windowNumber != told else { return }
                told = window.windowNumber
                announce(id, window: window.windowNumber)
            }
            tellWindow()
            // The last action that should have changed something: its line, and how its window looked before.
            var last: (line: Int, window: NSWindow, picture: Data?)?
            func note() {
                defer { last = nil }
                guard let last, LampRuntime.windowsOnScreen.first === last.window,
                      LampRuntime.picture(of: last.window) == last.picture else { return }
                report[last.line] += " (nothing changed on screen)"
            }
            /// `shown` is where Lamp's cursor was sent for this action during the pause before it, if anywhere;
            /// the spot is found again now that it's due, since the app may have moved it meanwhile.
            func step(_ index: Int, shown: Aim?) {
                guard batch.carriesOn else { return }
                keepBarPanel()
                note()
                guard index < actions.count else {
                    batch.end()
                    // Let the app react, then show the result.
                    after(0.6) {
                        keepBarPanel()
                        report.append(outcome(since: front, before, wasDialog: dialog))
                        answer(stopped: false)
                    }
                    return
                }
                let action = actions[index]
                let held = action.action == "key" ? min(action.amount ?? 0, 10) : 0
                let pause = action.action == "wait" ? min(action.amount ?? 1, 10) : action.action == "bar_icon" ? 1 : held > 0 ? held + 0.2 : 0.35
                // The cursor is on the spot already, sent there during the last pause. Where it isn't (the first
                // action; a target that wasn't on screen yet; one that has moved since, or a window that has opened
                // over it), it goes now, and the action waits the lead for it.
                var lead = 0.0
                if let aim = aimed(action), !(shown.map { $0.window == aim.window && hypot($0.point.x - aim.point.x, $0.point.y - aim.point.y) < 2 } ?? false) {
                    announce(id, aim, in: Self.lead)
                    lead = Self.lead
                }
                let due = lead + pause
                // The next step is set up first: a click that opens a save panel or an alert doesn't return until
                // that closes, and the steps after it are how it gets answered.
                var next: Aim?
                after(due) { step(index + 1, shown: next) }
                // The next action's spot is shown while this one's pause runs, so the cursor is there when it's
                // due and nothing waits for it: once the app has taken this action up (`settle`), and no sooner
                // than the glide needs, so that after a long wait the screen is read late, not at its start.
                if index + 1 < actions.count {
                    let early = max(lead + Self.settle, due - 0.95)
                    if due - early >= 0.2 {
                        after(early) {
                            guard batch.carriesOn, let aim = aimed(actions[index + 1]) else { return }
                            next = aim
                            announce(id, aim, in: due - early)
                        }
                    }
                }
                func act() {
                    guard batch.carriesOn else { return }
                    batch.done = index + 1
                    let line = report.count
                    report.append("\(action.action): opened something that waits for an answer before the app carries on")
                    if action.action != "wait", action.item == nil, let window = LampRuntime.windowsOnScreen.first,
                       !(window is NSSavePanel) {
                        last = (line, window, LampRuntime.picture(of: window))
                    }
                    report[line] = run(action)
                    if action.action != "bar_icon" { keepBarPanel() }
                    tellWindow()
                    // A menu that was only read out, or an action that found nothing to do, isn't expected to change anything.
                    if report[line].contains("\n") || report[line].contains("nothing on the screen is called that") || report[line].contains("several things are called that") { last = nil }
                }
                if lead > 0 { after(lead) { act() } } else { act() }
            }
            after(0) { step(0, shown: nil) }
        }

        /// How long an action waits for Lamp's cursor when it couldn't be sent ahead (`step`): the first of a
        /// batch, or one whose spot wasn't there to be seen during the pause before it.
        static let lead = 0.2
        /// How long after an action the next one's spot is looked for: a press is taken up on the run loop's
        /// next turn, so what it opened or changed is on screen by then.
        static let settle = 0.1

        /// Where an action happens on screen, what it's doing in a few words, which window that's in, and
        /// whether it presses there, for the cursor Lamp shows going to each spot first.
        typealias Aim = (point: CGPoint, doing: String, window: Int, press: Bool)

        /// Where an action happens on screen, what it's doing in a few words, and whether it presses there, for
        /// the cursor Lamp shows going to each spot first. Nil for what happens nowhere in particular (a key, a
        /// menu, a wait, typing into whatever has focus). The point is in screen points from the top left of the
        /// main display, as Lamp draws.
        private static func aimed(_ action: Action) -> Aim? {
            let verbs = ["click": "clicking", "double_click": "double-clicking", "right_click": "right-clicking", "drag": "dragging",
                         "scroll": "scrolling", "type": "typing into", "key": "pressing a key in"]
            let named = action.target?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false
            guard var verb = verbs[action.action], named || !["type", "key"].contains(action.action),
                  let window = LampRuntime.windowsOnScreen.first, !(window is NSSavePanel), let frame = window.contentView?.superview else { return nil }
            var x = action.x, y = action.y, name = ""
            if named, let target = action.target?.trimmingCharacters(in: .whitespacesAndNewlines) {
                let items = elements(in: window).map(\.item)
                guard case .one(let index) = LampScreen.find(target, in: items) else { return nil }
                x = items[index].frame.midX
                y = items[index].frame.midY
                name = items[index].label.count > 30 ? String(items[index].label.prefix(29)) + "…" : items[index].label
            }
            guard let x, let y else { return nil }
            if name.isEmpty { verb = verb.replacingOccurrences(of: " into", with: "").replacingOccurrences(of: " in", with: "") }
            let scale = LampRuntime.scale(of: window)
            let local = NSPoint(x: x / scale, y: frame.bounds.height - y / scale)
            guard frame.bounds.contains(local) else { return nil }
            let onScreen = window.convertPoint(toScreen: frame.convert(local, to: nil))
            let top = NSScreen.screens.first?.frame.maxY ?? 0
            return (CGPoint(x: onScreen.x, y: top - onScreen.y), name.isEmpty ? verb : verb + " " + name, window.windowNumber,
                    ["click", "double_click", "right_click", "type"].contains(action.action))
        }

        /// Tells Lamp where the next action happens and how long until it does (`in`, seconds: the cursor is paced
        /// to arrive just before), or just which window the actions are in. In the notification's object, the
        /// one part a sandboxed app may send.
        private static func announce(_ id: String, _ aim: Aim, in seconds: Double) {
            announce(id, ["x": aim.point.x, "y": aim.point.y, "doing": aim.doing, "window": aim.window, "press": aim.press, "in": seconds])
        }

        private static func announce(_ id: String, window: Int) { announce(id, ["window": window]) }

        private static func announce(_ id: String, _ fields: [String: Any]) {
            let step = fields.merging(["id": id]) { $1 }
            guard let data = try? JSONSerialization.data(withJSONObject: step) else { return }
            DistributedNotificationCenter.default().postNotificationName(
                Notification.Name(LampInstall.note + "useAppStep." + LampInstall.slug), object: String(decoding: data, as: UTF8.self),
                userInfo: nil, deliverImmediately: true)
        }

        /// Steps run from run-loop timers, not the main dispatch queue: that queue stands still while a step is
        /// inside a save panel or an alert, and with it the rest of the app.
        private static func after(_ seconds: Double, _ work: @escaping @MainActor () -> Void) {
            let timer = Timer(timeInterval: seconds, repeats: false) { _ in MainActor.assumeIsolated { work() } }
            RunLoop.main.add(timer, forMode: .common)
        }

        /// What a person would notice at a glance once the actions are done. A click that missed leaves the
        /// window looking exactly as it did, which is worth saying: otherwise the builder blames its code.
        private static func outcome(since window: NSWindow?, _ picture: Data?, wasDialog: Bool) -> String {
            guard let front = LampRuntime.windowsOnScreen.first else { return "The app has no window open now." }
            if let panel = front as? NSSavePanel { return filePanel(panel) }
            if front !== window {
                if isBarPanel(front) {
                    return "The panel behind the app's menu bar icon is open now. It's the first picture, and clicks and keys go " +
                        "to it until it closes (escape closes it)."
                }
                if isDialog(front) {
                    return "A dialog or sheet is open now. It's the first picture, and clicks and keys go to it until it closes."
                }
                let name = front.title.isEmpty ? "another window" : "\"\(front.title)\""
                return wasDialog ? "The dialog closed: \(name) is in front again." : "A different window is in front now: \(name)."
            }
            return LampRuntime.picture(of: front) == picture
                ? "Nothing in the window changed: it looks exactly as it did before these actions."
                : "The window looks different now."
        }

        private static func isDialog(_ window: NSWindow) -> Bool { window.isSheet || window is NSPanel }

        /// The panel SwiftUI shows for a MenuBarExtra with the window style.
        static func isBarPanel(_ window: NSWindow) -> Bool { String(describing: type(of: window)).contains("MenuBarExtra") }

        /// The system's open and save panels are drawn by another process, so they can't be clicked from here.
        private static func filePanel(_ panel: NSSavePanel) -> String {
            let folder = panel.directoryURL?.path ?? "an unknown folder"
            if panel is NSOpenPanel {
                return "The system's open panel is showing \(folder). It can't be used from here: press escape to cancel it."
            }
            return "The system's save panel is open, about to save \"\(panel.nameFieldStringValue)\" in \(folder). It can't be " +
                "clicked or typed in from here: press return to save there, or escape to cancel."
        }

        private static func run(_ action: Action) -> String {
            if action.action == "menu" { return menuBar(action.item) }
            if action.action == "bar_icon" { return barIcon(action.item) }
            guard let window = LampRuntime.windowsOnScreen.first, let frame = window.contentView?.superview else {
                return "\(action.action): the app has no window open"
            }
            // What the action names, found in the window's own accessibility tree: it's acted on where it has
            // an action of its own, and its middle is the point to click otherwise.
            var action = action
            var named: (item: LampScreen.Item, id: String, element: AXUIElement)?
            if let target = action.target?.trimmingCharacters(in: .whitespacesAndNewlines), !target.isEmpty, !(window is NSSavePanel) {
                let elements = elements(in: window)
                let items = elements.map(\.item)
                switch LampScreen.find(target, in: items) {
                case .one(let index):
                    named = (items[index], LampScreen.ids(for: items)[index], elements[index].element)
                    action.x = items[index].frame.midX
                    action.y = items[index].frame.midY
                case .none:
                    return "\(action.action) \"\(target)\": nothing on the screen is called that. Use an id or exact name from the " +
                        "screen as text, or x and y for what isn't listed there."
                case .several(let ids):
                    return "\(action.action) \"\(target)\": several things are called that (\(ids.joined(separator: ", "))). Use one of their ids."
                }
            }
            let what = named.map { LampScreen.name($0.item, id: $0.id) }
            // Pictures run top-down in pixels; windows run bottom-up in points.
            let scale = LampRuntime.scale(of: window)
            let point = NSPoint(x: (action.x ?? 0) / scale, y: frame.bounds.height - (action.y ?? 0) / scale)
            let size = "\(Int(frame.bounds.width * scale)) by \(Int(frame.bounds.height * scale))"
            if let panel = window as? NSSavePanel, action.action != "wait" {
                switch (action.action, action.key?.lowercased()) {
                case ("key", "return") where !(panel is NSOpenPanel), ("key", "enter") where !(panel is NSOpenPanel):
                    // The panel's own Save button answers to the real keyboard only; end it as that would.
                    if let parent = panel.sheetParent { parent.endSheet(panel, returnCode: .OK) } else { NSApp.stopModal(withCode: .OK) }
                    panel.orderOut(nil)
                    return "pressed return: saved as \(panel.url?.path ?? panel.nameFieldStringValue)"
                case ("key", "escape"):
                    panel.cancel(nil)
                    return "pressed escape: canceled the panel"
                default:
                    return "\(action.action): " + filePanel(panel)
                }
            }
            if isBarPanel(window), action.action == "key", action.key?.lowercased() == "escape" {
                releaseBarPanel()
                return "pressed escape: closed the menu bar icon's panel"
            }
            switch action.action {
            case "click", "double_click", "right_click":
                guard let x = action.x, let y = action.y else { return "\(action.action): needs a target, or x and y" }
                let label = what.map { "\(action.action) \($0): " } ?? "\(action.action) at \(Int(x)), \(Int(y)): "
                // A thing that presses itself (a button, a switch, a link, a row's disclosure) is asked to, the
                // way VoiceOver asks it, so the click can't miss. A picker's press would open its menu on the
                // user's screen, and a row's or field's is a click: those go by the point.
                if let named, action.action == "click", action.item == nil, pressable.contains(named.item.role) {
                    guard !named.item.disabled else { return label + "it's dimmed right now, so nothing happened" }
                    if AXUIElementPerformAction(named.element, kAXPressAction as CFString) == .success { return label + "pressed" }
                }
                guard frame.bounds.contains(point) else { return label + "outside the window, whose picture is \(size) pixels" }
                guard let view = frame.hitTest(point) else { return label + "nothing there" }
                if action.action == "right_click" { return label + contextMenu(of: view, at: point, in: window, pick: action.item) }
                // A pop-up button or pull-down menu: its menu would open on the user's screen and wait there.
                if let popUp = sequence(first: view, next: \.superview).first(where: { $0 is NSPopUpButton }) as? NSPopUpButton {
                    return label + self.popUp(popUp, pick: action.item)
                }
                if action.item != nil { return label + "there's no menu there, so `item` has nothing to pick from" }
                return label + click(view, at: point, in: window, count: action.action == "click" ? 1 : 2)
            case "type":
                let text = action.text ?? ""
                if let named, let what {
                    // A slider or stepper takes the number; a field takes the keyboard, with the text in place of
                    // what it held, so a value typed over "0.00" isn't "0.00120".
                    if named.item.role == "slider" || named.item.role == "stepper" {
                        guard let value = Double(text) else { return "type into \(what): give it a number" }
                        guard AXUIElementSetAttributeValue(named.element, kAXValueAttribute as CFString, value as CFTypeRef) == .success else {
                            return "type into \(what): it didn't take the number"
                        }
                        return "set \(what) to \(LampScreen.number(value))"
                    }
                    guard LampScreen.prefix(for: named.item.role) == "f" else {
                        return "type into \(what): it isn't a text field. Click it, or type into a field."
                    }
                    guard let view = frame.hitTest(point) else { return "type into \(what): nothing there" }
                    _ = click(view, at: point, in: window, count: 1)
                    // What the field holds is selected through its editor (the key for Select All belongs to
                    // the Edit menu, which not every app has), so the text typed next takes its place.
                    if let editor = window.firstResponder as? NSText { editor.selectAll(nil) } else { send("a", code: 0, flags: [.command], to: window) }
                    // Nothing to type over the selection: delete it, so an empty text clears the field.
                    if text.isEmpty { send(String(UnicodeScalar(127)), code: 51, flags: [], to: window) }
                    for character in text { send(String(character), code: 0, flags: [], to: window) }
                    return text.isEmpty ? "cleared \(what)" : "typed \"\(text)\" into \(what), in place of what it held"
                }
                for character in text { send(String(character), code: 0, flags: [], to: window) }
                return "typed \"\(text)\" into \(focus(of: window))"
            case "key":
                let name = action.key ?? ""
                guard let (characters, code, flags) = key(name) else { return "key \(name): not a key I know" }
                // Held down, as a game's controls are: pressed now and let go after `amount` seconds, through the
                // app's own event queue, where key monitors (a game's, LampScene's) see it. The app runs meanwhile.
                if let seconds = action.amount, seconds > 0, named == nil {
                    let hold = min(seconds, 10)
                    guard let down = event(.keyDown, characters, code, flags, window),
                          let up = event(.keyUp, characters, code, flags, window) else { return "key \(name): couldn't press it" }
                    guard let batch = Handover.current else { return "key \(name): couldn't press it" }
                    batch.hold(down, up, for: hold)
                    return "held \(name) for \(LampScreen.number(hold)) s, sent to \(focus(of: window))"
                }
                if let named, let what {
                    // Up and down step a slider or stepper; anything else goes to the thing once it has focus.
                    if named.item.role == "slider" || named.item.role == "stepper", name == "up" || name == "down" {
                        let stepped = AXUIElementPerformAction(named.element, (name == "up" ? kAXIncrementAction : kAXDecrementAction) as CFString) == .success
                        return stepped ? "stepped \(what) \(name)" : "key \(name): \(what) didn't take the step"
                    }
                    if let view = frame.hitTest(point) { _ = click(view, at: point, in: window, count: 1) }
                    send(characters, code: code, flags: flags, to: window)
                    return "pressed \(name) in \(what)"
                }
                // Shortcuts belong to the menu bar and to buttons (a dialog's default button takes Return), which
                // see a key before whatever has focus.
                if let event = event(.keyDown, characters, code, flags, window) {
                    if !flags.isDisjoint(with: [.command, .control]), NSApp.mainMenu?.performKeyEquivalent(with: event) == true {
                        return "pressed \(name): a menu command"
                    }
                    if window.performKeyEquivalent(with: event) { return "pressed \(name): a button's shortcut in the window" }
                }
                send(characters, code: code, flags: flags, to: window)
                return "pressed \(name), sent to \(focus(of: window))"
            case "scroll":
                guard let view = frame.hitTest(point), let cg = CGEvent(scrollWheelEvent2Source: nil, units: .pixel, wheelCount: 1,
                                                                         wheel1: Int32(-(action.amount ?? 200)), wheel2: 0, wheel3: 0),
                      let event = NSEvent(cgEvent: cg) else { return "scroll: nothing to scroll there" }
                (view.enclosingScrollView ?? view).scrollWheel(with: event)
                return "scrolled \(Int(action.amount ?? 200)) points" + (what.map { " in \($0)" } ?? "")
            case "drag":
                guard let x = action.x, let y = action.y, let toX = action.to_x, let toY = action.to_y else {
                    return "drag: needs where it starts (a target, or x and y) and where it ends (to_x and to_y)"
                }
                let end = NSPoint(x: toX / scale, y: frame.bounds.height - toY / scale)
                guard frame.bounds.contains(point), frame.bounds.contains(end) else {
                    return "drag: outside the window, whose picture is \(size) pixels"
                }
                guard let view = frame.hitTest(point) else { return "drag: nothing there" }
                drag(view, from: point, to: end, in: window)
                let dragged = "dragged from \(Int(x)), \(Int(y)) to \(Int(toX)), \(Int(toY))" + (what.map { ", starting on \($0)" } ?? "")
                if #available(macOS 27, *), !NSApp.isActive {
                    return dragged + " (the app isn't in front, so something that only answers drags won't have taken it)"
                }
                return dragged
            case "wait":
                return "waited \(action.amount ?? 1) s"
            default:
                return "\(action.action): not an action I know"
            }
        }

        // MARK: The screen as text

        /// What takes a press of its own, as VoiceOver gives one. Not a picker (its press opens a menu on the
        /// user's screen), not a field or a row (a click is how those are chosen).
        private static let pressable: Set<String> = ["button", "switch", "choice", "link", "menu item", "disclosure", "tab"]

        /// Everything in the window that the app's own accessibility tree names (what VoiceOver would read), in
        /// reading order, each with the element it was read from, which takes the presses. Read through the
        /// accessibility API on this app's own process, which needs no permission: it's the one way to see
        /// SwiftUI's elements, whose bridge to AppKit stays asleep until an accessibility client asks, and
        /// it shows AppKit's and SwiftUI's alike. Frames are in the picture's pixels.
        static func elements(in window: NSWindow) -> [(item: LampScreen.Item, element: AXUIElement)] {
            guard let frame = window.contentView?.superview, let root = axWindow(for: window) else { return [] }
            let scale = LampRuntime.scale(of: window)
            // The accessibility API counts from the top left of the main screen, pictures from the window's.
            let origin = CGPoint(x: window.frame.minX, y: (NSScreen.screens.first?.frame.maxY ?? 0) - window.frame.maxY)
            let bounds = CGRect(origin: origin, size: frame.bounds.size)
            var found: [(item: LampScreen.Item, element: AXUIElement)] = []
            func string(_ value: CFTypeRef?) -> String {
                switch value {
                case let text as String: text
                case let text as NSAttributedString: text.string
                case let number as NSNumber: LampScreen.number(number.doubleValue)
                default: ""
                }
            }
            func trimmed(_ text: String) -> String { text.trimmingCharacters(in: .whitespacesAndNewlines) }
            /// A row's words, so one row can be told from the next: what its cells say, up to three pieces.
            func words(in element: AXUIElement, depth: Int) -> [String] {
                var out: [String] = []
                guard depth < 6 else { return out }
                for child in axAttribute(element, kAXChildrenAttribute) as? [AXUIElement] ?? [] {
                    guard out.count < 3 else { break }
                    if axAttribute(child, kAXRoleAttribute) as? String == kAXStaticTextRole {
                        let text = trimmed(string(axAttribute(child, kAXValueAttribute)))
                        if !text.isEmpty { out.append(text) }
                    } else {
                        out += words(in: child, depth: depth + 1)
                    }
                }
                return out
            }
            let wanted = [kAXRoleAttribute, kAXSubroleAttribute, kAXDescriptionAttribute, kAXTitleAttribute, kAXPlaceholderValueAttribute, kAXValueAttribute,
                          kAXPositionAttribute, kAXSizeAttribute, kAXSelectedAttribute, kAXEnabledAttribute, kAXChildrenAttribute]
            // A web view's insides aren't read: each read of them waits on the main thread, where this runs, until it
            // times out, so a page froze the app for seconds. Its frame, as the accessibility API counts, tells it apart.
            // A page is looked at its own way (a screen's or a game's preview); the outline is of the app around it.
            var webViews: [CGRect] = []
            if let web = NSClassFromString("WKWebView") {
                func collect(_ view: NSView) {
                    if view.isKind(of: web) {
                        let rect = window.convertToScreen(view.convert(view.bounds, to: nil))
                        webViews.append(CGRect(x: rect.minX, y: (NSScreen.screens.first?.frame.maxY ?? 0) - rect.maxY, width: rect.width, height: rect.height))
                    } else {
                        view.subviews.forEach(collect)
                    }
                }
                if let content = window.contentView { collect(content) }
            }
            func isWebView(_ rect: CGRect) -> Bool {
                webViews.contains { abs($0.minX - rect.minX) < 2 && abs($0.minY - rect.minY) < 2 && abs($0.width - rect.width) < 2 && abs($0.height - rect.height) < 2 }
            }
            func visit(_ element: AXUIElement, depth: Int, under: Set<String>) {
                guard depth < 60, found.count < 400 else { return }
                let read = axAttributes(element, wanted)
                let role = read[0] as? String ?? "", subrole = read[1] as? String ?? ""
                var position = CGPoint.zero, size = CGSize.zero
                if let value = read[6] { AXValueGetValue(value as! AXValue, .cgPoint, &position) }
                if let value = read[7] { AXValueGetValue(value as! AXValue, .cgSize, &size) }
                let rect = CGRect(origin: position, size: size)
                var under = under
                let visible = !rect.isEmpty && bounds.contains(CGPoint(x: rect.midX, y: rect.midY))
                let control = controls.contains(role)
                // The window itself, its own buttons (close, zoom) and its title aren't the app's.
                if visible, role != kAXWindowRole, !windowOwn.contains(subrole), !(depth == 1 && role == kAXStaticTextRole) {
                    var label = trimmed([read[2], read[3], read[4]].lazy.compactMap { $0 as? String }.first { !$0.isEmpty } ?? "")
                    var value = trimmed(string(read[5]))
                    // Plain text's words are its name; a control's value is its state, named or not.
                    if label.isEmpty, !control { label = value; value = "" }
                    var captions: Set<String> = []
                    if role == kAXRowRole, label.isEmpty {
                        let pieces = words(in: element, depth: 0)
                        captions = Set(pieces)
                        label = pieces.joined(separator: " · ")
                    }
                    // A control's own caption (a button's text) is the control, not a second thing.
                    if control || (!label.isEmpty && !(role == kAXStaticTextRole && under.contains(label))) {
                        found.append((LampScreen.Item(
                            role: word(for: role, subrole), label: label, value: value,
                            frame: CGRect(x: (rect.minX - origin.x) * scale, y: (rect.minY - origin.y) * scale, width: rect.width * scale, height: rect.height * scale),
                            selected: (read[8] as? Bool) == true, disabled: (read[9] as? Bool) == false), element))
                        if control { under = captions.union([label]) }
                    }
                }
                if isWebView(rect) { return }
                for child in read[10] as? [AXUIElement] ?? [] { visit(child, depth: depth + 1, under: under) }
            }
            visit(root, depth: 0, under: [])
            return found
        }

        /// This window as the accessibility API has it: the one of this app's windows, or sheets on them, in
        /// the same place and of the same size.
        private static func axWindow(for window: NSWindow) -> AXUIElement? {
            let top = (NSScreen.screens.first?.frame.maxY ?? 0) - window.frame.maxY
            func matches(_ element: AXUIElement) -> Bool {
                var position = CGPoint.zero, size = CGSize.zero
                if let value = axAttribute(element, kAXPositionAttribute) { AXValueGetValue(value as! AXValue, .cgPoint, &position) }
                if let value = axAttribute(element, kAXSizeAttribute) { AXValueGetValue(value as! AXValue, .cgSize, &size) }
                return abs(position.x - window.frame.minX) < 2 && abs(position.y - top) < 2
                    && abs(size.width - window.frame.width) < 2 && abs(size.height - window.frame.height) < 2
            }
            let windows = axAttribute(AXUIElementCreateApplication(getpid()), kAXWindowsAttribute) as? [AXUIElement] ?? []
            // A clear window laid over this one (an overlay of the app's own) has its frame too, and nothing in it.
            let matching = windows.filter(matches)
            if let found = matching.first(where: { (axAttribute($0, kAXChildrenAttribute) as? [AXUIElement])?.isEmpty == false }) ?? matching.first {
                return found
            }
            for parent in windows {
                for child in axAttribute(parent, kAXChildrenAttribute) as? [AXUIElement] ?? [] where axAttribute(child, kAXRoleAttribute) as? String == kAXSheetRole {
                    if matches(child) { return child }
                }
            }
            return nil
        }

        private static func axAttribute(_ element: AXUIElement, _ name: String) -> CFTypeRef? {
            var value: CFTypeRef?
            return AXUIElementCopyAttributeValue(element, name as CFString, &value) == .success ? value : nil
        }

        /// Several attributes in one call; what an element doesn't have comes back as nil in its place.
        private static func axAttributes(_ element: AXUIElement, _ names: [String]) -> [CFTypeRef?] {
            var values: CFArray?
            guard AXUIElementCopyMultipleAttributeValues(element, names as CFArray, [], &values) == .success,
                  let list = values as? [AnyObject], list.count == names.count else { return names.map { axAttribute(element, $0) } }
            return list.map { value in
                if value is NSNull || (CFGetTypeID(value) == AXValueGetTypeID() && AXValueGetType(value as! AXValue) == .axError) { return nil }
                return value
            }
        }

        /// Listed even with no name: something to act on, which a name would help.
        private static let controls: Set<String> = [kAXButtonRole, kAXCheckBoxRole, kAXRadioButtonRole, kAXTextFieldRole, kAXTextAreaRole, kAXComboBoxRole,
                                                    kAXSliderRole, kAXIncrementorRole, "AXLink", kAXMenuItemRole, kAXPopUpButtonRole, kAXMenuButtonRole,
                                                    kAXRowRole, kAXDisclosureTriangleRole, kAXColorWellRole, kAXTabGroupRole]

        /// The window's own buttons, which belong to macOS.
        private static let windowOwn: Set<String> = [kAXCloseButtonSubrole, kAXMinimizeButtonSubrole, kAXZoomButtonSubrole, kAXFullScreenButtonSubrole]

        private static func word(for role: String, _ subrole: String) -> String {
            switch (role, subrole) {
            case (kAXButtonRole, _): "button"
            case (kAXRadioButtonRole, "AXTabButton"): "tab"
            case (kAXRadioButtonRole, _): "choice"
            case (kAXTextFieldRole, kAXSearchFieldSubrole): "search field"
            case (kAXTextFieldRole, kAXSecureTextFieldSubrole): "password field"
            case (kAXTextFieldRole, _): "text field"
            case (kAXTextAreaRole, _): "text area"
            case (kAXComboBoxRole, _): "combo box"
            case (kAXStaticTextRole, _): "text"
            case (kAXCheckBoxRole, _): "switch"
            case (kAXSliderRole, _): "slider"
            case (kAXImageRole, _): "picture"
            case ("AXLink", _): "link"
            case ("AXHeading", _): "heading"
            case (kAXTabGroupRole, _): "tabs"
            case (kAXPopUpButtonRole, _): "picker"
            case (kAXMenuButtonRole, _): "menu button"
            case (kAXMenuItemRole, _): "menu item"
            case (kAXIncrementorRole, _): "stepper"
            case (kAXProgressIndicatorRole, _): "progress"
            case (kAXRowRole, _): "row"
            case (kAXDisclosureTriangleRole, _): "disclosure"
            case (kAXColorWellRole, _): "color well"
            case (kAXGroupRole, _): "group"
            case (kAXListRole, _), (kAXTableRole, _), (kAXOutlineRole, _): "list"
            default: "thing"
            }
        }

        // MARK: Menus

        /// Menus are never opened: they'd appear on the user's screen and hold the app up until something is
        /// picked. Their items are read out instead, and one is picked by name.

        /// The menu bar: lists it, or picks "File > Export…".
        private static func menuBar(_ path: String?) -> String {
            guard let bar = NSApp.mainMenu else { return "menu: the app has no menu bar" }
            guard let path, !path.isEmpty else { return "menu: the menu bar has\n" + list(bar, depth: 2) }
            return "menu \"\(path)\": " + pick(path, in: bar)
        }

        /// The app's icon in the menu bar (a MenuBarExtra or status item): opens the panel behind it, or reads out
        /// and picks from its menu. The system owns the icon itself, so a click can't be sent to it; the item is
        /// asked to present instead.
        private static func barIcon(_ pick: String?) -> String {
            guard let item = LampMenuBar.statusItem else { return "bar_icon: the app has no icon in the menu bar" }
            if LampMenuBar.style == .toggle, let menu = LampMenuBar.rightClickMenu {
                let title = LampMenuBar.switchTitle
                func state() -> String { LampMenuBar.switchBinding?.wrappedValue == true ? "on" : "off" }
                if pick?.lowercased() == "click" {
                    LampMenuBar.switchBinding?.wrappedValue.toggle()
                    return "bar_icon: clicked the icon: \"\(title)\" is now \(state())"
                }
                fill(menu)
                guard let pick else {
                    return "bar_icon: a click on the icon switches \"\(title)\" (now \(state())); a right-click shows a menu with\n"
                        + list(menu, depth: 2) + "\nNothing was opened. Use bar_icon with `item` set to \"click\" to click the icon, "
                        + "or to a name to pick it from the menu."
                }
                return "bar_icon: " + self.pick(pick, in: menu)
            }
            if let menu = item.menu {
                fill(menu)
                guard let pick else {
                    return "bar_icon: the icon shows a menu with\n" + list(menu, depth: 2) +
                        "\nIt wasn't opened. To pick one, use bar_icon again with `item` set to its name."
                }
                return "bar_icon: " + self.pick(pick, in: menu)
            }
            if NSApp.windows.contains(where: { isBarPanel($0) && $0.isVisible }) {
                return "bar_icon: its panel is already open: it's the first picture. Escape closes it."
            }
            // Presenting makes this app active, and the panel closes again when it stops being active. So the app
            // the user was in gets the keyboard straight back, and the panel is put back up without it.
            let previous = NSWorkspace.shared.frontmostApplication
            let present = Selector(("_requestExpandedInterfaceSession"))
            if item.responds(to: present) { item.perform(present) } else { item.button?.performClick(nil) }
            holdsBarPanel = true
            barPanelUsed = Date()
            if let panel = NSApp.windows.first(where: isBarPanel) { setQuiet(panel, true) }   // it's kept between openings
            // As soon as the panel exists, the keyboard goes back to where it was.
            var tries = 0
            func handBack() {
                tries += 1
                guard NSApp.windows.contains(where: isBarPanel) || tries > 50 else { return after(0.02) { handBack() } }
                keepBarPanel()
                NSApp.deactivate()
                if let previous, previous != .current { previous.activate() }
                after(0.3) { keepBarPanel() }
            }
            handBack()
            // The user gets the panel back to themselves once the builder has left it alone for a while.
            let idle = Timer(timeInterval: 10, repeats: true) { timer in
                MainActor.assumeIsolated {
                    guard !holdsBarPanel || Date().timeIntervalSince(barPanelUsed) > 90 else { return }
                    releaseBarPanel()
                }
            }
            barPanelIdle?.invalidate()
            barPanelIdle = idle
            RunLoop.main.add(idle, forMode: .common)
            return "bar_icon: asked the app's menu bar icon to open"
        }

        /// Whether the builder has the icon's panel open. The panel closes itself whenever the app stops being
        /// active, which is most of the time while the builder works, so it's put back up. And while the builder
        /// has it, it can't take the keyboard: a panel can hold it even when its app isn't the active one, and
        /// would swallow what the user types elsewhere.
        private static var holdsBarPanel = false
        static var hasBarPanel: Bool { holdsBarPanel }
        /// Gives the panel back once the builder has left it alone for a while.
        private static var barPanelIdle: Timer?
        private static var barPanelUsed = Date()

        static func keepBarPanel() {
            guard holdsBarPanel, let panel = NSApp.windows.first(where: isBarPanel) else { return }
            setQuiet(panel, true)
            if panel.isKeyWindow { panel.orderOut(nil) }
            if !panel.isVisible { panel.orderFrontRegardless() }
        }

        private static func releaseBarPanel() {
            LampMenuBar.close()
            NSApp.windows.first(where: isBarPanel)?.orderOut(nil)
        }

        /// The panel has closed (the app closes it to open Settings, say), so the builder no longer has it.
        static func forgetBarPanel() {
            holdsBarPanel = false
            barPanelIdle?.invalidate()   // or it would close a panel the person opened since
            barPanelIdle = nil
            if let panel = NSApp.windows.first(where: isBarPanel) { setQuiet(panel, false) }
        }

        /// Makes a window refuse the keyboard, or accept it again. Its class's `canBecomeKey` is replaced once with
        /// one that says no for windows marked quiet and otherwise answers as before.
        private static func setQuiet(_ panel: NSWindow, _ quiet: Bool) {
            let mark = unsafeBitCast(#selector(getter: NSWindow.canBecomeKey), to: UnsafeRawPointer.self)
            objc_setAssociatedObject(panel, mark, quiet ? true : nil, .OBJC_ASSOCIATION_RETAIN)
            guard quiet, let kind: AnyClass = object_getClass(panel), !quietClasses.contains(ObjectIdentifier(kind)) else { return }
            quietClasses.insert(ObjectIdentifier(kind))
            let selector = #selector(getter: NSWindow.canBecomeKey)
            guard let before = class_getMethodImplementation(kind, selector) else { return }
            let answer = unsafeBitCast(before, to: (@convention(c) (AnyObject, Selector) -> Bool).self)
            let replacement: @convention(block) (AnyObject) -> Bool = { window in
                objc_getAssociatedObject(window, mark) != nil ? false : answer(window, selector)
            }
            class_replaceMethod(kind, selector, imp_implementationWithBlock(replacement), "c@:")
        }

        private static var quietClasses: Set<ObjectIdentifier> = []

        /// A pop-up button (a picker) or pull-down menu.
        private static func popUp(_ button: NSPopUpButton, pick path: String?) -> String {
            guard let menu = button.menu else { return "a menu with nothing in it" }
            // SwiftUI builds a Menu's items when its button is about to show them.
            let willShow = Selector(("popUpButtonCell:willShowMenu:"))
            if let builder = menu.delegate as? NSObject, builder.responds(to: willShow) { builder.perform(willShow, with: button.cell, with: menu) }
            fill(menu)
            guard menu.items.count > (button.pullsDown ? 1 : 0) else { return "a menu whose items can't be read from here" }
            let kind = button.pullsDown ? "a pull-down menu" : "a pop-up menu, now set to \"\(button.titleOfSelectedItem ?? "")\","
            guard let path else {
                return "\(kind) with\n" + list(menu, depth: 2, skipFirst: button.pullsDown) +
                    "\nIt wasn't opened. To pick one, click here again with `item` set to its name."
            }
            // A picker's items have no action of their own: choosing one is selecting it.
            if !button.pullsDown, let index = menu.items.firstIndex(where: { matches($0, path) }), menu.items[index].isEnabled {
                button.selectItem(at: index)
                if let action = menu.items[index].action {
                    NSApp.sendAction(action, to: menu.items[index].target, from: menu.items[index])
                } else if let action = button.action {
                    NSApp.sendAction(action, to: button.target, from: button)
                }
                return "\(kind) picked \"\(menu.items[index].title)\""
            }
            return "\(kind) " + pick(path, in: menu)
        }

        /// The menu a right-click would show.
        private static func contextMenu(of view: NSView, at point: NSPoint, in window: NSWindow, pick path: String?) -> String {
            guard let event = NSEvent.mouseEvent(with: .rightMouseDown, location: point, modifierFlags: [],
                                                 timestamp: ProcessInfo.processInfo.systemUptime, windowNumber: window.windowNumber,
                                                 context: nil, eventNumber: 0, clickCount: 1, pressure: 1),
                  let menu = sequence(first: view, next: \.superview).lazy.compactMap({ $0.menu(for: event) }).first else {
                return "no menu appears there"
            }
            fill(menu)
            guard let path else {
                return "a menu with\n" + list(menu, depth: 2) + "\nIt wasn't opened. To pick one, right_click here again with `item` set to its name."
            }
            return pick(path, in: menu)
        }

        /// Menus fill themselves in just before they open.
        private static func fill(_ menu: NSMenu) {
            menu.delegate?.menuNeedsUpdate?(menu)
            menu.update()
        }

        private static func matches(_ item: NSMenuItem, _ name: String) -> Bool {
            func plain(_ text: String) -> String {
                text.lowercased().replacingOccurrences(of: "...", with: "…").trimmingCharacters(in: .whitespaces)
            }
            return !item.isSeparatorItem && (plain(item.title) == plain(name) || plain(item.title) == plain(name) + "…")
        }

        /// Picks "Item" or "Submenu > Item" from a menu, the way choosing it by hand would.
        private static func pick(_ path: String, in menu: NSMenu) -> String {
            var menu = menu
            let names = path.components(separatedBy: ">").map { $0.trimmingCharacters(in: .whitespaces) }
            for (position, name) in names.enumerated() {
                fill(menu)
                guard let index = menu.items.firstIndex(where: { matches($0, name) }) else {
                    return "there's no \"\(name)\" there. It has\n" + list(menu, depth: 1)
                }
                let item = menu.items[index]
                if position < names.count - 1 {
                    guard let submenu = item.submenu else { return "\"\(item.title)\" has no submenu" }
                    menu = submenu
                } else if let submenu = item.submenu {
                    fill(submenu)
                    return "\"\(item.title)\" is a submenu with\n" + list(submenu, depth: 1)
                } else {
                    guard item.isEnabled else { return "\"\(item.title)\" is grayed out right now" }
                    menu.performActionForItem(at: index)
                    return "picked \"\(item.title)\""
                }
            }
            return "nothing to pick"
        }

        /// A menu's items, one per line, with what's ticked or grayed out.
        private static func list(_ menu: NSMenu, depth: Int, indent: String = "  ", skipFirst: Bool = false) -> String {
            var lines: [String] = []
            // A pull-down menu's first item is its own title.
            for item in menu.items.dropFirst(skipFirst ? 1 : 0) where !item.isSeparatorItem && !item.isHidden && !item.title.isEmpty {
                var line = indent + "\"\(item.title)\""
                if item.state == .on { line += " (ticked)" }
                if !item.isEnabled, item.submenu == nil { line += " (grayed out)" }
                if !item.keyEquivalent.isEmpty, item.submenu == nil { line += "  " + shortcut(item) }
                lines.append(line)
                if let submenu = item.submenu, depth > 1, lines.count < 80 {
                    fill(submenu)
                    lines.append(list(submenu, depth: depth - 1, indent: indent + "  "))
                } else if item.submenu != nil {
                    lines[lines.count - 1] += " ▸"
                }
            }
            return lines.filter { !$0.isEmpty }.prefix(80).joined(separator: "\n")
        }

        private static func shortcut(_ item: NSMenuItem) -> String {
            var keys: [String] = []
            if item.keyEquivalentModifierMask.contains(.control) { keys.append("ctrl") }
            if item.keyEquivalentModifierMask.contains(.option) { keys.append("option") }
            if item.keyEquivalentModifierMask.contains(.shift) || item.keyEquivalent != item.keyEquivalent.lowercased() { keys.append("shift") }
            if item.keyEquivalentModifierMask.contains(.command) { keys.append("cmd") }
            return (keys + [item.keyEquivalent.lowercased()]).joined(separator: "+")
        }

        // MARK: Clicks and keys

        /// Presses at one point, moves in steps to another and lets go. The moves and the release are queued before
        /// the press, so a control that follows the mouse in a loop of its own (a slider, a split view's divider)
        /// reads them as they come; whatever is left is handed to the view, which is how SwiftUI's drag gestures
        /// (a canvas, a game, a 3D scene) take them.
        private static func drag(_ view: NSView, from start: NSPoint, to end: NSPoint, in window: NSWindow) {
            let begun = ProcessInfo.processInfo.systemUptime
            func event(_ type: NSEvent.EventType, _ point: NSPoint, _ step: Int) -> NSEvent? {
                NSEvent.mouseEvent(with: type, location: point, modifierFlags: [], timestamp: begun + Double(step) * 0.016,
                                   windowNumber: window.windowNumber, context: nil, eventNumber: 0, clickCount: 1,
                                   pressure: type == .leftMouseUp ? 0 : 1)
            }
            guard let down = event(.leftMouseDown, start, 0) else { return }
            let steps = 16
            for i in 1...steps {
                let t = CGFloat(i) / CGFloat(steps)
                if let moved = event(.leftMouseDragged, NSPoint(x: start.x + (end.x - start.x) * t, y: start.y + (end.y - start.y) * t), i) {
                    NSApp.postEvent(moved, atStart: false)
                }
            }
            if let up = event(.leftMouseUp, end, steps + 1) { NSApp.postEvent(up, atStart: false) }
            // From macOS 27 SwiftUI's gestures take the pointer only as the window dispatches it, and only in the key
            // window, as with a click.
            if #available(macOS 27, *) {
                asKey(window) {
                    window.sendEvent(down)
                    while let next = NSApp.nextEvent(matching: [.leftMouseDragged, .leftMouseUp], until: .distantPast, inMode: .default, dequeue: true) {
                        window.sendEvent(next)
                        if next.type == .leftMouseUp { break }
                    }
                }
                return
            }
            view.mouseDown(with: down)
            while let next = NSApp.nextEvent(matching: [.leftMouseDragged, .leftMouseUp], until: .distantPast, inMode: .default, dequeue: true) {
                if next.type == .leftMouseUp { view.mouseUp(with: next); break }
                view.mouseDragged(with: next)
            }
        }

        /// A tap or drag gesture takes the pointer only in the key window, as a real press makes it. A panel that had
        /// the keyboard (the chat beside the window) gets it back, so what the person types there stays there.
        private static func asKey(_ window: NSWindow, _ body: () -> Void) {
            let keyBefore = NSApp.keyWindow
            if NSApp.isActive, !window.isKeyWindow, window.canBecomeKey { window.makeKey() }
            body()
            if let keyBefore, keyBefore !== window, keyBefore is NSPanel, keyBefore.isVisible { keyBefore.makeKey() }
        }

        private static func click(_ view: NSView, at point: NSPoint, in window: NSWindow, count: Int) -> String {
            for n in 1...count {
                func event(_ type: NSEvent.EventType) -> NSEvent? {
                    NSEvent.mouseEvent(with: type, location: point, modifierFlags: [], timestamp: ProcessInfo.processInfo.systemUptime,
                                       windowNumber: window.windowNumber, context: nil, eventNumber: 0, clickCount: n,
                                       pressure: type == .leftMouseDown ? 1 : 0)
                }
                guard let down = event(.leftMouseDown), let up = event(.leftMouseUp) else { return "couldn't click" }
                // AppKit controls (buttons, fields, column headers) track the mouse and take the mouse-up from the
                // event queue. SwiftUI's own views (plain buttons, toggles) leave it there and want it handed to them.
                // From macOS 27 SwiftUI presses nothing for a click handed straight to its view, only for one the
                // window dispatches, which reaches it whether or not the window is key; before, through the window a
                // click on an inactive window would only activate it, so it went straight to the view.
                NSApp.postEvent(up, atStart: true)
                if #available(macOS 27, *) {
                    asKey(window) {
                        window.sendEvent(down)
                        if let unused = NSApp.nextEvent(matching: .leftMouseUp, until: .distantPast, inMode: .default, dequeue: true) {
                            window.sendEvent(unused)
                        }
                    }
                } else {
                    view.mouseDown(with: down)
                    if let unused = NSApp.nextEvent(matching: .leftMouseUp, until: .distantPast, inMode: .default, dequeue: true) {
                        view.mouseUp(with: unused)
                    }
                }
            }
            // A row of a list, table or sidebar: AppKit only selects rows while the real mouse is held down, so
            // select it directly. A double-click opens the row, as Return does.
            if let table = sequence(first: view, next: \.superview).first(where: { $0 is NSTableView }) as? NSTableView,
               view === table || !(view is NSControl) {
                let row = table.row(at: table.convert(point, from: nil))
                guard row >= 0 else { return "an empty part of a list" }
                window.makeFirstResponder(table)
                guard table.delegate?.tableView?(table, shouldSelectRow: row) != false else {
                    return "row \(row + 1) of a list, which can't be selected"
                }
                table.selectRowIndexes([row], byExtendingSelection: false)
                guard count == 2 else { return "row \(row + 1) of a list, now selected" }
                send("\r", code: 36, flags: [], to: window)
                return "row \(row + 1) of a list, selected and opened"
            }
            if #available(macOS 27, *), !NSApp.isActive {
                return describe(view) + " (the app isn't in front, so something that only answers taps won't have taken the click)"
            }
            return describe(view)
        }

        /// A short name for what was clicked, when AppKit can say.
        private static func describe(_ view: NSView) -> String {
            switch view {
            case let button as NSButton: return button.title.isEmpty ? "a button" : "the \"\(button.title)\" button"
            case is NSTextField, is NSTextView: return "a text field"
            case is NSTableHeaderView: return "a column header"
            case is NSSegmentedControl: return "a segmented control"
            case is NSSlider: return "a slider"
            default: return "the app's content"
            }
        }

        /// What typing and keys go to.
        private static func focus(of window: NSWindow) -> String {
            switch window.firstResponder {
            case is NSText: return "a text field"
            case is NSTableView: return "a list"
            case nil, is NSWindow: return "the window (nothing has keyboard focus: click a text field or list first)"
            default: return "the app's content"
            }
        }

        private static func event(_ type: NSEvent.EventType, _ characters: String, _ code: UInt16, _ flags: NSEvent.ModifierFlags,
                                  _ window: NSWindow) -> NSEvent? {
            NSEvent.keyEvent(with: type, location: .zero, modifierFlags: flags, timestamp: ProcessInfo.processInfo.systemUptime,
                             windowNumber: window.windowNumber, context: nil, characters: characters,
                             charactersIgnoringModifiers: characters, isARepeat: false, keyCode: code)
        }

        private static func send(_ characters: String, code: UInt16, flags: NSEvent.ModifierFlags, to window: NSWindow) {
            for type in [NSEvent.EventType.keyDown, .keyUp] {
                if let event = event(type, characters, code, flags, window) { window.sendEvent(event) }
            }
        }

        /// "cmd+shift+z" → characters, key code and modifier flags.
        private static func key(_ name: String) -> (String, UInt16, NSEvent.ModifierFlags)? {
            var parts = name.lowercased().split(separator: "+").map(String.init)
            guard let last = parts.popLast() else { return nil }
            var flags: NSEvent.ModifierFlags = []
            for part in parts {
                switch part {
                case "cmd", "command": flags.insert(.command)
                case "shift": flags.insert(.shift)
                case "option", "alt": flags.insert(.option)
                case "ctrl", "control": flags.insert(.control)
                default: return nil
                }
            }
            func scalar(_ value: Int) -> String { String(UnicodeScalar(UInt32(value))!) }
            let keys: [String: (String, UInt16)] = [
                "return": ("\r", 36), "enter": ("\r", 36), "tab": ("\t", 48), "space": (" ", 49), "delete": (scalar(127), 51),
                "escape": (scalar(27), 53), "left": (scalar(NSLeftArrowFunctionKey), 123), "right": (scalar(NSRightArrowFunctionKey), 124),
                "down": (scalar(NSDownArrowFunctionKey), 125), "up": (scalar(NSUpArrowFunctionKey), 126),
            ]
            if let (characters, code) = keys[last] { return (characters, code, flags) }
            guard last.count == 1 else { return nil }
            // A letter or digit's own key on a US keyboard, as a game reading key codes (LampScene's W A S D) expects.
            let codes: [Character: UInt16] = ["a": 0, "s": 1, "d": 2, "f": 3, "h": 4, "g": 5, "z": 6, "x": 7, "c": 8, "v": 9,
                "b": 11, "q": 12, "w": 13, "e": 14, "r": 15, "y": 16, "t": 17, "1": 18, "2": 19, "3": 20, "4": 21, "6": 22,
                "5": 23, "9": 25, "7": 26, "8": 28, "0": 29, "o": 31, "u": 32, "i": 34, "p": 35, "l": 37, "j": 38, "k": 40,
                "n": 45, "m": 46]
            return (last, codes[Character(last)] ?? 0, flags)
        }
    }

    #endif


    // MARK: - iCloud

    /// Keeps the person's data the same on every device signed in to their iCloud account: an app for both
    /// the Mac and the iPhone shows one list on both, and an iPhone & iPad app the same on each device. Lamp
    /// signs the app for iCloud when capabilities.json says `{"icloud": true}` (Template.Capabilities writes
    /// the entitlements and names the container in Info.plist); without that, or with no iCloud account on
    /// the device, the data stays on the device and `status` says so.
    ///
    ///     @StateObject private var notes = LampSync.collection("notes", of: Note.self)
    ///     notes.items          // [Note]; the view follows changes made here or on another device
    ///     notes.put(note)      // add, or replace the one with the same id
    ///     notes.delete(id)
    ///     LampSync.shared.status   // "Synced with iCloud", or why not, for a settings screen
    ///
    /// Each collection is kept on the device in LampStore as well, so the app works offline and before its
    /// first sync. iCloud's own engine (CKSyncEngine) sends what changed here and brings what changed
    /// elsewhere, in a zone of the app's own in the person's private database. The same item changed in two
    /// places at once: the later change wins. An item is a record with its JSON, so adding a property to a
    /// saved type is safe (decode it with a default) and removing or renaming one is not, as with LampStore.
    @MainActor
    final class LampSync: NSObject, ObservableObject, CKSyncEngineDelegate {
        static let shared = LampSync()

        /// What iCloud is doing for this app, in words for a settings screen.
        @Published private(set) var status = "Starting iCloud…"
        /// Whether the app was built for iCloud (capabilities.json) and the device has an account.
        @Published private(set) var isSyncing = false

        /// The one object for a collection's name, so every view that asks sees the same items.
        static func collection<T: Codable & Identifiable>(_ name: String, of type: T.Type) -> Collection<T> {
            if let existing = shared.collections[name] as? Collection<T> { return existing }
            let collection = Collection<T>(name: name)
            shared.collections[name] = collection
            return collection
        }

        /// A list of one kind of thing, kept here and in iCloud.
        final class Collection<T: Codable & Identifiable>: ObservableObject, LampSyncedCollection {
            let name: String
            @Published private(set) var items: [T] = []
            private let local: LampStore.Collection<T>

            init(name: String) {
                self.name = name
                local = LampStore.collection(LampSync.prefix + name, of: T.self)
                items = local.all()
            }

            /// Adds the item, or replaces the one with the same id, here and then everywhere.
            func put(_ item: T) {
                local.put(item)
                replace(item)
                LampSync.shared.changed(name, id: "\(item.id)", deleted: false)
            }

            func delete(_ id: T.ID) {
                local.delete(id)
                items.removeAll { "\($0.id)" == "\(id)" }
                LampSync.shared.changed(name, id: "\(id)", deleted: true)
            }

            func get(_ id: T.ID) -> T? { items.first { "\($0.id)" == "\(id)" } }

            var count: Int { items.count }

            private func replace(_ item: T) {
                if let index = items.firstIndex(where: { "\($0.id)" == "\(item.id)" }) { items[index] = item } else { items.append(item) }
            }

            // What the engine needs of a collection whose type it doesn't know.
            func reload(id: String) {
                guard let json = LampStore.query("SELECT json FROM forge_items WHERE collection = ? AND id = ?", LampSync.prefix + name, id).first?["json"] as? String,
                      let data = json.data(using: .utf8), let item = try? LampStore.decoder.decode(T.self, from: data) else { return }
                replace(item)
            }

            func forget(id: String) { items.removeAll { "\($0.id)" == id } }
        }

        // MARK: The engine

        static let prefix = "icloud."
        private var collections: [String: any LampSyncedCollection] = [:]
        private var engine: CKSyncEngine?
        private var container: CKContainer?
        private let zoneID = CKRecordZone.ID(zoneName: "Lamp", ownerName: CKCurrentUserDefaultName)
        /// Each record as iCloud last saw it (its system fields, archived), so a change is sent as a change
        /// to that record and not as a second copy of it.
        private var known: [String: Data] = [:]

        private override init() {
            super.init()
            guard let identifier = Bundle.main.object(forInfoDictionaryKey: "LampICloudContainer") as? String else {
                status = "Not set up for iCloud: declare {\"icloud\": true} in capabilities.json and build again. The data stays on this device."
                return
            }
            let container = CKContainer(identifier: identifier)
            self.container = container
            known = LampStore.load([String: Data].self, from: "icloud.records") ?? [:]
            let state = LampStore.load(CKSyncEngine.State.Serialization.self, from: "icloud.state")
            var configuration = CKSyncEngine.Configuration(database: container.privateCloudDatabase, stateSerialization: state, delegate: self)
            configuration.automaticallySync = true
            let engine = CKSyncEngine(configuration)
            self.engine = engine
            engine.state.add(pendingDatabaseChanges: [.saveZone(CKRecordZone(zoneID: zoneID))])
            Task {
                await checkAccount()
                // Asked for straight away rather than left to the engine's own timing, so a fresh install
                // shows what's in iCloud as soon as it can.
                do { try await engine.fetchChanges() } catch { print("LampSync: couldn't fetch from iCloud: \(error)") }
            }
        }

        private func checkAccount() async {
            guard let container else { return }
            do {
                let account = try await container.accountStatus()
                isSyncing = account == .available
                status = switch account {
                case .available: "Synced with iCloud"
                case .noAccount: "Not signed in to iCloud on this device, so the data stays here. Sign in under System Settings to sync it."
                case .restricted: "iCloud is restricted on this device, so the data stays here."
                case .temporarilyUnavailable: "iCloud isn't available right now; the data stays here until it is."
                default: "Couldn't tell whether iCloud is available; the data stays here for now."
                }
            } catch {
                isSyncing = false
                status = "iCloud isn't reachable: \(error.localizedDescription). The data stays here for now."
            }
            print("LampSync: \(status)")
        }

        /// Something changed here: iCloud is told at its next send.
        fileprivate func changed(_ collection: String, id: String, deleted: Bool) {
            guard let engine else { return }
            let recordID = CKRecord.ID(recordName: Self.recordName(collection, id), zoneID: zoneID)
            engine.state.add(pendingRecordZoneChanges: [deleted ? .deleteRecord(recordID) : .saveRecord(recordID)])
            // Sent now, not at the engine's leisure: the other device should see it within moments.
            Task { do { try await engine.sendChanges() } catch { print("LampSync: couldn't send to iCloud: \(error)") } }
        }

        /// A record is named by its collection and its id, so one it comes back to can be found.
        static func recordName(_ collection: String, _ id: String) -> String { collection + "|" + id }
        static func parse(recordName: String) -> (collection: String, id: String)? {
            guard let bar = recordName.firstIndex(of: "|") else { return nil }
            return (String(recordName[..<bar]), String(recordName[recordName.index(after: bar)...]))
        }

        /// Everything kept here goes up again: after a sign-in, or when the zone in iCloud was deleted.
        private func resendEverything() {
            guard let engine else { return }
            known = [:]
            LampStore.save(known, to: "icloud.records")
            engine.state.add(pendingDatabaseChanges: [.saveZone(CKRecordZone(zoneID: zoneID))])
            let rows = LampStore.query("SELECT collection, id FROM forge_items WHERE collection LIKE ?", Self.prefix + "%")
            let changes = rows.compactMap { row -> CKSyncEngine.PendingRecordZoneChange? in
                guard let collection = row["collection"] as? String, let id = row["id"] as? String else { return nil }
                return .saveRecord(CKRecord.ID(recordName: Self.recordName(String(collection.dropFirst(Self.prefix.count)), id), zoneID: zoneID))
            }
            engine.state.add(pendingRecordZoneChanges: changes)
        }

        /// The record to send for a change: the item's JSON on the record iCloud knows, or on a new one, with
        /// the time the item was changed here, so a conflict is settled by when the edits were made and not
        /// by when they happened to be sent.
        private func record(for recordID: CKRecord.ID) -> CKRecord? {
            guard let (collection, id) = Self.parse(recordName: recordID.recordName),
                  let row = LampStore.query("SELECT json, updated FROM forge_items WHERE collection = ? AND id = ?", Self.prefix + collection, id).first,
                  let json = row["json"] as? String
            else { return nil }   // deleted here since: nothing to send
            let modified = (row["updated"] as? Double).map { Date(timeIntervalSince1970: $0) } ?? Date()
            let record: CKRecord
            if let data = known[recordID.recordName], let unarchiver = try? NSKeyedUnarchiver(forReadingFrom: data),
               let kept = CKRecord(coder: unarchiver) {
                record = kept
            } else {
                record = CKRecord(recordType: "LampItem", recordID: recordID)
            }
            record["collection"] = collection as CKRecordValue
            record["json"] = json as CKRecordValue
            record["modified"] = modified as CKRecordValue
            return record
        }

        /// A record from iCloud, taken as this device's copy of the item, unless this device has a newer
        /// edit of it still to be sent: that one stays, and goes up as a change to the record iCloud has.
        private func apply(_ record: CKRecord) {
            guard let (collection, id) = Self.parse(recordName: record.recordID.recordName),
                  let json = record["json"] as? String else { return }
            let theirs = record["modified"] as? Date ?? Date()
            if let engine, engine.state.pendingRecordZoneChanges.contains(.saveRecord(record.recordID)),
               let updated = LampStore.query("SELECT updated FROM forge_items WHERE collection = ? AND id = ?", Self.prefix + collection, id).first?["updated"] as? Double,
               Date(timeIntervalSince1970: updated) > theirs {
                remember(record)
                return
            }
            LampStore.execute("INSERT OR REPLACE INTO forge_items (collection, id, json, updated) VALUES (?, ?, ?, ?)",
                              Self.prefix + collection, id, json, theirs.timeIntervalSince1970)
            collections[collection]?.reload(id: id)
            remember(record)
        }

        private func remove(_ recordID: CKRecord.ID) {
            guard let (collection, id) = Self.parse(recordName: recordID.recordName) else { return }
            LampStore.execute("DELETE FROM forge_items WHERE collection = ? AND id = ?", Self.prefix + collection, id)
            collections[collection]?.forget(id: id)
            known[recordID.recordName] = nil
        }

        private func remember(_ record: CKRecord) {
            let archiver = NSKeyedArchiver(requiringSecureCoding: true)
            record.encodeSystemFields(with: archiver)
            known[record.recordID.recordName] = archiver.encodedData
        }

        // MARK: CKSyncEngineDelegate

        func handleEvent(_ event: CKSyncEngine.Event, syncEngine: CKSyncEngine) async {
            switch event {
            case .stateUpdate(let update):
                LampStore.save(update.stateSerialization, to: "icloud.state")
            case .accountChange(let change):
                switch change.changeType {
                case .signIn: resendEverything()
                case .signOut, .switchAccounts:
                    // The data stays, as this device's; the next account gets it sent afresh.
                    known = [:]
                    LampStore.save(known, to: "icloud.records")
                @unknown default: break
                }
                await checkAccount()
            case .fetchedDatabaseChanges(let changes):
                // The zone deleted from iCloud (the person cleared the app's data there): what's here goes up again.
                if changes.deletions.contains(where: { $0.zoneID == zoneID }) { resendEverything() }
            case .fetchedRecordZoneChanges(let changes):
                for modification in changes.modifications { apply(modification.record) }
                for deletion in changes.deletions { remove(deletion.recordID) }
                LampStore.save(known, to: "icloud.records")
            case .sentDatabaseChanges(let sent):
                for (zone, error) in sent.failedZoneSaves.map({ ($0.zone.zoneID.zoneName, $0.error) }) { print("LampSync: couldn't make the zone \(zone) in iCloud: \(error)") }
            case .sentRecordZoneChanges(let sent):
                for record in sent.savedRecords { remember(record) }
                for failure in sent.failedRecordSaves {
                    let recordID = failure.record.recordID
                    if failure.error.code != .serverRecordChanged { print("LampSync: couldn't save \(recordID.recordName) to iCloud: \(failure.error)") }
                    switch failure.error.code {
                    case .serverRecordChanged:
                        // Changed elsewhere meanwhile: the later change wins, and the loser is told.
                        guard let server = failure.error.serverRecord else { break }
                        let mine = failure.record["modified"] as? Date ?? .distantPast
                        let theirs = server["modified"] as? Date ?? .distantPast
                        if mine > theirs {
                            server["json"] = failure.record["json"]
                            server["collection"] = failure.record["collection"]
                            server["modified"] = mine as CKRecordValue
                            remember(server)
                            syncEngine.state.add(pendingRecordZoneChanges: [.saveRecord(recordID)])
                        } else {
                            apply(server)
                        }
                    case .zoneNotFound:
                        syncEngine.state.add(pendingDatabaseChanges: [.saveZone(CKRecordZone(zoneID: zoneID))])
                        syncEngine.state.add(pendingRecordZoneChanges: [.saveRecord(recordID)])
                    case .unknownItem:
                        // iCloud no longer has the record it was a change to: sent again as a new one.
                        known[recordID.recordName] = nil
                        syncEngine.state.add(pendingRecordZoneChanges: [.saveRecord(recordID)])
                    default: break
                    }
                }
                for recordID in sent.deletedRecordIDs { known[recordID.recordName] = nil }
                LampStore.save(known, to: "icloud.records")
            default:
                break
            }
        }

        func nextRecordZoneChangeBatch(_ context: CKSyncEngine.SendChangesContext, syncEngine: CKSyncEngine) async -> CKSyncEngine.RecordZoneChangeBatch? {
            let scope = context.options.scope
            let changes = syncEngine.state.pendingRecordZoneChanges.filter { scope.contains($0) }
            guard !changes.isEmpty else { return nil }
            return await CKSyncEngine.RecordZoneChangeBatch(pendingChanges: changes) { recordID in
                await self.record(for: recordID)
            }
        }
    }

    /// A collection as the engine sees it, whatever its items' type.
    @MainActor
    protocol LampSyncedCollection: AnyObject {
        func reload(id: String)
        func forget(id: String)
    }


    // MARK: - Health

    // Apple TV hasn't this framework.
    #if !os(tvOS)
    /// The person's Health data (steps, heart rate, sleep, workouts, weight, what they ate and drank), read and
    /// written through HealthKit on an iPhone or iPad, once capabilities.json says `{"healthkit": true}`. A
    /// Mac has no Health data of its own (`isAvailable` is false there), so an app for both reads on the
    /// iPhone and keeps what the Mac shows in LampSync. The simulator has HealthKit but no data: save a sample
    /// to have something to read.
    ///
    ///     try await LampHealth.authorize(read: [.steps, .heartRate, .sleep], write: [.caloriesEaten])
    ///     let steps = try await LampHealth.total(.steps)                 // today's
    ///     let rate = try await LampHealth.latest(.heartRate)?.value     // beats per minute
    ///     let hours = try await LampHealth.sleep()                      // last night, asleep
    ///     let week = try await LampHealth.dailyTotals(.activeCalories, days: 7)
    ///     let runs = try await LampHealth.workouts(days: 7)
    ///     try await LampHealth.save(.caloriesEaten, 350)               // logged now
    ///
    /// Every value is in the unit `Kind.unitName` says (steps, km, kcal, bpm, kg, cm, %, ml, mg, g, hours).
    /// Each call throws a plain message when Health isn't available or the person hasn't allowed it.
    enum LampHealth {
        enum Kind: String, CaseIterable, Codable {
            case steps, distance, flightsClimbed, activeCalories, restingCalories, exerciseMinutes, standHours
            case heartRate, restingHeartRate, heartRateVariability, bloodOxygen, respiratoryRate, bodyTemperature
            case weight, height, bodyFat, bodyMassIndex, waistCircumference
            case water, caffeine, caloriesEaten, protein, carbohydrates, fat, fiber, sugar, sodium
            case bloodGlucose, bloodPressureSystolic, bloodPressureDiastolic
            /// Not a quantity but a stretch of time: read with `sleep()`, never with `total` or `latest`.
            case sleep

            var identifier: HKQuantityTypeIdentifier {
                switch self {
                case .steps: .stepCount
                case .distance: .distanceWalkingRunning
                case .flightsClimbed: .flightsClimbed
                case .activeCalories: .activeEnergyBurned
                case .restingCalories: .basalEnergyBurned
                case .exerciseMinutes: .appleExerciseTime
                case .standHours: .appleStandTime
                case .heartRate: .heartRate
                case .restingHeartRate: .restingHeartRate
                case .heartRateVariability: .heartRateVariabilitySDNN
                case .bloodOxygen: .oxygenSaturation
                case .respiratoryRate: .respiratoryRate
                case .bodyTemperature: .bodyTemperature
                case .weight: .bodyMass
                case .height: .height
                case .bodyFat: .bodyFatPercentage
                case .bodyMassIndex: .bodyMassIndex
                case .waistCircumference: .waistCircumference
                case .water: .dietaryWater
                case .caffeine: .dietaryCaffeine
                case .caloriesEaten: .dietaryEnergyConsumed
                case .protein: .dietaryProtein
                case .carbohydrates: .dietaryCarbohydrates
                case .fat: .dietaryFatTotal
                case .fiber: .dietaryFiber
                case .sugar: .dietarySugar
                case .sodium: .dietarySodium
                case .bloodGlucose: .bloodGlucose
                case .bloodPressureSystolic: .bloodPressureSystolic
                case .bloodPressureDiastolic: .bloodPressureDiastolic
                case .sleep: .stepCount   // never used: sleep is a category, read by sleep()
                }
            }

            var unit: HKUnit {
                switch self {
                case .steps, .flightsClimbed, .bodyMassIndex: .count()
                case .distance: .meterUnit(with: .kilo)
                case .activeCalories, .restingCalories, .caloriesEaten: .kilocalorie()
                case .exerciseMinutes: .minute()
                case .standHours, .sleep: .hour()
                case .heartRate, .restingHeartRate, .respiratoryRate: HKUnit.count().unitDivided(by: .minute())
                case .heartRateVariability: .secondUnit(with: .milli)
                case .bloodOxygen, .bodyFat: .percent()
                case .bodyTemperature: .degreeCelsius()
                case .weight: .gramUnit(with: .kilo)
                case .height, .waistCircumference: .meterUnit(with: .centi)
                case .water: .literUnit(with: .milli)
                case .caffeine, .sodium: .gramUnit(with: .milli)
                case .protein, .carbohydrates, .fat, .fiber, .sugar: .gram()
                case .bloodGlucose: HKUnit.gramUnit(with: .milli).unitDivided(by: .literUnit(with: .deci))
                case .bloodPressureSystolic, .bloodPressureDiastolic: .millimeterOfMercury()
                }
            }

            /// The unit as a person would write it beside the number.
            var unitName: String {
                switch self {
                case .steps: "steps"
                case .flightsClimbed: "flights"
                case .bodyMassIndex: ""
                case .distance: "km"
                case .activeCalories, .restingCalories, .caloriesEaten: "kcal"
                case .exerciseMinutes: "min"
                case .standHours, .sleep: "hours"
                case .heartRate, .restingHeartRate: "bpm"
                case .respiratoryRate: "breaths/min"
                case .heartRateVariability: "ms"
                case .bloodOxygen, .bodyFat: "%"
                case .bodyTemperature: "°C"
                case .weight: "kg"
                case .height, .waistCircumference: "cm"
                case .water: "ml"
                case .caffeine, .sodium: "mg"
                case .protein, .carbohydrates, .fat, .fiber, .sugar: "g"
                case .bloodGlucose: "mg/dL"
                case .bloodPressureSystolic, .bloodPressureDiastolic: "mmHg"
                }
            }

            /// Whether a day's samples add up (steps, calories, water) or the latest one is the answer (weight,
            /// heart rate): `total` sums the first kind and averages the second.
            var isCumulative: Bool {
                switch self {
                case .steps, .distance, .flightsClimbed, .activeCalories, .restingCalories, .exerciseMinutes, .standHours,
                     .water, .caffeine, .caloriesEaten, .protein, .carbohydrates, .fat, .fiber, .sugar, .sodium: true
                default: false
                }
            }

            /// HealthKit keeps percentages as fractions; people write them as percent.
            fileprivate var scale: Double { unit == .percent() ? 100 : 1 }
        }

        struct Sample: Identifiable, Codable {
            var id: UUID              // HealthKit's own, so the same record reads as the same item every time
            var kind: Kind
            var value: Double
            var date: Date
            /// The app or device that recorded it ("Apple Watch", the app's own name).
            var source: String
        }

        struct Workout: Identifiable, Codable {
            var id: UUID            // HealthKit's own
            var name: String        // "Running", "Cycling", "Strength Training"…
            var start: Date
            var end: Date
            var calories: Double?   // kcal
            var distance: Double?   // km
            var minutes: Double { end.timeIntervalSince(start) / 60 }
        }

        struct Failure: LocalizedError {
            let message: String
            var errorDescription: String? { message }
        }

        /// Whether this device has Health data at all: an iPhone or iPad does, a Mac doesn't.
        static var isAvailable: Bool { HKHealthStore.isHealthDataAvailable() }

        private static let store = HKHealthStore()

        private static func ready() throws {
            guard isAvailable else {
                #if os(macOS)
                throw Failure(message: "Health data isn't available on a Mac: read it on the iPhone and keep what the Mac shows in LampSync.")
                #else
                throw Failure(message: "Health data isn't available on this device.")
                #endif
            }
        }

        /// Asks the person once for the kinds the app reads and writes (iOS shows its own sheet; what they
        /// refuse reads as nothing, as Apple has it). Call before anything else, and again for new kinds.
        static func authorize(read: [Kind], write: [Kind] = [], workouts: Bool = false) async throws {
            try ready()
            var toRead: Set<HKObjectType> = []
            var toWrite: Set<HKSampleType> = []
            for kind in read {
                if kind == .sleep { toRead.insert(HKCategoryType(.sleepAnalysis)) } else { toRead.insert(HKQuantityType(kind.identifier)) }
            }
            for kind in write where kind != .sleep { toWrite.insert(HKQuantityType(kind.identifier)) }
            if workouts { toRead.insert(HKObjectType.workoutType()) }
            do {
                try await store.requestAuthorization(toShare: toWrite, read: toRead)
            } catch {
                throw Failure(message: "Health access couldn't be asked for: \(error.localizedDescription)")
            }
        }

        /// A day's total for what adds up (steps, calories eaten), or its average for what doesn't (heart rate).
        static func total(_ kind: Kind, on day: Date = Date()) async throws -> Double {
            try ready()
            guard kind != .sleep else { return try await sleep(nightEnding: day) }
            let bounds = dayBounds(day)
            return try await statistic(kind, from: bounds.start, to: bounds.end)
        }

        /// One number per day, oldest first, for the last `days` days: what a chart wants.
        static func dailyTotals(_ kind: Kind, days: Int = 7) async throws -> [(day: Date, value: Double)] {
            try ready()
            var totals: [(day: Date, value: Double)] = []
            let calendar = Calendar.current
            for back in stride(from: max(1, days) - 1, through: 0, by: -1) {
                let day = calendar.date(byAdding: .day, value: -back, to: calendar.startOfDay(for: Date())) ?? Date()
                totals.append((day, try await total(kind, on: day)))
            }
            return totals
        }

        /// The most recent sample, or nil when there is none the app may see.
        static func latest(_ kind: Kind) async throws -> Sample? {
            try await samples(kind, from: .distantPast, to: Date(), limit: 1).first
        }

        /// Every sample in the last `days` days, newest first.
        static func samples(_ kind: Kind, days: Int = 7) async throws -> [Sample] {
            try await samples(kind, from: Calendar.current.date(byAdding: .day, value: -max(1, days), to: Date()) ?? Date(), to: Date(), limit: HKObjectQueryNoLimit)
        }

        /// Hours asleep in the night that ended on `day`: between the evening before and noon.
        static func sleep(nightEnding day: Date = Date()) async throws -> Double {
            try ready()
            let calendar = Calendar.current
            let noon = calendar.date(bySettingHour: 12, minute: 0, second: 0, of: day) ?? day
            let evening = calendar.date(byAdding: .hour, value: -18, to: noon) ?? day
            let predicate = HKQuery.predicateForSamples(withStart: evening, end: noon, options: .strictStartDate)
            let found: [HKSample] = try await withCheckedThrowingContinuation { continuation in
                let query = HKSampleQuery(sampleType: HKCategoryType(.sleepAnalysis), predicate: predicate, limit: HKObjectQueryNoLimit, sortDescriptors: nil) { _, samples, error in
                    if let error { continuation.resume(throwing: Failure(message: "Sleep couldn't be read: \(error.localizedDescription)")) } else { continuation.resume(returning: samples ?? []) }
                }
                store.execute(query)
            }
            let asleep: Set<Int> = [HKCategoryValueSleepAnalysis.asleepUnspecified.rawValue, HKCategoryValueSleepAnalysis.asleepCore.rawValue,
                                    HKCategoryValueSleepAnalysis.asleepDeep.rawValue, HKCategoryValueSleepAnalysis.asleepREM.rawValue]
            // A watch's stages and a sleep app's one long record cover the same hours: counted once, as the
            // union of the stretches asleep, within the night.
            let stretches = found.compactMap { $0 as? HKCategorySample }.filter { asleep.contains($0.value) }
                .map { (max($0.startDate, evening), min($0.endDate, noon)) }.filter { $0.0 < $0.1 }
            return asleepSeconds(stretches) / 3600
        }

        /// Seconds covered by the stretches, overlaps counted once.
        static func asleepSeconds(_ stretches: [(Date, Date)]) -> Double {
            var total = 0.0
            var current: (Date, Date)?
            for stretch in stretches.sorted(by: { $0.0 < $1.0 }) {
                if let open = current, stretch.0 <= open.1 {
                    current = (open.0, max(open.1, stretch.1))
                } else {
                    if let open = current { total += open.1.timeIntervalSince(open.0) }
                    current = stretch
                }
            }
            if let open = current { total += open.1.timeIntervalSince(open.0) }
            return total
        }

        /// Workouts in the last `days` days, newest first.
        static func workouts(days: Int = 7) async throws -> [Workout] {
            try ready()
            let start = Calendar.current.date(byAdding: .day, value: -max(1, days), to: Date()) ?? Date()
            let predicate = HKQuery.predicateForSamples(withStart: start, end: Date(), options: .strictStartDate)
            let sort = NSSortDescriptor(key: HKSampleSortIdentifierEndDate, ascending: false)
            let found: [HKSample] = try await withCheckedThrowingContinuation { continuation in
                let query = HKSampleQuery(sampleType: .workoutType(), predicate: predicate, limit: HKObjectQueryNoLimit, sortDescriptors: [sort]) { _, samples, error in
                    if let error { continuation.resume(throwing: Failure(message: "Workouts couldn't be read: \(error.localizedDescription)")) } else { continuation.resume(returning: samples ?? []) }
                }
                store.execute(query)
            }
            return found.compactMap { $0 as? HKWorkout }.map { workout in
                let calories = workout.statistics(for: HKQuantityType(.activeEnergyBurned))?.sumQuantity()?.doubleValue(for: .kilocalorie())
                let distance = [HKQuantityTypeIdentifier.distanceWalkingRunning, .distanceCycling, .distanceSwimming]
                    .compactMap { workout.statistics(for: HKQuantityType($0))?.sumQuantity()?.doubleValue(for: .meterUnit(with: .kilo)) }.first
                return Workout(id: workout.uuid, name: name(of: workout.workoutActivityType), start: workout.startDate, end: workout.endDate, calories: calories, distance: distance)
            }
        }

        /// Logs a sample, as the app's own: calories eaten, water, weight, or anything else the person tells it.
        static func save(_ kind: Kind, _ value: Double, at date: Date = Date()) async throws {
            try ready()
            guard kind != .sleep else { throw Failure(message: "Sleep can't be logged this way.") }
            let quantity = HKQuantity(unit: kind.unit, doubleValue: value / kind.scale)
            let sample = HKQuantitySample(type: HKQuantityType(kind.identifier), quantity: quantity, start: date, end: date)
            do {
                try await store.save(sample)
            } catch {
                throw Failure(message: "Couldn't save to Health: \(error.localizedDescription)")
            }
        }

        // MARK: Behind the calls

        private static func dayBounds(_ day: Date) -> (start: Date, end: Date) {
            let start = Calendar.current.startOfDay(for: day)
            return (start, Calendar.current.date(byAdding: .day, value: 1, to: start) ?? day)
        }

        private static func statistic(_ kind: Kind, from start: Date, to end: Date) async throws -> Double {
            let predicate = HKQuery.predicateForSamples(withStart: start, end: end, options: .strictStartDate)
            let options: HKStatisticsOptions = kind.isCumulative ? .cumulativeSum : .discreteAverage
            return try await withCheckedThrowingContinuation { continuation in
                let query = HKStatisticsQuery(quantityType: HKQuantityType(kind.identifier), quantitySamplePredicate: predicate, options: options) { _, statistics, error in
                    if let failure = error as? HKError, failure.code == .errorNoData { continuation.resume(returning: 0); return }
                    if let error { continuation.resume(throwing: Failure(message: "\(kind.rawValue) couldn't be read: \(error.localizedDescription)")); return }
                    let quantity = kind.isCumulative ? statistics?.sumQuantity() : statistics?.averageQuantity()
                    continuation.resume(returning: (quantity?.doubleValue(for: kind.unit) ?? 0) * kind.scale)
                }
                store.execute(query)
            }
        }

        private static func samples(_ kind: Kind, from start: Date, to end: Date, limit: Int) async throws -> [Sample] {
            try ready()
            guard kind != .sleep else { throw Failure(message: "Sleep is read with sleep(), as hours.") }
            let predicate = HKQuery.predicateForSamples(withStart: start, end: end, options: .strictStartDate)
            let sort = NSSortDescriptor(key: HKSampleSortIdentifierEndDate, ascending: false)
            let found: [HKSample] = try await withCheckedThrowingContinuation { continuation in
                let query = HKSampleQuery(sampleType: HKQuantityType(kind.identifier), predicate: predicate, limit: limit, sortDescriptors: [sort]) { _, samples, error in
                    if let error { continuation.resume(throwing: Failure(message: "\(kind.rawValue) couldn't be read: \(error.localizedDescription)")) } else { continuation.resume(returning: samples ?? []) }
                }
                store.execute(query)
            }
            return found.compactMap { $0 as? HKQuantitySample }.map {
                Sample(id: $0.uuid, kind: kind, value: $0.quantity.doubleValue(for: kind.unit) * kind.scale, date: $0.endDate, source: $0.sourceRevision.source.name)
            }
        }

        private static func name(of type: HKWorkoutActivityType) -> String {
            switch type {
            case .running: "Running"
            case .walking: "Walking"
            case .cycling: "Cycling"
            case .swimming: "Swimming"
            case .hiking: "Hiking"
            case .yoga: "Yoga"
            case .functionalStrengthTraining, .traditionalStrengthTraining: "Strength Training"
            case .highIntensityIntervalTraining: "HIIT"
            case .rowing: "Rowing"
            case .elliptical: "Elliptical"
            case .stairClimbing: "Stair Climbing"
            case .coreTraining: "Core Training"
            case .pilates: "Pilates"
            case .dance, .cardioDance: "Dance"
            case .tennis: "Tennis"
            case .soccer: "Soccer"
            case .basketball: "Basketball"
            case .golf: "Golf"
            case .cooldown: "Cooldown"
            case .mixedCardio: "Mixed Cardio"
            default: "Workout"
            }
        }
    }
    #endif


    // MARK: - Photos

    /// The person's photo library: what they took, by day and place, their albums, a picture at the size
    /// wanted, what a picture shows (tags worked out on the device), and saving one. The picker for choosing
    /// a picture is SwiftUI's own `PhotosPicker`. Nothing to declare; the system asks the person once.
    ///
    ///     guard try await LampPhotos.authorize() else { … }
    ///     let week = try await LampPhotos.photos(days: 7)                      // newest first
    ///     let there = try await LampPhotos.photos(near: 51.5, -0.12, km: 2)    // around a place
    ///     let image = await LampPhotos.image(week[0], size: 800)              // LampImage?
    ///     let tags = await LampPhotos.tags(of: week[0])                        // ["beach", "sunset"]
    ///     let albums = try await LampPhotos.albums()
    ///     try await LampPhotos.save(image)
    ///
    /// Photos' own people, memories and search aren't open to apps; `tags(of:)` is the device's own look at a
    /// picture (Vision), good for sorting and finding, not a transcript of Photos. The simulator can't do it
    /// (no tags there); a Mac and an iPhone can.
    enum LampPhotos {
        struct Photo: Identifiable, Codable, Hashable {
            var id: String          // Photos' identifier for the picture; the same across launches
            var date: Date?
            var latitude: Double?
            var longitude: Double?
            var isVideo: Bool
            var isFavorite: Bool
            var width: Int
            var height: Int
            var seconds: Double     // a video's length; 0 for a picture
        }

        struct Album: Identifiable, Codable, Hashable {
            var id: String
            var title: String
            var count: Int
        }

        struct Failure: LocalizedError {
            let message: String
            var errorDescription: String? { message }
        }

        /// Asks once; false when the person refused (or allowed only some pictures, which still reads as allowed).
        static func authorize(toSave: Bool = false) async throws -> Bool {
            let status = await PHPhotoLibrary.requestAuthorization(for: toSave ? .readWrite : .readWrite)
            return status == .authorized || status == .limited
        }

        /// Pictures and videos taken in the last `days` days, newest first.
        static func photos(days: Int = 30, limit: Int = 500) async throws -> [Photo] {
            let since = Calendar.current.date(byAdding: .day, value: -max(1, days), to: Date()) ?? Date()
            return try fetch(NSPredicate(format: "creationDate >= %@", since as NSDate), limit: limit)
        }

        /// Those taken within `km` of a place, newest first, among the last year's by default.
        static func photos(near latitude: Double, _ longitude: Double, km: Double = 1, days: Int = 365, limit: Int = 500) async throws -> [Photo] {
            let there = CLLocation(latitude: latitude, longitude: longitude)
            return try await photos(days: days, limit: 10_000).filter { photo in
                guard let lat = photo.latitude, let lon = photo.longitude else { return false }
                return CLLocation(latitude: lat, longitude: lon).distance(from: there) <= km * 1000
            }.prefix(limit).map { $0 }
        }

        static func favorites(limit: Int = 500) async throws -> [Photo] {
            try fetch(NSPredicate(format: "isFavorite == YES"), limit: limit)
        }

        /// The person's own albums, and Photos' standard ones that have something in them (Favorites, Selfies, Screenshots…).
        static func albums() async throws -> [Album] {
            try authorized()
            var albums: [Album] = []
            let options = PHFetchOptions()
            for kind in [PHAssetCollectionType.album, .smartAlbum] {
                PHAssetCollection.fetchAssetCollections(with: kind, subtype: .any, options: options).enumerateObjects { collection, _, _ in
                    let count = PHAsset.fetchAssets(in: collection, options: nil).count
                    guard count > 0, let title = collection.localizedTitle else { return }
                    albums.append(Album(id: collection.localIdentifier, title: title, count: count))
                }
            }
            return albums
        }

        static func photos(in album: Album, limit: Int = 500) async throws -> [Photo] {
            try authorized()
            guard let collection = PHAssetCollection.fetchAssetCollections(withLocalIdentifiers: [album.id], options: nil).firstObject else { return [] }
            let options = PHFetchOptions()
            options.sortDescriptors = [NSSortDescriptor(key: "creationDate", ascending: false)]
            options.fetchLimit = limit
            var found: [Photo] = []
            PHAsset.fetchAssets(in: collection, options: options).enumerateObjects { asset, _, _ in found.append(photo(asset)) }
            return found
        }

        /// The picture itself, at most `size` points on its long side (the whole thing with `size: 0`), or nil
        /// when it can't be loaded (in iCloud and offline, say).
        static func image(_ photo: Photo, size: CGFloat = 1024) async -> LampImage? {
            guard let asset = PHAsset.fetchAssets(withLocalIdentifiers: [photo.id], options: nil).firstObject else { return nil }
            let options = PHImageRequestOptions()
            options.isNetworkAccessAllowed = true
            options.deliveryMode = .highQualityFormat
            let target = size > 0 ? CGSize(width: size, height: size) : PHImageManagerMaximumSize
            return await withCheckedContinuation { continuation in
                var done = false
                PHImageManager.default().requestImage(for: asset, targetSize: target, contentMode: .aspectFit, options: options) { image, info in
                    guard !done, (info?[PHImageResultIsDegradedKey] as? Bool) != true else { return }
                    done = true
                    continuation.resume(returning: image)
                }
            }
        }

        /// What the picture shows, as the device sees it: up to ten tags, surest first ("beach", "dog", "document").
        static func tags(of photo: Photo, limit: Int = 10) async -> [String] {
            guard let image = await image(photo, size: 512), let cgImage = image.lampCGImage else { return [] }
            let request = VNClassifyImageRequest()
            let handler = VNImageRequestHandler(cgImage: cgImage, options: [:])
            guard (try? handler.perform([request])) != nil else { return [] }
            return (request.results ?? []).filter { $0.confidence > 0.3 }.prefix(limit).map { $0.identifier.replacingOccurrences(of: "_", with: " ") }
        }

        /// Puts a picture in the person's library, as the app's.
        static func save(_ image: LampImage) async throws {
            guard try await authorize(toSave: true) else { throw Failure(message: "The app isn't allowed to add to Photos.") }
            do {
                try await PHPhotoLibrary.shared().performChanges { PHAssetChangeRequest.creationRequestForAsset(from: image) }
            } catch {
                throw Failure(message: "Couldn't save to Photos: \(error.localizedDescription)")
            }
        }

        private static func authorized() throws {
            let status = PHPhotoLibrary.authorizationStatus(for: .readWrite)
            guard status == .authorized || status == .limited else {
                throw Failure(message: status == .notDetermined ? "Ask for Photos first: LampPhotos.authorize()." : "The app isn't allowed to see Photos. The person can allow it in Settings.")
            }
        }

        private static func fetch(_ predicate: NSPredicate, limit: Int) throws -> [Photo] {
            try authorized()
            let options = PHFetchOptions()
            options.predicate = predicate
            options.sortDescriptors = [NSSortDescriptor(key: "creationDate", ascending: false)]
            options.fetchLimit = limit
            var found: [Photo] = []
            PHAsset.fetchAssets(with: options).enumerateObjects { asset, _, _ in found.append(photo(asset)) }
            return found
        }

        private static func photo(_ asset: PHAsset) -> Photo {
            Photo(id: asset.localIdentifier, date: asset.creationDate, latitude: asset.location?.coordinate.latitude,
                  longitude: asset.location?.coordinate.longitude, isVideo: asset.mediaType == .video, isFavorite: asset.isFavorite,
                  width: asset.pixelWidth, height: asset.pixelHeight, seconds: asset.mediaType == .video ? asset.duration : 0)
        }
    }

    // MARK: - Location

    /// Where the person is: once, as they move, and the places they stop at (iPhone only), with names from the
    /// map. The system asks once; `always` is for watching while the app is closed, which also needs
    /// `"backgroundModes": ["location"]` in capabilities.json.
    ///
    ///     let here = try await LampLocation.current()          // Place: coordinates and "Street, Town"
    ///     let km = LampLocation.distance(from: here, to: there)
    ///     let office = try await LampLocation.find("1 Infinite Loop, Cupertino")
    ///     LampLocation.shared.watch()                           // `.current` follows big moves (a few hundred meters)
    ///     LampLocation.shared.watchVisits()                     // iPhone: `.visits`, where they stopped and for how long
    @MainActor
    final class LampLocation: NSObject, ObservableObject, CLLocationManagerDelegate {
        static let shared = LampLocation()

        struct Place: Codable, Hashable {
            var latitude: Double
            var longitude: Double
            var accuracy: Double      // meters
            var date: Date
            var name: String?         // "Street, Town", when the map knows
        }

        struct Visit: Identifiable, Codable, Hashable {
            var id = UUID()
            var latitude: Double
            var longitude: Double
            var arrived: Date
            var left: Date?           // nil while still there
            var name: String?
            var minutes: Double { (left ?? Date()).timeIntervalSince(arrived) / 60 }
        }

        struct Failure: LocalizedError {
            let message: String
            var errorDescription: String? { message }
        }

        /// The latest place, kept up by `watch()` or any `current()`.
        @Published private(set) var current: Place?
        /// Places the person stopped at, newest first, kept across launches (iPhone, after `watchVisits()`).
        @Published private(set) var visits: [Visit] = []
        /// Whether the person has allowed the app to know where they are.
        @Published private(set) var isAllowed = false
        /// What's going on, for a settings screen.
        @Published private(set) var status = "Not asked yet"

        private let manager = CLLocationManager()
        /// Everyone waiting on the person's answer, each settled once: one question answers them all.
        private var waiting: [(always: Bool, answer: CheckedContinuation<Bool, Never>)] = []
        private var once: [CheckedContinuation<CLLocation, Error>] = []
        /// What's been asked to run: a watcher waiting on the person's answer starts only if it still is.
        private var wantsMoves = false
        private var wantsVisits = false
        /// Asking for Always: iOS shows that question once, ignores it after (and while the person allowed
        /// just once), and says nothing when it does. Nothing is remembered about it: a question that takes
        /// the app out of the foreground is answered when the app is back, and one that doesn't, at once.
        private var askingAlways = false
        private var shownWhileAsking = false
        private let kept = LampStore.collection("location.visits", of: Visit.self)

        private override init() {
            super.init()
            manager.delegate = self
            manager.desiredAccuracy = kCLLocationAccuracyHundredMeters
            visits = kept.all(orderBy: "arrived", descending: true)
            isAllowed = Self.allowed(manager.authorizationStatus)
            // The system's question makes the app inactive; when it's active again the person has answered,
            // even with an answer that changes nothing (keeping "While Using" when asked for Always), which
            // the location manager doesn't report.
            #if os(macOS)
            let active = NSApplication.didBecomeActiveNotification
            #else
            let active = UIApplication.didBecomeActiveNotification
            #endif
            NotificationCenter.default.addObserver(forName: active, object: nil, queue: .main) { _ in
                MainActor.assumeIsolated { LampLocation.shared.settle() }
            }
            #if os(iOS)
            // The question for Always takes the app out of the foreground while it shows: then wait for the answer.
            NotificationCenter.default.addObserver(forName: UIApplication.willResignActiveNotification, object: nil, queue: .main) { _ in
                MainActor.assumeIsolated {
                    let me = LampLocation.shared
                    if me.askingAlways { me.shownWhileAsking = true }
                }
            }
            #endif
        }

        /// Asks once (while in use, or always for watching in the background); true when allowed. A question
        /// the system won't ask again (refused, restricted, Always asked before) answers straight away.
        static func authorize(always: Bool = false) async -> Bool {
            let me = shared
            let status = me.manager.authorizationStatus
            if status == .denied || status == .restricted { return false }
            #if os(iOS)
            if always ? status == .authorizedAlways : Self.allowed(status) { return true }
            #else
            if Self.allowed(status) { return true }
            #endif
            return await withCheckedContinuation { continuation in
                me.waiting.append((always, continuation))
                #if os(iOS)
                if always {
                    // A question already open answers this caller too: asking again would do nothing, and
                    // starting over would answer everyone before the person has.
                    guard !me.askingAlways else { return }
                    me.askingAlways = true
                    me.shownWhileAsking = false
                    me.manager.requestAlwaysAuthorization()
                    // Not shown (asked before, or under Allow Once): nothing will answer, so answer now.
                    Task { @MainActor in
                        try? await Task.sleep(for: .seconds(1.5))
                        guard me.askingAlways, !me.shownWhileAsking else { return }
                        me.askingAlways = false
                        me.settle(force: true)
                    }
                } else if status == .notDetermined {
                    me.manager.requestWhenInUseAuthorization()
                }
                #else
                if status == .notDetermined { me.manager.requestWhenInUseAuthorization() }
                #endif
            }
        }

        /// Answers everyone waiting, once, from where things stand now, unless the question is still open.
        private func settle(force: Bool = false) {
            let status = manager.authorizationStatus
            guard !waiting.isEmpty, force || status != .notDetermined else { return }
            askingAlways = false
            let everyone = waiting
            waiting = []
            for waiter in everyone {
                #if os(iOS)
                waiter.answer.resume(returning: waiter.always ? status == .authorizedAlways : Self.allowed(status))
                #else
                waiter.answer.resume(returning: Self.allowed(status))
                #endif
            }
        }

        /// Where the person is now, named when the map knows the place.
        static func current() async throws -> Place {
            guard await authorize() else { throw Failure(message: "The app isn't allowed to know where the person is. They can allow it in Settings.") }
            let location: CLLocation = try await withCheckedThrowingContinuation { continuation in
                shared.once.append(continuation)
                shared.manager.requestLocation()
            }
            let place = Place(latitude: location.coordinate.latitude, longitude: location.coordinate.longitude, accuracy: location.horizontalAccuracy,
                              date: location.timestamp, name: await name(of: location.coordinate.latitude, location.coordinate.longitude))
            shared.current = place
            return place
        }

        /// "Street, Town" for coordinates, when the map knows.
        static func name(of latitude: Double, _ longitude: Double) async -> String? {
            guard let mark = try? await CLGeocoder().reverseGeocodeLocation(CLLocation(latitude: latitude, longitude: longitude)).first else { return nil }
            let parts = [mark.name, mark.locality].compactMap { $0 }.filter { !$0.isEmpty }
            return parts.isEmpty ? nil : Array(NSOrderedSet(array: parts)).compactMap { $0 as? String }.joined(separator: ", ")
        }

        /// Coordinates for an address or a place's name.
        static func find(_ address: String) async throws -> Place {
            guard let mark = try? await CLGeocoder().geocodeAddressString(address).first, let location = mark.location else {
                throw Failure(message: "No place found for \"\(address)\".")
            }
            return Place(latitude: location.coordinate.latitude, longitude: location.coordinate.longitude, accuracy: location.horizontalAccuracy,
                         date: Date(), name: [mark.name, mark.locality].compactMap { $0 }.joined(separator: ", "))
        }

        /// Kilometers between two places, as the crow flies.
        static func distance(from a: Place, to b: Place) -> Double {
            CLLocation(latitude: a.latitude, longitude: a.longitude).distance(from: CLLocation(latitude: b.latitude, longitude: b.longitude)) / 1000
        }

        /// Keeps `current` up as the person moves a few hundred meters or more, sparing the battery.
        func watch() {
            wantsMoves = true
            Task {
                guard await Self.authorize(), wantsMoves else { return }
                // Apple TV and Vision Pro don't follow big moves: they stay put.
                #if os(iOS) || os(macOS)
                manager.startMonitoringSignificantLocationChanges()
                #endif
                status = "Following big moves"
            }
        }

        /// Keeps `visits`: where the person stops and for how long, even with the app closed. iPhone only;
        /// needs `always` and the location background mode.
        func watchVisits() {
            #if os(iOS)
            wantsVisits = true
            Task {
                guard await Self.authorize(always: true) else { status = "Visits need Always: the person can allow it in Settings"; return }
                guard wantsVisits else { return }
                manager.startMonitoringVisits()
                status = "Noting where the person stops"
            }
            #else
            status = "Visits are the iPhone's: a Mac doesn't note them"
            #endif
        }

        func stop() {
            wantsMoves = false
            wantsVisits = false
            #if os(iOS) || os(macOS)
            manager.stopMonitoringSignificantLocationChanges()
            #endif
            #if os(iOS)
            manager.stopMonitoringVisits()
            #endif
            status = "Not watching"
        }

        private static func allowed(_ status: CLAuthorizationStatus) -> Bool {
            #if os(macOS)
            status == .authorizedAlways || status == .authorized
            #elseif os(iOS)
            status == .authorizedWhenInUse || status == .authorizedAlways
            #else
            status == .authorizedWhenInUse
            #endif
        }

        // MARK: CLLocationManagerDelegate

        nonisolated func locationManagerDidChangeAuthorization(_ manager: CLLocationManager) {
            let status = manager.authorizationStatus
            Task { @MainActor in
                isAllowed = Self.allowed(status)
                self.status = isAllowed ? "Allowed" : status == .notDetermined ? "Not asked yet" : "Not allowed; the person can allow it in Settings"
                settle()
            }
        }

        nonisolated func locationManager(_ manager: CLLocationManager, didUpdateLocations locations: [CLLocation]) {
            guard let location = locations.last else { return }
            Task { @MainActor in
                let waiting = once
                once = []
                for continuation in waiting { continuation.resume(returning: location) }
                if waiting.isEmpty {
                    current = Place(latitude: location.coordinate.latitude, longitude: location.coordinate.longitude, accuracy: location.horizontalAccuracy,
                                    date: location.timestamp, name: await Self.name(of: location.coordinate.latitude, location.coordinate.longitude))
                }
            }
        }

        nonisolated func locationManager(_ manager: CLLocationManager, didFailWithError error: Error) {
            Task { @MainActor in
                let waiting = once
                once = []
                for continuation in waiting { continuation.resume(throwing: Failure(message: "Couldn't find where the person is: \(error.localizedDescription)")) }
            }
        }

        #if os(iOS)
        nonisolated func locationManager(_ manager: CLLocationManager, didVisit visit: CLVisit) {
            let arrived = visit.arrivalDate == .distantPast ? Date() : visit.arrivalDate
            let left: Date? = visit.departureDate == .distantFuture ? nil : visit.departureDate
            let latitude = visit.coordinate.latitude, longitude = visit.coordinate.longitude
            Task { @MainActor in
                // One record per stop: the arrival's record gets its departure when the person leaves.
                var record = visits.first { abs($0.arrived.timeIntervalSince(arrived)) < 60 && $0.left == nil }
                    ?? Visit(latitude: latitude, longitude: longitude, arrived: arrived, left: nil, name: nil)
                record.left = left
                if record.name == nil { record.name = await Self.name(of: latitude, longitude) }
                kept.put(record)
                visits = kept.all(orderBy: "arrived", descending: true)
            }
        }
        #endif
    }

    // MARK: - Weather

    /// The weather, from Apple's own service: now, the next hours and the next days, anywhere or where the
    /// person is. Needs `{"weather": true}` in capabilities.json, which signs the app for it (so apps with
    /// an iPhone half, which Apple signs for a team). Apple also asks the team to turn WeatherKit on for the
    /// app under App Services at developer.apple.com, once; until then the calls fail with a message saying so.
    ///
    ///     let now = try await LampWeather.now(latitude: 51.5, longitude: -0.12)   // °C, condition, symbol
    ///     let today = try await LampWeather.hours(latitude: 51.5, longitude: -0.12)
    ///     let week = try await LampWeather.days(latitude: 51.5, longitude: -0.12)
    ///     let here = try await LampWeather.here()                                   // where the person is
    enum LampWeather {
        struct Now: Codable {
            var temperature: Double       // °C
            var feelsLike: Double
            var condition: String         // "Partly cloudy"
            var symbol: String            // an SF Symbol: "cloud.sun"
            var humidity: Double          // %
            var windKph: Double
            var uvIndex: Int
            var isDaylight: Bool
        }

        struct Hour: Codable, Identifiable {
            var id: Date { date }
            var date: Date
            var temperature: Double
            var condition: String
            var symbol: String
            var rainChance: Double        // %
        }

        struct Day: Codable, Identifiable {
            var id: Date { date }
            var date: Date
            var high: Double
            var low: Double
            var condition: String
            var symbol: String
            var rainChance: Double
            var sunrise: Date?
            var sunset: Date?
        }

        struct Failure: LocalizedError {
            let message: String
            var errorDescription: String? { message }
        }

        static func now(latitude: Double, longitude: Double) async throws -> Now {
            let weather = try await fetch { try await WeatherService.shared.weather(for: CLLocation(latitude: latitude, longitude: longitude), including: .current) }
            return Now(temperature: celsius(weather.temperature), feelsLike: celsius(weather.apparentTemperature),
                       condition: weather.condition.description, symbol: weather.symbolName, humidity: weather.humidity * 100,
                       windKph: weather.wind.speed.converted(to: .kilometersPerHour).value, uvIndex: weather.uvIndex.value, isDaylight: weather.isDaylight)
        }

        static func hours(latitude: Double, longitude: Double, count: Int = 24) async throws -> [Hour] {
            let forecast = try await fetch { try await WeatherService.shared.weather(for: CLLocation(latitude: latitude, longitude: longitude), including: .hourly) }
            return forecast.forecast.filter { $0.date >= Date().addingTimeInterval(-3600) }.prefix(count).map {
                Hour(date: $0.date, temperature: celsius($0.temperature), condition: $0.condition.description, symbol: $0.symbolName, rainChance: $0.precipitationChance * 100)
            }
        }

        static func days(latitude: Double, longitude: Double, count: Int = 7) async throws -> [Day] {
            let forecast = try await fetch { try await WeatherService.shared.weather(for: CLLocation(latitude: latitude, longitude: longitude), including: .daily) }
            return forecast.forecast.prefix(count).map {
                Day(date: $0.date, high: celsius($0.highTemperature), low: celsius($0.lowTemperature), condition: $0.condition.description,
                    symbol: $0.symbolName, rainChance: $0.precipitationChance * 100, sunrise: $0.sun.sunrise, sunset: $0.sun.sunset)
            }
        }

        /// Now, where the person is.
        static func here() async throws -> Now {
            let place = try await LampLocation.current()
            return try await now(latitude: place.latitude, longitude: place.longitude)
        }

        private static func celsius(_ measurement: Measurement<UnitTemperature>) -> Double {
            (measurement.converted(to: .celsius).value * 10).rounded() / 10
        }

        private static func fetch<T>(_ work: () async throws -> T) async throws -> T {
            do {
                return try await work()
            } catch {
                let text = "\(error) \(error.localizedDescription)"
                if text.contains("WDSJWTAuthenticator") || text.contains("401") || text.contains("403") || text.contains("permission") {
                    throw Failure(message: "Apple's weather service refused the app. It needs WeatherKit turned on for the app at developer.apple.com (Identifiers → the app → App Services), and `{\"weather\": true}` in capabilities.json; new settings there take up to half an hour.")
                }
                throw Failure(message: "The weather couldn't be fetched: \(error.localizedDescription)")
            }
        }
    }

    /// Apple's weather attribution, which Apple's terms ask for wherever its weather is shown: the Apple Weather
    /// mark for the light or dark look, linking to the page of where the data comes from.
    ///
    ///     VStack { WeatherView(now: now); LampWeatherAttribution() }
    struct LampWeatherAttribution: View {
        @Environment(\.colorScheme) private var scheme
        @State private var attribution: WeatherAttribution?
        var height: CGFloat = 12

        /// Apple's page of weather sources, linked to until the mark has loaded, so the attribution is never missing.
        private static let sourcesPage = URL(string: "https://weatherkit.apple.com/legal-attribution.html")!

        var body: some View {
            Group {
                if let attribution {
                    Link(destination: attribution.legalPageURL) {
                        AsyncImage(url: scheme == .dark ? attribution.combinedMarkDarkURL : attribution.combinedMarkLightURL) { image in
                            image.resizable().scaledToFit()
                        } placeholder: {
                            Text(attribution.serviceName).font(.caption2)
                        }
                        .frame(height: height)
                    }
                    .accessibilityLabel(attribution.serviceName)
                } else {
                    Link("Weather data sources", destination: Self.sourcesPage).font(.caption2)
                }
            }
            .task {
                // Asked again, less often each time, until it answers: offline at first is no reason to go without.
                var pause: UInt64 = 2
                while attribution == nil, !Task.isCancelled {
                    attribution = try? await WeatherService.shared.attribution
                    if attribution == nil {
                        try? await Task.sleep(nanoseconds: pause * 1_000_000_000)
                        pause = min(pause * 2, 60)
                    }
                }
            }
        }
    }

    // MARK: - Music

    /// Apple Music: what the person has played lately, their library, the catalog, and playing a song. Needs
    /// an Apple Music subscription on the device and the person's leave, asked once. Apple also asks the team
    /// to turn MusicKit on for the app under App Services at developer.apple.com, once.
    ///
    ///     guard try await LampMusic.authorize() else { … }
    ///     let recent = try await LampMusic.recentlyPlayed()
    ///     let mine = try await LampMusic.library(limit: 200)
    ///     let found = try await LampMusic.search("blue in green")
    ///     try await LampMusic.play(found[0])
    ///     let playing = LampMusic.nowPlaying        // iPhone: whatever the Music app is playing
    enum LampMusic {
        struct Song: Identifiable, Codable, Hashable {
            var id: String
            var title: String
            var artist: String
            var album: String
            var seconds: Double
            var artworkURL: String?
            /// From the person's library (`library()`, `recentlyPlayed()`), whose ids aren't the catalog's.
            var inLibrary: Bool?
        }

        struct Failure: LocalizedError {
            let message: String
            var errorDescription: String? { message }
        }

        /// Asks once; false when the person refused.
        static func authorize() async -> Bool {
            await MusicAuthorization.request() == .authorized
        }

        static func recentlyPlayed(limit: Int = 25) async throws -> [Song] {
            try await allowed()
            var request = MusicRecentlyPlayedRequest<MusicKit.Song>()
            request.limit = limit
            return try await run { try await request.response().items.map { song($0) } }   // catalog songs
        }

        /// Songs in the person's own library, most recently added first.
        static func library(limit: Int = 100) async throws -> [Song] {
            try await allowed()
            var request = MusicLibraryRequest<MusicKit.Song>()
            request.limit = limit
            request.sort(by: \.libraryAddedDate, ascending: false)
            return try await run { try await request.response().items.map { song($0, inLibrary: true) } }
        }

        /// Songs in Apple Music's catalog matching the words.
        static func search(_ text: String, limit: Int = 25) async throws -> [Song] {
            try await allowed()
            var request = MusicCatalogSearchRequest(term: text, types: [MusicKit.Song.self])
            request.limit = limit
            return try await run { try await request.response().songs.map { song($0) } }
        }

        /// Plays the song through the app's own player: a library song from the library (it may be one the
        /// person added themselves, which the catalog doesn't have), any other from the catalog.
        static func play(_ song: Song) async throws {
            try await allowed()
            let id = MusicItemID(song.id)
            let found: MusicKit.Song?
            if song.inLibrary == true {
                var request = MusicLibraryRequest<MusicKit.Song>()
                request.filter(matching: \.id, equalTo: id)
                found = try await run { try await request.response().items.first }
            } else {
                let request = MusicCatalogResourceRequest<MusicKit.Song>(matching: \.id, equalTo: id)
                found = try await run { try await request.response().items.first }
            }
            guard let item = found else { throw Failure(message: "That song can't be found to play.") }
            let player = ApplicationMusicPlayer.shared
            player.queue = [item]
            do { try await player.play() } catch { throw Failure(message: "Couldn't play it: \(error.localizedDescription)") }
        }

        static func pause() { ApplicationMusicPlayer.shared.pause() }

        #if os(iOS)
        /// What the Music app is playing right now, or nil.
        static var nowPlaying: Song? {
            guard let entry = SystemMusicPlayer.shared.queue.currentEntry, case .song(let item) = entry.item else { return nil }
            return song(item)
        }
        #endif

        private static func allowed() async throws {
            guard await authorize() else { throw Failure(message: "The app isn't allowed to use Apple Music. The person can allow it in Settings.") }
        }

        private static func run<T>(_ work: () async throws -> T) async throws -> T {
            do {
                return try await work()
            } catch {
                let text = "\(error)"
                if text.contains("401") || text.contains("403") || text.contains("developerTokenRequestFailed") {
                    throw Failure(message: "Apple Music refused the app. It needs MusicKit turned on for the app at developer.apple.com (Identifiers → the app → App Services), once.")
                }
                throw Failure(message: "Apple Music didn't answer: \(error.localizedDescription)")
            }
        }

        private static func song(_ item: MusicKit.Song, inLibrary: Bool = false) -> Song {
            Song(id: item.id.rawValue, title: item.title, artist: item.artistName, album: item.albumTitle ?? "",
                 seconds: item.duration ?? 0, artworkURL: item.artwork?.url(width: 300, height: 300)?.absoluteString,
                 inLibrary: inLibrary ? true : nil)
        }
    }

    // MARK: - Roku

    /// A Roku on the person's network, driven the way Roku's own phone app drives it (its External Control
    /// Protocol, on port 8060): nothing is installed on the Roku. It takes commands only once the person has set
    /// Settings, System, Advanced system settings, Control by mobile apps, Network access to Enabled (a Roku
    /// says Limited until then, which refuses them). Never suggest Permissive.
    ///
    ///     let rokus = await LampRoku.find()                         // every Roku that answers, by name
    ///     guard let roku = rokus.first else { … }                   // say none was found, and how to set one up
    ///     try await roku.launch(named: "Netflix")                    // by the name on its home screen
    ///     try await roku.launch(appID: "837", contentID: "dQw4w9WgXcQ", mediaType: "movie")   // a deep link
    ///     try await roku.press(.play)                                // .home, .select, .up, .back, .volumeUp …
    ///     try await roku.type("star trek")                           // into the keyboard on its screen
    ///     let open = try await roku.activeApp()                      // nil on the home screen
    ///     let now = try await roku.playing()                         // state, position and duration
    ///     try await roku.power(on: false)                            // Roku TVs only (roku.isTV)
    ///     try await roku.input(.hdmi1)
    struct LampRoku: Identifiable, Codable, Hashable {
        var id: String          // its serial number
        var name: String        // what the person called it ("Living Room")
        var model: String
        var address: String
        var isTV: Bool
        /// Control by mobile apps: "enabled", "limited", "disabled", or "" where the Roku doesn't say.
        var control: String

        /// Whether it takes key presses and launches from apps now.
        var canBeControlled: Bool { control != "limited" && control != "disabled" }

        struct App: Identifiable, Codable, Hashable {
            var id: String
            var name: String
            var version: String
        }

        struct Playing: Codable, Hashable {
            var state: String       // "play", "pause", "buffer", "stop", "close", "none"
            var appID: String?
            var position: Double?   // seconds
            var duration: Double?
        }

        enum Key: String, CaseIterable {
            case home = "Home", back = "Back", select = "Select", up = "Up", down = "Down", left = "Left", right = "Right"
            case play = "Play", rewind = "Rev", fastForward = "Fwd", replay = "InstantReplay", info = "Info"
            case search = "Search", enter = "Enter", backspace = "Backspace", findRemote = "FindRemote"
            // A Roku TV's, and a player's that controls its TV.
            case volumeUp = "VolumeUp", volumeDown = "VolumeDown", mute = "VolumeMute"
            case powerOn = "PowerOn", powerOff = "PowerOff", channelUp = "ChannelUp", channelDown = "ChannelDown"
        }

        enum Input: String, CaseIterable {
            case tuner = "InputTuner", hdmi1 = "InputHDMI1", hdmi2 = "InputHDMI2", hdmi3 = "InputHDMI3", hdmi4 = "InputHDMI4", av1 = "InputAV1"
        }

        struct Failure: LocalizedError {
            let message: String
            var errorDescription: String? { message }
        }

        /// What the person does once on the Roku for apps to control it.
        static let setUp = "On the Roku, open Settings, then System, Advanced system settings, Control by mobile apps, and set Network access to Enabled."

        // MARK: Finding

        /// Every Roku that answers on this network, by name. It asks the way Roku's own app does (SSDP), then where
        /// one was found before, and only then each address near this device's, since an iPhone app may not ask
        /// the whole network at once. The first time, the system asks the person whether the app may use the local
        /// network, and nothing answers until they allow it: offer to look again.
        static func find(timeout: TimeInterval = 3) async -> [LampRoku] {
            let answered = await ssdp(timeout: min(timeout, 2))
            var found = await read(Array(Set(answered + remembered)), timeout: timeout)
            // Where SSDP got no answer (an iPhone app can't send it), the Rokus found before are only a start: one added
            // or moved since is found by the sweep.
            if answered.isEmpty {
                let more = await read(neighbours().filter { address in !found.contains { $0.address == address } }, timeout: 1.5)
                found += more.filter { roku in !found.contains { $0.id == roku.id } }
            }
            if !found.isEmpty { UserDefaults.standard.set(found.map(\.address), forKey: rememberKey) }
            return found.sorted { $0.name.localizedStandardCompare($1.name) == .orderedAscending }
        }

        /// The Roku at an address the person typed, read fresh.
        static func at(_ address: String) async throws -> LampRoku {
            let xml = try await request(address, "/query/device-info", method: "GET", timeout: 4)
            guard let roku = roku(at: address, from: xml) else { throw Failure(message: "Nothing at \(address) answered as a Roku.") }
            return roku
        }

        // MARK: Reading

        /// Every field the Roku tells about itself ("software-version", "power-mode", "is-tv" …).
        func info() async throws -> [String: String] {
            let xml = try await Self.request(address, "/query/device-info", method: "GET")
            var fields: [String: String] = [:]
            for match in Self.matches(#"<([a-z0-9-]+)>([^<]*)</\1>"#, in: xml) { fields[match[0]] = Self.unescaped(match[1]) }
            return fields
        }

        /// The apps on its home screen.
        func apps() async throws -> [App] {
            Self.apps(in: try await Self.request(address, "/query/apps", method: "GET"))
        }

        /// What's open on it: nil on the home screen.
        func activeApp() async throws -> App? {
            let xml = try await Self.request(address, "/query/active-app", method: "GET")
            guard !xml.contains("type=\"home\"") else { return nil }
            return Self.apps(in: xml).first { !$0.id.isEmpty }
        }

        /// What it's playing, if anything.
        func playing() async throws -> Playing {
            let xml = try await Self.request(address, "/query/media-player", method: "GET")
            func seconds(_ tag: String) -> Double? {
                Self.matches("<\(tag)>([0-9]+) ms</\(tag)>", in: xml).first.flatMap { Double($0[0]) }.map { $0 / 1000 }
            }
            let state = Self.matches(#"<player[^>]* state="([^"]*)""#, in: xml).first?[0] ?? "none"
            let app = Self.matches(#"<plugin[^>]* id="([^"]*)""#, in: xml).first?[0]
            return Playing(state: state, appID: app, position: seconds("position"), duration: seconds("duration"))
        }

        // MARK: Doing

        /// Opens an app, and with a content id and media type ("movie", "episode", "series", "live", the app's own
        /// words) goes straight to that show, where the app supports deep links.
        func launch(appID: String, contentID: String? = nil, mediaType: String? = nil) async throws {
            var query: [URLQueryItem] = []
            if let contentID { query.append(URLQueryItem(name: "contentId", value: contentID)) }
            if let mediaType { query.append(URLQueryItem(name: "mediaType", value: mediaType)) }
            var parts = URLComponents()
            parts.queryItems = query.isEmpty ? nil : query
            let id = appID.addingPercentEncoding(withAllowedCharacters: .alphanumerics) ?? appID
            // The Roku answers once the app has opened, which can take several seconds.
            _ = try await Self.request(address, "/launch/\(id)" + (parts.percentEncodedQuery.map { "?" + $0 } ?? ""), method: "POST", timeout: 20)
        }

        /// Opens the app with this name on its home screen ("Netflix", "YouTube").
        func launch(named name: String, contentID: String? = nil, mediaType: String? = nil) async throws {
            let apps = try await apps()
            let wanted = name.lowercased()
            guard let app = apps.first(where: { $0.name.lowercased() == wanted }) ?? apps.first(where: { $0.name.lowercased().contains(wanted) }) else {
                throw Failure(message: "\(self.name) has no app called \(name). Add it from the Roku's home screen first.")
            }
            try await launch(appID: app.id, contentID: contentID, mediaType: mediaType)
        }

        func press(_ key: Key) async throws {
            try await send("/keypress/\(key.rawValue)")
        }

        /// Types into the keyboard on its screen, a character at a time, as its remote's app does.
        func type(_ text: String) async throws {
            for character in text {
                let letter = String(character).addingPercentEncoding(withAllowedCharacters: .alphanumerics) ?? ""
                try await send("/keypress/Lit_\(letter)")
            }
        }

        /// Turns a Roku TV on or off. A Roku player has no power of its own to switch.
        func power(on: Bool) async throws {
            guard isTV else { throw Failure(message: "\(name) is a Roku player, not a Roku TV, so it can't be turned on or off.") }
            try await press(on ? .powerOn : .powerOff)
        }

        /// Switches a Roku TV to one of its inputs.
        func input(_ input: Input) async throws {
            guard isTV else { throw Failure(message: "\(name) is a Roku player, not a Roku TV, so it has no inputs.") }
            try await send("/keypress/\(input.rawValue)")
        }

        // MARK: Talking to it

        private func send(_ path: String) async throws {
            _ = try await Self.request(address, path, method: "POST")
        }

        private static func request(_ address: String, _ path: String, method: String, timeout: TimeInterval = 5) async throws -> String {
            guard let url = URL(string: "http://\(address):8060\(path)") else { throw Failure(message: "\(address) isn't a Roku's address.") }
            var request = URLRequest(url: url, timeoutInterval: timeout)
            request.httpMethod = method
            if method == "POST" { request.httpBody = Data() }
            let data: Data
            let response: URLResponse
            do { (data, response) = try await URLSession.shared.data(for: request) }
            catch { throw Failure(message: "The Roku at \(address) didn't answer. Check that it's on and on the same Wi-Fi.") }
            let status = (response as? HTTPURLResponse)?.statusCode ?? 0
            if status == 401 || status == 403 { throw Failure(message: "The Roku doesn't take commands from apps yet. " + setUp) }
            guard (200..<300).contains(status) else { throw Failure(message: "The Roku answered \(status) to \(path).") }
            return String(decoding: data, as: UTF8.self)
        }

        private static let rememberKey = "lamp.roku.addresses"
        private static var remembered: [String] { UserDefaults.standard.stringArray(forKey: rememberKey) ?? [] }

        private static func read(_ addresses: [String], timeout: TimeInterval) async -> [LampRoku] {
            var found: [LampRoku] = []
            // A few dozen at a time: a sweep of a whole home network is 254 addresses.
            for batch in stride(from: 0, to: addresses.count, by: 48).map({ Array(addresses[$0..<min($0 + 48, addresses.count)]) }) {
                await withTaskGroup(of: LampRoku?.self) { group in
                    for address in batch {
                        group.addTask { (try? await request(address, "/query/device-info", method: "GET", timeout: timeout)).flatMap { roku(at: address, from: $0) } }
                    }
                    for await roku in group { if let roku, !found.contains(where: { $0.id == roku.id }) { found.append(roku) } }
                }
            }
            return found
        }

        private static func roku(at address: String, from xml: String) -> LampRoku? {
            func field(_ tag: String) -> String { matches("<\(tag)>([^<]*)</\(tag)>", in: xml).first.map { unescaped($0[0]) } ?? "" }
            let serial = field("serial-number")
            guard !serial.isEmpty else { return nil }
            let model = field("friendly-model-name").isEmpty ? field("model-name") : field("friendly-model-name")
            let name = field("user-device-name").isEmpty ? model : field("user-device-name")
            // ecp-setting-mode isn't in Roku's documentation, but Rokus report it.
            return LampRoku(id: serial, name: name, model: model, address: address, isTV: field("is-tv") == "true", control: field("ecp-setting-mode"))
        }

        private static func apps(in xml: String) -> [App] {
            matches(#"<app ([^>]*)>([^<]*)</app>"#, in: xml).map { match in
                let attributes = Dictionary(matches(#"([a-z-]+)="([^"]*)""#, in: match[0]).map { ($0[0], $0[1]) }) { first, _ in first }
                return App(id: attributes["id"] ?? "", name: unescaped(match[1]), version: attributes["version"] ?? "")
            }
        }

        private static func matches(_ pattern: String, in text: String) -> [[String]] {
            guard let regex = try? NSRegularExpression(pattern: pattern) else { return [] }
            return regex.matches(in: text, range: NSRange(text.startIndex..., in: text)).map { match in
                (1..<match.numberOfRanges).map { Range(match.range(at: $0), in: text).map { String(text[$0]) } ?? "" }
            }
        }

        private static func unescaped(_ text: String) -> String {
            text.replacingOccurrences(of: "&lt;", with: "<").replacingOccurrences(of: "&gt;", with: ">")
                .replacingOccurrences(of: "&quot;", with: "\"").replacingOccurrences(of: "&apos;", with: "'")
                .replacingOccurrences(of: "&amp;", with: "&")
        }

        /// The addresses that answered an SSDP search for Rokus. An iPhone app may not send it without an entitlement
        /// Apple grants on request; then nothing answers, and the sweep finds them instead.
        private static func ssdp(timeout: TimeInterval) async -> [String] {
            await Task.detached { () -> [String] in
                let socketID = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP)
                guard socketID >= 0 else { return [] }
                defer { close(socketID) }
                var wait = timeval(tv_sec: 0, tv_usec: 250_000)
                setsockopt(socketID, SOL_SOCKET, SO_RCVTIMEO, &wait, socklen_t(MemoryLayout<timeval>.size))
                var to = sockaddr_in()
                to.sin_family = sa_family_t(AF_INET)
                to.sin_port = in_port_t(1900).bigEndian
                to.sin_addr.s_addr = inet_addr("239.255.255.250")
                let search = Array("M-SEARCH * HTTP/1.1\r\nHOST: 239.255.255.250:1900\r\nMAN: \"ssdp:discover\"\r\nST: roku:ecp\r\nMX: 1\r\n\r\n".utf8)
                let sent = withUnsafePointer(to: &to) { pointer in
                    pointer.withMemoryRebound(to: sockaddr.self, capacity: 1) { sendto(socketID, search, search.count, 0, $0, socklen_t(MemoryLayout<sockaddr_in>.size)) }
                }
                guard sent > 0 else { return [] }
                var found: [String] = []
                var buffer = [UInt8](repeating: 0, count: 2048)
                let end = Date().addingTimeInterval(timeout)
                while Date() < end {
                    let count = recv(socketID, &buffer, buffer.count, 0)
                    guard count > 0 else { continue }
                    let answer = String(decoding: buffer[0..<count], as: UTF8.self)
                    guard answer.lowercased().contains("roku:ecp"),
                          let line = answer.split(whereSeparator: \.isNewline).first(where: { $0.lowercased().hasPrefix("location:") }),
                          let host = URL(string: line.dropFirst("location:".count).trimmingCharacters(in: .whitespaces))?.host,
                          !found.contains(host) else { continue }
                    found.append(host)
                }
                return found
            }.value
        }

        /// The other addresses of this device's home network (its /24), for the sweep.
        private static func neighbours() -> [String] { LampNetwork.neighbours() }
    }

    // MARK: - Network

    /// What's on the person's home network, for an app that controls, plays to or reads their devices (a remote for
    /// the TV and speakers, what's playing, a light), and the system's Local Network permission that comes first: on
    /// the iPhone, and on a Mac since macOS 15, nothing on the network answers until the person allows it.
    ///
    ///     // After the app has said in its own words why it looks (a first screen, a button):
    ///     switch await LampNetwork.requestAccess() {             // the system asks the person once
    ///     case .allowed: devices = await LampNetwork.find()       // everything that answers, with what it says of itself
    ///     case .denied: Text(LampNetwork.allowHint)               // where to turn it on; offer to look again
    ///     default: Text("Join your home Wi-Fi to find your devices.")
    ///     }
    ///     LampNetwork.access                                      // the last answer, without asking
    ///
    /// `find()` asks with SSDP (to the whole network on a Mac, and to each address on it, which also works on an
    /// iPhone) and with Bonjour, for the types the app declares in capabilities.json's `bonjourServices` (an iPhone
    /// app sees only those; a Mac app also looks for common ones: AirPlay, Google Cast, Sonos, Spotify Connect,
    /// HomeKit). Each device comes with its address, name, maker and model, what it answered SSDP for and the
    /// Bonjour services it offers: enough to work out how to reach it. A Roku is `LampRoku`'s.
    enum LampNetwork {
        struct Access: RawRepresentable, Hashable, Codable {
            var rawValue: String
            /// Not asked yet, or not on a home network (no Wi-Fi or Ethernet with a private address).
            static let unknown = Access(rawValue: "unknown")
            static let allowed = Access(rawValue: "allowed")
            /// The person said no, or hasn't answered the system's question.
            static let denied = Access(rawValue: "denied")
        }

        struct Device: Identifiable, Codable, Hashable {
            var id: String { address }
            var address: String
            /// What it calls itself (its UPnP friendly name or Bonjour name), else its address.
            var name: String
            var maker: String
            var model: String
            /// The SERVER line of its SSDP answer ("Roku/15.3.4 UPnP/1.0 Roku/15.3.4"); empty when it didn't answer SSDP.
            var server: String
            /// What it answered SSDP for ("roku:ecp", "urn:schemas-upnp-org:device:MediaRenderer:1").
            var ssdp: [String]
            /// Where its UPnP description is, from its SSDP answer.
            var location: String?
            var bonjour: [Service]
        }

        struct Service: Codable, Hashable {
            var type: String    // "_sonos._tcp"
            var name: String
            var port: Int?
            /// What it says of itself in its TXT record (an AirPlay device's "model", a Cast device's "md" and "fn").
            var txt: [String: String] = [:]
        }

        /// Where the person turns Local Network on for this app.
        static var allowHint: String {
            #if os(iOS)
            "Allow Local Network for this app in Settings, Privacy & Security, Local Network."
            #else
            "Allow this app in System Settings, Privacy & Security, Local Network."
            #endif
        }

        private static let accessKey = "lamp.network.access", askedKey = "lamp.network.asked"

        /// The last answer `requestAccess()` heard, without asking.
        static var access: Access {
            Access(rawValue: UserDefaults.standard.string(forKey: accessKey) ?? "unknown")
        }

        /// Asks for the local network. The first time, the system puts its question up and this waits for the
        /// person's answer (`timeout` at most); after that it says how things stand at once. Call it after the app has
        /// said why, never at launch.
        static func requestAccess(timeout: TimeInterval = 60) async -> Access {
            guard let target = neighbours().first else { return remember(.unknown) }
            let asked = UserDefaults.standard.bool(forKey: askedKey)
            UserDefaults.standard.set(true, forKey: askedKey)
            let until = Date().addingTimeInterval(asked ? 0 : timeout)
            while true {
                let now = await probe(target)
                if now == .allowed || Date() >= until { return remember(now) }
                try? await Task.sleep(for: .seconds(1))
            }
        }

        @discardableResult private static func remember(_ access: Access) -> Access {
            UserDefaults.standard.set(access.rawValue, forKey: accessKey)
            return access
        }

        /// A datagram to a neighbor, which is what has the system ask; its path says whether the network is allowed.
        private static func probe(_ address: String) async -> Access {
            let connection = NWConnection(host: NWEndpoint.Host(address), port: 1900, using: .udp)
            return await withCheckedContinuation { continuation in
                let once = Once()
                @Sendable func finish(_ access: Access) {
                    guard once.take() else { return }
                    connection.cancel()
                    continuation.resume(returning: access)
                }
                connection.stateUpdateHandler = { state in
                    switch state {
                    case .ready:
                        connection.send(content: Data(search("ssdp:all").utf8), completion: .contentProcessed { _ in finish(.allowed) })
                    case .waiting, .failed:
                        finish(connection.currentPath?.unsatisfiedReason == .localNetworkDenied ? .denied : .unknown)
                    default: break
                    }
                }
                connection.start(queue: .global())
                DispatchQueue.global().asyncAfter(deadline: .now() + 3) { finish(.unknown) }
            }
        }

        // MARK: Finding

        /// Everything that answers on the home network, by name. `bonjour` adds Bonjour types to look for; on an iPhone
        /// each must be in capabilities.json's `bonjourServices`, or the system refuses to look.
        static func find(bonjour: [String] = [], timeout: TimeInterval = 3) async -> [Device] {
            var wanted = Set(bonjour + (Bundle.main.object(forInfoDictionaryKey: "NSBonjourServices") as? [String] ?? []))
            #if os(macOS)
            wanted.formUnion(["_airplay._tcp", "_googlecast._tcp", "_sonos._tcp", "_spotify-connect._tcp", "_hap._tcp"])
            #endif
            let types = Array(wanted)
            async let answered = ssdp(timeout: timeout)
            async let advertised = browse(types, timeout: timeout)
            var byAddress: [String: Device] = [:]
            for answer in await answered {
                var device = byAddress[answer.address] ?? Device(address: answer.address, name: answer.address, maker: "", model: "", server: "", ssdp: [], bonjour: [])
                if device.server.isEmpty { device.server = answer.server }
                if !answer.target.isEmpty, !answer.target.hasPrefix("uuid:"), !device.ssdp.contains(answer.target) { device.ssdp.append(answer.target) }
                if device.location == nil, let location = answer.location, URL(string: location)?.host == answer.address { device.location = location }
                byAddress[answer.address] = device
            }
            for (address, service) in await advertised {
                var device = byAddress[address] ?? Device(address: address, name: service.name, maker: "", model: "", server: "", ssdp: [], bonjour: [])
                if !device.bonjour.contains(service) { device.bonjour.append(service) }
                if device.name == address { device.name = service.name }
                byAddress[address] = device
            }
            // Each SSDP device's own description: what it's called, who made it, what it is.
            await withTaskGroup(of: Device.self) { group in
                for device in byAddress.values {
                    group.addTask { await described(device) }
                }
                for await device in group { byAddress[device.address] = device }
            }
            // This device answers its own Bonjour look; it isn't one of the person's things to control.
            let mine = own()
            return byAddress.values.filter { !mine.contains($0.address) && !$0.address.hasPrefix("127.") }
                .sorted { $0.name.localizedStandardCompare($1.name) == .orderedAscending }
        }

        private static func described(_ device: Device) async -> Device {
            guard let location = device.location, let url = URL(string: location), url.scheme == "http",
                  let (data, _) = try? await URLSession.shared.data(for: URLRequest(url: url, timeoutInterval: 2)) else { return device }
            let xml = String(decoding: data, as: UTF8.self)
            func tag(_ name: String) -> String? {
                guard let open = xml.range(of: "<\(name)>"), let close = xml.range(of: "</\(name)>", range: open.upperBound..<xml.endIndex) else { return nil }
                let text = String(xml[open.upperBound..<close.lowerBound]).replacingOccurrences(of: "&amp;", with: "&")
                    .replacingOccurrences(of: "&lt;", with: "<").replacingOccurrences(of: "&gt;", with: ">")
                    .replacingOccurrences(of: "&quot;", with: "\"").replacingOccurrences(of: "&apos;", with: "'")
                    .trimmingCharacters(in: .whitespacesAndNewlines)
                return text.isEmpty ? nil : text
            }
            var device = device
            // A speaker's room ("Living Room") is what the person calls it, where its friendly name is a serial number.
            if let name = tag("roomName") ?? tag("friendlyName") { device.name = name }
            device.maker = tag("manufacturer") ?? device.maker
            device.model = tag("modelName") ?? tag("modelDescription") ?? device.model
            return device
        }

        private struct Answer {
            let address: String, server: String, location: String?, target: String
        }

        private static func search(_ target: String) -> String {
            "M-SEARCH * HTTP/1.1\r\nHOST: 239.255.255.250:1900\r\nMAN: \"ssdp:discover\"\r\nMX: 1\r\nST: \(target)\r\n\r\n"
        }

        /// One SSDP search, to the whole network where the system lets it (a Mac) and to each address near this
        /// device's, which needs no multicast and so works on an iPhone too. Most players and TVs answer either.
        private static func ssdp(timeout: TimeInterval) async -> [Answer] {
            let hosts = neighbours()
            return await Task.detached { () -> [Answer] in
                let socketID = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP)
                guard socketID >= 0 else { return [] }
                defer { close(socketID) }
                var wait = timeval(tv_sec: 0, tv_usec: 250_000)
                setsockopt(socketID, SOL_SOCKET, SO_RCVTIMEO, &wait, socklen_t(MemoryLayout<timeval>.size))
                let message = Array(search("ssdp:all").utf8)
                // Sent without waiting: a send to an address nobody has can stall while the network looks for it.
                let flags = fcntl(socketID, F_GETFL)
                _ = fcntl(socketID, F_SETFL, flags | O_NONBLOCK)
                for host in ["239.255.255.250"] + hosts {
                    var to = sockaddr_in()
                    to.sin_family = sa_family_t(AF_INET)
                    to.sin_port = in_port_t(1900).bigEndian
                    to.sin_addr.s_addr = inet_addr(host)
                    for _ in 0..<2 {
                        let sent = withUnsafePointer(to: &to) { pointer in
                            pointer.withMemoryRebound(to: sockaddr.self, capacity: 1) { sendto(socketID, message, message.count, 0, $0, socklen_t(MemoryLayout<sockaddr_in>.size)) }
                        }
                        // A full buffer is given a moment; any other refusal (no route, an address that's away) is skipped.
                        guard sent < 0, errno == EAGAIN || errno == ENOBUFS else { break }
                        usleep(5_000)
                    }
                }
                _ = fcntl(socketID, F_SETFL, flags)
                var found: [Answer] = []
                var buffer = [UInt8](repeating: 0, count: 4096)
                let end = Date().addingTimeInterval(timeout)
                while Date() < end {
                    var from = sockaddr_in()
                    var length = socklen_t(MemoryLayout<sockaddr_in>.size)
                    let count = withUnsafeMutablePointer(to: &from) {
                        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) { recvfrom(socketID, &buffer, buffer.count, 0, $0, &length) }
                    }
                    guard count > 0 else { continue }
                    let address = String(cString: inet_ntoa(from.sin_addr))
                    var fields: [String: String] = [:]
                    for line in String(decoding: buffer[0..<count], as: UTF8.self).split(whereSeparator: \.isNewline).dropFirst() {
                        guard let colon = line.firstIndex(of: ":") else { continue }
                        fields[line[..<colon].lowercased()] = line[line.index(after: colon)...].trimmingCharacters(in: .whitespaces)
                    }
                    found.append(Answer(address: address, server: fields["server"] ?? "", location: fields["location"], target: fields["st"] ?? ""))
                }
                return found
            }.value
        }

        /// The devices that advertise these Bonjour types, each resolved to its address, without reaching the device.
        private static func browse(_ types: [String], timeout: TimeInterval) async -> [(String, Service)] {
            await withTaskGroup(of: [(String, Service)].self) { group in
                for type in types {
                    group.addTask {
                        // Resolved all at once: a home can have a dozen AirPlay speakers, each a moment's wait.
                        await withTaskGroup(of: (String, Service)?.self) { each in
                            for (endpoint, txt) in await services(of: type, timeout: timeout) {
                                guard case .service(let name, _, let domain, _) = endpoint else { continue }
                                each.addTask {
                                    await Task.detached { resolve(name: name, type: type, domain: domain) }.value
                                        .map { ($0.0, Service(type: type, name: name, port: $0.1, txt: txt)) }
                                }
                            }
                            var found: [(String, Service)] = []
                            for await one in each { if let one { found.append(one) } }
                            return found
                        }
                    }
                }
                var all: [(String, Service)] = []
                for await found in group { all += found }
                return all
            }
        }

        private static func services(of type: String, timeout: TimeInterval) async -> [(NWEndpoint, [String: String])] {
            let browser = NWBrowser(for: .bonjourWithTXTRecord(type: type, domain: nil), using: .tcp)
            let seen = Seen()
            browser.browseResultsChangedHandler = { results, _ in
                seen.set(results.map { result in
                    if case .bonjour(let record) = result.metadata { return (result.endpoint, record.dictionary) }
                    return (result.endpoint, [:])
                })
            }
            browser.start(queue: .global())
            try? await Task.sleep(for: .seconds(timeout))
            browser.cancel()
            return seen.endpoints
        }

        /// What a browser has seen so far, from its own queue.
        private final class Seen: @unchecked Sendable {
            private let lock = NSLock()
            private var list: [(NWEndpoint, [String: String])] = []
            func set(_ endpoints: [(NWEndpoint, [String: String])]) { lock.lock(); list = endpoints; lock.unlock() }
            var endpoints: [(NWEndpoint, [String: String])] { lock.lock(); defer { lock.unlock() }; return list }
        }

        /// The first of several callers to finish a wait, so it's resumed once.
        private final class Once: @unchecked Sendable {
            private let lock = NSLock()
            private var done = false
            func take() -> Bool { lock.lock(); defer { lock.unlock() }; if done { return false }; done = true; return true }
        }

        /// A Bonjour service's IPv4 address and port, asked of the network (mDNS) and never of the device: its host and
        /// port from the service's record, then the host's address.
        private static func resolve(name: String, type: String, domain: String) -> (String, Int?)? {
            final class Answer { var host: String?; var port: Int? }
            let answer = Answer()
            var reference: DNSServiceRef?
            let heard: DNSServiceResolveReply = { _, _, _, code, _, host, port, _, _, context in
                guard code == kDNSServiceErr_NoError, let host, let context else { return }
                let answer = Unmanaged<Answer>.fromOpaque(context).takeUnretainedValue()
                answer.host = String(cString: host)
                answer.port = Int(UInt16(bigEndian: port))
            }
            let started = withExtendedLifetime(answer) {
                DNSServiceResolve(&reference, 0, 0, name, type, domain, heard, Unmanaged.passUnretained(answer).toOpaque())
            }
            guard started == kDNSServiceErr_NoError, let reference else { return nil }
            defer { DNSServiceRefDeallocate(reference) }
            var waiting = pollfd(fd: DNSServiceRefSockFD(reference), events: Int16(POLLIN), revents: 0)
            if poll(&waiting, 1, 3000) > 0 { DNSServiceProcessResult(reference) }
            guard let host = answer.host else { return nil }
            var hints = addrinfo()
            hints.ai_family = AF_INET
            hints.ai_socktype = SOCK_STREAM
            var found: UnsafeMutablePointer<addrinfo>?
            guard getaddrinfo(host, nil, &hints, &found) == 0, let first = found, let address = first.pointee.ai_addr else { return nil }
            defer { freeaddrinfo(found) }
            let ip = address.withMemoryRebound(to: sockaddr_in.self, capacity: 1) { String(cString: inet_ntoa($0.pointee.sin_addr)) }
            return (ip, answer.port)
        }

        /// The other addresses of this device's home network (its /24).
        static func neighbours() -> [String] {
            var hosts: [String] = []
            for ip in homeAddresses().sorted() {
                for last in UInt32(1)...254 where ip & 0xFFFF_FF00 | last != ip {
                    let host = ip & 0xFFFF_FF00 | last
                    let text = "\(host >> 24).\(host >> 16 & 0xFF).\(host >> 8 & 0xFF).\(host & 0xFF)"
                    if !hosts.contains(text) { hosts.append(text) }
                }
            }
            return hosts
        }

        /// This device's own addresses on a home network: 10/8, 172.16/12 and 192.168/16.
        private static func homeAddresses() -> Set<UInt32> {
            var list: UnsafeMutablePointer<ifaddrs>?
            guard getifaddrs(&list) == 0, let first = list else { return [] }
            defer { freeifaddrs(list) }
            var own: Set<UInt32> = []
            for pointer in sequence(first: first, next: { $0.pointee.ifa_next }) {
                let entry = pointer.pointee
                guard let address = entry.ifa_addr, address.pointee.sa_family == sa_family_t(AF_INET),
                      Int32(entry.ifa_flags) & IFF_UP != 0, Int32(entry.ifa_flags) & IFF_LOOPBACK == 0 else { continue }
                let ip = address.withMemoryRebound(to: sockaddr_in.self, capacity: 1) { UInt32(bigEndian: $0.pointee.sin_addr.s_addr) }
                if ip >> 24 == 10 || ip >> 20 == 0xAC1 || ip >> 16 == 0xC0A8 { own.insert(ip) }
            }
            return own
        }

        private static func own() -> Set<String> {
            Set(homeAddresses().map { "\($0 >> 24).\($0 >> 16 & 0xFF).\($0 >> 8 & 0xFF).\($0 & 0xFF)" })
        }
    }

    #if os(iOS)
    // MARK: - Home

    /// The person's home, as HomeKit has it: lights, locks, thermostats, sensors and switches, to read and to
    /// act on. iPhone only. Needs `{"homekit": true}` in capabilities.json, which signs the app for it; the
    /// system asks the person once.
    ///
    ///     let things = try await LampHome.accessories()          // each with its room and what it is
    ///     try await LampHome.set(lamp, on: true)
    ///     try await LampHome.set(lamp, brightness: 40)
    ///     try await LampHome.set(door, locked: true)
    ///     let fresh = try await LampHome.read(sensor)             // its latest value
    @MainActor
    final class LampHome: NSObject, ObservableObject, HMHomeManagerDelegate {
        static let shared = LampHome()

        struct Accessory: Identifiable, Codable, Hashable {
            var id: String            // HomeKit's identifier
            var name: String
            var room: String
            var kind: String          // "Light", "Lock", "Thermostat", "Sensor", "Switch", "Outlet", or the category's name
            var isOn: Bool?           // lights, switches, outlets
            var brightness: Int?      // %
            var isLocked: Bool?
            var temperature: Double?  // °C, from a thermostat or sensor
            var humidity: Double?     // %
            var isReachable: Bool
        }

        struct Failure: LocalizedError {
            let message: String
            var errorDescription: String? { message }
        }

        @Published private(set) var accessories: [Accessory] = []
        @Published private(set) var status = "Loading the home…"

        private let manager = HMHomeManager()
        private var loaded = false
        private var waiting: [CheckedContinuation<Void, Never>] = []

        private override init() {
            super.init()
            manager.delegate = self
        }

        /// Everything in the person's primary home, read fresh.
        static func accessories() async throws -> [Accessory] {
            let me = shared
            if !me.loaded { await withCheckedContinuation { me.waiting.append($0) } }
            guard let home = me.manager.primaryHome else {
                throw Failure(message: me.manager.authorizationStatus.contains(.restricted) ? "The app isn't allowed to see the home. The person can allow it in Settings." : "No home is set up on this iPhone.")
            }
            var found: [Accessory] = []
            for accessory in home.accessories {
                for service in accessory.services where Self.kinds[service.serviceType] != nil {
                    for characteristic in service.characteristics where characteristic.properties.contains(HMCharacteristicPropertyReadable) {
                        try? await characteristic.readValue()
                    }
                    found.append(me.describe(accessory, service))
                }
            }
            me.accessories = found
            me.status = "\(found.count) things in \(home.name)"
            return found
        }

        static func set(_ accessory: Accessory, on: Bool) async throws {
            try await write(accessory, HMCharacteristicTypePowerState, on)
        }

        static func set(_ accessory: Accessory, brightness: Int) async throws {
            try await write(accessory, HMCharacteristicTypeBrightness, max(0, min(100, brightness)))
        }

        static func set(_ accessory: Accessory, locked: Bool) async throws {
            try await write(accessory, HMCharacteristicTypeTargetLockMechanismState, locked ? HMCharacteristicValueLockMechanismState.secured.rawValue : HMCharacteristicValueLockMechanismState.unsecured.rawValue)
        }

        /// The thing again, with its latest values.
        static func read(_ accessory: Accessory) async throws -> Accessory {
            try await accessories().first { $0.id == accessory.id } ?? accessory
        }

        private static func write(_ accessory: Accessory, _ type: String, _ value: Any) async throws {
            guard let (device, service) = shared.find(accessory.id) else { throw Failure(message: "\(accessory.name) isn't in the home any more.") }
            guard let characteristic = service.characteristics.first(where: { $0.characteristicType == type }) else {
                throw Failure(message: "\(accessory.name) can't do that.")
            }
            do { try await characteristic.writeValue(value) } catch { throw Failure(message: "\(device.name) didn't take it: \(error.localizedDescription)") }
        }

        private func find(_ id: String) -> (HMAccessory, HMService)? {
            guard let home = manager.primaryHome else { return nil }
            for accessory in home.accessories {
                for service in accessory.services where service.uniqueIdentifier.uuidString == id { return (accessory, service) }
            }
            return nil
        }

        private static let kinds: [String: String] = [
            HMServiceTypeLightbulb: "Light", HMServiceTypeLockMechanism: "Lock", HMServiceTypeThermostat: "Thermostat",
            HMServiceTypeTemperatureSensor: "Sensor", HMServiceTypeHumiditySensor: "Sensor", HMServiceTypeMotionSensor: "Sensor",
            HMServiceTypeContactSensor: "Sensor", HMServiceTypeOccupancySensor: "Sensor", HMServiceTypeSwitch: "Switch",
            HMServiceTypeOutlet: "Outlet", HMServiceTypeFan: "Fan", HMServiceTypeGarageDoorOpener: "Garage door",
            HMServiceTypeWindowCovering: "Blind", HMServiceTypeDoorbell: "Doorbell",
        ]

        private func describe(_ accessory: HMAccessory, _ service: HMService) -> Accessory {
            func value<T>(_ type: String, as: T.Type) -> T? { service.characteristics.first { $0.characteristicType == type }?.value as? T }
            let lock = value(HMCharacteristicTypeCurrentLockMechanismState, as: Int.self)
            return Accessory(id: service.uniqueIdentifier.uuidString, name: service.name.isEmpty ? accessory.name : service.name,
                             room: accessory.room?.name ?? "", kind: Self.kinds[service.serviceType] ?? service.localizedDescription,
                             isOn: value(HMCharacteristicTypePowerState, as: Bool.self), brightness: value(HMCharacteristicTypeBrightness, as: Int.self),
                             isLocked: lock.map { $0 == HMCharacteristicValueLockMechanismState.secured.rawValue },
                             temperature: value(HMCharacteristicTypeCurrentTemperature, as: Double.self),
                             humidity: value(HMCharacteristicTypeCurrentRelativeHumidity, as: Double.self), isReachable: accessory.isReachable)
        }

        // MARK: HMHomeManagerDelegate

        nonisolated func homeManagerDidUpdateHomes(_ manager: HMHomeManager) {
            Task { @MainActor in
                loaded = true
                let waiting = self.waiting
                self.waiting = []
                for continuation in waiting { continuation.resume() }
            }
        }
    }
    #endif

    /// The app's own files, from its Assets/ folder, bundled inside it (Contents/Resources/Assets).
    ///
    ///     let logo = LampAssets.image("logo.png")
    ///     let csv = LampAssets.text("prices.csv")
    enum LampAssets {
        #if LAMP_LIVE
        // A live build reads them from the app's folder, so a file added while the app is open is there at once.
        static var folder: URL? { URL(fileURLWithPath: LampInstall.app + "/Assets") }
        #else
        static var folder: URL? { Bundle.main.resourceURL?.appendingPathComponent("Assets") }
        #endif

        static func url(_ name: String) -> URL? {
            guard let url = folder?.appendingPathComponent(name),
                  FileManager.default.fileExists(atPath: url.path) else { return nil }
            return url
        }

        static func image(_ name: String) -> LampImage? { url(name).flatMap(LampImage.lamp(contentsOf:)) }

        static func text(_ name: String) -> String? { url(name).flatMap { try? String(contentsOf: $0, encoding: .utf8) } }

        /// Every file's name.
        static var names: [String] {
            guard let folder else { return [] }
            return ((try? FileManager.default.contentsOfDirectory(atPath: folder.path)) ?? []).sorted()
        }
    }

    /// JavaScriptCore's execution limit. It's in the framework but not its public headers; it has been stable
    /// since 2013 and is what Mac apps that host scripts use to stop runaway code.
    private typealias JSShouldTerminateCallback = @convention(c) (JSContextRef?, UnsafeMutableRawPointer?) -> Bool
    @_silgen_name("JSContextGroupSetExecutionTimeLimit")
    private func JSContextGroupSetExecutionTimeLimit(_ group: JSContextGroupRef?, _ limit: Double,
                                                     _ callback: JSShouldTerminateCallback?, _ context: UnsafeMutableRawPointer?)

    /// Behavior the AI writes while the app runs: small JavaScript functions against an API the app exposes.
    /// Use it when the app needs logic nobody wrote in advance: what happens when two invented objects meet,
    /// how a new kind of actor behaves, a rule the person just described. The AI gets the exposed functions'
    /// names and docs and writes the function body; the app runs it in a sealed JavaScript context.
    ///
    ///     let world = LampScript()
    ///     world.expose("spawn", "spawn(name, x, y): adds a new thing at a point. Returns its id.") { args in
    ///         scene.spawn(args[0].toString(), at: args[1].toDouble(), args[2].toDouble())
    ///     }
    ///     world.expose("push", "push(id, dx, dy): pushes a thing.") { args in physics.push(args[0].toString(), args[1].toDouble(), args[2].toDouble()); return nil }
    ///     world.exposeAsync("isTrue", "isTrue(question, about): asks the decision model; returns a boolean.") { args in
    ///         try await LampAI.isTrue(args[0].toString(), about: args[1].toObject())
    ///     }
    ///     // Later, when a magnet first meets a key:
    ///     let rule = try await world.write("the rule for when a \(a.name) touches a \(b.name)",
    ///                                      parameters: ["a", "b"], for: "magnet|key")
    ///     try await world.run(rule, with: [a.dictionary, b.dictionary])
    ///
    /// Scripts run in a context that only has what the app exposed plus plain JavaScript (no files, network or
    /// Mac access), with a time limit. `write` caches scripts by key in LampStore, so a behavior is written
    /// once and reused; `forget(key)` throws one away. Keep the exposed API small and well described: that's
    /// what makes the AI's scripts correct. Keep movement, rendering and physics in Swift; scripts decide what
    /// should happen, not how to draw it. Report script errors to the person only when it matters to them.
    @MainActor
    final class LampScript {
        struct Failure: LocalizedError {
            let message: String
            var errorDescription: String? { message }
        }

        /// A script the AI wrote: the source of a JavaScript function `(params...) => { ... }`.
        struct Script: Codable, Identifiable, Equatable {
            var id: String          // the cache key
            var parameters: [String]
            var source: String
            var request: String
        }

        private let context: JSContext
        private var api: [(name: String, doc: String)] = []
        private var pending: [String: Task<Script, Error>] = [:]
        /// Runs waiting on a script's promise, by run number. If the engine stops a script after an await, the
        /// promise never settles (the aborted microtask just stops), so the native side settles the run instead.
        private var waiting: [Int: CheckedContinuation<Any?, Error>] = [:]
        private var runCount = 0
        /// The run whose JavaScript is executing right now (the engine runs one at a time), so a stop can be
        /// blamed on the right run and siblings suspended at an await are left alone.
        private var current: Int?
        private let scripts = LampStore.collection("forge_scripts", of: Script.self)
        /// A sentence about the app, so the AI knows what the scripts are for: "Draw is a kids' cartoon puzzle
        /// game where written words become doodles that interact." Set it once; it goes into every request.
        var purpose = ""
        /// How long a script's JavaScript may run, per run, before the engine stops it (so a runaway loop
        /// can't freeze the app). Time spent awaiting an exposed async function (isTrue, ask) doesn't count:
        /// the engine is idle then.
        var timeLimit: TimeInterval = 2

        init() {
            context = JSContext(virtualMachine: JSVirtualMachine())!
            // Keep the exception on the context so run() can report it (the default handler would drop it).
            context.exceptionHandler = { context, exception in
                context?.exception = exception
            }
            // Helpers scripts can rely on.
            context.evaluateScript("""
            const console = { log: (...args) => __log(args.map(a => typeof a === 'string' ? a : JSON.stringify(a)).join(' ')) };
            """)
            let log: @convention(block) (String) -> Void = { print("script: \($0)") }
            context.setObject(log, forKeyedSubscript: "__log" as NSString)
            applyTimeLimit()
        }

        // MARK: Exposing the app

        /// A function scripts can call. `doc` is one line in the form "name(args): what it does", which is what
        /// the AI sees. The handler gets the arguments as JSValues and returns a value (or nil) back to the script.
        func expose(_ name: String, _ doc: String, _ handler: @escaping ([JSValue]) -> Any?) {
            api.append((name, doc))
            let block: @convention(block) () -> Any? = {
                let args = JSContext.currentArguments() as? [JSValue] ?? []
                return handler(args)
            }
            context.setObject(block, forKeyedSubscript: name as NSString)
        }

        /// A function that awaits something (the decision model, a text model). Scripts call it with `await`.
        func exposeAsync(_ name: String, _ doc: String, _ handler: @escaping ([JSValue]) async throws -> Any?) {
            api.append((name, doc))
            // Registered blocks live as long as the context, which this object owns: capture it weakly so the
            // context's function doesn't keep the owner (and its compiled scripts) alive after it's let go.
            let block: @convention(block) () -> JSValue = { [weak self] in
                guard let self, let context = JSContext.current() else { return JSValue(undefinedIn: JSContext.current()) }
                let args = JSContext.currentArguments() as? [JSValue] ?? []
                // A promise the script awaits; resolved on the main actor when the Swift work finishes.
                let caller = self.current
                let promise = JSValue(newPromiseIn: context) { [weak self] resolve, reject in
                    Task { @MainActor in
                        guard let self else { return }
                        var result: Result<Any?, Error>
                        do { result = .success(try await handler(args)) } catch { result = .failure(error) }
                        // Resuming the script runs its next section now, on behalf of the run that called us.
                        let previous = self.current
                        self.current = caller
                        switch result {
                        case .success(let value): resolve?.call(withArguments: [value ?? NSNull()])
                        case .failure(let error): reject?.call(withArguments: [error.localizedDescription])
                        }
                        // If the engine stopped the script in that section, its promise never settles, so the
                        // run is failed from here. The engine only reports the stop on its next entry: give it one.
                        self.context.evaluateScript("0")
                        self.failCurrentIfTerminated()
                        self.current = previous
                    }
                }
                return promise ?? JSValue(undefinedIn: context)
            }
            context.setObject(block, forKeyedSubscript: name as NSString)
        }

        /// What the AI is told it can call.
        var apiDescription: String { api.map { "- " + $0.doc }.joined(separator: "\n") }

        // MARK: Writing scripts

        /// Asks the AI for a function that does `what`, taking `parameters`, using only the exposed API.
        /// Cached under `key`; the same key gives the same script until `forget(key)`.
        func write(_ what: String, parameters: [String], for key: String, context extra: String = "") async throws -> Script {
            if let saved = scripts.get(key) { return saved }
            if let running = pending[key] { return try await running.value }
            let task = Task<Script, Error> { @MainActor in
                let system = """
                You help a Mac app add behavior while it runs by writing a small JavaScript function. \
                \(purpose.isEmpty ? "" : purpose + " ")The app offers these functions:
                \(apiDescription)

                Use only those and plain JavaScript (Math, JSON, arrays, strings): there is no browser, Node, \
                timers or imports. Functions described as async must be awaited. Keep it to a few lines that make \
                the described thing happen. Reply with just the function body: no function keyword, no name, no \
                fences, no explanation.
                """
                let prompt = """
                Write the body of an async function with parameters (\(parameters.joined(separator: ", "))) that does: \
                \(what)
                \(extra.isEmpty ? "" : "\nContext:\n" + extra)
                """
                // Sonnet: it writes these reliably, where Opus's safety classifier often refuses code requests.
                var body = try await LampAI.ask(prompt, system: system, model: "sonnet")
                body = Self.stripFences(body)
                let script = Script(id: key, parameters: parameters, source: body, request: what)
                try compile(script)   // fails now, not when it first runs
                scripts.put(script)
                return script
            }
            pending[key] = task
            defer { pending[key] = nil }
            return try await task.value
        }

        func forget(_ key: String) { scripts.delete(key) }
        func forgetAll() { scripts.deleteAll() }

        // MARK: Running scripts

        /// Runs the script with the given arguments (JSON-friendly values: numbers, strings, arrays, dictionaries)
        /// and returns what it returned, as a Swift value. Throws if the script fails or runs past `timeLimit`.
        @discardableResult
        func run(_ script: Script, with arguments: [Any] = []) async throws -> Any? {
            let function = try compile(script)
            context.exception = nil
            applyTimeLimit()
            runCount += 1
            let number = runCount
            let previous = current
            current = number
            defer { current = previous }
            let result = function.call(withArguments: arguments.map { $0 })
            if let exception = context.exception {
                context.exception = nil
                throw failure(for: exception.toString() ?? "unknown")
            }
            guard let result else { throw Failure(message: "The script didn't run.") }
            // An async function returns a promise: wait for it. The run is settled exactly once, by whichever
            // comes first: the promise's handlers, or the native side noticing the engine stopped the script.
            if result.isObject, result.hasProperty("then") {
                return try await withCheckedThrowingContinuation { continuation in
                    waiting[number] = continuation
                    let onDone: @convention(block) (JSValue) -> Void = { [weak self] in
                        self?.settle(number, with: .success(Self.swift($0)))
                    }
                    let onFail: @convention(block) (JSValue) -> Void = { [weak self] in
                        guard let self else { return }
                        self.settle(number, with: .failure(self.failure(for: $0.toString() ?? "unknown")))
                    }
                    result.invokeMethod("then", withArguments: [
                        JSValue(object: onDone, in: context)!, JSValue(object: onFail, in: context)!,
                    ])
                    failCurrentIfTerminated()
                }
            }
            return Self.swift(result)
        }

        private func settle(_ number: Int, with outcome: Result<Any?, Error>) {
            guard let continuation = waiting.removeValue(forKey: number) else { return }
            continuation.resume(with: outcome)
        }

        /// If the engine has just stopped the script that was executing, fail that run (and only that run:
        /// siblings suspended at an await still have live promises).
        private func failCurrentIfTerminated() {
            guard let exception = context.exception, (exception.toString() ?? "").contains("execution terminated") else { return }
            context.exception = nil
            if let current { settle(current, with: .failure(failure(for: "execution terminated"))) }
        }

        private func failure(for text: String) -> Failure {
            Failure(message: text.contains("execution terminated")
                    ? "The script ran for more than \(timeLimit) seconds and was stopped." : "Script error: \(text)")
        }

        private var compiled: [String: JSValue] = [:]

        @discardableResult
        private func compile(_ script: Script) throws -> JSValue {
            let cacheKey = script.id + "\u{1}" + script.source
            if let function = compiled[cacheKey] { return function }
            context.exception = nil
            let source = "(async function(\(script.parameters.joined(separator: ", "))) {\n\(script.source)\n})"
            guard let function = context.evaluateScript(source), function.isObject, context.exception == nil else {
                throw Failure(message: "The script has a syntax error: \(context.exception?.toString() ?? "unknown")")
            }
            compiled[cacheKey] = function
            return function
        }

        /// The engine's own execution limit: it interrupts the script wherever it is, whatever loop or call form
        /// it used, so no source rewriting is needed and strings and comments are never touched. The limit
        /// applies to the whole context (every run shares it), and each JavaScript section of a run restarts
        /// the clock, since the engine only counts time while it's executing.
        private func applyTimeLimit() {
            let group = JSContextGetGroup(context.jsGlobalContextRef)
            JSContextGroupSetExecutionTimeLimit(group, timeLimit, { _, _ in true }, nil)
        }

        private static func stripFences(_ text: String) -> String {
            var t = text.trimmingCharacters(in: .whitespacesAndNewlines)
            if t.hasPrefix("```") {
                t = String(t.drop(while: { $0 != "\n" }).dropFirst())
                if let end = t.range(of: "```", options: .backwards) { t = String(t[..<end.lowerBound]) }
            }
            // The whole reply is one function (`async function (a, b) { … }`, `function f(a) { … }`,
            // `(a, b) => { … }`, `async (a) => { … }`) rather than a body: take the body out of it. Whether the
            // wrapper really encloses the entire reply is decided by the JavaScript parser, not by scanning
            // the text: the reply must parse as a single function expression, and what's inside the braces
            // must parse as a function body. A reply that starts with a helper function and goes on, or has
            // callbacks, regex literals or braces in strings, isn't one expression and is kept as is.
            let wrapper = #"^(?:async\s+)?(?:function\b[^{]*|\([^()]*\)\s*=>|[A-Za-z_$][\w$]*\s*=>)\s*\{"#
            if let open = t.range(of: wrapper, options: .regularExpression), t.hasSuffix("}") {
                let inner = String(t[open.upperBound..<t.index(before: t.endIndex)])
                if Self.parses(t, asBody: false) && Self.parses(inner, asBody: true) { t = inner }
            }
            return t.trimmingCharacters(in: .whitespacesAndNewlines)
        }

        /// Whether JavaScriptCore can parse `source` as an async function body (asBody) or as an expression.
        /// Parsing only, in a throwaway context: nothing runs.
        static func parses(_ source: String, asBody: Bool) -> Bool {
            let probe = JSContext(virtualMachine: JSVirtualMachine())!
            let program = asBody ? "async function __f() {\n\(source)\n}" : "(\(source))"
            // new Function compiles its argument without running it; a syntax error throws.
            let check = "(function() { try { new Function(\(Self.jsString(program))); return true; } catch (e) { return false; } })()"
            return probe.evaluateScript(check)?.toBool() ?? false
        }

        private static func jsString(_ text: String) -> String {
            let data = try? JSONSerialization.data(withJSONObject: [text])
            let array = data.flatMap { String(data: $0, encoding: .utf8) } ?? "[\"\"]"
            return String(array.dropFirst().dropLast())
        }

        /// JSValue → plain Swift (String, Double, Bool, [Any], [String: Any] or nil).
        static func swift(_ value: JSValue) -> Any? {
            if value.isUndefined || value.isNull { return nil }
            if value.isBoolean { return value.toBool() }
            if value.isNumber { return value.toDouble() }
            if value.isString { return value.toString() }
            return value.toObject()
        }
    }

    #if os(macOS)
    // Mac only: there are no other apps to drive on a phone.

    /// Does a task with the other apps on this Mac, the way the person would, using what they're already
    /// signed in to: Slack, Mail, Messages, Notes, Chrome or Safari (Gmail, LinkedIn, a CRM…), and so on.
    /// Lamp drives those apps in the background and returns the answer as text. Use it when the information
    /// lives in another app and there's no file or API to read instead.
    ///
    ///     let brief = try await LampComputer.ask("Summarize the LinkedIn profile open in Chrome as a prospect brief")
    ///     let recent = try await LampComputer.ask("List the 5 newest emails in Gmail in Chrome as JSON: [{from, subject, time}]")
    ///     try await LampComputer.perform("In Slack, open #sales and post: Demo moved to 3pm")
    ///
    /// `ask` only looks (reads windows and scrolls). `perform` may also click, type and press keys, and the
    /// person approves each of those in Lamp first. Both take 10–60 seconds: show progress, run them only when
    /// the person asks, and show `error.localizedDescription` on failure (for example when using other apps
    /// isn't set up yet in Lamp's Settings). The first use asks the person to turn it on.
    enum LampComputer {
        static func ask(_ task: String) async throws -> String {
            try await run(task, act: false)
        }

        @discardableResult
        static func perform(_ task: String) async throws -> String {
            try await run(task, act: true)
        }

        private static func run(_ task: String, act: Bool) async throws -> String {
            let reply = try await LampAI.post("/ai/computer", ["task": task, "act": act], timeout: 900)
            guard let text = reply["text"] as? String else { throw LampAI.Failure(message: "Using other apps failed.") }
            return text
        }
    }

    #endif

    #if os(macOS)
    /// This app's sidebar in Chrome, beside the page the person is on: a page of the app's own (`startPage`, below).
    /// An app built before pages publishes a Surface instead, which Lamp's extension draws, sending each click back
    /// to `handle`. Every Chrome tab has a sidebar of its
    /// own: `surface(tab)` draws one tab's, and `event.tab` says which tab a click came from, so keep what a click
    /// prepares (a preview, a draft) by tab and two pages never mix. Declare where it fits in browser.json at the
    /// app's root. Start it once, from the app's shared model:
    ///
    ///     LampBrowser.start(surface: { tab in model.sidebar(for: tab) }, handle: { event in await model.handle(event) })
    ///
    /// A page is read only when a button with `readsPage` (the page's readable text) or `readsSelection` (only the
    /// passage the person selected) is clicked. Page text is untrusted: give it to LampAI as `data:`.
    @MainActor
    enum LampBrowser {
        /// A heading with text under it, a list (`items`, one line each), or both.
        struct Section: Codable { var title: String; var text: String = ""; var items: [String] = [] }
        /// A field the person can change before clicking. `lines` above 1 makes it a box for longer text.
        struct Field: Codable { var id: String; var label: String; var value: String = ""; var lines: Int = 1 }
        /// A button. The first is drawn as the main one. Never both `readsPage` and `readsSelection`.
        struct Action: Codable { var id: String; var label: String; var readsPage: Bool = false; var readsSelection: Bool = false }
        struct Surface: Codable {
            var title: String
            var detail: String = ""
            var sections: [Section] = []
            var fields: [Field] = []
            var actions: [Action] = []
            var busy: Bool = false
        }
        struct Page: Codable {
            var url: String
            var title: String
            /// The page's readable text, or only the selected passage when `scope` is "selection".
            var text: String
            var scope: String?
            /// The page was longer than the 24,000 characters given: what's missing may be further down.
            var truncated: Bool?
            var isSelection: Bool { scope == "selection" }
            /// Whether `quote` is in the page's text word for word, ignoring case, spacing and the style of quote
            /// marks and dashes. An AI can make a quote up: check each one before showing or saving it as the page's.
            func contains(_ quote: String) -> Bool {
                func plain(_ s: String) -> String {
                    var t = s.lowercased()
                    for (from, to) in [("\u{2018}", "'"), ("\u{2019}", "'"), ("\u{201C}", "\""), ("\u{201D}", "\""),
                                       ("\u{2013}", "-"), ("\u{2014}", "-"), ("\u{00A0}", " ")] { t = t.replacingOccurrences(of: from, with: to) }
                    return t.split(whereSeparator: \.isWhitespace).joined(separator: " ")
                }
                let wanted = plain(quote)
                return !wanted.isEmpty && plain(text).contains(wanted)
            }
        }
        struct Event: Codable {
            var id: String
            /// Which Chrome tab the click came from (or Lamp's own preview of the sidebar).
            var tab: String
            var action: String
            /// What the person typed, by field id.
            var fields: [String: String]
            var page: Page?
        }
        private static var service: Task<Void, Never>?
        /// Start once from a shared app model. The sidebar stays up across opening and closing windows.
        static func start(surface: @escaping (_ tab: String) -> Surface, handle: @escaping (Event) async -> Void) {
            guard service == nil else { return }
            service = Task { await serve(surface: surface, handle: handle) }
        }
        /// For a sidebar that shows the same on every tab: one that keeps no draft or preview.
        static func start(surface: @escaping () -> Surface, handle: @escaping (Event) async -> Void) {
            start(surface: { _ in surface() }, handle: handle)
        }
        /// Asks Lamp to show this app's offer to connect Chrome. No browser installation belongs in app code.
        static func openSetup() async {
            _ = try? await LampAI.post("/browser/setup", [:], timeout: 10)
        }
        /// Publishes the surface twice a second, for each tab the sidebar is open in, and runs one click at a
        /// time. A click is acknowledged after `handle` returns; make saves idempotent by the page or item.
        private static func serve(surface: @escaping (String) -> Surface, handle: @escaping (Event) async -> Void) async {
            let boot = UUID().uuidString
            var ack: String?
            var handling: String?
            var tabs: [String] = []
            var work: Task<Void, Never>?
            defer { work?.cancel() }
            func encoded(_ tab: String) throws -> Any {
                var published = surface(tab)
                published.busy = published.busy || handling != nil
                return try JSONSerialization.jsonObject(with: JSONEncoder().encode(published))
            }
            while !Task.isCancelled {
                var pause = 0.5
                do {
                    var body: [String: Any] = ["boot": boot, "surface": try encoded(""),
                                               "surfaces": try Dictionary(uniqueKeysWithValues: tabs.prefix(16).map { ($0, try encoded($0)) })]
                    if let ack { body["ack"] = ack }
                    var request = URLRequest(url: URL(string: lampGateway + "/browser/surface")!)
                    request.httpMethod = "POST"
                    request.timeoutInterval = 5
                    request.setValue("Bearer \(LampInstall.token)", forHTTPHeaderField: "Authorization")
                    request.setValue("application/json", forHTTPHeaderField: "Content-Type")
                    request.httpBody = try JSONSerialization.data(withJSONObject: body)
                    let (data, response) = try await URLSession.shared.data(for: request)
                    let status = (response as? HTTPURLResponse)?.statusCode ?? 0
                    if status == 400, let reply = try? JSONSerialization.jsonObject(with: data) as? [String: Any] {
                        print("The browser sidebar couldn't be drawn: \(reply["error"] as? String ?? "") Check its sizes: up to 8 actions, 12 fields, 20 sections.")
                    }
                    // Lamp without the sidebar turned on: asked again now and then, in case it's turned on.
                    guard status == 200, let reply = try JSONSerialization.jsonObject(with: data) as? [String: Any] else {
                        pause = status == 404 || status == 403 ? 5 : 1
                        throw CancellationError()
                    }
                    tabs = reply["tabs"] as? [String] ?? []
                    if let rawEvent = reply["event"],
                       let event = try? JSONDecoder().decode(Event.self, from: JSONSerialization.data(withJSONObject: rawEvent)),
                       handling == nil, event.id != ack {
                        handling = event.id
                        work = Task { await handle(event); ack = event.id; handling = nil }
                    }
                } catch { /* Lamp closed or not ready: the sidebar shows again once it answers. */ }
                do { try await Task.sleep(for: .seconds(pause)) } catch { return }
            }
        }

        // MARK: The sidebar as the app's own page

        /// A call from the sidebar page's script, `lamp.call(name, body)`: its name, the Chrome tab it came from
        /// (keep what one tab prepares apart from another's), and the JSON it sent.
        struct Call: Sendable {
            var name: String
            var tab: String
            var body: Data
            func decode<T: Decodable>(_ type: T.Type) throws -> T {
                try JSONDecoder().decode(T.self, from: body.isEmpty ? Data("null".utf8) : body)
            }
        }
        /// Thrown from a page call: its message is what the page's `lamp.call` rejects with.
        struct Failure: Error, LocalizedError {
            var message: String
            init(_ message: String) { self.message = message }
            var errorDescription: String? { message }
        }

        /// The app serves its sidebar page itself (Assets/Sidebar, index.html first) on this Mac's own address, at a
        /// name and port of its own, so its sidebar works while the app is open whether Lamp is or not. Chrome's
        /// sidebar frames it; the page asks the app for its data and actions with `lamp.call`, and for the page the
        /// person is on with `lamp.readPage()` after a click, or when the app's right-click item is chosen (`lamp.onMenu`).
        /// `api` answers the calls, on the main actor:
        ///
        ///     LampBrowser.startPage { call in
        ///         switch call.name {
        ///         case "list": return model.saved
        ///         case "preview": return try await model.preview(call.decode(LampBrowser.Page.self), tab: call.tab)
        ///         default: throw LampBrowser.Failure("Unknown call \(call.name).")
        ///         }
        ///     }
        ///
        /// Call `pageChanged()` when what the page shows changed in the app, so `lamp.onChange` fires there.
        ///
        /// The page itself (Assets/Sidebar/index.html, its CSS and JavaScript beside it) is described, with a page
        /// to start from that goes through every state, in Lamp's chrome-sidebar skill: open it with `read_skill`.
        /// A call that fails throws `Failure`, whose message the page shows; the page loads nothing from the
        /// internet, so a picture of an item reaches it from the app (`/assets/<file>`, or a `data:` URL).
        static func startPage(api: @escaping @MainActor (Call) async throws -> any Encodable) {
            pageAPI = api
            PageServer.queue.async { PageServer.listen() }
        }
        static func pageChanged() { PageServer.queue.async { PageServer.version += 1 } }
        fileprivate static var pageAPI: (@MainActor (Call) async throws -> any Encodable)?

        /// A small HTTP server for the one page. Only requests naming the app's own host get anything (a website
        /// that points a name of its own at this Mac is refused), the page's data only with the key Chrome's
        /// sidebar was given, and only the extension may frame the page.
        fileprivate enum PageServer {
            /// The first of the ports the app may use; when another program has it, the next few are tried, as
            /// Chrome's sidebar and Lamp's preview do. Only this app answers its own name on any of them.
            static let firstPort = UInt16(clamping: LampInstall.number("sidebarPort"))
            static let tries = UInt16(clamping: max(1, LampInstall.number("sidebarTries")))
            nonisolated(unsafe) static var port: UInt16 = firstPort
            static let host = LampInstall.value("sidebarHost")
            static let key = LampInstall.value("sidebarKey")
            static let queue = DispatchQueue(label: "LampBrowser.page")
            nonisolated(unsafe) static var listeners: [NWListener] = []
            nonisolated(unsafe) static var version = 0
            static let policy = "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; font-src 'self' data:; connect-src 'self'; form-action 'none'; base-uri 'none'; frame-ancestors \(LampInstall.value("sidebarFramer"))"

            static var folder: URL? { LampAssets.folder?.appendingPathComponent("Sidebar") }

            /// Both of this Mac's own addresses, since Chrome tries `::1` first for a `.localhost` name: a program
            /// holding either one at a port would otherwise get the page's address, and its key, there. When either is
            /// taken, the next port is tried for both.
            static func listen(offset: UInt16 = 0) {
                guard listeners.isEmpty else { return }
                guard offset < tries, let endpoint = NWEndpoint.Port(rawValue: firstPort + offset) else {
                    return print("The sidebar page couldn't be served: other programs have ports \(firstPort)–\(firstPort + tries - 1).")
                }
                var made: [NWListener] = []
                for address in [IPv4Address.loopback as IPAddress, IPv6Address.loopback as IPAddress] {
                    let parameters = NWParameters.tcp
                    parameters.requiredLocalEndpoint = .hostPort(host: address is IPv4Address ? .ipv4(.loopback) : .ipv6(.loopback), port: endpoint)
                    // Network won't hold both addresses at one port without it; another program still can't share it.
                    parameters.allowLocalEndpointReuse = true
                    guard let listener = try? NWListener(using: parameters) else { made.forEach { $0.cancel() }; return listen(offset: offset + 1) }
                    made.append(listener)
                }
                listeners = made
                port = firstPort + offset
                for listener in made {
                    listener.newConnectionHandler = { accept($0) }
                    listener.stateUpdateHandler = { state in
                        switch state {
                        case .failed, .waiting:
                            // One address taken is the port taken: both move on together.
                            guard listeners.contains(where: { $0 === listener }) else { return }
                            listeners.forEach { $0.cancel() }
                            listeners = []
                            listen(offset: offset + 1)
                        default: break
                        }
                    }
                    listener.start(queue: queue)
                }
            }

            struct Request {
                var method: String, path: String, headers: [String: String], body: Data
                /// Nil until the whole request has arrived.
                init?(_ data: Data) {
                    guard let end = data.range(of: Data("\r\n\r\n".utf8)),
                          let head = String(data: data[..<end.lowerBound], encoding: .utf8) else { return nil }
                    var lines = head.components(separatedBy: "\r\n")
                    let first = lines.removeFirst().split(separator: " ")
                    guard first.count >= 2 else { return nil }
                    method = String(first[0]); path = String(first[1]); headers = [:]
                    for line in lines {
                        guard let colon = line.firstIndex(of: ":") else { continue }
                        headers[line[..<colon].lowercased()] = line[line.index(after: colon)...].trimmingCharacters(in: .whitespaces)
                    }
                    let length = Int(headers["content-length"] ?? "0") ?? 0
                    guard length >= 0, data.count - end.upperBound >= length else { return nil }
                    body = data[end.upperBound..<(end.upperBound + length)]
                }
            }

            static func accept(_ connection: NWConnection) {
                connection.start(queue: queue)
                var received = Data()
                var arrived = false
                // A request has a few seconds to arrive whole; the app's answer (an AI answer can take a minute) has
                // as long as it needs.
                queue.asyncAfter(deadline: .now() + 15) { if !arrived { connection.cancel() } }
                func read() {
                    connection.receive(minimumIncompleteLength: 1, maximumLength: 65_536) { data, _, complete, error in
                        if let data { received.append(data) }
                        if received.count > 1_100_000 { return connection.cancel() }
                        if let request = Request(received) { arrived = true; return respond(request, on: connection) }
                        if complete || error != nil { return connection.cancel() }
                        read()
                    }
                }
                read()
            }

            /// An SF Symbol as a PNG at `size` points (drawn at twice that), in `color` (hex) or black.
            @MainActor static func symbolPNG(_ name: String, color: String?, size: Int, weight: String?) -> Data? {
                let points = CGFloat(min(max(size, 8), 128))
                let weights: [String: NSFont.Weight] = ["ultralight": .ultraLight, "thin": .thin, "light": .light, "regular": .regular,
                                                        "medium": .medium, "semibold": .semibold, "bold": .bold, "heavy": .heavy, "black": .black]
                var tint = NSColor.black
                if let color, color.count == 6, let rgb = UInt32(color, radix: 16) {
                    tint = NSColor(srgbRed: CGFloat((rgb >> 16) & 255) / 255, green: CGFloat((rgb >> 8) & 255) / 255, blue: CGFloat(rgb & 255) / 255, alpha: 1)
                }
                let config = NSImage.SymbolConfiguration(pointSize: points, weight: weights[weight ?? ""] ?? .regular)
                    .applying(NSImage.SymbolConfiguration(paletteColors: [tint]))
                guard let symbol = NSImage(systemSymbolName: name, accessibilityDescription: nil)?.withSymbolConfiguration(config) else { return nil }
                let pixels = NSSize(width: ceil(symbol.size.width * 2), height: ceil(symbol.size.height * 2))
                guard let rep = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: Int(pixels.width), pixelsHigh: Int(pixels.height), bitsPerSample: 8,
                                                 samplesPerPixel: 4, hasAlpha: true, isPlanar: false, colorSpaceName: .deviceRGB, bytesPerRow: 0, bitsPerPixel: 0) else { return nil }
                rep.size = symbol.size
                NSGraphicsContext.saveGraphicsState()
                NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: rep)
                symbol.draw(in: NSRect(origin: .zero, size: symbol.size))
                NSGraphicsContext.restoreGraphicsState()
                return rep.representation(using: .png, properties: [:])
            }

            static func send(_ status: Int, _ type: String, _ body: Data, on connection: NWConnection) {
                let reason = [200: "OK", 400: "Bad Request", 403: "Forbidden", 404: "Not Found", 421: "Misdirected Request", 503: "Unavailable"][status] ?? "Error"
                let head = "HTTP/1.1 \(status) \(reason)\r\nContent-Type: \(type)\r\nContent-Length: \(body.count)\r\n" +
                    "Content-Security-Policy: \(policy)\r\nX-Content-Type-Options: nosniff\r\nCross-Origin-Resource-Policy: same-origin\r\n" +
                    "Referrer-Policy: no-referrer\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n"
                connection.send(content: Data(head.utf8) + body, completion: .contentProcessed { _ in connection.cancel() })
            }
            static func json(_ status: Int, _ value: [String: Any], on connection: NWConnection) {
                send(status, "application/json", (try? JSONSerialization.data(withJSONObject: value)) ?? Data("{}".utf8), on: connection)
            }

            static func respond(_ request: Request, on connection: NWConnection) {
                // A website can point any name at this Mac, and another program may have taken the app's first
                // port: only the app's own name, at the port it has, is answered.
                guard request.headers["host"] == "\(host):\(port)" else { return json(421, ["error": "Wrong host."], on: connection) }
                let path = request.path.split(separator: "?", maxSplits: 1).first.map(String.init) ?? "/"
                // Proof that this is the app, not another program that took one of its ports: the key's signature
                // over the sidebar's nonce and the port asked, which only the app can make and which fits only the
                // address it was asked at. Chrome's sidebar hands the page its key only after checking it.
                if path == "/lamp/proof", request.method == "GET" {
                    let query = request.path.split(separator: "?", maxSplits: 1).dropFirst().first.map(String.init) ?? ""
                    guard let nonce = URLComponents(string: "?" + query)?.queryItems?.first(where: { $0.name == "nonce" })?.value,
                          !nonce.isEmpty, nonce.count <= 100 else { return json(400, ["error": "No nonce."], on: connection) }
                    let code = HMAC<SHA256>.authenticationCode(for: Data("\(nonce):\(port)".utf8), using: SymmetricKey(data: Data(key.utf8)))
                    return json(200, ["proof": code.map { String(format: "%02x", $0) }.joined()], on: connection)
                }
                // The symbols the window shows, drawn by the app as the window draws them, so the page can use the same.
                if path.hasPrefix("/symbols/") {
                    let query = URLComponents(string: request.path)?.queryItems ?? []
                    let value = { (name: String) in query.first { $0.name == name }?.value }
                    let name = String(path.dropFirst("/symbols/".count)).replacingOccurrences(of: ".png", with: "")
                    guard name.count <= 80, name.allSatisfy({ $0.isLetter || $0.isNumber || $0 == "." }),
                          let png = DispatchQueue.main.sync(execute: { MainActor.assumeIsolated { symbolPNG(name, color: value("color"),
                                                                                 size: Int(value("size") ?? "") ?? 32, weight: value("weight")) } }) else {
                        return send(404, "text/plain", Data("Not found".utf8), on: connection)
                    }
                    return send(200, "image/png", png, on: connection)
                }
                // The app's own pictures (its Assets folder), so an item shows the picture the window shows for it.
                if path.hasPrefix("/assets/") {
                    let parts = path.dropFirst("/assets/".count).split(separator: "/").map { String($0).removingPercentEncoding ?? "" }
                    let images = ["png": "image/png", "jpg": "image/jpeg", "jpeg": "image/jpeg", "gif": "image/gif", "webp": "image/webp",
                                  "heic": "image/heic", "svg": "image/svg+xml"]
                    guard let assets = LampAssets.folder, !parts.isEmpty, parts.allSatisfy({ !$0.isEmpty && !$0.hasPrefix(".") }),
                          let type = images[(parts.last! as NSString).pathExtension.lowercased()] else {
                        return send(404, "text/plain", Data("Not found".utf8), on: connection)
                    }
                    let root = assets.resolvingSymlinksInPath().path + "/"
                    let file = parts.reduce(assets) { $0.appendingPathComponent($1) }.resolvingSymlinksInPath()
                    guard file.path.hasPrefix(root), let data = try? Data(contentsOf: file) else {
                        return send(404, "text/plain", Data("Not found".utf8), on: connection)
                    }
                    return send(200, type, data, on: connection)
